INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dartilesm/bytebuzz/shadcn', 'community', 'dartilesm', 'bytebuzz', 'dartilesm/bytebuzz', 'shadcn', 2, 2, 45, '2026-03-07T20:47:58Z', '2026-03-08T01:59:29.866Z', 'cefd8f067461a5994741aef6be1e285bb62c5a0dceef79006dd3caaa4fbfec1a', '{"id":"dartilesm/bytebuzz/shadcn","name":"shadcn","description":{"en":"shadcn is a framework for building UI components and design systems, enabling developers to share and manage code snippets efficiently. It benefits developers and tech enthusiasts looking to connect with like-minded users.","zh":"shadcn UI是一个用于构建UI组件和设计系统的框架，支持通过CLI命令安装组件","ja":"shadcn UIは、UIコンポーネントとデザインシステムを構築するためのフレームワークで、CLIコマンドを使用してコンポーネントをインストールできます","ko":"shadcn UI는 UI 컴포넌트와 디자인 시스템을 구축하기 위한 프레임워크로, CLI 명령어를 통해 컴포넌트를 설치할 수 있습니다","es":"shadcn es un framework de UI que permite a los desarrolladores crear componentes y sistemas de diseño personalizados para sus proyectos","fr":"shadcn est un framework d''interface utilisateur qui permet aux développeurs de créer des composants et des systèmes de conception personnalisés pour leurs projets","de":"shadcn ist ein UI-Framework, das es Entwicklern ermöglicht, anpassbare Komponenten und Designsysteme für ihre Projekte zu erstellen","pt":"O shadcn é um framework UI para desenvolvedores que permite criar componentes e design systems personalizados. Ele oferece recursos avançados para melhorar a produtividade e a eficiência","ru":"Shadcn - это фреймворк UI для разработчиков, который позволяет создавать пользовательские компоненты и системы дизайна. Он предлагает передовые возможности для повышения производительности и эффективности","ar":"shadcn هو إطار العمل UI للمطورين الذي يسمح بإنشاء مكونات وأنظمة تصميم مخصصة. يقدم ميزات متقدمة لتحسين الإنتاجية والكفاءة"},"seo":{"title":{"en":"shadcn: UI Component Setup Guide | AI Agent Skill","zh":"shadcn UI框架安装指南","ja":"shadcn UIフレームワークのセットアップガイド","ko":"shadcn UI 프레임워크 설정 가이드","es":"Guía de configuración de shadcn: Framework de UI para des...","fr":"Guide d''installation de shadcn: Framework d''interface uti...","de":"Einrichtungsleitfaden für shadcn: UI-Framework für Entwic...","pt":"Guia de Configuração do shadcn: Framework UI Avançado","ru":"Настройка shadcn: Руководство по использованию ИИ Агентов","ar":"دليل إعداد shadcn: إطار العمل UI المتقدم"},"description":{"en":"Discover how to integrate shadcn into your project and streamline UI component management - get started with our expert guide","zh":"了解shadcn UI框架的技术细节，包括CLI命令和组件安装","ja":"shadcn UIフレームワークの技術的特徴、CLIコマンド、コンポーネントのインストールについて","ko":"shadcn UI 프레임워크의 기술적 세부 사항, CLI 명령어, 컴포넌트 설치 방법","es":"Aprende a configurar y utilizar shadcn, un framework de UI para desarrolladores que ofrece componentes personalizables y sistemas de diseño","fr":"Découvrez comment installer et utiliser shadcn, un framework d''interface utilisateur pour les développeurs qui propose des composants personnalisables et des...","de":"Erfahren Sie, wie Sie shadcn konfigurieren und verwenden, ein UI-Framework für Entwickler mit anpassbaren Komponenten und Designsystemen","pt":"Aprenda a configurar o shadcn, um framework UI para desenvolvedores, e descubra seus recursos avançados para construir componentes e design systems","ru":"Узнайте, как настроить shadcn, фреймворк UI для разработчиков, и откройте для себя его передовые возможности для создания компонентов и систем дизайна","ar":"تعرف على كيفية تهيئة shadcn، إطار العمل UI للمطورين، واكتشف ميزاته المتقدمة لإنشاء المكونات وأنظمة التصميم"},"definition":{"en":"shadcn is a UI component framework that allows developers to add components as source code to their projects via the CLI using commands like npx shadcn@latest","zh":"shadcn UI是用于构建UI组件和设计系统的框架","ja":"shadcn UIは、UIコンポーネントとデザインシステムを構築するためのフレームワーク","ko":"shadcn UI는 UI 컴포넌트와 디자인 시스템을 구축하기 위한 프레임워크","es":"shadcn es un framework de UI que se utiliza para crear componentes y sistemas de diseño personalizados","fr":"shadcn est un framework d''interface utilisateur utilisé pour créer des composants et des systèmes de conception personnalisés","de":"shadcn ist ein UI-Framework, das zur Erstellung von anpassbaren Komponenten und Designsystemen verwendet wird","pt":"O shadcn é um framework UI que permite criar componentes e design systems personalizados para desenvolvedores","ru":"Shadcn - это фреймворк UI, который позволяет создавать пользовательские компоненты и системы дизайна для разработчиков","ar":"shadcn هو إطار العمل UI الذي يسمح بإنشاء مكونات وأنظمة تصميم مخصصة للمطورين"},"features":{"en":["Adds UI components as source code to projects via the CLI","Supports project package runners like npx, pnpm, and bunx","Provides a design system framework for building consistent UI","Enables users to run CLI commands with the project''s package manager","Generates project information in JSON format using npx shadcn@latest info --json"],"zh":["支持通过CLI命令安装组件","提供设计系统构建功能","支持多种包管理器（pnpm、bun等）","提供项目信息查询功能（npx shadcn@latest info）","支持JSON格式的项目信息输出"],"ja":["CLIコマンドを使用してコンポーネントをインストール","デザインシステムの構築機能を提供","複数のパッケージマネージャー（pnpm、bunなど）をサポート","プロジェクト情報の照会機能（npx shadcn@latest info）","JSON形式のプロジェクト情報出力をサポート"],"ko":["CLI 명령어를 통해 컴포넌트를 설치할 수 있습니다","디자인 시스템 구축 기능을 제공합니다","여러 가지 패키지 매니저(pnpm, bun 등)를 지원합니다","프로젝트 정보 조회 기능(npx shadcn@latest info)을 제공합니다","JSON 형식의 프로젝트 정보 출력을 지원합니다"],"es":["Componentes personalizables vía CLI","Sistemas de diseño integrados","Compatibilidad con diferentes administradores de paquetes","Uso de npmx, pnpm o bunx como corredor de paquetes","Soporte para proyectos con différents gerentes de paquetes"],"fr":["Composants personnalisables via CLI","Systèmes de conception intégrés","Compatibilité avec différents gestionnaires de paquets","Utilisation de npmx, pnpm ou bunx comme exécuteur de paquets","Prise en charge de projets avec différents gestionnaires de paquets"],"de":["Anpassbare Komponenten über die CLI","Integrierte Designsysteme","Kompatibilität mit verschiedenen Paketmanagern","Verwendung von npmx, pnpm oder bunx als Paketrunner","Unterstützung für Projekte mit unterschiedlichen Paketmanagern"],"pt":["Criação de componentes personalizados via CLI","Integração com gerenciadores de pacotes como npm e pnpm","Suporte a design systems personalizados","Comandos CLI avançados para gerenciar componentes e design systems","Integração com o framework shadcn/ui"],"ru":["Создание пользовательских компонентов через CLI","Интеграция с менеджерами пакетов như npm и pnpm","Поддержка пользовательских систем дизайна","Продвинутые команды CLI для управления компонентами и системами дизайна","Интеграция с фреймворком shadcn/ui"],"ar":["إنشاء مكونات مخصصة عبر CLI","التكامل مع مدراء الحزم مثل npm و pnpm","دعم لأنظمة التصميم المخصصة","أوامر CLI متقدمة لادارة المكونات وأنظمة التصميم","التكامل مع إطار العمل shadcn/ui"]},"keywords":{"en":["how to use shadcn","shadcn ui component framework","shadcn alternative","shadcn vs bytebuzz","shadcn install guide","shadcn setup for developers","shadcn cli commands","shadcn design system"],"zh":["shadcn UI","UI框架","CLI命令","组件安装","设计系统","包管理器","JSON输出","AIエージェント","前端开发"],"ja":["shadcn UI","UIフレームワーク","CLIコマンド","コンポーネントのインストール","デザインシステム","パッケージマネージャー","JSON出力","AIエージェント","フロントエンド開発"],"ko":["shadcn UI","UI 프레임워크","CLI 명령어","컴포넌트 설치","디자인 시스템","패키지 매니저","JSON 출력","AI 에이전트","프론트엔드 개발"],"es":["shadcn","framework de UI","componentes personalizables","sistemas de diseño","CLI","npmx","pnpm","bunx","desarrollo de software","herramientas de desarrollo"],"fr":["shadcn","framework d''interface utilisateur","composants personnalisables","systèmes de conception","CLI","npmx","pnpm","bunx","développement de logiciels","outils de développement"],"de":["shadcn","UI-Framework","anpassbare Komponenten","Designsysteme","CLI","npmx","pnpm","bunx","Softwareentwicklung","Entwicklungstools"],"pt":["shadcn","framework UI","desenvolvimento de software","componentes personalizados","design systems","CLI","npm","pnpm","gerenciamento de pacotes"],"ru":["shadcn","фреймворк UI","разработка программного обеспечения","пользовательские компоненты","системы дизайна","CLI","npm","pnpm","управление пакетами"],"ar":["shadcn","إطار العمل UI","تطوير البرمجيات","مكونات مخصصة","أنظمة التصميم","CLI","npm","pnpm","إدارة الحزم"]}},"owner":"dartilesm","repo":"bytebuzz","repoPath":"dartilesm/bytebuzz","stars":2,"forks":2,"updatedAt":"2026-03-07T20:47:58Z","topics":[],"category":"community","skillMd":{"name":"shadcn","description":"Manages shadcn components and projects — adding, searching, fixing, debugging, styling, and composing UI. Provides project context, component docs, and usage examples. Applies when working with shadcn/ui, component registries, presets, --preset codes, or any project with a components.json file. Also triggers for shadcn init, create an app with --preset, or switch to --preset.","bodyPreview":"# shadcn/ui\n\nA framework for building ui, components and design systems. Components are added as source code to the user''s project via the CLI.\n\n> **IMPORTANT:** Run all CLI commands using the project''s package runner: `npx shadcn@latest`, `pnpm dlx shadcn@latest`, or `bunx --bun shadcn@latest` — based on the project''s `packageManager`. Examples below use `npx shadcn@latest` but substitute the correct runner for the project.\n\n## Current Project Context\n\n```json\n!`npx shadcn@latest info --json 2>","body":"# shadcn/ui\n\nA framework for building ui, components and design systems. Components are added as source code to the user''s project via the CLI.\n\n> **IMPORTANT:** Run all CLI commands using the project''s package runner: `npx shadcn@latest`, `pnpm dlx shadcn@latest`, or `bunx --bun shadcn@latest` — based on the project''s `packageManager`. Examples below use `npx shadcn@latest` but substitute the correct runner for the project.\n\n## Current Project Context\n\n```json\n!`npx shadcn@latest info --json 2>/dev/null || echo ''{\"error\": \"No shadcn project found. Run shadcn init first.\"}''`\n```\n\nThe JSON above contains the project config and installed components. Use `npx shadcn@latest docs <component>` to get documentation and example URLs for any component.\n\n## Principles\n\n1. **Use existing components first.** Use `npx shadcn@latest search` to check registries before writing custom UI. Check community registries too.\n2. **Compose, don''t reinvent.** Settings page = Tabs + Card + form controls. Dashboard = Sidebar + Card + Chart + Table.\n3. **Use built-in variants before custom styles.** `variant=\"outline\"`, `size=\"sm\"`, etc.\n4. **Use semantic colors.** `bg-primary`, `text-muted-foreground` — never raw values like `bg-blue-500`.\n\n## Critical Rules\n\nThese rules are **always enforced**. Each links to a file with Incorrect/Correct code pairs.\n\n### Styling & Tailwind → [styling.md](./rules/styling.md)\n\n- **`className` for layout, not styling.** Never override component colors or typography.\n- **No `space-x-*` or `space-y-*`.** Use `flex` with `gap-*`. For vertical stacks, `flex flex-col gap-*`.\n- **Use `size-*` when width and height are equal.** `size-10` not `w-10 h-10`.\n- **Use `truncate` shorthand.** Not `overflow-hidden text-ellipsis whitespace-nowrap`.\n- **No manual `dark:` color overrides.** Use semantic tokens (`bg-background`, `text-muted-foreground`).\n- **Use `cn()` for conditional classes.** Don''t write manual template literal ternaries.\n- **No manual `z-index` on overlay components.** Dialog, Sheet, Popover, etc. handle their own stacking.\n\n### Forms & Inputs → [forms.md](./rules/forms.md)\n\n- **Forms use `FieldGroup` + `Field`.** Never use raw `div` with `space-y-*` or `grid gap-*` for form layout.\n- **`InputGroup` uses `InputGroupInput`/`InputGroupTextarea`.** Never raw `Input`/`Textarea` inside `InputGroup`.\n- **Buttons inside inputs use `InputGroup` + `InputGroupAddon`.**\n- **Option sets (2–7 choices) use `ToggleGroup`.** Don''t loop `Button` with manual active state.\n- **`FieldSet` + `FieldLegend` for grouping related checkboxes/radios.** Don''t use a `div` with a heading.\n- **Field validation uses `data-invalid` + `aria-invalid`.** `data-invalid` on `Field`, `aria-invalid` on the control. For disabled: `data-disabled` on `Field`, `disabled` on the control.\n\n### Component Structure → [composition.md](./rules/composition.md)\n\n- **Items always inside their Group.** `SelectItem` → `SelectGroup`. `DropdownMenuItem` → `DropdownMenuGroup`. `CommandItem` → `CommandGroup`.\n- **Use `asChild` (radix) or `render` (base) for custom triggers.** Check `base` field from `npx shadcn@latest info`. → [base-vs-radix.md](./rules/base-vs-radix.md)\n- **Dialog, Sheet, and Drawer always need a Title.** `DialogTitle`, `SheetTitle`, `DrawerTitle` required for accessibility. Use `className=\"sr-only\"` if visually hidden.\n- **Use full Card composition.** `CardHeader`/`CardTitle`/`CardDescription`/`CardContent`/`CardFooter`. Don''t dump everything in `CardContent`.\n- **Button has no `isPending`/`isLoading`.** Compose with `Spinner` + `data-icon` + `disabled`.\n- **`TabsTrigger` must be inside `TabsList`.** Never render triggers directly in `Tabs`.\n- **`Avatar` always needs `AvatarFallback`.** For when the image fails to load.\n\n### Use Components, Not Custom Markup → [composition.md](./rules/composition.md)\n\n- **Use existing components before custom markup.** Check if a component exists before writing a styled `div`.\n- **Callouts use `Alert`.** Don''t build custom styled divs.\n- **Empty states use `Empty`.** Don''t build custom empty state markup.\n- **Toast via `sonner`.** Use `toast()` from `sonner`.\n- **Use `Separator`** instead of `<hr>` or `<div className=\"border-t\">`.\n- **Use `Skeleton`** for loading placeholders. No custom `animate-pulse` divs.\n- **Use `Badge`** instead of custom styled spans.\n\n### Icons → [icons.md](./rules/icons.md)\n\n- **Icons in `Button` use `data-icon`.** `data-icon=\"inline-start\"` or `data-icon=\"inline-end\"` on the icon.\n- **No sizing classes on icons inside components.** Components handle icon sizing via CSS. No `size-4` or `w-4 h-4`.\n- **Pass icons as objects, not string keys.** `icon={CheckIcon}`, not a string lookup.\n\n### CLI\n\n- **Never decode or fetch preset codes manually.** Pass them directly to `npx shadcn@latest init --preset <code>`.\n\n## Key Patterns\n\nThese are the most common patterns that differentiate correct shadcn/ui code. For edge cases, see the linked rule files above.\n\n```tsx\n// Form layout: FieldGroup + Field, not div + Label.\n<FieldGroup>\n  <Field>\n    <FieldLabel htmlFor=\"email\">Email</FieldLabel>\n    <Input id=\"email\" />\n  </Field>\n</FieldGroup>\n\n// Validation: data-invalid on Field, aria-invalid on the control.\n<Field data-invalid>\n  <FieldLabel>Email</FieldLabel>\n  <Input aria-invalid />\n  <FieldDescription>Invalid email.</FieldDescription>\n</Field>\n\n// Icons in buttons: data-icon, no sizing classes.\n<Button>\n  <SearchIcon data-icon=\"inline-start\" />\n  Search\n</Button>\n\n// Spacing: gap-*, not space-y-*.\n<div className=\"flex flex-col gap-4\">  // correct\n<div className=\"space-y-4\">           // wrong\n\n// Equal dimensions: size-*, not w-* h-*.\n<Avatar className=\"size-10\">   // correct\n<Avatar className=\"w-10 h-10\"> // wrong\n\n// Status colors: Badge variants or semantic tokens, not raw colors.\n<Badge variant=\"secondary\">+20.1%</Badge>    // correct\n<span className=\"text-emerald-600\">+20.1%</span> // wrong\n```\n\n## Component Selection\n\n| Need                       | Use                                                                                                 |\n| -------------------------- | --------------------------------------------------------------------------------------------------- |\n| Button/action              | `Button` with appropriate variant                                                                   |\n| Form inputs                | `Input`, `Select`, `Combobox`, `Switch`, `Checkbox`, `RadioGroup`, `Textarea`, `InputOTP`, `Slider` |\n| Toggle between 2–5 options | `ToggleGroup` + `ToggleGroupItem`                                                                   |\n| Data display               | `Table`, `Card`, `Badge`, `Avatar`                                                                  |\n| Navigation                 | `Sidebar`, `NavigationMenu`, `Breadcrumb`, `Tabs`, `Pagination`                                     |\n| Overlays                   | `Dialog` (modal), `Sheet` (side panel), `Drawer` (bottom sheet), `AlertDialog` (confirmation)       |\n| Feedback                   | `sonner` (toast), `Alert`, `Progress`, `Skeleton`, `Spinner`                                        |\n| Command palette            | `Command` inside `Dialog`                                                                           |\n| Charts                     | `Chart` (wraps Recharts)                                                                            |\n| Layout                     | `Card`, `Separator`, `Resizable`, `ScrollArea`, `Accordion`, `Collapsible`                          |\n| Empty states               | `Empty`                                                                                             |\n| Menus                      | `DropdownMenu`, `ContextMenu`, `Menubar`                                                            |\n| Tooltips/info              | `Tooltip`, `HoverCard`, `Popover`                                                                   |\n\n## Key Fields\n\nThe injected project context contains these key fields:\n\n- **`aliases`** → use the actual alias prefix for imports (e.g. `@/`, `~/`), never hardcode.\n- **`isRSC`** → when `true`, components using `useState`, `useEffect`, event handlers, or browser APIs need `\"use client\"` at the top of the file. Always reference this field when advising on the directive.\n- **`tailwindVersion`** → `\"v4\"` uses `@theme inline` blocks; `\"v3\"` uses `tailwind.config.js`.\n- **`tailwindCssFile`** → the global CSS file where custom CSS variables are defined. Always edit this file, never create a new one.\n- **`style`** → component visual treatment (e.g. `nova`, `vega`).\n- **`base`** → primitive library (`radix` or `base`). Affects component APIs and available props.\n- **`iconLibrary`** → determines icon imports. Use `lucide-react` for `lucide`, `@tabler/icons-react` for `tabler`, etc. Never assume `lucide-react`.\n- **`resolvedPaths`** → exact file-system destinations for components, utils, hooks, etc.\n- **`framework`** → routing and file conventions (e.g. Next.js App Router vs Vite SPA).\n- **`packageManager`** → use this for any non-shadcn dependency installs (e.g. `pnpm add date-fns` vs `npm install date-fns`).\n\nSee [cli.md — `info` command](./cli.md) for the full field reference.\n\n## Component Docs, Examples, and Usage\n\nRun `npx shadcn@latest docs <component>` to get the URLs for a component''s documentation, examples, and API reference. Fetch these URLs to get the actual content.\n\n```bash\nnpx shadcn@latest docs button dialog select\n```\n\n**When creating, fixing, debugging, or using a component, always run `npx shadcn@latest docs` and fetch the URLs first.** This ensures you''re working with the correct API and usage patterns rather than guessing.\n\n## Workflow\n\n1. **Get project context** — already injected above. Run `npx shadcn@latest info` again if you need to refresh.\n2. **Check installed components first** — before running `add`, always check the `components` list from project context or list the `resolvedPaths.ui` directory. Don''t import components that haven''t been added, and don''t re-add ones already installed.\n3. **Find components** — `npx shadcn@latest search`.\n4. **Get docs and examples** — run `npx shadcn@latest docs <component>` to get URLs, then fetch them. Use `npx shadcn@latest view` to browse registry items you haven''t installed. To preview changes to installed components, use `npx shadcn@latest add --diff`.\n5. **Install or update** — `npx shadcn@latest add`. When updating existing components, use `--dry-run` and `--diff` to preview changes first (see [Updating Components](#updating-components) below).\n6. **Fix imports in third-party components** — After adding components from community registries (e.g. `@bundui`, `@magicui`), check the added non-UI files for hardcoded import paths like `@/components/ui/...`. These won''t match the project''s actual aliases. Use `npx shadcn@latest info` to get the correct `ui` alias (e.g. `@workspace/ui/components`) and rewrite the imports accordingly. The CLI rewrites imports for its own UI files, but third-party registry components may use default paths that don''t match the project.\n7. **Review added components** — After adding a component or block from any registry, **always read the added files and verify they are correct**. Check for missing sub-components (e.g. `SelectItem` without `SelectGroup`), missing imports, incorrect composition, or violations of the [Critical Rules](#critical-rules). Also replace any icon imports with the project''s `iconLibrary` from the project context (e.g. if the registry item uses `lucide-react` but the project uses `hugeicons`, swap the imports and icon names accordingly). Fix all issues before moving on.\n8. **Registry must be explicit** — When the user asks to add a block or component, **do not guess the registry**. If no registry is specified (e.g. user says \"add a login block\" without specifying `@shadcn`, `@tailark`, etc.), ask which registry to use. Never default to a registry on behalf of the user.\n9. **Switching presets** — Ask the user first: **reinstall**, **merge**, or **skip**?\n   - **Reinstall**: `npx shadcn@latest init --preset <code> --force --reinstall`. Overwrites all components.\n   - **Merge**: `npx shadcn@latest init --preset <code> --force --no-reinstall`, then run `npx shadcn@latest info` to list installed components, then for each installed component use `--dry-run` and `--diff` to [smart merge](#updating-components) it individually.\n   - **Skip**: `npx shadcn@latest init --preset <code> --force --no-reinstall`. Only updates config and CSS, leaves components as-is.\n\n## Updating Components\n\nWhen the user asks to update a component from upstream while keeping their local changes, use `--dry-run` and `--diff` to intelligently merge. **NEVER fetch raw files from GitHub manually — always use the CLI.**\n\n1. Run `npx shadcn@latest add <component> --dry-run` to see all files that would be affected.\n2. For each file, run `npx shadcn@latest add <component> --diff <file>` to see what changed upstream vs local.\n3. Decide per file based on the diff:\n   - No local changes → safe to overwrite.\n   - Has local changes → read the local file, analyze the diff, and apply upstream updates while preserving local modifications.\n   - User says \"just update everything\" → use `--overwrite`, but confirm first.\n4. **Never use `--overwrite` without the user''s explicit approval.**\n\n## Quick Reference\n\n```bash\n# Create a new project.\nnpx shadcn@latest init --name my-app --preset base-nova\nnpx shadcn@latest init --name my-app --preset a2r6bw --template vite\n\n# Create a monorepo project.\nnpx shadcn@latest init --name my-app --preset base-nova --monorepo\nnpx shadcn@latest init --name my-app --preset base-nova --template next --monorepo\n\n# Initialize existing project.\nnpx shadcn@latest init --preset base-nova\nnpx shadcn@latest init --defaults  # shortcut: --template=next --preset=base-nova\n\n# Add components.\nnpx shadcn@latest add button card dialog\nnpx shadcn@latest add @magicui/shimmer-button\nnpx shadcn@latest add --all\n\n# Preview changes before adding/updating.\nnpx shadcn@latest add button --dry-run\nnpx shadcn@latest add button --diff button.tsx\nnpx shadcn@latest add @acme/form --view button.tsx\n\n# Search registries.\nnpx shadcn@latest search @shadcn -q \"sidebar\"\nnpx shadcn@latest search @tailark -q \"stats\"\n\n# Get component docs and example URLs.\nnpx shadcn@latest docs button dialog select\n\n# View registry item details (for items not yet installed).\nnpx shadcn@latest view @shadcn/button\n```\n\n**Named presets:** `base-nova`, `radix-nova`\n**Templates:** `next`, `vite`, `start`, `react-router`, `astro` (all support `--monorepo`) and `laravel` (not supported for monorepo)\n**Preset codes:** Base62 strings starting with `a` (e.g. `a2r6bw`), from [ui.shadcn.com](https://ui.shadcn.com).\n\n## Detailed References\n\n- [rules/forms.md](./rules/forms.md) — FieldGroup, Field, InputGroup, ToggleGroup, FieldSet, validation states\n- [rules/composition.md](./rules/composition.md) — Groups, overlays, Card, Tabs, Avatar, Alert, Empty, Toast, Separator, Skeleton, Badge, Button loading\n- [rules/icons.md](./rules/icons.md) — data-icon, icon sizing, passing icons as objects\n- [rules/styling.md](./rules/styling.md) — Semantic colors, variants, className, spacing, size, truncate, dark mode, cn(), z-index\n- [rules/base-vs-radix.md](./rules/base-vs-radix.md) — asChild vs render, Select, ToggleGroup, Slider, Accordion\n- [cli.md](./cli.md) — Commands, flags, presets, templates\n- [customization.md](./customization.md) — Theming, CSS variables, extending components\n"},"lastSynced":"2026-03-08T01:59:29.866Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing efficient UI component management and design system integration.","zh":"非常适合需要高效的UI组件管理和设计系统集成的前端代理。","ja":"フロントエンドエージェントが効率的なUIコンポーネント管理とデザインシステム統合を必要とする場合に最適です。","ko":"効率적인 UI 컴포넌트 관리와 디자인 시스템 통합이 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan una gestión eficiente de componentes de interfaz de usuario y una integración del sistema de diseño.","fr":"Parfait pour les agents Frontend qui ont besoin d''une gestion efficace des composants d''interface utilisateur et d''une intégration du système de conception.","de":"Perfekt für Frontend-Agenten, die eine effiziente Verwaltung von Benutzeroberflächenkomponenten und eine Integration des Designsystems benötigen.","pt":"Perfeito para Agentes Frontend que precisam de gerenciamento eficiente de componentes de interface do usuário e integração de sistema de design.","ru":"Идеально подходит для агентов Frontend, которым необходим эффективный менеджмент компонентов пользовательского интерфейса и интеграция системы дизайна.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يحتاج إلى إدارة فعالة لمكونات واجهة المستخدم وتكامل نظام التصميم."},"recommendation":{"en":"Empowers agents to manage and share UI components as source code via the CLI, utilizing package runners like `npx`, `pnpm dlx`, or `bunx` for seamless project integration, and enabling efficient design system development.","zh":"赋予代理管理和共享UI组件的能力，通过CLI以源代码的形式共享，利用包运行器如`npx`、`pnpm dlx`或`bunx`实现无缝的项目集成，并使设计系统开发更加高效。","ja":"エージェントがUIコンポーネントをソースコードとしてCLI経由で管理および共有できるようにし、`npx`、`pnpm dlx`、または`bunx`などのパッケージランナーを使用してプロジェクトのシームレスな統合を実現し、設計システムの開発を効率化します。","ko":"에이전트가 UI 컴포넌트를 소스 코드로 CLI를 통해 관리 및 공유할 수 있도록 하며, `npx`, `pnpm dlx`, 또는 `bunx`와 같은 패키지 러너를 사용하여 프로젝트에 무결점으로 통합하고, 디자인 시스템 개발을 효율적으로 합니다.","es":"Habilita a los agentes a gestionar y compartir componentes de interfaz de usuario como código fuente a través de la CLI, utilizando ejecutores de paquetes como `npx`, `pnpm dlx` o `bunx` para una integración de proyecto sin problemas y permitiendo un desarrollo eficiente del sistema de diseño.","fr":"Permet aux agents de gérer et de partager des composants d''interface utilisateur en tant que code source via la CLI, en utilisant des exécuteurs de paquets tels que `npx`, `pnpm dlx` ou `bunx` pour une intégration de projet sans problème et permettant un développement efficace du système de conception.","de":"Ermächtigt Agenten, Benutzeroberflächenkomponenten als Quellcode über die CLI zu verwalten und zu teilen, indem Paket-Runner wie `npx`, `pnpm dlx` oder `bunx` für eine reibungslose Projektintegration verwendet werden und eine effiziente Entwicklung des Designsystems ermöglicht.","pt":"Habilita os agentes a gerenciar e compartilhar componentes de interface do usuário como código-fonte via CLI, utilizando executores de pacotes como `npx`, `pnpm dlx` ou `bunx` para integração de projeto sem interrupções e permitindo o desenvolvimento eficiente do sistema de design.","ru":"Наделяет агентов возможностью управлять и делиться компонентами пользовательского интерфейса как исходным кодом через CLI, используя запускаемые пакеты как `npx`, `pnpm dlx` или `bunx` для бесшовной интеграции проекта и обеспечивая эффективное развитие системы дизайна.","ar":"يتمكن العملاء من إدارة ومشاركة مكونات واجهة المستخدم ككود مصدر عبر واجهة سطر الأوامر، باستخدام تشغيل حزم مثل `npx` و `pnpm dlx` و `bunx` من أجل دمج مشروع دون انقطاع وتتمكن من تطوير نظام التصميم بفعالية."},"useCases":{"en":["Building reusable UI components","Managing design systems across projects","Sharing code snippets efficiently via the CLI"],"zh":["构建可重用的UI组件","跨项目管理设计系统","通过CLI高效共享代码片段"],"ja":["再利用可能なUIコンポーネントの構築","設計システムのプロジェクト間管理","CLI経由でのコードスニペットの効率的な共有"],"ko":["재사용 가능한 UI 컴포넌트 구축","프로젝트 간 디자인 시스템 관리","CLI를 통한 코드 스니펫의 효율적인 공유"],"es":["Creación de componentes de interfaz de usuario reutilizables","Gestión de sistemas de diseño en varios proyectos","Compartir fragmentos de código de forma eficiente a través de la CLI"],"fr":["Création de composants d''interface utilisateur réutilisables","Gestion de systèmes de conception dans plusieurs projets","Partage de fragments de code de manière efficace via la CLI"],"de":["Erstellung von wiederverwendbaren Benutzeroberflächenkomponenten","Verwaltung von Designsystemen in mehreren Projekten","Effizientes Teilen von Code-Snippets über die CLI"],"pt":["Construir componentes de interface do usuário reutilizáveis","Gerenciar sistemas de design em vários projetos","Compartilhar trechos de código de forma eficiente via CLI"],"ru":["Создание многократно используемых компонентов пользовательского интерфейса","Управление системами дизайна в нескольких проектах","Эффективное обмен кодовыми фрагментами через CLI"],"ar":["بناء مكونات واجهة المستخدم قابلة لإعادة الاستخدام","إدارة أنظمة التصميم عبر المشاريع","مشاركة شذرات الكود بفعالية عبر واجهة سطر الأوامر"]},"limitations":{"en":["Requires project package runner (e.g., `npx`, `pnpm dlx`, or `bunx`)","CLI commands must be run using the project''s package runner"],"zh":["需要项目包运行器（例如`npx`、`pnpm dlx`或`bunx`）","CLI命令必须使用项目的包运行器运行"],"ja":["プロジェクトパッケージランナー（例：`npx`、`pnpm dlx`、または`bunx`）が必要","CLIコマンドはプロジェクトのパッケージランナーを使用して実行する必要がある"],"ko":["프로젝트 패키지 러너(`npx`, `pnpm dlx`, 또는 `bunx` 등)가 필요","CLI 명령어는 프로젝트의 패키지 러너를 사용하여 실행되어야 함"],"es":["Requiere un ejecutor de paquetes de proyecto (por ejemplo, `npx`, `pnpm dlx` o `bunx`)","Los comandos de la CLI deben ejecutarse utilizando el ejecutor de paquetes del proyecto"],"fr":["Nécessite un exécuteur de paquets de projet (par exemple, `npx`, `pnpm dlx` ou `bunx`)","Les commandes de la CLI doivent être exécutées en utilisant l''exécuteur de paquets du projet"],"de":["Benötigt einen Paket-Runner für das Projekt (z. B. `npx`, `pnpm dlx` oder `bunx`)","Die CLI-Befehle müssen mit dem Paket-Runner des Projekts ausgeführt werden"],"pt":["Exige um executor de pacote do projeto (por exemplo, `npx`, `pnpm dlx` ou `bunx`)","Os comandos CLI devem ser executados usando o executor de pacote do projeto"],"ru":["Требует запускаемого пакета проекта (например, `npx`, `pnpm dlx` или `bunx`)","Команды CLI должны запускаться с помощью запускаемого пакета проекта"],"ar":["يتطلب تشغيل حزمة المشروع (على سبيل المثال `npx` و `pnpm dlx` و `bunx`)","يجب تشغيل أوامر واجهة سطر الأوامر باستخدام تشغيل حزمة المشروع"]},"version":4},"contentHash":"cefd8f067461a5994741aef6be1e285bb62c5a0dceef79006dd3caaa4fbfec1a","qualityScore":45}');
