INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dartilesm/bytebuzz/shadcn', 'shadcn', 'dartilesm', 'bytebuzz', 'community', 'shadcn dartilesm bytebuzz community shadcn is a framework for building UI components and design systems, enabling developers to share and manage code snippets efficiently. It benefits developers and tech enthusiasts looking to connect with like-minded users. shadcn UI是一个用于构建UI组件和设计系统的框架，支持通过CLI命令安装组件 shadcn UIは、UIコンポーネントとデザインシステムを構築するためのフレームワークで、CLIコマンドを使用してコンポーネントをインストールできます shadcn UI는 UI 컴포넌트와 디자인 시스템을 구축하기 위한 프레임워크로, CLI 명령어를 통해 컴포넌트를 설치할 수 있습니다 shadcn es un framework de UI que permite a los desarrolladores crear componentes y sistemas de diseño personalizados para sus proyectos shadcn est un framework d''interface utilisateur qui permet aux développeurs de créer des composants et des systèmes de conception personnalisés pour leurs projets shadcn ist ein UI-Framework, das es Entwicklern ermöglicht, anpassbare Komponenten und Designsysteme für ihre Projekte zu erstellen O shadcn é um framework UI para desenvolvedores que permite criar componentes e design systems personalizados. Ele oferece recursos avançados para melhorar a produtividade e a eficiência Shadcn - это фреймворк UI для разработчиков, который позволяет создавать пользовательские компоненты и системы дизайна. Он предлагает передовые возможности для повышения производительности и эффективности shadcn هو إطار العمل UI للمطورين الذي يسمح بإنشاء مكونات وأنظمة تصميم مخصصة. يقدم ميزات متقدمة لتحسين الإنتاجية والكفاءة how to use shadcn shadcn ui component framework shadcn alternative shadcn vs bytebuzz shadcn install guide shadcn setup for developers shadcn cli commands shadcn design system shadcn UI UI框架 CLI命令 组件安装 设计系统 包管理器 JSON输出 AIエージェント 前端开发 Adds UI components as source code to projects via the CLI Supports project package runners like npx, pnpm, and bunx Provides a design system framework for building consistent UI Enables users to run CLI commands with the project''s package manager Generates project information in JSON format using npx shadcn@latest info --json shadcn is a UI component framework that allows developers to add components as source code to their projects via the CLI using commands like npx shadcn@latest');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AstroAir/react-quick-starter/shadcn', 'community', 'AstroAir', 'react-quick-starter', 'AstroAir/react-quick-starter', 'shadcn', 2, 0, 45, '2026-03-07T19:08:31Z', '2026-03-08T01:59:38.297Z', 'cefd8f067461a5994741aef6be1e285bb62c5a0dceef79006dd3caaa4fbfec1a', '{"id":"AstroAir/react-quick-starter/shadcn","name":"shadcn","description":{"en":"shadcn is a template for building UI components and design systems with React, Nextjs, and shadcn/ui. It benefits developers by providing a streamlined setup process using the CLI.","zh":"Shadcn UI是一个用于构建UI组件和设计系统的框架，支持React、Nextjs、Zustand和Tailwindcss","ja":"Shadcn AIエージェントは、UIコンポーネントとデザインシステムを構築するためのフレームワークで、React、Nextjs、Zustand、Tailwindcssをサポートしています","ko":"Shadcn UI 템플릿은 UI 컴포넌트와 디자인 시스템을 구축하는 프레임워크로, React, Nextjs, Zustand, Tailwindcss를 지원합니다","es":"shadcn es un framework para construir interfaces de usuario y componentes con React y Nextjs. Incluye zustand y tailwindcss","fr":"shadcn est un framework pour construire des interfaces utilisateur et des composants avec React et Nextjs, incluant zustand et tailwindcss","de":"shadcn ist ein Framework für die Erstellung von Benutzeroberflächen und Komponenten mit React und Nextjs, einschließlich zustand und tailwindcss","pt":"O Shadcn é um framework para construir interfaces de usuário personalizadas com React, Nextjs e Tailwindcss. Aprenda a configurá-lo para criar aplicações escaláveis","ru":"Shadcn - это фреймворк для создания кастомных интерфейсов пользователя с помощью React, Nextjs и Tailwindcss. Узнайте, как настроить его для создания масштабируемых приложений для ИИ Агентов","ar":"Shadcn هو إطار عمل لإنشاء واجهات مستخدم مخصصة باستخدام React و Nextjs و Tailwindcss. تعرف على كيفية إعدادها لإنشاء تطبيقات قابلة للتوسيع للأدوات الذكية"},"seo":{"title":{"en":"shadcn: Nextjs Template Setup Guide | AI Agent Skill","zh":"Shadcn UI框架_setup指南","ja":"Shadcn AIエージェントのベストプラクティス","ko":"Shadcn UI 템플릿 설정 가이드","es":"Guía de configuración de shadcn con React y Nextjs","fr":"Configurer shadcn avec React et Nextjs - Guide étape par ...","de":"Shadcn-Setup-Anleitung für React- und Nextjs-Entwickler","pt":"Guia de Configuração do Shadcn: Melhores Práticas para De...","ru":"Настройка Shadcn: Лучшие Практики для Разработчиков ИИ Аг...","ar":"دليل إعداد Shadcn: أفضل الممارسات لمنشئي الأدوات الذكية"},"description":{"en":"Unlock efficient UI development with shadcn, a React + Nextjs template. Learn how to integrate shadcn/ui, zustand, and tailwindcss for seamless project setup","zh":"了解Shadcn UI框架的特点和用途，包括React、Nextjs、Zustand和Tailwindcss的集成","ja":"Shadcn AIエージェントの機能と使い方を紹介します。React、Nextjs、Zustand、Tailwindcssとの連携についても","ko":"Shadcn UI 템플릿의 기능과 사용 방법을 알아보세요. React, Nextjs, Zustand, Tailwindcss와의 통합 등","es":"Aprende a configurar shadcn con React, Nextjs, y otras herramientas como zustand y tailwindcss para mejorar tus proyectos de desarrollo web","fr":"Découvrez comment configurer shadcn avec React, Nextjs, zustand et tailwindcss pour améliorer vos projets de développement web","de":"Erfahren Sie, wie Sie shadcn mit React, Nextjs, zustand und tailwindcss konfigurieren, um Ihre Webentwicklungsprojekte zu verbessern","pt":"Aprenda a configurar o Shadcn com React, Nextjs e Tailwindcss para criar interfaces de usuário personalizadas e escaláveis","ru":"Узнайте, как настроить Shadcn с помощью React, Nextjs и Tailwindcss для создания кастомных и масштабируемых интерфейсов пользователя для ИИ Агентов","ar":"تعرف على كيفية إعداد Shadcn باستخدام React و Nextjs و Tailwindcss لإنشاء واجهات مستخدم مخصصة وقابلة للتوسيع للأدوات الذكية"},"definition":{"en":"shadcn is a framework for building UI components and design systems, utilizing shadcn/ui, zustand, and tailwindcss for efficient development","zh":"Shadcn UI是一个用于构建UI组件和设计系统的框架","ja":"Shadcn AIエージェントは、UIコンポーネントとデザインシステムを構築するためのフレームワークです","ko":"Shadcn UI 템플릿은 UI 컴포넌트와 디자인 시스템을 구축하는 프레임워크입니다","es":"shadcn es un framework de código abierto para construir interfaces de usuario y componentes","fr":"shadcn est un framework open source pour construire des interfaces utilisateur et des composants","de":"shadcn ist ein Open-Source-Framework für die Erstellung von Benutzeroberflächen und Komponenten","pt":"Shadcn é um framework para construir interfaces de usuário personalizadas com React e Nextjs","ru":"Shadcn - это фреймворк для создания кастомных интерфейсов пользователя с помощью React и Nextjs для ИИ Агентов","ar":"Shadcn هو إطار عمل لإنشاء واجهات مستخدم مخصصة باستخدام React و Nextjs للأدوات الذكية"},"features":{"en":["Utilizes shadcn/ui for building UI components and design systems","Integrates with zustand for state management","Supports tailwindcss for styling","Provides a CLI for easy project setup and management using `npx shadcn@latest`","Allows for customization via source code addition to the user''s project","Ensures compatibility with various package managers, including pnpm and bun"],"zh":["支持React、Nextjs、Zustand和Tailwindcss","通过CLI命令添加UI组件","使用npx shadcn@latest运行CLI命令","支持多种包管理器（pnpm、bunx等）","提供JSON格式的项目信息"],"ja":["React、Nextjs、Zustand、Tailwindcssをサポート","CLIコマンドを使用してUIコンポーネントを追加","npx shadcn@latestを使用してCLIコマンドを実行","複数のパッケージマネージャー（pnpm、bunxなど）をサポート","JSON形式のプロジェクト情報を提供"],"ko":["React, Nextjs, Zustand, Tailwindcss를 지원","CLI 명령어를 사용하여 UI 컴포넌트를 추가","npx shadcn@latest를 사용하여 CLI 명령어를 실행","여러 가지 패키지 매니저（pnpm, bunx 등）를 지원","JSON 형식의 프로젝트 정보를 제공"],"es":["Integración con React y Nextjs","Uso de zustand para la gestión del estado","Diseño de componentes con tailwindcss","Instalación y configuración mediante CLI","Compatibilidad con diferentes gestores de paquetes"],"fr":["Intégration avec React et Nextjs","Utilisation de zustand pour la gestion de l''état","Conception de composants avec tailwindcss","Installation et configuration via CLI","Compatibilité avec différents gestionnaires de paquets"],"de":["Integration mit React und Nextjs","Verwendung von zustand für die Zustandsverwaltung","Komponenten-Design mit tailwindcss","Installation und Konfiguration über CLI","Kompatibilität mit verschiedenen Paket-Managern"],"pt":["Construção de interfaces de usuário personalizadas com React e Nextjs","Integração com Tailwindcss para estilos personalizados","Uso de Zustand para gerenciamento de estado","Instalação via CLI com suporte a diferentes gerenciadores de pacotes","Criação de componentes de interface de usuário personalizados com Shadcn/ui","Suporte a diferentes locais e internacionalização"],"ru":["Создание кастомных интерфейсов пользователя с помощью React и Nextjs для ИИ Агентов","Интеграция с Tailwindcss для кастомных стилей","Использование Zustand для управления состоянием","Установка через CLI с поддержкой разных менеджеров пакетов","Создание кастомных компонентов интерфейса пользователя с помощью Shadcn/ui","Поддержка разных локалей и интернационализации для ИИ Агентов"],"ar":["إنشاء واجهات مستخدم مخصصة باستخدام React و Nextjs للأدوات الذكية","التكامل مع Tailwindcss لأسلوب مخصص","استخدام Zustand لإدارة الحالة","التثبيت عبر CLI مع دعم مختلف مديري الحزم","إنشاء مكونات واجهة المستخدم المخصصة باستخدام Shadcn/ui","دعم المواقع الجغرافية المختلفة والتدويل للأدوات الذكية"]},"keywords":{"en":["how to use shadcn","shadcn setup guide","shadcn alternative","shadcn vs react","shadcn install","what is shadcn","shadcn ui components","shadcn nextjs template"],"zh":["Shadcn UI","React UI框架","Nextjs UI组件","Zustand状态管理","Tailwindcss样式","CLI命令","npx shadcn@latest","包管理器"],"ja":["Shadcn AIエージェント","React UIフレームワーク","Nextjs UIコンポーネント","Zustandステートマネージャー","Tailwindcssスタイル","CLIコマンド","npx shadcn@latest","パッケージマネージャー"],"ko":["Shadcn UI 템플릿","React UI 프레임워크","Nextjs UI 컴포넌트","Zustand 상태 관리","Tailwindcss 스타일","CLI 명령어","npx shadcn@latest","패키지 매니저"],"es":["shadcn","React","Nextjs","zustand","tailwindcss","framework de código abierto","desarrollo web","interfaces de usuario","componentes","CLI","gestores de paquetes"],"fr":["shadcn","React","Nextjs","zustand","tailwindcss","framework open source","développement web","interfaces utilisateur","composants","CLI","gestionnaires de paquets"],"de":["shadcn","React","Nextjs","zustand","tailwindcss","Open-Source-Framework","Webentwicklung","Benutzeroberflächen","Komponenten","CLI","Paket-Manager"],"pt":["Shadcn","React","Nextjs","Tailwindcss","Zustand","CLI","interfaces de usuário personalizadas","desenvolvimento de aplicações web","frameworks de front-end","bibliotecas de componentes"],"ru":["Shadcn","React","Nextjs","Tailwindcss","Zustand","CLI","кастомные интерфейсы пользователя","разработка веб-приложений","фреймворки фронтенда","библиотеки компонентов для ИИ Агентов"],"ar":["Shadcn","React","Nextjs","Tailwindcss","Zustand","CLI","واجهات المستخدم المخصصة","تطوير التطبيقات الويب","إطارات العمل الأمامية","مكتبات المكونات للأدوات الذكية"]}},"owner":"AstroAir","repo":"react-quick-starter","repoPath":"AstroAir/react-quick-starter","stars":2,"forks":0,"updatedAt":"2026-03-07T19:08:31Z","topics":[],"category":"community","skillMd":{"name":"shadcn","description":"Manages shadcn components and projects — adding, searching, fixing, debugging, styling, and composing UI. Provides project context, component docs, and usage examples. Applies when working with shadcn/ui, component registries, presets, --preset codes, or any project with a components.json file. Also triggers for shadcn init, create an app with --preset, or switch to --preset.","bodyPreview":"# shadcn/ui\n\nA framework for building ui, components and design systems. Components are added as source code to the user''s project via the CLI.\n\n> **IMPORTANT:** Run all CLI commands using the project''s package runner: `npx shadcn@latest`, `pnpm dlx shadcn@latest`, or `bunx --bun shadcn@latest` — based on the project''s `packageManager`. Examples below use `npx shadcn@latest` but substitute the correct runner for the project.\n\n## Current Project Context\n\n```json\n!`npx shadcn@latest info --json 2>","body":"# shadcn/ui\n\nA framework for building ui, components and design systems. Components are added as source code to the user''s project via the CLI.\n\n> **IMPORTANT:** Run all CLI commands using the project''s package runner: `npx shadcn@latest`, `pnpm dlx shadcn@latest`, or `bunx --bun shadcn@latest` — based on the project''s `packageManager`. Examples below use `npx shadcn@latest` but substitute the correct runner for the project.\n\n## Current Project Context\n\n```json\n!`npx shadcn@latest info --json 2>/dev/null || echo ''{\"error\": \"No shadcn project found. Run shadcn init first.\"}''`\n```\n\nThe JSON above contains the project config and installed components. Use `npx shadcn@latest docs <component>` to get documentation and example URLs for any component.\n\n## Principles\n\n1. **Use existing components first.** Use `npx shadcn@latest search` to check registries before writing custom UI. Check community registries too.\n2. **Compose, don''t reinvent.** Settings page = Tabs + Card + form controls. Dashboard = Sidebar + Card + Chart + Table.\n3. **Use built-in variants before custom styles.** `variant=\"outline\"`, `size=\"sm\"`, etc.\n4. **Use semantic colors.** `bg-primary`, `text-muted-foreground` — never raw values like `bg-blue-500`.\n\n## Critical Rules\n\nThese rules are **always enforced**. Each links to a file with Incorrect/Correct code pairs.\n\n### Styling & Tailwind → [styling.md](./rules/styling.md)\n\n- **`className` for layout, not styling.** Never override component colors or typography.\n- **No `space-x-*` or `space-y-*`.** Use `flex` with `gap-*`. For vertical stacks, `flex flex-col gap-*`.\n- **Use `size-*` when width and height are equal.** `size-10` not `w-10 h-10`.\n- **Use `truncate` shorthand.** Not `overflow-hidden text-ellipsis whitespace-nowrap`.\n- **No manual `dark:` color overrides.** Use semantic tokens (`bg-background`, `text-muted-foreground`).\n- **Use `cn()` for conditional classes.** Don''t write manual template literal ternaries.\n- **No manual `z-index` on overlay components.** Dialog, Sheet, Popover, etc. handle their own stacking.\n\n### Forms & Inputs → [forms.md](./rules/forms.md)\n\n- **Forms use `FieldGroup` + `Field`.** Never use raw `div` with `space-y-*` or `grid gap-*` for form layout.\n- **`InputGroup` uses `InputGroupInput`/`InputGroupTextarea`.** Never raw `Input`/`Textarea` inside `InputGroup`.\n- **Buttons inside inputs use `InputGroup` + `InputGroupAddon`.**\n- **Option sets (2–7 choices) use `ToggleGroup`.** Don''t loop `Button` with manual active state.\n- **`FieldSet` + `FieldLegend` for grouping related checkboxes/radios.** Don''t use a `div` with a heading.\n- **Field validation uses `data-invalid` + `aria-invalid`.** `data-invalid` on `Field`, `aria-invalid` on the control. For disabled: `data-disabled` on `Field`, `disabled` on the control.\n\n### Component Structure → [composition.md](./rules/composition.md)\n\n- **Items always inside their Group.** `SelectItem` → `SelectGroup`. `DropdownMenuItem` → `DropdownMenuGroup`. `CommandItem` → `CommandGroup`.\n- **Use `asChild` (radix) or `render` (base) for custom triggers.** Check `base` field from `npx shadcn@latest info`. → [base-vs-radix.md](./rules/base-vs-radix.md)\n- **Dialog, Sheet, and Drawer always need a Title.** `DialogTitle`, `SheetTitle`, `DrawerTitle` required for accessibility. Use `className=\"sr-only\"` if visually hidden.\n- **Use full Card composition.** `CardHeader`/`CardTitle`/`CardDescription`/`CardContent`/`CardFooter`. Don''t dump everything in `CardContent`.\n- **Button has no `isPending`/`isLoading`.** Compose with `Spinner` + `data-icon` + `disabled`.\n- **`TabsTrigger` must be inside `TabsList`.** Never render triggers directly in `Tabs`.\n- **`Avatar` always needs `AvatarFallback`.** For when the image fails to load.\n\n### Use Components, Not Custom Markup → [composition.md](./rules/composition.md)\n\n- **Use existing components before custom markup.** Check if a component exists before writing a styled `div`.\n- **Callouts use `Alert`.** Don''t build custom styled divs.\n- **Empty states use `Empty`.** Don''t build custom empty state markup.\n- **Toast via `sonner`.** Use `toast()` from `sonner`.\n- **Use `Separator`** instead of `<hr>` or `<div className=\"border-t\">`.\n- **Use `Skeleton`** for loading placeholders. No custom `animate-pulse` divs.\n- **Use `Badge`** instead of custom styled spans.\n\n### Icons → [icons.md](./rules/icons.md)\n\n- **Icons in `Button` use `data-icon`.** `data-icon=\"inline-start\"` or `data-icon=\"inline-end\"` on the icon.\n- **No sizing classes on icons inside components.** Components handle icon sizing via CSS. No `size-4` or `w-4 h-4`.\n- **Pass icons as objects, not string keys.** `icon={CheckIcon}`, not a string lookup.\n\n### CLI\n\n- **Never decode or fetch preset codes manually.** Pass them directly to `npx shadcn@latest init --preset <code>`.\n\n## Key Patterns\n\nThese are the most common patterns that differentiate correct shadcn/ui code. For edge cases, see the linked rule files above.\n\n```tsx\n// Form layout: FieldGroup + Field, not div + Label.\n<FieldGroup>\n  <Field>\n    <FieldLabel htmlFor=\"email\">Email</FieldLabel>\n    <Input id=\"email\" />\n  </Field>\n</FieldGroup>\n\n// Validation: data-invalid on Field, aria-invalid on the control.\n<Field data-invalid>\n  <FieldLabel>Email</FieldLabel>\n  <Input aria-invalid />\n  <FieldDescription>Invalid email.</FieldDescription>\n</Field>\n\n// Icons in buttons: data-icon, no sizing classes.\n<Button>\n  <SearchIcon data-icon=\"inline-start\" />\n  Search\n</Button>\n\n// Spacing: gap-*, not space-y-*.\n<div className=\"flex flex-col gap-4\">  // correct\n<div className=\"space-y-4\">           // wrong\n\n// Equal dimensions: size-*, not w-* h-*.\n<Avatar className=\"size-10\">   // correct\n<Avatar className=\"w-10 h-10\"> // wrong\n\n// Status colors: Badge variants or semantic tokens, not raw colors.\n<Badge variant=\"secondary\">+20.1%</Badge>    // correct\n<span className=\"text-emerald-600\">+20.1%</span> // wrong\n```\n\n## Component Selection\n\n| Need                       | Use                                                                                                 |\n| -------------------------- | --------------------------------------------------------------------------------------------------- |\n| Button/action              | `Button` with appropriate variant                                                                   |\n| Form inputs                | `Input`, `Select`, `Combobox`, `Switch`, `Checkbox`, `RadioGroup`, `Textarea`, `InputOTP`, `Slider` |\n| Toggle between 2–5 options | `ToggleGroup` + `ToggleGroupItem`                                                                   |\n| Data display               | `Table`, `Card`, `Badge`, `Avatar`                                                                  |\n| Navigation                 | `Sidebar`, `NavigationMenu`, `Breadcrumb`, `Tabs`, `Pagination`                                     |\n| Overlays                   | `Dialog` (modal), `Sheet` (side panel), `Drawer` (bottom sheet), `AlertDialog` (confirmation)       |\n| Feedback                   | `sonner` (toast), `Alert`, `Progress`, `Skeleton`, `Spinner`                                        |\n| Command palette            | `Command` inside `Dialog`                                                                           |\n| Charts                     | `Chart` (wraps Recharts)                                                                            |\n| Layout                     | `Card`, `Separator`, `Resizable`, `ScrollArea`, `Accordion`, `Collapsible`                          |\n| Empty states               | `Empty`                                                                                             |\n| Menus                      | `DropdownMenu`, `ContextMenu`, `Menubar`                                                            |\n| Tooltips/info              | `Tooltip`, `HoverCard`, `Popover`                                                                   |\n\n## Key Fields\n\nThe injected project context contains these key fields:\n\n- **`aliases`** → use the actual alias prefix for imports (e.g. `@/`, `~/`), never hardcode.\n- **`isRSC`** → when `true`, components using `useState`, `useEffect`, event handlers, or browser APIs need `\"use client\"` at the top of the file. Always reference this field when advising on the directive.\n- **`tailwindVersion`** → `\"v4\"` uses `@theme inline` blocks; `\"v3\"` uses `tailwind.config.js`.\n- **`tailwindCssFile`** → the global CSS file where custom CSS variables are defined. Always edit this file, never create a new one.\n- **`style`** → component visual treatment (e.g. `nova`, `vega`).\n- **`base`** → primitive library (`radix` or `base`). Affects component APIs and available props.\n- **`iconLibrary`** → determines icon imports. Use `lucide-react` for `lucide`, `@tabler/icons-react` for `tabler`, etc. Never assume `lucide-react`.\n- **`resolvedPaths`** → exact file-system destinations for components, utils, hooks, etc.\n- **`framework`** → routing and file conventions (e.g. Next.js App Router vs Vite SPA).\n- **`packageManager`** → use this for any non-shadcn dependency installs (e.g. `pnpm add date-fns` vs `npm install date-fns`).\n\nSee [cli.md — `info` command](./cli.md) for the full field reference.\n\n## Component Docs, Examples, and Usage\n\nRun `npx shadcn@latest docs <component>` to get the URLs for a component''s documentation, examples, and API reference. Fetch these URLs to get the actual content.\n\n```bash\nnpx shadcn@latest docs button dialog select\n```\n\n**When creating, fixing, debugging, or using a component, always run `npx shadcn@latest docs` and fetch the URLs first.** This ensures you''re working with the correct API and usage patterns rather than guessing.\n\n## Workflow\n\n1. **Get project context** — already injected above. Run `npx shadcn@latest info` again if you need to refresh.\n2. **Check installed components first** — before running `add`, always check the `components` list from project context or list the `resolvedPaths.ui` directory. Don''t import components that haven''t been added, and don''t re-add ones already installed.\n3. **Find components** — `npx shadcn@latest search`.\n4. **Get docs and examples** — run `npx shadcn@latest docs <component>` to get URLs, then fetch them. Use `npx shadcn@latest view` to browse registry items you haven''t installed. To preview changes to installed components, use `npx shadcn@latest add --diff`.\n5. **Install or update** — `npx shadcn@latest add`. When updating existing components, use `--dry-run` and `--diff` to preview changes first (see [Updating Components](#updating-components) below).\n6. **Fix imports in third-party components** — After adding components from community registries (e.g. `@bundui`, `@magicui`), check the added non-UI files for hardcoded import paths like `@/components/ui/...`. These won''t match the project''s actual aliases. Use `npx shadcn@latest info` to get the correct `ui` alias (e.g. `@workspace/ui/components`) and rewrite the imports accordingly. The CLI rewrites imports for its own UI files, but third-party registry components may use default paths that don''t match the project.\n7. **Review added components** — After adding a component or block from any registry, **always read the added files and verify they are correct**. Check for missing sub-components (e.g. `SelectItem` without `SelectGroup`), missing imports, incorrect composition, or violations of the [Critical Rules](#critical-rules). Also replace any icon imports with the project''s `iconLibrary` from the project context (e.g. if the registry item uses `lucide-react` but the project uses `hugeicons`, swap the imports and icon names accordingly). Fix all issues before moving on.\n8. **Registry must be explicit** — When the user asks to add a block or component, **do not guess the registry**. If no registry is specified (e.g. user says \"add a login block\" without specifying `@shadcn`, `@tailark`, etc.), ask which registry to use. Never default to a registry on behalf of the user.\n9. **Switching presets** — Ask the user first: **reinstall**, **merge**, or **skip**?\n   - **Reinstall**: `npx shadcn@latest init --preset <code> --force --reinstall`. Overwrites all components.\n   - **Merge**: `npx shadcn@latest init --preset <code> --force --no-reinstall`, then run `npx shadcn@latest info` to list installed components, then for each installed component use `--dry-run` and `--diff` to [smart merge](#updating-components) it individually.\n   - **Skip**: `npx shadcn@latest init --preset <code> --force --no-reinstall`. Only updates config and CSS, leaves components as-is.\n\n## Updating Components\n\nWhen the user asks to update a component from upstream while keeping their local changes, use `--dry-run` and `--diff` to intelligently merge. **NEVER fetch raw files from GitHub manually — always use the CLI.**\n\n1. Run `npx shadcn@latest add <component> --dry-run` to see all files that would be affected.\n2. For each file, run `npx shadcn@latest add <component> --diff <file>` to see what changed upstream vs local.\n3. Decide per file based on the diff:\n   - No local changes → safe to overwrite.\n   - Has local changes → read the local file, analyze the diff, and apply upstream updates while preserving local modifications.\n   - User says \"just update everything\" → use `--overwrite`, but confirm first.\n4. **Never use `--overwrite` without the user''s explicit approval.**\n\n## Quick Reference\n\n```bash\n# Create a new project.\nnpx shadcn@latest init --name my-app --preset base-nova\nnpx shadcn@latest init --name my-app --preset a2r6bw --template vite\n\n# Create a monorepo project.\nnpx shadcn@latest init --name my-app --preset base-nova --monorepo\nnpx shadcn@latest init --name my-app --preset base-nova --template next --monorepo\n\n# Initialize existing project.\nnpx shadcn@latest init --preset base-nova\nnpx shadcn@latest init --defaults  # shortcut: --template=next --preset=base-nova\n\n# Add components.\nnpx shadcn@latest add button card dialog\nnpx shadcn@latest add @magicui/shimmer-button\nnpx shadcn@latest add --all\n\n# Preview changes before adding/updating.\nnpx shadcn@latest add button --dry-run\nnpx shadcn@latest add button --diff button.tsx\nnpx shadcn@latest add @acme/form --view button.tsx\n\n# Search registries.\nnpx shadcn@latest search @shadcn -q \"sidebar\"\nnpx shadcn@latest search @tailark -q \"stats\"\n\n# Get component docs and example URLs.\nnpx shadcn@latest docs button dialog select\n\n# View registry item details (for items not yet installed).\nnpx shadcn@latest view @shadcn/button\n```\n\n**Named presets:** `base-nova`, `radix-nova`\n**Templates:** `next`, `vite`, `start`, `react-router`, `astro` (all support `--monorepo`) and `laravel` (not supported for monorepo)\n**Preset codes:** Base62 strings starting with `a` (e.g. `a2r6bw`), from [ui.shadcn.com](https://ui.shadcn.com).\n\n## Detailed References\n\n- [rules/forms.md](./rules/forms.md) — FieldGroup, Field, InputGroup, ToggleGroup, FieldSet, validation states\n- [rules/composition.md](./rules/composition.md) — Groups, overlays, Card, Tabs, Avatar, Alert, Empty, Toast, Separator, Skeleton, Badge, Button loading\n- [rules/icons.md](./rules/icons.md) — data-icon, icon sizing, passing icons as objects\n- [rules/styling.md](./rules/styling.md) — Semantic colors, variants, className, spacing, size, truncate, dark mode, cn(), z-index\n- [rules/base-vs-radix.md](./rules/base-vs-radix.md) — asChild vs render, Select, ToggleGroup, Slider, Accordion\n- [cli.md](./cli.md) — Commands, flags, presets, templates\n- [customization.md](./customization.md) — Theming, CSS variables, extending components\n"},"lastSynced":"2026-03-08T01:59:38.297Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents focused on building UI components and design systems with React and Nextjs.","zh":"适合专注于使用 React 和 Nextjs 构建 UI 组件和设计系统的前端代理。","ja":"React と Nextjs を使用して UI コンポーネントとデザイン システムを構築することに重点を置くフロントエンド エージェントに最適です。","ko":"React와 Nextjs를 사용하여 UI 컴포넌트와 디자인 시스템을 구축하는 데 중점을 둔 프론트엔드 에이전트에 적합합니다.","es":"Ideal para Agentes Frontend centrados en la creación de componentes de interfaz de usuario y sistemas de diseño con React y Nextjs.","fr":"Idéal pour les agents Frontend axés sur la création de composants d''interface utilisateur et de systèmes de conception avec React et Nextjs.","de":"Ideal für Frontend-Agents, die auf die Erstellung von Benutzeroberflächenkomponenten und Designsystemen mit React und Nextjs ausgerichtet sind.","pt":"Ideal para Agentes Frontend focados em construir componentes de interface do usuário e sistemas de design com React e Nextjs.","ru":"Идеально для агентов Frontend, ориентированных на создание компонентов пользовательского интерфейса и систем дизайна с React и Nextjs.","ar":"مثالية للوكلاء الأمامية الذين يركزون على بناء مكونات واجهة المستخدم وأنظمة التصميم مع React و Nextjs."},"recommendation":{"en":"Empowers agents to streamline UI development using the shadcn/ui framework, providing a CLI-driven setup process and seamless integration with React and Nextjs, leveraging components added as source code to the user''s project.","zh":"赋予代理简化 UI 开发的能力，使用 shadcn/ui 框架，提供基于 CLI 的设置过程，并与 React 和 Nextjs 无缝集成，利用将组件添加为源代码到用户的项目中。","ja":"エージェントに UI 開発を簡素化する能力を与え、shadcn/ui フレームワークを使用し、CLI ドリブンの設定プロセスを提供し、React と Nextjs にシームレスに統合し、コンポーネントをユーザーのプロジェクトにソース コードとして追加します。","ko":"에이전트에게 UI 개발을 단순화하는 능력을 부여하여 shadcn/ui 프레임워크를 사용하고 CLI 기반 설정 프로세스를 제공하며 React와 Nextjs와의無縫な統合을 제공하며, 컴포넌트를 사용자의 프로젝트에 소스 코드로 추가합니다.","es":"Permite a los agentes simplificar el desarrollo de la interfaz de usuario mediante el uso del framework shadcn/ui, que proporciona un proceso de configuración basado en CLI y una integración perfecta con React y Nextjs, aprovechando los componentes añadidos como código fuente al proyecto del usuario.","fr":"Permet aux agents de rationaliser le développement de l''interface utilisateur en utilisant le framework shadcn/ui, qui fournit un processus de configuration basé sur CLI et une intégration transparente avec React et Nextjs, en exploitant les composants ajoutés en tant que code source au projet de l''utilisateur.","de":"Ermöglicht es den Agenten, die Entwicklung der Benutzeroberfläche zu rationalisieren, indem sie das shadcn/ui-Framework verwenden, das einen CLI-basierten Konfigurationsprozess und eine nahtlose Integration mit React und Nextjs bietet, wobei die als Quellcode zum Benutzerprojekt hinzugefügten Komponenten genutzt werden.","pt":"Habilita os agentes a agilizar o desenvolvimento de UI usando o framework shadcn/ui, fornecendo um processo de configuração impulsionado por CLI e integração sem problemas com React e Nextjs, aproveitando componentes adicionados como código-fonte ao projeto do usuário.","ru":"Наделяет агентов возможностью оптимизировать разработку UI с помощью фреймворка shadcn/ui, обеспечивая процесс настройки, управляемый CLI, и бесшовную интеграцию с React и Nextjs, используя компоненты, добавленные в виде исходного кода в проект пользователя.","ar":"تمكين الوكلاء من تسريع تطوير واجهة المستخدم باستخدام إطار شادسن/واي، وتوفير عملية إعداد مدفوعة بواسطة واجهة سطر الأوامر ودمجها بشكل متجانس مع رياكت ونكست جيه إس، واستخدام المكونات المضافة كкод مصدر لمشروع المستخدم."},"useCases":{"en":["Automating UI component generation with shadcn/ui","Building design systems with React and Nextjs using shadcn templates","Streamlining project setup with the shadcn CLI"],"zh":["使用 shadcn/ui 自动化 UI 组件生成","使用 shadcn 模板构建 React 和 Nextjs 的设计系统","使用 shadcn CLI 简化项目设置"],"ja":["shadcn/ui を使用した UI コンポーネントの自動生成","shadcn テンプレートを使用した React と Nextjs のデザイン システムの構築","shadcn CLI を使用したプロジェクト設定の簡素化"],"ko":["shadcn/ui를 사용한 UI 컴포넌트 자동 생성","shadcn 템플릿을 사용한 React와 Nextjs의 디자인 시스템 구축","shadcn CLI를 사용한 프로젝트 설정 단순화"],"es":["Automatizar la generación de componentes de interfaz de usuario con shadcn/ui","Crear sistemas de diseño con React y Nextjs utilizando plantillas de shadcn","Racionalizar la configuración del proyecto con la CLI de shadcn"],"fr":["Automatiser la génération de composants d''interface utilisateur avec shadcn/ui","Concevoir des systèmes de conception avec React et Nextjs en utilisant des modèles de shadcn","Rationaliser la configuration du projet avec la CLI de shadcn"],"de":["Automatisieren der Erstellung von Benutzeroberflächenkomponenten mit shadcn/ui","Erstellen von Designsystemen mit React und Nextjs unter Verwendung von shadcn-Vorlagen","Rationalisieren der Projektkonfiguration mit der shadcn-CLI"],"pt":["Automatizar a geração de componentes de UI com shadcn/ui","Construir sistemas de design com React e Nextjs usando modelos shadcn","Agilizar a configuração do projeto com o shadcn CLI"],"ru":["Автоматизировать генерацию компонентов UI с помощью shadcn/ui","Создавать системы дизайна с React и Nextjs, используя шаблоны shadcn","Оптимизировать настройку проекта с помощью shadcn CLI"],"ar":["التحكم الآلي في توليد مكونات واجهة المستخدم مع شادسن/واي","بناء أنظمة التصميم مع رياكت ونكست جيه إس باستخدام قوالب شادسن","تسريع إعداد المشروع مع شادسن سي إل آي"]},"limitations":{"en":["Requires project package runner (npx, pnpm, or bunx)","Specific to React and Nextjs ecosystems"],"zh":["需要项目包运行器 (npx, pnpm 或 bunx)","特定于 React 和 Nextjs 生态系统"],"ja":["プロジェクト パッケージ ランナー (npx, pnpm または bunx) が必要","React と Nextjs のエコシステムに特有"],"ko":["프로젝트 패키지 러너(npx, pnpm 또는 bunx)가 필요","React와 Nextjs의 에코시스템에 특정"],"es":["Requiere un ejecutor de paquetes de proyecto (npx, pnpm o bunx)","Específico para los ecosistemas de React y Nextjs"],"fr":["Nécessite un exécuteur de paquets de projet (npx, pnpm ou bunx)","Spécifique aux écosystèmes de React et Nextjs"],"de":["Benötigt einen Projektpaket-Ausführer (npx, pnpm oder bunx)","Spezifisch für die Ökosysteme von React und Nextjs"],"pt":["Exige um executador