INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AstroAir/react-quick-starter/shadcn', 'shadcn', 'AstroAir', 'react-quick-starter', 'community', 'shadcn AstroAir react-quick-starter community shadcn is a template for building UI components and design systems with React, Nextjs, and shadcn/ui. It benefits developers by providing a streamlined setup process using the CLI. Shadcn UI是一个用于构建UI组件和设计系统的框架，支持React、Nextjs、Zustand和Tailwindcss Shadcn AIエージェントは、UIコンポーネントとデザインシステムを構築するためのフレームワークで、React、Nextjs、Zustand、Tailwindcssをサポートしています Shadcn UI 템플릿은 UI 컴포넌트와 디자인 시스템을 구축하는 프레임워크로, React, Nextjs, Zustand, Tailwindcss를 지원합니다 shadcn es un framework para construir interfaces de usuario y componentes con React y Nextjs. Incluye zustand y tailwindcss shadcn est un framework pour construire des interfaces utilisateur et des composants avec React et Nextjs, incluant zustand et tailwindcss shadcn ist ein Framework für die Erstellung von Benutzeroberflächen und Komponenten mit React und Nextjs, einschließlich zustand und tailwindcss O Shadcn é um framework para construir interfaces de usuário personalizadas com React, Nextjs e Tailwindcss. Aprenda a configurá-lo para criar aplicações escaláveis Shadcn - это фреймворк для создания кастомных интерфейсов пользователя с помощью React, Nextjs и Tailwindcss. Узнайте, как настроить его для создания масштабируемых приложений для ИИ Агентов Shadcn هو إطار عمل لإنشاء واجهات مستخدم مخصصة باستخدام React و Nextjs و Tailwindcss. تعرف على كيفية إعدادها لإنشاء تطبيقات قابلة للتوسيع للأدوات الذكية how to use shadcn shadcn setup guide shadcn alternative shadcn vs react shadcn install what is shadcn shadcn ui components shadcn nextjs template Shadcn UI React UI框架 Nextjs UI组件 Zustand状态管理 Tailwindcss样式 CLI命令 npx shadcn@latest 包管理器 Utilizes shadcn/ui for building UI components and design systems Integrates with zustand for state management Supports tailwindcss for styling Provides a CLI for easy project setup and management using `npx shadcn@latest` Allows for customization via source code addition to the user''s project Ensures compatibility with various package managers, including pnpm and bun shadcn is a framework for building UI components and design systems, utilizing shadcn/ui, zustand, and tailwindcss for efficient development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('openclaw/skills/github-kb', 'community', 'openclaw', 'skills', 'openclaw/skills', 'github-kb', 0, 0, 45, '2026-03-08T01:57:15.264Z', '2026-03-08T01:59:41.761Z', '8d62830e2d00b0b63fe36620febd451b583dbcfad38acf354a1d77942401e303', '{"id":"openclaw/skills/github-kb","name":"github-kb","description":{"en":"The github-kb skill enables developers to manage a local GitHub knowledge base and provide GitHub search capabilities via the gh CLI. It benefits developers who need to catalog and search their projects efficiently.","zh":"github-kb技能提供GitHub本地知识库管理和搜索功能，支持gh CLI命令","ja":"github-kbスキルは、GitHubのローカルナレッジベース管理と検索機能を提供し、gh CLIコマンドをサポート","ko":"github-kb 스킬은 GitHub 지식库 관리와 검색 기능을 제공하며, gh CLI 명령어를 지원합니다","es":"github-kb es una herramienta que permite gestionar una base de conocimiento local y realizar búsquedas en GitHub mediante la CLI de gh. Configura tu entorno con tokens de acceso y directorios personalizados","fr":"github-kb est un outil qui permet de gérer une base de connaissances locale et d''effectuer des recherches sur GitHub via la CLI de gh. Configurez votre environnement avec des jetons d''accès et des répertoires personnalisés","de":"github-kb ist ein Tool, mit dem Sie ein lokales Wissensrepository verwalten und GitHub-Suchen über die gh-CLI durchführen können. Konfigurieren Sie Ihre Umgebung mit Zugriffstoken und benutzerdefinierten Verzeichnissen","pt":"O github-kb é uma ferramenta para gerenciar um conhecimento local e realizar pesquisas no GitHub via gh CLI. Configure o github-kb com tokens de acesso e caminhos de diretório.","ru":"github-kb - это инструмент для управления локальной базой знаний и поиска на GitHub через gh CLI. Настройте github-kb с токенами доступа и путями директории.","ar":"github-kb هو أداة لإدارة المعرفة المحلية والبحث في GitHub عبر واجهة سطر الأوامر gh. أعد github-kb مع رموز