INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ImGoodBai/goodable/pdf', 'pdf', 'ImGoodBai', 'goodable', 'community', 'pdf ImGoodBai goodable community The pdf skill enables developers to perform essential PDF processing operations using Python libraries like pypdf. It benefits AI agent developers and users who need to automate PDF tasks. 本指南介绍如何使用 Python 库和命令行工具进行 PDF 处理，包括读取和提取文本 AI エージェントを使用した PDF 処理の方法を紹介します。Python と JavaScript ライブラリの使用方法を確認 PDF 처리를 위한 Python 및 CLI 도구 사용 방법을 설명합니다 Goodable es un entorno de trabajo de IA de escritorio que permite procesar PDF con Python y herramientas de línea de comandos Goodable est un espace de travail d''IA de bureau qui permet de traiter les PDF avec Python et des outils de ligne de commande Goodable ist eine Desktop-IA-Arbeitsumgebung, die die Verarbeitung von PDF mit Python und Kommandozeilen-Tools ermöglicht O processamento de PDF é uma operação essencial que pode ser realizada com bibliotecas Python e ferramentas de linha de comando. Обработка PDF является важнейшей операцией, которую можно выполнить с помощью библиотек Python и командной строки. معالجة ملفات PDF هي عملية أساسية يمكن إجراؤها باستخدام مكتبات Python وأدوات سطر الأوامر. how to use pdf with python pdf processing with pypdf pdf alternative to acrobat pdf vs smallpdf pdf install guide pdf setup for ai agents what is pdf processing pdf automation with ai PDF 处理 Python PDF 库 命令行工具 PDF AI エージェント PDF PDF 文本提取 pypdf 库 PDF 处理最佳实践 Reads PDF files using pypdf''s PdfReader Extracts text from PDF pages Utilizes PdfWriter for PDF writing operations Supports command-line tools for advanced features Follows instructions from forms.md for filling out PDF forms pdf is a skill for processing PDF files using Python libraries and command-line tools, enabling tasks like reading and extracting text from PDF documents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rawwerks/rlm-cli/rlm', 'community', 'rawwerks', 'rlm-cli', 'rawwerks/rlm-cli', 'rlm', 0, 0, 45, '2026-03-08T01:57:15.271Z', '2026-03-08T02:00:13.773Z', 'd69e096ed158d6ff4516238286c74ac9412111b5463dc032292e91aaf179cb9e', '{"id":"rawwerks/rlm-cli/rlm","name":"rlm","description":{"en":"The rlm skill enables AI agents to handle large context by recursively decomposing inputs. It supports files, directories, URLs, and stdin, making it a valuable tool for developers.","zh":"RLM CLI 是一种命令行工具，实现递归语言模型，支持多种输入类型。通过设置 API 密钥，轻松扩展语言模型能力","ja":"RLM CLI は、再帰言語モデルを実現するコマンドラインツールです。様々な入力タイプをサポートし、API キーを設定することで言語モデル機能を拡張します","ko":"RLM CLI는 재귀 언어 모델을 구현하는 명령줄 도구로 여러 입력 유형을 지원하며 API 키를 설정하여 언어 모델 기능을 확장합니다","es":"RLM es una CLI para modelos de lenguaje recursivos que permite manejar contexto infinito","fr":"RLM est une CLI pour les modèles de langage récursifs qui permet de gérer un contexte infini","de":"RLM ist eine CLI für rekursive Sprachmodelle, die es ermöglicht, unendlichen Kontext zu verarbeiten","pt":"RLM é uma ferramenta de linha de comando para modelos de linguagem recursivos, permitindo que LLMs lidem com contextos quase infinitos","ru":"RLM - это инструмент командной строки для рекурсивных языковых моделей, позволяющий ИИ Агентам обрабатывать почти бесконечные контексты","ar":"RLM هو أداة سطر الأوامر للنماذج اللغوية التكرارية، مما يسمح للوكلاء الذكيين بالتعامل مع السياقات شبه 무حدودة"},"seo":{"title":{"en":"rlm: Recursive Language Models CLI Setup Guide | AI Agent...","zh":"RLM CLI 设置指南：递归语言模型命令行工具","ja":"RLM CLI セットアップガイド：再帰言語モデルコマンドラインツール","ko":"RLM CLI 설정 가이드: 재귀 언어 모델 명령줄 도구","es":"Guía de configuración de RLM: CLI para modelos de lenguaj...","fr":"Guide de configuration RLM : CLI pour les modèles de lang...","de":"RLM-Setup-Anleitung: CLI für rekursive Sprachmodelle","pt":"Guia de Configuração do RLM: CLI para Modelos de Linguage...","ru":"Настройка RLM: Инструмент командной строки для рекурсивны...","ar":"دليل إعداد RLM: واجهة سطر الأوامر للنماذج اللغوية التكرار..."},"description":{"en":"Unlock near-infinite context with rlm CLI. Learn how to install and use Recursive Language Models for AI agents. Get started now!","zh":"使用 RLM CLI 实现递归语言模型，支持文件、目录、URL 和 stdin 输入，轻松扩展语言模型能力","ja":"RLM CLI を使用して再帰言語モデルを実現し、ファイル、ディレクトリ、URL、stdin 入力をサポートして言語モデル機能を拡張します","ko":"RLM CLI를 사용하여 재귀 언어 모델을 구현하고 파일, 디렉토리, URL 및 stdin 입력을 지원하여 언어 모델 기능을 확장합니다","es":"Aprende a instalar y utilizar RLM, una CLI para modelos de lenguaje recursivos que manejan contexto infinito","fr":"Découvrez comment installer et utiliser RLM, une CLI pour les modèles de langage récursifs qui gèrent un contexte infini","de":"Erfahren Sie, wie Sie RLM installieren und verwenden, eine CLI für rekursive Sprachmodelle mit unendlichem Kontext","pt":"Aprenda a instalar e usar o RLM, uma ferramenta de linha de comando para modelos de linguagem recursivos, e descubra suas funcionalidades avançadas","ru":"Узнайте, как установить и использовать RLM, инструмент командной строки для рекурсивных языковых моделей, и откройте для себя его расширенные возможности","ar":"تعرف على كيفية تثبيت واستخدام RLM، أداة سطر الأوامر للنماذج اللغوية التكرارية، واكتشف ميزاتها المتقدمة"},"definition":{"en":"rlm is a CLI for Recursive Language Models, allowing LLMs to process vast amounts of data by breaking it down into smaller parts.","zh":"RLM CLI 是一种递归语言模型的命令行工具，用于扩展语言模型能力","ja":"RLM CLI は再帰言語モデルのコマンドラインツールであり、言語モデル機能を拡張するために使用されます","ko":"RLM CLI는 재귀 언어 모델의 명령줄 도구로 언어 모델 기능을 확장하는 데 사용됩니다","es":"RLM es una herramienta de línea de comandos para modelos de lenguaje recursivos","fr":"RLM est un outil de ligne de commande pour les modèles de langage récursifs","de":"RLM ist ein Kommandozeilen-Tool für rekursive Sprachmodelle","pt":"RLM é uma ferramenta de linha de comando que habilita modelos de linguagem recursivos para lidar com contextos quase infinitos","ru":"RLM - это инструмент командной строки, который позволяет рекурсивным языковым моделям обрабатывать почти бесконечные контексты","ar":"RLM هو أداة سطر الأوامر التي تمكن النماذج اللغوية التكرارية من التعامل مع السياقات شبه 무حدودة"},"features":{"en":["Supports files, directories, URLs, and stdin for flexible input handling","Recursive decomposition of inputs for near-infinite context","Installs via pip or pipx for easy setup","Compatible with OpenRouter and OpenAI backends","Allows setting API keys for secure backend connections","Runs without installation using uvx rlm-cli"],"zh":["支持文件、目录、URL 和 stdin 输入","递归语言模型实现","支持设置 API 密钥","支持 pip 安装","支持 pipx 安装"],"ja":["ファイル、ディレクトリ、URL、stdin 入力をサポート","再帰言語モデルを実現","API キーを設定する機能","pip インストールをサポート","pipx インストールをサポート"],"ko":["파일, 디렉토리, URL 및 stdin 입력 지원","재귀 언어 모델 구현","API 키 설정 지원","pip 설치 지원","pipx 설치 지원"],"es":["Soporte para archivos, directorios, URLs y entrada estándar","Instalación mediante pip o pipx","Compatibilidad con backends como OpenRouter y OpenAI","Decomposición recursiva de entradas para manejar contexto infinito","Uso de claves de API para autenticación en backends","Ejecución sin instalación mediante uvx"],"fr":["Prise en charge de fichiers, de répertoires, d''URL et d''entrée standard","Installation via pip ou pipx","Compatibilité avec les backends tels que OpenRouter et OpenAI","Décomposition récursive des entrées pour gérer un contexte infini","Utilisation de clés d''API pour l''authentification sur les backends","Exécution sans installation via uvx"],"de":["Unterstützung für Dateien, Verzeichnisse, URLs und Standard-Eingabe","Installation über pip oder pipx","Kompatibilität mit Backends wie OpenRouter und OpenAI","Rekursive Zerlegung von Eingaben für unendlichen Kontext","Verwendung von API-Schlüsseln für Authentifizierung auf Backends","Ausführung ohne Installation über uvx"],"pt":["Suporte a arquivos, diretórios, URLs e stdin","Instalação via pip ou pipx","Compatibilidade com backends como OpenRouter e OpenAI","Capacidade de lidar com contextos quase infinitos","Interface de linha de comando intuitiva"],"ru":["Поддержка файлов, директорий, URL и stdin","Установка через pip или pipx","Совместимость с бэкендами như OpenRouter и OpenAI","Способность обрабатывать почти бесконечные контексты","Интуитивно понятный интерфейс командной строки"],"ar":["دعم الملفات والمجلدات والروابط والمدخلات","التثبيت عبر pip أو pipx","التوافق مع الخوادم الخلفية مثل OpenRouter و OpenAI","القدرة على التعامل مع السياقات شبه 무حدودة","واجهة سطر الأوامر المتوافقة"]},"keywords":{"en":["how to use rlm","what is rlm","rlm alternative","rlm vs OpenAI","rlm install","rlm setup guide","recursive language models","llm context handling","pip install rlm-cli"],"zh":["RLM CLI","递归语言模型","命令行工具","语言模型","AI 工具","AI エージェント","自然语言处理","机器学习"],"ja":["RLM CLI","再帰言語モデル","コマンドラインツール","言語モデル","AI ツール","AI エージェント","自然言語処理","機械学習"],"ko":["RLM CLI","재귀 언어 모델","명령줄 도구","언어 모델","AI 도구","AI 에이전트","자연어 처리","기계 학습"],"es":["RLM","modelos de lenguaje recursivos","CLI","contexto infinito","OpenRouter","OpenAI","pip","pipx","uvx","herramientas de AI"],"fr":["RLM","modèles de langage récursifs","CLI","contexte infini","OpenRouter","OpenAI","pip","pipx","uvx","outils d''IA"],"de":["RLM","rekursive Sprachmodelle","CLI","unendlicher Kontext","OpenRouter","OpenAI","pip","pipx","uvx","KI-Tools"],"pt":["RLM","Modelos de linguagem recursivos","CLI","Linha de comando","Instalação","Configuração","Ferramentas de desenvolvimento","Desenvolvimento de software","Tecnologia de linguagem natural"],"ru":["RLM","Рекурсивные языковые модели","CLI","Командная строка","Установка","Настройка","Инструменты разработки","Разработка программного обеспечения","Технология обработки естественного языка"],"ar":["RLM","النماذج اللغوية التكرارية","CLI","سطر الأوامر","التثبيت","الإعداد","أدوات التطوير","تطوير البرمجيات","تكنولوجيا معالجة اللغة الطبيعية"]}},"owner":"rawwerks","repo":"rlm-cli","repoPath":"rawwerks/rlm-cli","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.271Z","topics":[],"category":"community","skillMd":{"name":"rlm","description":"Recursive Language Models (RLM) CLI - enables LLMs to recursively process large contexts by decomposing inputs and calling themselves over parts. Use for code analysis, diff reviews, codebase exploration. Triggers on rlm ask, rlm complete, rlm search, rlm index.","bodyPreview":"# RLM CLI\n\nRecursive Language Models (RLM) CLI - enables LLMs to handle near-infinite context by recursively decomposing inputs and calling themselves over parts. Supports files, directories, URLs, and stdin.\n\n## Installation\n\n```bash\npip install rlm-cli    # or: pipx install rlm-cli\nuvx rlm-cli ask ...    # run without installing\n```\n\nSet an API key for your backend (openrouter is default):\n```bash\nexport OPENROUTER_API_KEY=...  # default backend\nexport OPENAI_API_KEY=...      # for --backend o","body":"# RLM CLI\n\nRecursive Language Models (RLM) CLI - enables LLMs to handle near-infinite context by recursively decomposing inputs and calling themselves over parts. Supports files, directories, URLs, and stdin.\n\n## Installation\n\n```bash\npip install rlm-cli    # or: pipx install rlm-cli\nuvx rlm-cli ask ...    # run without installing\n```\n\nSet an API key for your backend (openrouter is default):\n```bash\nexport OPENROUTER_API_KEY=...  # default backend\nexport OPENAI_API_KEY=...      # for --backend openai\nexport ANTHROPIC_API_KEY=...   # for --backend anthropic\n```\n\n## Commands\n\n### ask - Query with context\n\n```bash\nrlm ask <inputs> -q \"question\"\n```\n\n**Inputs** (combinable):\n| Type | Example | Notes |\n|------|---------|-------|\n| Directory | `rlm ask . -q \"...\"` | Recursive, respects .gitignore |\n| File | `rlm ask main.py -q \"...\"` | Single file |\n| URL | `rlm ask https://x.com -q \"...\"` | Auto-converts to markdown |\n| stdin | `git diff \\| rlm ask - -q \"...\"` | `-` reads from pipe |\n| Literal | `rlm ask \"text\" -q \"...\" --literal` | Treat as raw text |\n| Multiple | `rlm ask a.py b.py -q \"...\"` | Combine any types |\n\n**Options:**\n| Flag | Description |\n|------|-------------|\n| `-q \"...\"` | Question/prompt (required) |\n| `--backend` | Provider: `openrouter` (default), `openai`, `anthropic` |\n| `--model NAME` | Model override (format: `provider/model` or just `model`) |\n| `--json` | Machine-readable output |\n| `--output-format` | Output format: `text`, `json`, or `json-tree` |\n| `--summary` | Show execution summary with depth statistics |\n| `--extensions .py .ts` | Filter by extension |\n| `--include/--exclude` | Glob patterns |\n| `--max-iterations N` | Limit REPL iterations (default: 30) |\n| `--max-depth N` | Recursive RLM depth (default: 1 = no recursion) |\n| `--max-budget N.NN` | Spending limit in USD (requires OpenRouter) |\n| `--max-timeout N` | Time limit in seconds |\n| `--max-tokens N` | Total token limit (input + output) |\n| `--max-errors N` | Consecutive error limit before stopping |\n| `--no-index` | Skip auto-indexing |\n| `--exa` | Enable Exa web search (requires `EXA_API_KEY`) |\n| `--inject-file FILE` | Execute Python code between iterations |\n\n**JSON output structure:**\n```json\n{\"ok\": true, \"exit_code\": 0, \"result\": {\"response\": \"...\"}, \"stats\": {...}}\n```\n\n**JSON-tree output (`--output-format=json-tree`):**\nAdds execution tree showing nested RLM calls:\n```json\n{\n  \"result\": {\n    \"response\": \"...\",\n    \"tree\": {\n      \"depth\": 0,\n      \"model\": \"openai/gpt-4\",\n      \"duration\": 2.3,\n      \"cost\": 0.05,\n      \"iterations\": [...],\n      \"children\": [...]\n    }\n  }\n}\n```\n\n**Summary output (`--summary`):**\nShows depth-wise statistics after completion:\n- JSON mode: adds `summary` field to `stats`\n- Text mode: prints summary to stderr\n\n```\n=== RLM Execution Summary ===\nTotal depth: 2 | Nodes: 3 | Cost: $0.0054 | Duration: 17.38s\nDepth 0: 1 call(s) ($0.0047, 13.94s)\nDepth 1: 2 call(s) ($0.0007, 3.44s)\n```\n\n### complete - Query without context\n\n```bash\nrlm complete \"prompt text\"\nrlm complete \"Generate SQL\" --json --backend openai\n```\n\n### search - Search indexed files\n\n```bash\nrlm search \"query\" [options]\n```\n\n| Flag | Description |\n|------|-------------|\n| `--limit N` | Max results (default: 20) |\n| `--language python` | Filter by language |\n| `--paths-only` | Output file paths only |\n| `--json` | JSON output |\n\nAuto-indexes on first use. Manual index: `rlm index .`\n\n### index - Build search index\n\n```bash\nrlm index .              # Index current dir\nrlm index ./src --force  # Force full reindex\n```\n\n### doctor - Check setup\n\n```bash\nrlm doctor       # Check config, API keys, deps\nrlm doctor --json\n```\n\n## Workflows\n\n**Git diff review:**\n```bash\ngit diff | rlm ask - -q \"Review for bugs\"\ngit diff --cached | rlm ask - -q \"Ready to commit?\"\ngit diff HEAD~3 | rlm ask - -q \"Summarize changes\"\n```\n\n**Codebase analysis:**\n```bash\nrlm ask . -q \"Explain architecture\"\nrlm ask src/ -q \"How does auth work?\" --extensions .py\n```\n\n**Search + analyze:**\n```bash\nrlm search \"database\" --paths-only\nrlm ask src/db.py -q \"How is connection pooling done?\"\n```\n\n**Compare files:**\n```bash\nrlm ask old.py new.py -q \"What changed?\"\n```\n\n## Configuration\n\n**Precedence:** CLI flags > env vars > config file > defaults\n\n**Config locations:** `./rlm.yaml`, `./.rlm.yaml`, `~/.config/rlm/config.yaml`\n\n```yaml\nbackend: openrouter\nmodel: google/gemini-3-flash-preview\nmax_iterations: 30\n```\n\n**Environment variables:**\n- `RLM_BACKEND` - Default backend\n- `RLM_MODEL` - Default model\n- `RLM_CONFIG` - Config file path\n- `RLM_JSON=1` - Always output JSON\n\n## Recursion and Budget Limits\n\n### Recursive RLM (`--max-depth`)\n\nEnable recursive `llm_query()` calls where child RLMs process sub-tasks:\n\n```bash\n# 2 levels of recursion\nrlm ask . -q \"Research thoroughly\" --max-depth 2\n\n# With budget cap\nrlm ask . -q \"Analyze codebase\" --max-depth 3 --max-budget 0.50\n```\n\n### Budget Control (`--max-budget`)\n\nLimit spending per completion. Raises `BudgetExceededError` when exceeded:\n\n```bash\n# Cap at $1.00\nrlm complete \"Complex task\" --max-budget 1.00\n\n# Very low budget (will likely exceed)\nrlm ask . -q \"Analyze everything\" --max-budget 0.001\n```\n\n**Requirements:** OpenRouter backend (returns cost data in responses).\n\n### Other Limits\n\n**Timeout (`--max-timeout`)** - Stop after N seconds:\n```bash\nrlm complete \"Complex task\" --max-timeout 30\n```\n\n**Token limit (`--max-tokens`)** - Stop after N total tokens:\n```bash\nrlm ask . -q \"Analyze\" --max-tokens 10000\n```\n\n**Error threshold (`--max-errors`)** - Stop after N consecutive code errors:\n```bash\nrlm complete \"Write code\" --max-errors 3\n```\n\n### Stop Conditions\n\nRLM execution stops when any of these occur:\n1. **Final answer** - LLM calls `FINAL_VAR(\"variable_name\")` with the NAME of a variable (as a string)\n2. **Max iterations** - Exceeds `--max-iterations` (exit code 0, graceful - forces final answer)\n\n**FINAL_VAR usage** (common mistake - pass variable NAME, not value):\n```python\n# CORRECT:\nresult = {\"answer\": \"hello\", \"score\": 42}\nFINAL_VAR(\"result\")  # pass the variable NAME as a string\n\n# WRONG:\nFINAL_VAR(result)  # passing the dict directly causes AttributeError\n```\n3. **Max budget exceeded** - Spending > `--max-budget` (exit code 20, error)\n4. **Max timeout exceeded** - Time > `--max-timeout` (exit code 20, error with partial answer)\n5. **Max tokens exceeded** - Tokens > `--max-tokens` (exit code 20, error with partial answer)\n6. **Max errors exceeded** - Consecutive errors > `--max-errors` (exit code 20, error with partial answer)\n7. **User cancellation** - Ctrl+C or SIGUSR1 (exit code 0, returns partial answer as success)\n8. **Max depth reached** - Child RLM at depth 0 cannot recurse further\n\n**Note on max iterations:** This is a soft limit. When exceeded, RLM prompts the LLM one more time to provide a final answer. Modern LLMs typically complete in 1-2 iterations.\n\n**Partial answers:** When timeout, tokens, or errors stop execution, the error includes `partial_answer` if any response was generated before stopping.\n\n**Early exit (Ctrl+C):** Pressing Ctrl+C (or sending SIGUSR1) returns the partial answer as success (exit code 0) with `early_exit: true` in the result.\n\n### Inject File (--inject-file)\n\nUpdate REPL variables mid-run by modifying an inject file:\n\n```bash\n# Create inject file\necho ''focus = \"authentication\"'' > inject.py\n\n# Run with inject file\nrlm ask . -q \"Analyze based on ''focus''\" --inject-file inject.py\n\n# In another terminal, update mid-run\necho ''focus = \"authorization\"'' > inject.py\n```\n\nThe file is checked before each iteration and executed if modified.\n\n## Exit Codes\n\n| Code | Meaning |\n|------|---------|\n| 0 | Success |\n| 2 | CLI usage error |\n| 10 | Input error (file not found) |\n| 11 | Config error (missing API key) |\n| 20 | Backend/API error (includes budget exceeded) |\n| 30 | Runtime error |\n| 40 | Index/search error |\n\n## LLM Search Tools\n\nWhen `rlm ask` runs on a directory, the LLM gets search tools:\n\n| Tool | Cost | Privacy | Use For |\n|------|------|---------|---------|\n| `rg.search()` | Free | Local | Exact patterns, function names, imports |\n| `tv.search()` | Free | Local | Topics, concepts, related files |\n| `exa.search()` | **$** | **API** | Web search (requires `--exa` flag) |\n| `pi.*` | **$$$** | **API** | Hierarchical PDF/document navigation |\n\n### Free Local Tools (auto-loaded)\n\n- **rg.search(pattern, paths, globs)** - ripgrep for exact patterns\n- **tv.search(query, limit)** - Tantivy BM25 for concepts\n\n### Exa Web Search (--exa flag, Costs Money)\n\n⚠️ **Opt-in**: Requires `--exa` flag and `EXA_API_KEY` environment variable.\n\n**Setup:**\n```bash\nexport EXA_API_KEY=...  # Get from https://exa.ai\n```\n\n**Usage in REPL:**\n```python\nfrom rlm_cli.tools_search import exa, web\n\n# Basic search\nresults = exa.search(query=\"Python async patterns\", limit=5)\nfor r in results:\n    print(f\"{r[''title'']}: {r[''url'']}\")\n\n# With highlights (relevant excerpts)\nresults = exa.search(\n    query=\"error handling best practices\",\n    limit=3,\n    include_highlights=True\n)\n\n# Semantic alias\nresults = web(query=\"machine learning tutorial\", limit=5)\n\n# Find similar pages\nresults = exa.find_similar(url=\"https://example.com/article\", limit=5)\n```\n\n**exa.search() parameters:**\n| Param | Default | Description |\n|-------|---------|-------------|\n| `query` | required | Search query |\n| `limit` | 10 | Max results |\n| `search_type` | \"auto\" | \"auto\", \"neural\", or \"keyword\" |\n| `include_domains` | None | Only these domains |\n| `exclude_domains` | None | Exclude these domains |\n| `include_text` | False | Include full page text |\n| `include_highlights` | True | Include relevant excerpts |\n| `category` | None | \"company\", \"research paper\", \"news\", etc. |\n\n**When to use exa.search() / web():**\n- Finding external documentation, tutorials, articles\n- Researching topics beyond the local codebase\n- Finding similar pages to a reference URL\n\n### PageIndex (pi.* - Opt-in, Costs Money)\n\n⚠️ **WARNING**: PageIndex sends document content to LLM APIs and costs money.\n\n**Only use when:**\n1. User explicitly requests document/PDF analysis\n2. Document has hierarchical structure (reports, manuals)\n3. User accepts cost/privacy tradeoffs\n\n**Prerequisites:**\n- `OPENROUTER_API_KEY` (or other backend key) must be set in environment\n- PageIndex submodule must be initialized\n- Run within rlm-cli''s virtual environment (has required dependencies)\n\n**Setup (REQUIRED before any pi.* operation):**\n```python\nimport sys\nsys.path.insert(0, \"/path/to/rlm-cli/rlm\")        # rlm submodule\nsys.path.insert(0, \"/path/to/rlm-cli/pageindex\")  # pageindex submodule\n\nfrom rlm.clients import get_client\nfrom rlm_cli.tools_pageindex import pi\n\n# Configure with existing rlm backend\nclient = get_client(backend=\"openrouter\", backend_kwargs={\"model_name\": \"google/gemini-2.0-flash-001\"})\npi.configure(client)\n```\n\n**Indexing (costs $$$):**\n```python\n# Build tree index - THIS COSTS MONEY (no caching, re-indexes each call)\ntree = pi.index(path=\"report.pdf\")\n# Returns: PITree object with doc_name, nodes, doc_description, raw\n```\n\n**Viewing structure (free after indexing):**\n```python\n# Display table of contents\nprint(pi.toc(tree))\n\n# Get section by node_id (IDs are \"0000\", \"0001\", \"0002\", etc.)\nsection = pi.get_section(tree, \"0003\")\n# Returns: PINode with title, node_id, start_index, end_index, summary, children\n# Returns: None if not found\n\nif section:\n    print(f\"{section.title}: pages {section.start_index}-{section.end_index}\")\n```\n\n**Finding node IDs:**\nNode IDs are assigned sequentially (\"0000\", \"0001\", ...) in tree traversal order.\nTo see all node IDs, access the raw tree structure:\n```python\nimport json\nprint(json.dumps(tree.raw[\"structure\"], indent=2))\n# Each node has: title, node_id, start_index, end_index\n```\n\n**pi.* API Reference:**\n| Method | Cost | Returns | Description |\n|--------|------|---------|-------------|\n| `pi.configure(client)` | Free | None | Set rlm backend (REQUIRED first) |\n| `pi.status()` | Free | dict | Check availability, config, warning |\n| `pi.index(path=str)` | $$$ | PITree | Build tree from PDF |\n| `pi.toc(tree, max_depth=3)` | Free | str | Formatted table of contents |\n| `pi.get_section(tree, node_id)` | Free | PINode or None | Get section by ID |\n| `pi.available()` | Free | bool | Check if PageIndex installed |\n| `pi.configured()` | Free | bool | Check if client configured |\n\n**PITree attributes:** `doc_name`, `nodes` (list of PINode), `doc_description`, `raw` (dict)\n**PINode attributes:** `title`, `node_id`, `start_index`, `end_index`, `summary` (may be None), `children` (may be None)\n\n**Notes:**\n- `summary` is only populated if `add_summaries=True` in `pi.index()`\n- `children` is None for leaf nodes (sections with no subsections)\n- `tree.raw[\"structure\"]` is a flat list; hierarchy is in PINode.children\n- PageIndex extracts document structure (TOC), not content. Use page numbers to locate sections in the original PDF.\n\n**Example output from pi.toc():**\n```\n📄 annual_report.pdf\n\n• Executive Summary (p.1-5)\n• Financial Overview (p.6-20)\n  • Revenue (p.6-10)\n  • Expenses (p.11-15)\n  • Projections (p.16-20)\n• Risk Factors (p.21-35)\n```\n"},"lastSynced":"2026-03-08T02:00:13.773Z","agentAnalysis":{"suitability":{"en":"Perfect for Advanced Language Agents needing recursive context handling for large inputs via CLI","zh":"非常适合需要递归上下文处理来处理大型输入的高级语言代理，尤其是通过CLI","ja":"高度な言語エージェントが大規模な入力をCLI経由で再帰的に処理する必要がある場合に最適","ko":"고급 언어 에이전트가 대형 입력을 위한 재귀적 컨텍스트 처리가 필요한 경우, 특히 CLI를 통해 처리하는 경우에 적합","es":"Perfecto para Agentes de Lenguaje Avanzados que necesitan manejo de contexto recursivo para entradas grandes a través de CLI","fr":"Parfait pour les Agents de Langage Avancés nécessitant un traitement de contexte récursif pour les entrées importantes via CLI","de":"Perfekt für fortgeschrittene Sprachagenten, die rekursives Kontext-Handling für große Eingaben über CLI benötigen","pt":"Perfeito para Agentes de Linguagem Avançados que necessitam de tratamento de contexto recursivo para grandes entradas via CLI","ru":"Идеально подходит для продвинутых языковых агентов, которым требуется рекурсивная обработка контекста для больших входных данных через CLI","ar":"مثالي للوكلاء اللغويين المتقدمين الذين يحتاجون إلى معالجة السياق التكراري لحجم الإدخال الكبير عبر واجهة سطر الأوامر"},"recommendation":{"en":"Empowers agents to handle near-infinite context by recursively decomposing inputs using Recursive Language Models (RLM), supporting files, directories, URLs, and stdin, with backends like OpenRouter and OpenAI","zh":"使得代理能够通过递归语言模型（RLM）递归分解输入来处理几乎无限的上下文，支持文件、目录、URL和stdin，并且支持OpenRouter和OpenAI等后端","ja":"エージェントが再帰言語モデル（RLM）を使用して入力を再帰的に分解し、ほぼ無限のコンテキストを処理できるようにし、ファイル、ディレクトリ、URL、stdinをサポートし、OpenRouterやOpenAIなどのバックエンドをサポート","ko":"에이전트가 재귀 언어 모델(RLM)을 사용하여 입력을 재귀적으로 분해하여 거의 무한한 컨텍스트를 처리할 수 있도록 하며, 파일, 디렉토리, URL, stdin을 지원하며 OpenRouter 및 OpenAI와 같은 백엔드를 지원","es":"Habilita a los agentes a manejar un contexto casi infinito descomponiendo las entradas de forma recursiva utilizando Modelos de Lenguaje Recursivos (RLM), soportando archivos, directorios, URLs y stdin, con backends como OpenRouter y OpenAI","fr":"Permet aux agents de gérer un contexte presque infini en décomposant les entrées de manière récursive à l''aide de Modèles de Langage Récurifs (RLM), en prenant en charge les fichiers, les répertoires, les URL et stdin, avec des backends tels que OpenRouter et OpenAI","de":"Ermächtigt Agenten, einen fast unendlichen Kontext zu verarbeiten, indem sie Eingaben mithilfe von Rekursiven Sprachmodellen (RLM) rekursiv zerlegen, und unterstützt Dateien, Verzeichnisse, URLs und stdin, mit Backends wie OpenRouter und OpenAI","pt":"Habilita os agentes a lidar com um contexto quase infinito decompondo recursivamente as entradas usando Modelos de Linguagem Recursivos (RLM), suportando arquivos, diretórios, URLs e stdin, com backends como OpenRouter e OpenAI","ru":"Позволяет агентам обрабатывать практически бесконечный контекст, рекурсивно разбивая входные данные с помощью рекурсивных языковых моделей (RLM), поддерживая файлы, каталоги, URL и stdin, с использованием бэкендов, таких как OpenRouter и OpenAI","ar":"تمكين الوكلاء من التعامل مع سياق تقريبًا لا نهائي عن طريق تحليل الإدخالات بشكل تكراري باستخدام نماذج اللغة التكرارية (RLM)، ودعم الملفات والملفات الموجودة والرابط والstdin، مع الخوادم الخلفية مثل OpenRouter وOpenAI"},"useCases":{"en":["Decomposing large text files for analysis","Processing recursive directory structures for data extraction","Handling stdin for real-time input processing"],"zh":["将大型文本文件分解以进行分析","处理递归目录结构以提取数据","处理stdin以进行实时输入处理"],"ja":["分析のために大規模なテキストファイルを分解する","データ抽出のために再帰的なディレクトリ構造を処理する","リアルタイム入力処理のためにstdinを処理する"],"ko":["분석을 위해 대형 텍스트 파일을 분해하는 것","데이터 추출을 위해 재귀적인 디렉토리 구조를 처리하는 것","실시간 입력 처리를 위해 stdin을 처리하는 것"],"es":["Descomponer archivos de texto grandes para análisis","Procesar estructuras de directorios recursivos para extracción de datos","Manejar stdin para procesamiento de entrada en tiempo real"],"fr":["Décomposer des fichiers de texte importants pour l''analyse","Traiter des structures de répertoires récursifs pour l''extraction de données","Gérer stdin pour le traitement d''entrée en temps réel"],"de":["Große Textdateien für die Analyse zerlegen","Rekursive Verzeichnisstrukturen für die Datenextraktion verarbeiten","Stdin für die Echtzeit-Eingabeverarbeitung handhaben"],"pt":["Decompor arquivos de texto grandes para análise","Processar estruturas de diretório recursivo para extração de dados","Tratar stdin para processamento de entrada em tempo real"],"ru":["Разбить большие текстовые файлы для анализа","Обрабатывать рекурсивные структуры каталогов для извлечения данных","Обрабатывать stdin для обработки входных данных в реальном времени"],"ar":["تجزئة الملفات النصية الكبيرة للتحليل","معالجة هياكل الدليل التكراري لاستخراج البيانات","معالجة stdin لمعالجة الإدخال في الوقت الفعلي"]},"limitations":{"en":["Requires OpenRouter or OpenAI API Key for backend functionality","Dependent on pip or pipx for installation"],"zh":["需要OpenRouter或OpenAI API密钥来实现后端功能","依赖于pip或pipx来安装"],"ja":["バックエンド機能を実現するためにOpenRouterまたはOpenAI APIキーが必要","インストールにpipまたはpipxに依存"],"ko":["백엔드 기능을 구현하기 위해 OpenRouter 또는 OpenAI API 키가 필요","설치에 pip 또는 pipx에 의존"],"es":["Requiere una clave de API de OpenRouter o OpenAI para la funcionalidad de backend","Depende de pip o pipx para la instalación"],"fr":["Nécessite une clé d''API OpenRouter ou OpenAI pour la fonctionnalité de backend","Dépend de pip ou pipx pour l''installation"],"de":["Benötigt einen OpenRouter- oder OpenAI-API-Schlüssel für die Backend-Funktionalität","Hängt von pip oder pipx für die Installation ab"],"pt":["Exige Chave de API OpenRouter ou OpenAI para funcionalidade de backend","Dependente de pip ou pipx para instalação"],"ru":["Требует ключ API OpenRouter или OpenAI для функциональности бэкенда","Зависит от pip или pipx для установки"],"ar":["يتطلب مفتاح API OpenRouter أو OpenAI للوظائف الخلفية","يعتمد على pip أو pipx للتثبيت"]},"version":4},"contentHash":"d69e096ed158d6ff4516238286c74ac9412111b5463dc032292e91aaf179cb9e","qualityScore":45}');
