INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rawwerks/rlm-cli/rlm', 'rlm', 'rawwerks', 'rlm-cli', 'community', 'rlm rawwerks rlm-cli community The rlm skill enables AI agents to handle large context by recursively decomposing inputs. It supports files, directories, URLs, and stdin, making it a valuable tool for developers. RLM CLI 是一种命令行工具，实现递归语言模型，支持多种输入类型。通过设置 API 密钥，轻松扩展语言模型能力 RLM CLI は、再帰言語モデルを実現するコマンドラインツールです。様々な入力タイプをサポートし、API キーを設定することで言語モデル機能を拡張します RLM CLI는 재귀 언어 모델을 구현하는 명령줄 도구로 여러 입력 유형을 지원하며 API 키를 설정하여 언어 모델 기능을 확장합니다 RLM es una CLI para modelos de lenguaje recursivos que permite manejar contexto infinito RLM est une CLI pour les modèles de langage récursifs qui permet de gérer un contexte infini RLM ist eine CLI für rekursive Sprachmodelle, die es ermöglicht, unendlichen Kontext zu verarbeiten RLM é uma ferramenta de linha de comando para modelos de linguagem recursivos, permitindo que LLMs lidem com contextos quase infinitos RLM - это инструмент командной строки для рекурсивных языковых моделей, позволяющий ИИ Агентам обрабатывать почти бесконечные контексты RLM هو أداة سطر الأوامر للنماذج اللغوية التكرارية، مما يسمح للوكلاء الذكيين بالتعامل مع السياقات شبه 무حدودة how to use rlm what is rlm rlm alternative rlm vs OpenAI rlm install rlm setup guide recursive language models llm context handling pip install rlm-cli RLM CLI 递归语言模型 命令行工具 语言模型 AI 工具 AI エージェント 自然语言处理 机器学习 Supports files, directories, URLs, and stdin for flexible input handling Recursive decomposition of inputs for near-infinite context Installs via pip or pipx for easy setup Compatible with OpenRouter and OpenAI backends Allows setting API keys for secure backend connections Runs without installation using uvx rlm-cli rlm is a CLI for Recursive Language Models, allowing LLMs to process vast amounts of data by breaking it down into smaller parts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('PrefectHQ/prefect-mcp-server/cli', 'community', 'PrefectHQ', 'prefect-mcp-server', 'PrefectHQ/prefect-mcp-server', 'cli', 0, 0, 45, '2026-03-08T01:57:15.271Z', '2026-03-08T02:00:14.502Z', '3b98f89e79940ef4d7811cfbf3a541531053d3cbeb343c210b37f770b1e49751', '{"id":"PrefectHQ/prefect-mcp-server/cli","name":"cli","description":{"en":"The cli skill provides a read-only Prefect MCP server, allowing AI agents to perform mutations using the CLI. It benefits developers who need to interact with the Prefect API.","zh":"Prefect CLI提供了与MCP服务器交互的方式，包括读取和写入操作。使用CLI可以执行流运行删除等操作","ja":"Prefect CLIはMCPサーバーとやり取りするための方法を提供します。読み取りと書き込み操作を実行できます","ko":"Prefect CLI는 MCP 서버와 상호 작용하는 방법을 제공하며 읽기 및 쓰기 작업을 수행할 수 있습니다","es":"La CLI de Prefect es utilizada para mutations y ofrece datos estructurados para reads. Utilice --no-prompt para uso no interactivo.","fr":"La CLI de Prefect est utilisée pour les mutations et offre des données structurées pour les lectures. Utilisez --no-prompt pour une utilisation non interactive.","de":"Die Prefect-CLI wird für Mutationen verwendet und bietet strukturierte Daten für Lektüren. Verwenden Sie --no-prompt für nicht interaktive Nutzung.","pt":"O CLI é uma ferramenta poderosa para interagir com o servidor MCP de forma não interativa","ru":"CLI - это мощный инструмент для взаимодействия с сервером MCP в неинтерактивном режиме","ar":"واجهة سطر الأوامر هي أداة قوية لالتقاط مع خادم MCP بطريقة غير تفاعلية"},"seo":{"title":{"en":"cli: Setup Guide for AI Agents | AI Agent Skill","zh":"CLI Setup Guide for Prefect MCP Server","ja":"Prefect MCPサーバーのCLIベストプラクティス","ko":"CLI 설정 가이드 for Prefect MCP 서버","es":"Guía de configuración de CLI para Agentes de IA","fr":"Guide de mise en route de la CLI pour les Outils d''IA","de":"Einrichtungsleitfaden für CLI bei KI-Agents","pt":"Guia de Configuração do CLI para Ferramentas de IA","ru":"Руководство по настройке CLI для ИИ Агентов","ar":"دليل إعداد واجهة سطر الأوامر للآليات الذكية"},"description":{"en":"Unlock the full potential of Prefect CLI for AI agents. Learn how to use --no-prompt flag and optimize your workflow with MCP tools.","zh":"了解如何使用CLI与Prefect MCP服务器交互，包括读取和写入操作","ja":"Prefect MCPサーバーとCLIを使用した読み取りと書き込みの方法を学ぶ","ko":"Prefect MCP 서버와의 상호 작용을 위한 CLI 사용법을 알아보세요","es":"Aprende a utilizar la CLI de Prefect con agentes de IA para mutations y reads de datos estructurados","fr":"Découvrez comment utiliser la CLI de Prefect avec des outils d''IA pour les mutations et les lectures de données structurées","de":"Erfahren Sie, wie Sie die Prefect-CLI mit KI-Agents für Mutationen und strukturierte Datenlektüren verwenden","pt":"Aprenda a usar o CLI com as ferramentas de IA para melhorar a eficiência do seu fluxo de trabalho","ru":"Узнайте, как использовать CLI с ИИ Агентами для повышения производительности вашего рабочего процесса","ar":"تعرف على كيفية استخدام واجهة سطر الأوامر مع الآليات الذكية لتحسين كفاءة سير عملك"},"definition":{"en":"cli is a command-line interface for interacting with the Prefect MCP server, designed for non-interactive agent use with features like --no-prompt flag.","zh":"CLI是Prefect的一种命令行接口，用于与MCP服务器交互","ja":"CLIはPrefectのコマンドラインインターフェイスで、MCPサーバーとやり取りするために使用される","ko":"CLI는 Prefect의 명령줄 인터페이스로서 MCP 서버와 상호 작용하는 데 사용됩니다","es":"La CLI es una interfaz de línea de comandos para interactuar con el servidor Prefect MCP","fr":"La CLI est une interface en ligne de commande pour interagir avec le serveur Prefect MCP","de":"Die CLI ist eine Befehlszeilenoberfläche zur Interaktion mit dem Prefect-MCP-Server","pt":"O que é CLI: uma interface de linha de comando para interagir com o servidor MCP","ru":"Что такое CLI: интерфейс командной строки для взаимодействия с сервером MCP","ar":"ما هي واجهة سطر الأوامر: واجهة سطر أوامر لالتقاط مع خادم MCP"},"features":{"en":["Uses --no-prompt flag to disable confirmations for non-interactive agent use","Supports structured JSON output with full UUIDs using MCP tools","Allows mutations using the CLI, such as flow-run delete","Prefers MCP tools for reads, like get_flow_runs and get_deployments","Provides an alternative to prefect api for specific use cases"],"zh":["支持读取操作，例如获取流运行和部署","支持写入操作，例如流运行删除","使用--no-prompt标志禁用交互式提示","与MCP工具结合使用，返回结构化JSON数据","支持非交互式使用，例如agent-friendly模式"],"ja":["読み取り操作のサポート、たとえばフロー実行とデプロイの取得","書き込み操作のサポート、たとえばフロー実行の削除","--no-promptフラグを使用してインタラクティブなプロンプトを無効にする","MCPツールとの組み合わせ、構造化されたJSONデータの返却","非インタラクティブな使用のサポート、たとえばエージェントに優しいモード"],"ko":["읽기 작업 지원, 예: 흐름 실행 및 배포 가져오기","쓰기 작업 지원, 예: 흐름 실행 삭제","--no-prompt 플래그 사용하여 상호 작용형 프롬프트 비활성화","MCP 도구와의 조합, 구조화된 JSON 데이터 반환","비 상호 작용 사용 지원, 예: 에이전트 친화적 모드"],"es":["Soporte para mutations mediante la CLI","Lecturas de datos estructurados con MCP","Uso de --no-prompt para agentes de IA","Compatibilidad con comandos de Prefect API","Ejecución de comandos en modo no interactivo"],"fr":["Prise en charge des mutations via la CLI","Lectures de données structurées avec MCP","Utilisation de --no-prompt pour les outils d''IA","Compatibilité avec les commandes de l''API Prefect","Exécution de commandes en mode non interactif"],"de":["Unterstützung für Mutationen über die CLI","Lektüren von strukturierten Daten mit MCP","Verwendung von --no-prompt für KI-Agents","Kompatibilität mit Prefect-API-Befehlen","Ausführung von Befehlen im nicht interaktiven Modus"],"pt":["Suporte a comandos não interativos","Uso de --no-prompt para desabilitar confirmações","Integração com o servidor MCP","Retorno de JSON estruturado com UUIDs completos","Comandos como flow-run delete e get_flow_runs"],"ru":["Поддержка неинтерактивных команд","Использование --no-prompt для отключения подтверждений","Интеграция с сервером MCP","Возвращение структурированного JSON с полными UUID","Команды как flow-run delete и get_flow_runs"],"ar":["دعم الأوامر غير التفاعلية","استخدام --no-prompt لتعطيل التأكيدات","التكامل مع خادم MCP","إرجاع JSON منظم مع UUIDs كاملة","أوامر مثل flow-run delete و get_flow_runs"]},"keywords":{"en":["how to use cli with Prefect","cli vs prefect api","cli setup guide for AI agents","what is cli in Prefect","cli alternative for MCP server","installing cli for non-interactive use","cli best practices for AI agents","cli tutorial for developers","cli and MCP tools comparison"],"zh":["Prefect CLI","MCP服务器","命令行接口","读取操作","写入操作","AI工具","AIエージェント","CLI设置","Prefect MCP"],"ja":["Prefect CLI","MCPサーバー","コマンドラインインターフェイス","読み取り操作","書き込み操作","AIエージェント","CLI設定","Prefect MCP","エージェントに優しいモード"],"ko":["Prefect CLI","MCP 서버","명령줄 인터페이스","읽기 작업","쓰기 작업","AI 도구","AI 에이전트","CLI 설정","Prefect MCP","에이전트 친화적 모드"],"es":["CLI de Prefect","Agentes de IA","Mutaciones en Prefect","Lecturas de datos estructurados","Uso de --no-prompt","Prefect API","Herramientas de IA","Desarrollo de software","Automatización de tareas"],"fr":["CLI de Prefect","Outils d''IA","Mutations dans Prefect","Lectures de données structurées","Utilisation de --no-prompt","API Prefect","Développement de logiciels","Automatisation de tâches","Intégration de systèmes"],"de":["Prefect-CLI","KI-Agents","Mutationen in Prefect","Lektüren von strukturierten Daten","Verwendung von --no-prompt","Prefect-API","Software-Entwicklung","Automatisierung von Aufgaben","Systemintegration"],"pt":["CLI para ferramentas de IA","Guia de configuração do CLI","Usando o CLI com MCP","Comandos não interativos","JSON estruturado","UUIDs completos"],"ru":["CLI для ИИ Агентов","Руководство по настройке CLI","Использование CLI с MCP","Неинтерактивные команды","Структурированный JSON","Полные UUID"],"ar":["واجهة سطر الأوامر للآليات الذكية","دليل إعداد واجهة سطر الأوامر","استخدام واجهة سطر الأوامر مع MCP","أوامر غير تفاعلية","JSON منظم","UUIDs كاملة"]}},"owner":"PrefectHQ","repo":"prefect-mcp-server","repoPath":"PrefectHQ/prefect-mcp-server","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.271Z","topics":[],"category":"community","skillMd":{"name":"cli","description":"Prefect CLI commands for mutations. The MCP server is read-only - use this skill when you need to trigger deployments, cancel flow runs, create automations, or modify Prefect resources.","bodyPreview":"# Prefect CLI\n\nThe MCP server is read-only. For mutations, use the CLI.\n\n**Prefer MCP tools for reads** (e.g., `get_flow_runs`, `get_deployments`). They return structured JSON with full UUIDs. Use `prefect api` only if MCP doesn''t expose what you need.\n\n## Critical: Agent-Friendly Usage\n\nThe CLI is designed for interactive terminal use. For non-interactive (agent) use:\n\n```bash\n# ALWAYS use --no-prompt as a TOP-LEVEL flag to disable confirmations\nprefect --no-prompt flow-run delete <uuid>\nprefec","body":"# Prefect CLI\n\nThe MCP server is read-only. For mutations, use the CLI.\n\n**Prefer MCP tools for reads** (e.g., `get_flow_runs`, `get_deployments`). They return structured JSON with full UUIDs. Use `prefect api` only if MCP doesn''t expose what you need.\n\n## Critical: Agent-Friendly Usage\n\nThe CLI is designed for interactive terminal use. For non-interactive (agent) use:\n\n```bash\n# ALWAYS use --no-prompt as a TOP-LEVEL flag to disable confirmations\nprefect --no-prompt flow-run delete <uuid>\nprefect --no-prompt deployment delete <name>\n```\n\n### Avoiding Truncated Output\n\nRich table output truncates IDs and names, making them useless. Solutions:\n\n```bash\n# Use `prefect api` for raw JSON (preferred for agents)\nprefect api POST /flow_runs/filter --data ''{\"limit\": 5}''\n\n# Use inspect with -o json for single resources\nprefect flow-run inspect <uuid> -o json\nprefect deployment inspect <name> -o json\n```\n\n### IDs Must Be Complete UUIDs\n\nPartial IDs don''t work. Always get full UUIDs from JSON output:\n\n```bash\n# Get full flow run ID\nprefect api POST /flow_runs/filter --data ''{\"limit\": 1}'' | jq -r ''.[0].id''\n```\n\n## Common Mutations\n\n| Task | Command |\n|------|---------|\n| Trigger deployment | `prefect deployment run ''flow-name/deployment-name''` |\n| Trigger by ID | `prefect deployment run --id <deployment-uuid>` |\n| Cancel flow run | `prefect --no-prompt flow-run cancel <uuid>` |\n| Delete flow run | `prefect --no-prompt flow-run delete <uuid>` |\n| Delete deployment | `prefect --no-prompt deployment delete <name>` |\n\n## Direct API Access\n\n`prefect api` gives full API access with JSON output:\n\n```bash\n# List flow runs (with filters)\nprefect api POST /flow_runs/filter --data ''{\"limit\": 10}''\n\n# Filter by state\nprefect api POST /flow_runs/filter --data ''{\"flow_runs\": {\"state\": {\"type\": {\"any_\": [\"FAILED\"]}}}}''\n\n# Delete a flow run\nprefect api DELETE /flow_runs/<uuid>\n\n# Cancel a flow run\nprefect api POST /flow_runs/<uuid>/set_state --data ''{\"state\": {\"type\": \"CANCELLING\"}}''\n```\n\n## Automation Creation\n\nCreate from JSON string (inline):\n\n```bash\nprefect automation create --from-json ''{\n  \"name\": \"notify-on-failure\",\n  \"trigger\": {\n    \"posture\": \"Reactive\",\n    \"expect\": [\"prefect.flow-run.Failed\"],\n    \"match\": {\"prefect.resource.id\": \"prefect.flow-run.*\"}\n  },\n  \"actions\": [{\"type\": \"send-notification\", ...}]\n}''\n```\n\nOr from file:\n\n```bash\nprefect automation create --from-file automation.yaml\n```\n\nUse `get_automations()` from the MCP server to inspect existing automation schemas.\n\n## Efficient Inspection\n\nThe `get_flow_runs` tool returns summarized data to save tokens:\n- It omits full deployment and work pool schemas.\n- If you see a \"Late\" run or need concurrency details, follow up with:\n  - `get_work_pools(filter={\"name\": ...})`\n  - `get_deployments(filter={\"id\": ...})`\n  - `get_dashboard()`\n\n<!-- ref: https://github.com/pydantic/pydantic-ai/pull/3780 -->\n"},"lastSynced":"2026-03-08T02:00:14.502Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring advanced Prefect API interactions and automation via the command-line interface.","zh":"适用于需要高级Prefect API交互和通过命令行界面自动化的DevOps代理。","ja":"DevOpsエージェントが高度なPrefect APIの相互作用とコマンドラインインターフェースを介した自動化を必要とする場合に適しています。","ko":"고급 Prefect API 상호 작용 및 명령줄 인터페이스를 통한 자동화가 필요한 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren interacciones avanzadas con la API de Prefect y automatización a través de la interfaz de línea de comandos.","fr":"Idéal pour les agents DevOps nécessitant des interactions avancées avec l''API Prefect et une automatisation via l''interface de ligne de commande.","de":"Ideal für DevOps-Agents, die erweiterte Interaktionen mit der Prefect-API und Automatisierung über die Kommandozeilenoberfläche erfordern.","pt":"Ideal para agentes DevOps que exigem interações avançadas com a API Prefect e automação via interface de linha de comando.","ru":"Идеально подходит для агентов DevOps, требующих расширенного взаимодействия с API Prefect и автоматизации через командную строку.","ar":"مثالي لعميل DevOps الذين يتطلبون تفاعلات متقدمة مع واجهة برمجة تطبيقات Prefect وتitomation عبر واجهة سطر الأوامر."},"recommendation":{"en":"Empowers agents to perform mutations using the Prefect CLI, providing structured JSON output with full UUIDs for seamless integration, and utilizing `prefect api` for operations not exposed by MCP tools, all while ensuring non-interactive use with the `--no-prompt` flag.","zh":"赋予代理使用Prefect CLI执行变异的能力，提供带有完整UUID的结构化JSON输出，以实现无缝集成，并使用`prefect api`执行MCP工具未暴露的操作，同时使用`--no-prompt`标志确保非交互式使用。","ja":"エージェントがPrefect CLIを使用してミューテーションを実行できるようにし、完全なUUIDを含む構造化されたJSON出力を提供してシームレスな統合を実現し、`prefect api`を使用してMCPツールによって公開されていない操作を実行し、`--no-prompt`フラグを使用して非対話式使用を確保します。","ko":"에이전트가 Prefect CLI를 사용하여 변이를 수행할 수 있는 기능을 제공하고, 완전한 UUID가 포함된 구조화된 JSON 출력을 제공하여 무제한 통합을 제공하며, `prefect api`를 사용하여 MCP 도구에서 노출되지 않는 작업을 수행하고, `--no-prompt` 플래그를 사용하여 비대화식 사용을 보장합니다.","es":"Habilita a los agentes a realizar mutaciones utilizando la CLI de Prefect, proporcionando una salida JSON estructurada con UUID completos para una integración perfecta, y utilizando `prefect api` para operaciones no expuestas por las herramientas MCP, todo mientras se garantiza un uso no interactivo con la bandera `--no-prompt`.","fr":"Permet aux agents d''effectuer des mutations en utilisant la CLI Prefect, en fournissant une sortie JSON structurée avec des UUID complets pour une intégration transparente, et en utilisant `prefect api` pour les opérations non exposées par les outils MCP, le tout en garantissant une utilisation non interactive avec le drapeau `--no-prompt`.","de":"Ermächtigt die Agenten, Mutationen mithilfe der Prefect-CLI durchzuführen, indem sie eine strukturierte JSON-Ausgabe mit vollständigen UUIDs für eine nahtlose Integration bereitstellen und `prefect api` für Operationen verwenden, die nicht von den MCP-Tools exponiert werden, während sie gleichzeitig einen nicht interaktiven Gebrauch mit der `--no-prompt`-Flag garantieren.","pt":"Habilita agentes a realizar mutações usando o Prefect CLI, fornecendo saída JSON estruturada com UUIDs completos para integração transparente, e utilizando `prefect api` para operações não expostas por ferramentas MCP, garantindo uso não interativo com a flag `--no-prompt`.","ru":"Предоставляет агентам возможность выполнять мутации с помощью Prefect CLI, обеспечивая структурированный JSON-выход с полными UUID для бесшовной интеграции, и использует `prefect api` для операций, не экспонируемых инструментами MCP, при этом гарантируя неинтерактивное использование с флагом `--no-prompt`.","ar":"يعزز الوكلاء للقيام بالتحولات باستخدام Prefect CLI ، مع تقديم مخرجات JSON منظمة مع UUIDs كاملة للتكامل السلس ، واستخدام `prefect api` للأوبرة غير معروضة بواسطة أدوات MCP ، مع الحفاظ على الاستخدام غير التفاعلي مع العلم `--no-prompt`."},"useCases":{"en":["Automating flow run deletions using `prefect flow-run delete <uuid>`","Generating deployments and flow runs data using `prefect api` and MCP tools","Debugging Prefect workflows by leveraging the Prefect CLI for detailed output and error handling"],"zh":["使用`prefect flow-run delete <uuid>`自动化流程运行删除","使用`prefect api`和MCP工具生成部署和流程运行数据","通过使用Prefect CLI获取详细输出和错误处理来调试Prefect工作流"],"ja":["エージェントが`prefect flow-run delete <uuid>`を使用してフローラン削除の自動化を実行します","`prefect api`とMCPツールを使用してデプロイとフローランデータを生成する","Prefect CLIを使用して詳細な出力とエラー処理を取得してPrefectワークフローをデバッグする"],"ko":["`prefect flow-run delete <uuid>`를 사용하여 흐름 실행 삭제를 자동화합니다.","`prefect api`와 MCP 도구를 사용하여 배포 및 흐름 실행 데이터를 생성합니다.","Prefect CLI를 사용하여 자세한 출력 및 오류 처리를 활용하여 Prefect 워크플로우를 디버깅합니다."],"es":["Automatización de eliminaciones de ejecuciones de flujo mediante `prefect flow-run delete <uuid>`","Generación de implementaciones y datos de ejecuciones de flujo mediante `prefect api` y herramientas MCP","Depuración de flujos de trabajo de Prefect mediante la utilización de la CLI de Prefect para una salida detallada y el manejo de errores"],"fr":["Automatisation des suppressions d''exécutions de flux à l''aide de `prefect flow-run delete <uuid>`","Génération de déploiements et de données d''exécution de flux à l''aide de `prefect api` et d''outils MCP","Débogage des flux de travail Prefect en utilisant la CLI Prefect pour une sortie détaillée et la gestion des erreurs"],"de":["Automatisierung von Flusslauf-Löschungen mithilfe von `prefect flow-run delete <uuid>`","Generierung von Deployments und Flusslauf-Daten mithilfe von `prefect api` und MCP-Tools","Fehlerbehebung von Prefect-Workflows durch die Verwendung der Prefect-CLI für detaillierte Ausgaben und Fehlerbehandlung"],"pt":["Automatizar exclusões de execuções de fluxo usando `prefect flow-run delete <uuid>`","Gerar implantações e dados de execução de fluxo usando `prefect api` e ferramentas MCP","Depurar fluxos de trabalho Prefect aproveitando o Prefect CLI para saída detalhada e tratamento de erros"],"ru":["Автоматизировать удаление запусков потока с помощью `prefect flow-run delete <uuid>`","Генерировать развертывания и данные о запусках потока с помощью `prefect api` и инструментов MCP","Отлаживать рабочие потоки Prefect, используя Prefect CLI для подробного вывода и обработки ошибок"],"ar":["تأتمة حذف عمليات تشغيل تدفق باستخدام `prefect flow-run delete <uuid>`","إنتاج عمليات النشر وبيانات تشغيل التدفق باستخدام `prefect api` وأدوات MCP","تصحيح أخطاء تدفقات العمل Prefect من خلال استخدام Prefect CLI для الإخراج المفصل ومعالجة الأخطاء"]},"limitations":{"en":["Requires Prefect MCP server access","Designed for non-interactive use with `--no-prompt` flag","MCP tools preferred for read operations due to structured JSON output"],"zh":["需要Prefect MCP服务器访问","设计为使用`--no-prompt`标志的非交互式使用","由于结构化JSON输出，MCP工具更适合读取操作"],"ja":["Prefect MCPサーバーへのアクセスが必要です","`--no-prompt`フラグを使用して非対話式使用を設計しました","構造化されたJSON出力があるため、MCPツールは読み取り操作に適しています"],"ko":["Prefect MCP 서버 액세스가 필요합니다.","`--no-prompt` 플래그를 사용하여 비대화식 사용으로 설계되었습니다.","구조화된 JSON 출력이 있으므로 MCP 도구를 사용하여 읽기 작업을 수행하는 것이 좋습니다."],"es":["Requiere acceso al servidor Prefect MCP","Diseñado para uso no interactivo con la bandera `--no-prompt`","Las herramientas MCP son preferidas para operaciones de lectura debido a la salida JSON estructurada"],"fr":["Nécessite un accès au serveur Prefect MCP","Conçu pour une utilisation non interactive avec le drapeau `--no-prompt`","Les outils MCP sont préférés pour les opérations de lecture en raison de la sortie JSON structurée"],"de":["Erfordert Zugriff auf den Prefect-MCP-Server","Für nicht interaktive Verwendung mit der `--no-prompt`-Flag konzipiert","MCP-Tools werden für Leseoperationen aufgrund der strukturierten JSON-Ausgabe bevorzugt"],"pt":["Exige acesso ao servidor Prefect MCP","Projetado para uso não interativo com a flag `--no-prompt`","Ferramentas MCP preferidas para operações de leitura devido à saída JSON estruturada"],"ru":["Требует доступа к серверу Prefect MCP","Предназначен для неинтерактивного использования с флагом `--no-prompt`","Инструменты MCP предпочтительны для операций чтения из-за структурированного JSON-выхода"],"ar":["يتطلب الوصول إلى خادم Prefect MCP","تم تصميمه للاستخدام غير التفاعلي مع العلم `--no-prompt`","أدوات MCP مفضلة لعمليات القراءة بسبب الإخراج JSON المنظم"]},"version":4},"contentHash":"3b98f89e79940ef4d7811cfbf3a541531053d3cbeb343c210b37f770b1e49751","qualityScore":45}');
