INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('PrefectHQ/prefect-mcp-server/cli', 'cli', 'PrefectHQ', 'prefect-mcp-server', 'community', 'cli PrefectHQ prefect-mcp-server community The cli skill provides a read-only Prefect MCP server, allowing AI agents to perform mutations using the CLI. It benefits developers who need to interact with the Prefect API. Prefect CLI提供了与MCP服务器交互的方式，包括读取和写入操作。使用CLI可以执行流运行删除等操作 Prefect CLIはMCPサーバーとやり取りするための方法を提供します。読み取りと書き込み操作を実行できます Prefect CLI는 MCP 서버와 상호 작용하는 방법을 제공하며 읽기 및 쓰기 작업을 수행할 수 있습니다 La CLI de Prefect es utilizada para mutations y ofrece datos estructurados para reads. Utilice --no-prompt para uso no interactivo. La CLI de Prefect est utilisée pour les mutations et offre des données structurées pour les lectures. Utilisez --no-prompt pour une utilisation non interactive. Die Prefect-CLI wird für Mutationen verwendet und bietet strukturierte Daten für Lektüren. Verwenden Sie --no-prompt für nicht interaktive Nutzung. O CLI é uma ferramenta poderosa para interagir com o servidor MCP de forma não interativa CLI - это мощный инструмент для взаимодействия с сервером MCP в неинтерактивном режиме واجهة سطر الأوامر هي أداة قوية لالتقاط مع خادم MCP بطريقة غير تفاعلية how to use cli with Prefect cli vs prefect api cli setup guide for AI agents what is cli in Prefect cli alternative for MCP server installing cli for non-interactive use cli best practices for AI agents cli tutorial for developers cli and MCP tools comparison Prefect CLI MCP服务器 命令行接口 读取操作 写入操作 AI工具 AIエージェント CLI设置 Prefect MCP Uses --no-prompt flag to disable confirmations for non-interactive agent use Supports structured JSON output with full UUIDs using MCP tools Allows mutations using the CLI, such as flow-run delete Prefers MCP tools for reads, like get_flow_runs and get_deployments Provides an alternative to prefect api for specific use cases cli is a command-line interface for interacting with the Prefect MCP server, designed for non-interactive agent use with features like --no-prompt flag.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('czlonkowski/n8n-skills/n8n-mcp-tools-expert', 'community', 'czlonkowski', 'n8n-skills', 'czlonkowski/n8n-skills', 'n8n-mcp-tools-expert', 0, 0, 45, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:32.511Z', 'abb7737f1ef3e7087c840b8bb8c1e5315414a7fb503c539c6b117e79852c2114', '{"id":"czlonkowski/n8n-skills/n8n-mcp-tools-expert","name":"n8n-mcp-tools-expert","description":{"en":"The n8n-mcp-tools-expert skillset enables developers to build flawless n8n workflows using tools like Node Discovery and Configuration Validation. Ideal for AI agents and workflow automation experts.","zh":"n8n-mcp-tools-expert 是一个用于构建无缝的 n8n 工作流的技能，提供工具分类、节点发现和工作流管理等功能","ja":"n8n-mcp-tools-expert は、無欠の n8n ワークフローを構築するためのスキルです。ツールのカテゴリ、ノードの検出、ワークフローの管理などを提供します","ko":"n8n-mcp-tools-expert는 완벽한 n8n 워크플ロー 구축을 위한 스킬입니다. 도구 분류, 노드 검색 및 워크플로 관리 등을 제공합니다","es":"El skill n8n-mcp-tools-expert proporciona una guía maestra para utilizar herramientas de servidor MCP de n8n para crear flujos de trabajo","fr":"Le skill n8n-mcp-tools-expert fournit un guide maître pour utiliser les outils de serveur MCP de n8n pour créer des flux de travail","de":"Der Skill n8n-mcp-tools-expert bietet einen Master-Leitfaden für die Verwendung von n8n-MCP-Server-Tools zur Erstellung von Workflows","pt":"O n8n-mcp-tools-expert é um skillset para Claude Code que permite criar fluxos de trabalho perfeitos com n8n. Inclui ferramentas como Node Discovery e Configuration Validation.","ru":"n8n-mcp-tools-expert - это набор навыков для Claude Code, который позволяет создавать идеальные рабочие процессы с помощью n8n. Включает в себя инструменты, такие как Node Discovery и Configuration Validation.","ar":"n8n-mcp-tools-expert هو مجموعة من المهارات ل Claude Code التي تمكن من إنشاء سير عمل مثالية مع n8n. يتضمن أدوات مثل اكتشاف العقد و التحقق من الصحة"},"seo":{"title":{"en":"n8n-mcp-tools-expert: Master Guide for AI Agents | AI Age...","zh":"n8n-mcp-tools-expert 工作流设置指南","ja":"n8n-mcp-tools-expert ワークフロー構築ベストプラクティス","ko":"n8n-mcp-tools-expert 워크플ロー 구축 가이드","es":"Guía de configuración para n8n-mcp-tools-expert","fr":"Guide de mise en place pour n8n-mcp-tools-expert","de":"Einrichtungsleitfaden für n8n-mcp-tools-expert","pt":"Guia de Configuração n8n-mcp-tools-expert: Melhores Práticas","ru":"Настройка n8n-mcp-tools-expert: Руководство по ИИ Агентам","ar":"دليل إعداد n8n-mcp-tools-expert: أدوات ذكاء اصطناعي"},"description":{"en":"Unlock the full potential of n8n-mcp-tools-expert with our expert guide. Learn how to build flawless workflows and discover the power of Node Discovery, Conf...","zh":"使用 n8n-mcp-tools-expert 构建无缝的 n8n 工作流，了解工具分类、节点发现和工作流管理","ja":"n8n-mcp-tools-expert を使用して無欠の n8n ワークフローを構築する方法を学びましょう。ツールのカテゴリ、ノードの検出、ワークフローの管理について","ko":"n8n-mcp-tools-expert를 사용하여 완벽한 n8n 워크플ロー 구축 방법을 알아보세요. 도구 분류, 노드 검색 및 워크플로 관리에 대해","es":"Aprende a utilizar n8n-mcp-tools-expert para crear flujos de trabajo perfectos con herramientas de categorías como Node Discovery y Configuration Validation","fr":"Découvrez comment utiliser n8n-mcp-tools-expert pour créer des flux de travail parfaits avec des outils de catégories comme Node Discovery et Configuration V...","de":"Erfahren Sie, wie Sie n8n-mcp-tools-expert verwenden, um perfekte Workflows mit Tools aus Kategorien wie Node Discovery und Configuration Validation zu erste...","pt":"Aprenda a configurar o n8n-mcp-tools-expert para criar fluxos de trabalho perfeitos com Node Discovery, Configuration Validation e mais","ru":"Узнайте, как настроить n8n-mcp-tools-expert для создания идеальных рабочих процессов с помощью Node Discovery, Configuration Validation и других инструментов...","ar":"تعلم كيفية إعداد n8n-mcp-tools-expert لإنشاء سير عمل مثالية مع اكتشاف العقد و التحقق من الصحة و المزيد من أدوات الوكلاء الذكية"},"definition":{"en":"n8n-mcp-tools-expert is a skillset for building n8n workflows using a range of tools, including Node Discovery, Configuration Validation, and Workflow Management.","zh":"n8n-mcp-tools-expert 是一个用于构建和管理 n8n 工作流的 AI 工具","ja":"n8n-mcp-tools-expert は、n8n ワークフローを構築および管理するための AI エージェントです","ko":"n8n-mcp-tools-expert는 n8n 워크플ロー 구축 및 관리를 위한 AI 에이전트입니다","es":"n8n-mcp-tools-expert es un skill que proporciona herramientas para crear flujos de trabajo perfectos con n8n","fr":"n8n-mcp-tools-expert est un skill qui fournit des outils pour créer des flux de travail parfaits avec n8n","de":"n8n-mcp-tools-expert ist ein Skill, der Tools zur Erstellung von perfekten Workflows mit n8n bereitstellt","pt":"O n8n-mcp-tools-expert é um skillset que fornece ferramentas para criar fluxos de trabalho perfeitos com n8n","ru":"n8n-mcp-tools-expert - это набор навыков, который предоставляет инструменты для создания идеальных рабочих процессов с помощью n8n","ar":"n8n-mcp-tools-expert هو مجموعة من المهارات التي توفر أدوات لإنشاء سير عمل مثالية مع n8n"},"features":{"en":["Utilizes Node Discovery for efficient workflow creation","Performs Configuration Validation for error-free workflows","Manages workflows with the Workflow Management tool","Accesses a Template Library with 2,700+ real workflows","Provides Documentation & Guides for tool usage and AI agent integration"],"zh":["工具分类","节点发现","工作流管理","模板库","文档和指南"],"ja":["ツールのカテゴリ","ノードの検出","ワークフローの管理","テンプレートライブラリ","ドキュメントとガイド"],"ko":["도구 분류","노드 검색","워크플로 관리","템플릿 라이브러리","문서 및 가이드"],"es":["Node Discovery para búsqueda de nodos","Configuration Validation para validación de configuraciones","Workflow Management para gestión de flujos de trabajo","Template Library con 2.700+ flujos de trabajo reales","Documentación y guías para herramientas y agentes de AI"],"fr":["Node Discovery pour la recherche de nœuds","Configuration Validation pour la validation de configurations","Workflow Management pour la gestion de flux de travail","Template Library avec 2.700+ flux de travail réels","Documentation et guides pour les outils et les agents d''IA"],"de":["Node Discovery zur Suche nach Knoten","Configuration Validation zur Überprüfung von Konfigurationen","Workflow Management zur Verwaltung von Workflows","Template Library mit 2.700+ realen Workflows","Dokumentation und Anleitungen für Tools und KI-Agents"],"pt":["Node Discovery para encontrar os nodes certos","Configuration Validation para garantir configurações corretas","Workflow Management para gerenciar fluxos de trabalho","Template Library com 2.700+ fluxos de trabalho reais","Documentation & Guides para ajuda adicional"],"ru":["Node Discovery для поиска нужных узлов","Configuration Validation для обеспечения правильных конфигураций","Workflow Management для управления рабочими процессами","Template Library с 2.700+ реальными рабочими процессами","Documentation & Guides для дополнительной помощи"],"ar":["اكتشاف العقد لfinding العقد المناسبة","التحقق من الصحة لضمان إعدادات صحيحة","إدارة سير العمل لتنظيم سير العمل","مكتبة القوالب مع 2.700+ سير عمل حقيقي","التعليمات والإرشادات للمساعدة الإضافية"]},"keywords":{"en":["n8n-mcp-tools-expert setup guide","how to use n8n-mcp-tools-expert","n8n-mcp-tools-expert vs Zapier","n8n-mcp-tools-expert install","what is n8n-mcp-tools-expert","n8n-mcp-tools-expert alternative","n8n workflow automation","n8n-mcp-tools-expert documentation","n8n-mcp-tools-expert tutorial"],"zh":["n8n-mcp-tools-expert","n8n 工作流","AI 工具","工作流管理","节点发现","模板库","n8n-mcp"],"ja":["n8n-mcp-tools-expert","n8n ワークフロー","AI エージェント","ワークフローの管理","ノードの検出","テンプレートライブラリ","n8n-mcp"],"ko":["n8n-mcp-tools-expert","n8n 워크플ロー","AI 에이전트","워크플로 관리","노드 검색","템플릿 라이브러리","n8n-mcp"],"es":["n8n-mcp-tools-expert","flujos de trabajo","Node Discovery","Configuration Validation","Workflow Management","Template Library","agentes de AI","herramientas de servidor MCP","guías de configuración"],"fr":["n8n-mcp-tools-expert","flux de travail","Node Discovery","Configuration Validation","Workflow Management","Template Library","agents d''IA","outils de serveur MCP","guides de configuration"],"de":["n8n-mcp-tools-expert","Workflows","Node Discovery","Configuration Validation","Workflow Management","Template Library","KI-Agents","MCP-Server-Tools","Konfigurationsleitfäden"],"pt":["n8n-mcp-tools-expert","fluxos de trabalho perfeitos","Node Discovery","Configuration Validation","Workflow Management","Template Library"," Claude Code","n8n"],"ru":["n8n-mcp-tools-expert","идеальные рабочие процессы","Node Discovery","Configuration Validation","Workflow Management","Template Library"," Claude Code","n8n","ИИ Агенты"],"ar":["n8n-mcp-tools-expert","سير عمل مثالية","اكتشاف العقد","التحقق من الصحة","إدارة سير العمل","مكتبة القوالب"," Claude Code","n8n","وكلاء ذكاء اصطناعي"]}},"owner":"czlonkowski","repo":"n8n-skills","repoPath":"czlonkowski/n8n-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.274Z","topics":[],"category":"community","skillMd":{"name":"n8n-mcp-tools-expert","description":"Expert guide for using n8n-mcp MCP tools effectively. Use when searching for nodes, validating configurations, accessing templates, managing workflows, or using any n8n-mcp tool. Provides tool selection guidance, parameter formats, and common patterns.","bodyPreview":"# n8n MCP Tools Expert\n\nMaster guide for using n8n-mcp MCP server tools to build workflows.\n\n---\n\n## Tool Categories\n\nn8n-mcp provides tools organized into categories:\n\n1. **Node Discovery** → [SEARCH_GUIDE.md](SEARCH_GUIDE.md)\n2. **Configuration Validation** → [VALIDATION_GUIDE.md](VALIDATION_GUIDE.md)\n3. **Workflow Management** → [WORKFLOW_GUIDE.md](WORKFLOW_GUIDE.md)\n4. **Template Library** - Search and deploy 2,700+ real workflows\n5. **Documentation & Guides** - Tool docs, AI agent guide, Co","body":"# n8n MCP Tools Expert\n\nMaster guide for using n8n-mcp MCP server tools to build workflows.\n\n---\n\n## Tool Categories\n\nn8n-mcp provides tools organized into categories:\n\n1. **Node Discovery** → [SEARCH_GUIDE.md](SEARCH_GUIDE.md)\n2. **Configuration Validation** → [VALIDATION_GUIDE.md](VALIDATION_GUIDE.md)\n3. **Workflow Management** → [WORKFLOW_GUIDE.md](WORKFLOW_GUIDE.md)\n4. **Template Library** - Search and deploy 2,700+ real workflows\n5. **Documentation & Guides** - Tool docs, AI agent guide, Code node guides\n\n---\n\n## Quick Reference\n\n### Most Used Tools (by success rate)\n\n| Tool | Use When | Speed |\n|------|----------|-------|\n| `search_nodes` | Finding nodes by keyword | <20ms |\n| `get_node` | Understanding node operations (detail=\"standard\") | <10ms |\n| `validate_node` | Checking configurations (mode=\"full\") | <100ms |\n| `n8n_create_workflow` | Creating workflows | 100-500ms |\n| `n8n_update_partial_workflow` | Editing workflows (MOST USED!) | 50-200ms |\n| `validate_workflow` | Checking complete workflow | 100-500ms |\n| `n8n_deploy_template` | Deploy template to n8n instance | 200-500ms |\n\n---\n\n## Tool Selection Guide\n\n### Finding the Right Node\n\n**Workflow**:\n```\n1. search_nodes({query: \"keyword\"})\n2. get_node({nodeType: \"nodes-base.name\"})\n3. [Optional] get_node({nodeType: \"nodes-base.name\", mode: \"docs\"})\n```\n\n**Example**:\n```javascript\n// Step 1: Search\nsearch_nodes({query: \"slack\"})\n// Returns: nodes-base.slack\n\n// Step 2: Get details\nget_node({nodeType: \"nodes-base.slack\"})\n// Returns: operations, properties, examples (standard detail)\n\n// Step 3: Get readable documentation\nget_node({nodeType: \"nodes-base.slack\", mode: \"docs\"})\n// Returns: markdown documentation\n```\n\n**Common pattern**: search → get_node (18s average)\n\n### Validating Configuration\n\n**Workflow**:\n```\n1. validate_node({nodeType, config: {}, mode: \"minimal\"}) - Check required fields\n2. validate_node({nodeType, config, profile: \"runtime\"}) - Full validation\n3. [Repeat] Fix errors, validate again\n```\n\n**Common pattern**: validate → fix → validate (23s thinking, 58s fixing per cycle)\n\n### Managing Workflows\n\n**Workflow**:\n```\n1. n8n_create_workflow({name, nodes, connections})\n2. n8n_validate_workflow({id})\n3. n8n_update_partial_workflow({id, operations: [...]})\n4. n8n_validate_workflow({id}) again\n5. n8n_update_partial_workflow({id, operations: [{type: \"activateWorkflow\"}]})\n```\n\n**Common pattern**: iterative updates (56s average between edits)\n\n---\n\n## Critical: nodeType Formats\n\n**Two different formats** for different tools!\n\n### Format 1: Search/Validate Tools\n```javascript\n// Use SHORT prefix\n\"nodes-base.slack\"\n\"nodes-base.httpRequest\"\n\"nodes-base.webhook\"\n\"nodes-langchain.agent\"\n```\n\n**Tools that use this**:\n- search_nodes (returns this format)\n- get_node\n- validate_node\n- validate_workflow\n\n### Format 2: Workflow Tools\n```javascript\n// Use FULL prefix\n\"n8n-nodes-base.slack\"\n\"n8n-nodes-base.httpRequest\"\n\"n8n-nodes-base.webhook\"\n\"@n8n/n8n-nodes-langchain.agent\"\n```\n\n**Tools that use this**:\n- n8n_create_workflow\n- n8n_update_partial_workflow\n\n### Conversion\n\n```javascript\n// search_nodes returns BOTH formats\n{\n  \"nodeType\": \"nodes-base.slack\",          // For search/validate tools\n  \"workflowNodeType\": \"n8n-nodes-base.slack\"  // For workflow tools\n}\n```\n\n---\n\n## Common Mistakes\n\n### Mistake 1: Wrong nodeType Format\n\n**Problem**: \"Node not found\" error\n\n```javascript\n// WRONG\nget_node({nodeType: \"slack\"})  // Missing prefix\nget_node({nodeType: \"n8n-nodes-base.slack\"})  // Wrong prefix\n\n// CORRECT\nget_node({nodeType: \"nodes-base.slack\"})\n```\n\n### Mistake 2: Using detail=\"full\" by Default\n\n**Problem**: Huge payload, slower response, token waste\n\n```javascript\n// WRONG - Returns 3-8K tokens, use sparingly\nget_node({nodeType: \"nodes-base.slack\", detail: \"full\"})\n\n// CORRECT - Returns 1-2K tokens, covers 95% of use cases\nget_node({nodeType: \"nodes-base.slack\"})  // detail=\"standard\" is default\nget_node({nodeType: \"nodes-base.slack\", detail: \"standard\"})\n```\n\n**When to use detail=\"full\"**:\n- Debugging complex configuration issues\n- Need complete property schema with all nested options\n- Exploring advanced features\n\n**Better alternatives**:\n1. `get_node({detail: \"standard\"})` - for operations list (default)\n2. `get_node({mode: \"docs\"})` - for readable documentation\n3. `get_node({mode: \"search_properties\", propertyQuery: \"auth\"})` - for specific property\n\n### Mistake 3: Not Using Validation Profiles\n\n**Problem**: Too many false positives OR missing real errors\n\n**Profiles**:\n- `minimal` - Only required fields (fast, permissive)\n- `runtime` - Values + types (recommended for pre-deployment)\n- `ai-friendly` - Reduce false positives (for AI configuration)\n- `strict` - Maximum validation (for production)\n\n```javascript\n// WRONG - Uses default profile\nvalidate_node({nodeType, config})\n\n// CORRECT - Explicit profile\nvalidate_node({nodeType, config, profile: \"runtime\"})\n```\n\n### Mistake 4: Ignoring Auto-Sanitization\n\n**What happens**: ALL nodes sanitized on ANY workflow update\n\n**Auto-fixes**:\n- Binary operators (equals, contains) → removes singleValue\n- Unary operators (isEmpty, isNotEmpty) → adds singleValue: true\n- IF/Switch nodes → adds missing metadata\n\n**Cannot fix**:\n- Broken connections\n- Branch count mismatches\n- Paradoxical corrupt states\n\n```javascript\n// After ANY update, auto-sanitization runs on ALL nodes\nn8n_update_partial_workflow({id, operations: [...]})\n// → Automatically fixes operator structures\n```\n\n### Mistake 5: Not Using Smart Parameters\n\n**Problem**: Complex sourceIndex calculations for multi-output nodes\n\n**Old way** (manual):\n```javascript\n// IF node connection\n{\n  type: \"addConnection\",\n  source: \"IF\",\n  target: \"Handler\",\n  sourceIndex: 0  // Which output? Hard to remember!\n}\n```\n\n**New way** (smart parameters):\n```javascript\n// IF node - semantic branch names\n{\n  type: \"addConnection\",\n  source: \"IF\",\n  target: \"True Handler\",\n  branch: \"true\"  // Clear and readable!\n}\n\n{\n  type: \"addConnection\",\n  source: \"IF\",\n  target: \"False Handler\",\n  branch: \"false\"\n}\n\n// Switch node - semantic case numbers\n{\n  type: \"addConnection\",\n  source: \"Switch\",\n  target: \"Handler A\",\n  case: 0\n}\n```\n\n### Mistake 6: Not Using intent Parameter\n\n**Problem**: Less helpful tool responses\n\n```javascript\n// WRONG - No context for response\nn8n_update_partial_workflow({\n  id: \"abc\",\n  operations: [{type: \"addNode\", node: {...}}]\n})\n\n// CORRECT - Better AI responses\nn8n_update_partial_workflow({\n  id: \"abc\",\n  intent: \"Add error handling for API failures\",\n  operations: [{type: \"addNode\", node: {...}}]\n})\n```\n\n---\n\n## Tool Usage Patterns\n\n### Pattern 1: Node Discovery (Most Common)\n\n**Common workflow**: 18s average between steps\n\n```javascript\n// Step 1: Search (fast!)\nconst results = await search_nodes({\n  query: \"slack\",\n  mode: \"OR\",  // Default: any word matches\n  limit: 20\n});\n// → Returns: nodes-base.slack, nodes-base.slackTrigger\n\n// Step 2: Get details (~18s later, user reviewing results)\nconst details = await get_node({\n  nodeType: \"nodes-base.slack\",\n  includeExamples: true  // Get real template configs\n});\n// → Returns: operations, properties, metadata\n```\n\n### Pattern 2: Validation Loop\n\n**Typical cycle**: 23s thinking, 58s fixing\n\n```javascript\n// Step 1: Validate\nconst result = await validate_node({\n  nodeType: \"nodes-base.slack\",\n  config: {\n    resource: \"channel\",\n    operation: \"create\"\n  },\n  profile: \"runtime\"\n});\n\n// Step 2: Check errors (~23s thinking)\nif (!result.valid) {\n  console.log(result.errors);  // \"Missing required field: name\"\n}\n\n// Step 3: Fix config (~58s fixing)\nconfig.name = \"general\";\n\n// Step 4: Validate again\nawait validate_node({...});  // Repeat until clean\n```\n\n### Pattern 3: Workflow Editing\n\n**Most used update tool**: 99.0% success rate, 56s average between edits\n\n```javascript\n// Iterative workflow building (NOT one-shot!)\n// Edit 1\nawait n8n_update_partial_workflow({\n  id: \"workflow-id\",\n  intent: \"Add webhook trigger\",\n  operations: [{type: \"addNode\", node: {...}}]\n});\n\n// ~56s later...\n\n// Edit 2\nawait n8n_update_partial_workflow({\n  id: \"workflow-id\",\n  intent: \"Connect webhook to processor\",\n  operations: [{type: \"addConnection\", source: \"...\", target: \"...\"}]\n});\n\n// ~56s later...\n\n// Edit 3 (validation)\nawait n8n_validate_workflow({id: \"workflow-id\"});\n\n// Ready? Activate!\nawait n8n_update_partial_workflow({\n  id: \"workflow-id\",\n  intent: \"Activate workflow for production\",\n  operations: [{type: \"activateWorkflow\"}]\n});\n```\n\n---\n\n## Detailed Guides\n\n### Node Discovery Tools\nSee [SEARCH_GUIDE.md](SEARCH_GUIDE.md) for:\n- search_nodes\n- get_node with detail levels (minimal, standard, full)\n- get_node modes (info, docs, search_properties, versions)\n\n### Validation Tools\nSee [VALIDATION_GUIDE.md](VALIDATION_GUIDE.md) for:\n- Validation profiles explained\n- validate_node with modes (minimal, full)\n- validate_workflow complete structure\n- Auto-sanitization system\n- Handling validation errors\n\n### Workflow Management\nSee [WORKFLOW_GUIDE.md](WORKFLOW_GUIDE.md) for:\n- n8n_create_workflow\n- n8n_update_partial_workflow (17 operation types!)\n- Smart parameters (branch, case)\n- AI connection types (8 types)\n- Workflow activation (activateWorkflow/deactivateWorkflow)\n- n8n_deploy_template\n- n8n_workflow_versions\n\n---\n\n## Template Usage\n\n### Search Templates\n\n```javascript\n// Search by keyword (default mode)\nsearch_templates({\n  query: \"webhook slack\",\n  limit: 20\n});\n\n// Search by node types\nsearch_templates({\n  searchMode: \"by_nodes\",\n  nodeTypes: [\"n8n-nodes-base.httpRequest\", \"n8n-nodes-base.slack\"]\n});\n\n// Search by task type\nsearch_templates({\n  searchMode: \"by_task\",\n  task: \"webhook_processing\"\n});\n\n// Search by metadata (complexity, setup time)\nsearch_templates({\n  searchMode: \"by_metadata\",\n  complexity: \"simple\",\n  maxSetupMinutes: 15\n});\n```\n\n### Get Template Details\n\n```javascript\nget_template({\n  templateId: 2947,\n  mode: \"structure\"  // nodes+connections only\n});\n\nget_template({\n  templateId: 2947,\n  mode: \"full\"  // complete workflow JSON\n});\n```\n\n### Deploy Template Directly\n\n```javascript\n// Deploy template to your n8n instance\nn8n_deploy_template({\n  templateId: 2947,\n  name: \"My Weather to Slack\",  // Custom name (optional)\n  autoFix: true,  // Auto-fix common issues (default)\n  autoUpgradeVersions: true  // Upgrade node versions (default)\n});\n// Returns: workflow ID, required credentials, fixes applied\n```\n\n---\n\n## Self-Help Tools\n\n### Get Tool Documentation\n\n```javascript\n// Overview of all tools\ntools_documentation()\n\n// Specific tool details\ntools_documentation({\n  topic: \"search_nodes\",\n  depth: \"full\"\n})\n\n// Code node guides\ntools_documentation({topic: \"javascript_code_node_guide\", depth: \"full\"})\ntools_documentation({topic: \"python_code_node_guide\", depth: \"full\"})\n```\n\n### AI Agent Guide\n\n```javascript\n// Comprehensive AI workflow guide\nai_agents_guide()\n// Returns: Architecture, connections, tools, validation, best practices\n```\n\n### Health Check\n\n```javascript\n// Quick health check\nn8n_health_check()\n\n// Detailed diagnostics\nn8n_health_check({mode: \"diagnostic\"})\n// → Returns: status, env vars, tool status, API connectivity\n```\n\n---\n\n## Tool Availability\n\n**Always Available** (no n8n API needed):\n- search_nodes, get_node\n- validate_node, validate_workflow\n- search_templates, get_template\n- tools_documentation, ai_agents_guide\n\n**Requires n8n API** (N8N_API_URL + N8N_API_KEY):\n- n8n_create_workflow\n- n8n_update_partial_workflow\n- n8n_validate_workflow (by ID)\n- n8n_list_workflows, n8n_get_workflow\n- n8n_test_workflow\n- n8n_executions\n- n8n_deploy_template\n- n8n_workflow_versions\n- n8n_autofix_workflow\n\nIf API tools unavailable, use templates and validation-only workflows.\n\n---\n\n## Unified Tool Reference\n\n### get_node (Unified Node Information)\n\n**Detail Levels** (mode=\"info\", default):\n- `minimal` (~200 tokens) - Basic metadata only\n- `standard` (~1-2K tokens) - Essential properties + operations (RECOMMENDED)\n- `full` (~3-8K tokens) - Complete schema (use sparingly)\n\n**Operation Modes**:\n- `info` (default) - Node schema with detail level\n- `docs` - Readable markdown documentation\n- `search_properties` - Find specific properties (use with propertyQuery)\n- `versions` - List all versions with breaking changes\n- `compare` - Compare two versions\n- `breaking` - Show only breaking changes\n- `migrations` - Show auto-migratable changes\n\n```javascript\n// Standard (recommended)\nget_node({nodeType: \"nodes-base.httpRequest\"})\n\n// Get documentation\nget_node({nodeType: \"nodes-base.webhook\", mode: \"docs\"})\n\n// Search for properties\nget_node({nodeType: \"nodes-base.httpRequest\", mode: \"search_properties\", propertyQuery: \"auth\"})\n\n// Check versions\nget_node({nodeType: \"nodes-base.executeWorkflow\", mode: \"versions\"})\n```\n\n### validate_node (Unified Validation)\n\n**Modes**:\n- `full` (default) - Comprehensive validation with errors/warnings/suggestions\n- `minimal` - Quick required fields check only\n\n**Profiles** (for mode=\"full\"):\n- `minimal` - Very lenient\n- `runtime` - Standard (default, recommended)\n- `ai-friendly` - Balanced for AI workflows\n- `strict` - Most thorough (production)\n\n```javascript\n// Full validation with runtime profile\nvalidate_node({nodeType: \"nodes-base.slack\", config: {...}, profile: \"runtime\"})\n\n// Quick required fields check\nvalidate_node({nodeType: \"nodes-base.webhook\", config: {}, mode: \"minimal\"})\n```\n\n---\n\n## Performance Characteristics\n\n| Tool | Response Time | Payload Size |\n|------|---------------|--------------|\n| search_nodes | <20ms | Small |\n| get_node (standard) | <10ms | ~1-2KB |\n| get_node (full) | <100ms | 3-8KB |\n| validate_node (minimal) | <50ms | Small |\n| validate_node (full) | <100ms | Medium |\n| validate_workflow | 100-500ms | Medium |\n| n8n_create_workflow | 100-500ms | Medium |\n| n8n_update_partial_workflow | 50-200ms | Small |\n| n8n_deploy_template | 200-500ms | Medium |\n\n---\n\n## Best Practices\n\n### Do\n- Use `get_node({detail: \"standard\"})` for most use cases\n- Specify validation profile explicitly (`profile: \"runtime\"`)\n- Use smart parameters (`branch`, `case`) for clarity\n- Include `intent` parameter in workflow updates\n- Follow search → get_node → validate workflow\n- Iterate workflows (avg 56s between edits)\n- Validate after every significant change\n- Use `includeExamples: true` for real configs\n- Use `n8n_deploy_template` for quick starts\n\n### Don''t\n- Use `detail: \"full\"` unless necessary (wastes tokens)\n- Forget nodeType prefix (`nodes-base.*`)\n- Skip validation profiles\n- Try to build workflows in one shot (iterate!)\n- Ignore auto-sanitization behavior\n- Use full prefix (`n8n-nodes-base.*`) with search/validate tools\n- Forget to activate workflows after building\n\n---\n\n## Summary\n\n**Most Important**:\n1. Use **get_node** with `detail: \"standard\"` (default) - covers 95% of use cases\n2. nodeType formats differ: `nodes-base.*` (search/validate) vs `n8n-nodes-base.*` (workflows)\n3. Specify **validation profiles** (`runtime` recommended)\n4. Use **smart parameters** (`branch=\"true\"`, `case=0`)\n5. Include **intent parameter** in workflow updates\n6. **Auto-sanitization** runs on ALL nodes during updates\n7. Workflows can be **activated via API** (`activateWorkflow` operation)\n8. Workflows are built **iteratively** (56s avg between edits)\n\n**Common Workflow**:\n1. search_nodes → find node\n2. get_node → understand config\n3. validate_node → check config\n4. n8n_create_workflow → build\n5. n8n_validate_workflow → verify\n6. n8n_update_partial_workflow → iterate\n7. activateWorkflow → go live!\n\nFor details, see:\n- [SEARCH_GUIDE.md](SEARCH_GUIDE.md) - Node discovery\n- [VALIDATION_GUIDE.md](VALIDATION_GUIDE.md) - Configuration validation\n- [WORKFLOW_GUIDE.md](WORKFLOW_GUIDE.md) - Workflow management\n\n---\n\n**Related Skills**:\n- n8n Expression Syntax - Write expressions in workflow fields\n- n8n Workflow Patterns - Architectural patterns from templates\n- n8n Validation Expert - Interpret validation errors\n- n8n Node Configuration - Operation-specific requirements\n- n8n Code JavaScript - Write JavaScript in Code nodes\n- n8n Code Python - Write Python in Code nodes\n"},"lastSynced":"2026-03-08T02:00:32.511Z","agentAnalysis":{"suitability":{"en":"Perfect for Workflow Automation Agents needing advanced n8n workflow management capabilities using Node Discovery and Configuration Validation.","zh":"非常适合需要使用 Node Discovery 和 Configuration Validation 进行高级 n8n 工作流管理的工作流自动化代理。","ja":"Node Discovery と Configuration Validation を使用した高度な n8n ワークフロー管理機能が必要なワークフロー自動化エージェントに最適です。","ko":"Node Discovery와 Configuration Validation를 사용하여 고급 n8n 워크플ロー 관리 기능이 필요한 워크플ロー 자동화 에이전트에 적합합니다.","es":"Perfecto para Agentes de Automatización de Flujo de Trabajo que necesitan capacidades avanzadas de gestión de flujos de trabajo n8n utilizando Node Discovery y Validación de Configuración.","fr":"Parfait pour les Agents d''Automatisation de Workflow nécessitant des capacités avancées de gestion de workflow n8n utilisant Node Discovery et Validation de Configuration.","de":"Perfekt für Workflow-Automatisierungsagenten, die erweiterte n8n-Workflow-Managementfunktionen unter Verwendung von Node Discovery und Konfigurationsvalidierung benötigen.","pt":"Perfeito para Agentes de Automação de Fluxo de Trabalho que precisam de capacidades avançadas de gerenciamento de fluxo de trabalho n8n usando Node Discovery e Validação de Configuração.","ru":"Идеально подходит для агентов автоматизации рабочих процессов, которым требуются продвинутые возможности управления рабочими процессами n8n с помощью Node Discovery и валидации конфигурации.","ar":"مثالي لعميل автомاتیزاسیون تدفق العمل الذي يحتاج إلى قدرات متقدمة لإدارة تدفق العمل n8n باستخدام Node Discovery وتأكيد الإعدادات."},"recommendation":{"en":"Empowers agents to build flawless n8n workflows using tools like Node Discovery for efficient workflow creation and Configuration Validation for error-free deployments, leveraging a vast Template Library of 2,700+ real workflows and comprehensive Documentation & Guides.","zh":"赋予代理构建无缺陷的 n8n 工作流的能力，使用 Node Discovery 进行高效的工作流创建和 Configuration Validation 进行无错误的部署，利用 2,700+ 个真实工作流的庞大模板库和全面性的文档与指南。","ja":"エージェントが Node Discovery を使用した効率的なワークフロー作成と Configuration Validation を使用したエラーのないデプロイメントにより、欠陥のない n8n ワークフローを構築する能力を提供します。2,700+ の実際のワークフローを含む広範なテンプレート ライブラリと包括的なドキュメント & ガイドを活用します。","ko":"에이전트가 Node Discovery를 사용하여 효율적인 워크플ロー 생성과 Configuration Validation를 사용하여 오류 없는 배포를 통해 결함이 없는 n8n 워크플ロー 구축 능력을 제공합니다. 2,700+개의 실제 워크플로우를 포함하는 광범위한 템플릿 라이브러리와 포괄적인 문서 및 가이드를 활용합니다.","es":"Habilita a los agentes a crear flujos de trabajo n8n impecables utilizando herramientas como Node Discovery para una creación de flujos de trabajo eficiente y Validación de Configuración para implementaciones sin errores, aprovechando una vasta Biblioteca de Plantillas de 2,700+ flujos de trabajo reales y Documentación y Guías completas.","fr":"Permet aux agents de créer des flux de travail n8n impeccables en utilisant des outils comme Node Discovery pour une création de flux de travail efficace et Validation de Configuration pour des déploiements sans erreurs, en exploitant une vaste Bibliothèque de Modèles de 2,700+ flux de travail réels et une Documentation et des Guides complets.","de":"Ermächtigt Agenten, fehlerfreie n8n-Workflows mit Tools wie Node Discovery für eine effiziente Workflow-Erstellung und Konfigurationsvalidierung für fehlerfreie Bereitstellungen zu erstellen, die auf einer umfassenden Bibliothek von 2,700+ realen Workflows und umfassender Dokumentation und Anleitungen basieren.","pt":"Habilita os agentes a criar fluxos de trabalho n8n impecáveis usando ferramentas como Node Discovery para criação de fluxo de trabalho eficiente e Validação de Configuração para implantações sem erros, aproveitando uma vasta Biblioteca de Modelos de 2.700+ fluxos de trabalho reais e Documentação e Guias abrangentes.","ru":"Наделяет агентов возможностью создавать безупречные рабочие процессы n8n с помощью инструментов, таких как Node Discovery для эффективного создания рабочих процессов, и валидации конфигурации для развертывания без ошибок, используя обширную библиотеку шаблонов из 2 700+ реальных рабочих процессов и всестороннюю документацию и руководства.","ar":"يمكن للوكيل من إنشاء تدفقات عمل n8n خالية من الأخطاء باستخدام أدوات مثل Node Discovery لإنشاء تدفق عمل فعال وتأكيد الإعدادات لتنفيذ بدون أخطاء، واستخدام مكتبة قوالب واسعة من 2,700+ تدفق عمل حقيقي وتوثيق ودلائل شاملة."},"useCases":{"en":["Automating workflow validation using Configuration Validation","Discovering and integrating nodes efficiently with Node Discovery","Deploying proven workflows from the Template Library"],"zh":["使用 Configuration Validation 进行工作流验证自动化","使用 Node Discovery 高效地发现和集成节点","从模板库部署经过验证的工作流"],"ja":["Configuration Validation を使用したワークフロー検証の自動化","Node Discovery を使用したノードの効率的な検出と統合","テンプレート ライブラリから検証済みのワークフローをデプロイ"],"ko":["Configuration Validation를 사용하여 워크플ロー 검증 자동화","Node Discovery를 사용하여 노드의 효율적인 검색 및 통합","템플릿 라이브러리에서 검증된 워크플ロー 배포"],"es":["Automatizar la validación de flujos de trabajo utilizando Validación de Configuración","Descubrir e integrar nodos de manera eficiente con Node Discovery","Implementar flujos de trabajo probados de la Biblioteca de Plantillas"],"fr":["Automatiser la validation des flux de travail en utilisant la Validation de Configuration","Découvrir et intégrer des nœuds de manière efficace avec Node Discovery","Déployer des flux de travail éprouvés de la Bibliothèque de Modèles"],"de":["Automatisieren der Workflow-Validierung unter Verwendung von Konfigurationsvalidierung","Effizientes Entdecken und Integrieren von Knoten mit Node Discovery","Bereitstellen von bewährten Workflows aus der Bibliothek von Vorlagen"],"pt":["Automatizar a validação do fluxo de trabalho usando Validação de Configuração","Descobrir e integrar nós de forma eficiente com Node Discovery","Implantar fluxos de trabalho comprovados da Biblioteca de Modelos"],"ru":["Автоматизировать проверку рабочего процесса с помощью валидации конфигурации","Эффективно обнаруживать и интегрировать узлы с помощью Node Discovery","Развертывать проверенные рабочие процессы из библиотеки шаблонов"],"ar":["تأتمتة التحقق من تدفق العمل باستخدام تأكيد الإعدادات","اكتشاف وتكامل العقد بفعالية مع Node Discovery","نشر تدفقات العمل المثبتة من مكتبة القوالب"]},"limitations":{"en":["Requires n8n-mcp server setup","Limited to n8n workflow automation"],"zh":["需要 n8n-mcp 服务器设置","仅限 n8n 工作流自动化"],"ja":["n8n-mcp サーバーの設定が必要","n8n ワークフロー自動化に限定"],"ko":["n8n-mcp 서버 설정이 필요","n8n 워크플ロー 자동화에만 제한"],"es":["Requiere configuración del servidor n8n-mcp","Limitado a la automatización de flujos de trabajo n8n"],"fr":["Nécessite une configuration du serveur n8n-mcp","Limité à l''automatisation des flux de travail n8n"],"de":["Benötigt n8n-mcp-Server-Einrichtung","Begrenzt auf n8n-Workflow-Automatisierung"],"pt":["Requer configuração do servidor n8n-mcp","Limitado à automação de fluxo de trabalho n8n"],"ru":["Требуется настройка сервера n8n-mcp","Ограниченная автоматизация рабочих процессов n8n"],"ar":["يتطلب إعداد خادم n8n-mcp","محدودة لتأتمتة تدفق العمل n8n"]},"version":4},"contentHash":"abb7737f1ef3e7087c840b8bb8c1e5315414a7fb503c539c6b117e79852c2114","qualityScore":45}');
