INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('czlonkowski/n8n-skills/n8n-mcp-tools-expert', 'n8n-mcp-tools-expert', 'czlonkowski', 'n8n-skills', 'community', 'n8n-mcp-tools-expert czlonkowski n8n-skills community The n8n-mcp-tools-expert skillset enables developers to build flawless n8n workflows using tools like Node Discovery and Configuration Validation. Ideal for AI agents and workflow automation experts. n8n-mcp-tools-expert 是一个用于构建无缝的 n8n 工作流的技能，提供工具分类、节点发现和工作流管理等功能 n8n-mcp-tools-expert は、無欠の n8n ワークフローを構築するためのスキルです。ツールのカテゴリ、ノードの検出、ワークフローの管理などを提供します n8n-mcp-tools-expert는 완벽한 n8n 워크플ロー 구축을 위한 스킬입니다. 도구 분류, 노드 검색 및 워크플로 관리 등을 제공합니다 El skill n8n-mcp-tools-expert proporciona una guía maestra para utilizar herramientas de servidor MCP de n8n para crear flujos de trabajo Le skill n8n-mcp-tools-expert fournit un guide maître pour utiliser les outils de serveur MCP de n8n pour créer des flux de travail Der Skill n8n-mcp-tools-expert bietet einen Master-Leitfaden für die Verwendung von n8n-MCP-Server-Tools zur Erstellung von Workflows O n8n-mcp-tools-expert é um skillset para Claude Code que permite criar fluxos de trabalho perfeitos com n8n. Inclui ferramentas como Node Discovery e Configuration Validation. n8n-mcp-tools-expert - это набор навыков для Claude Code, который позволяет создавать идеальные рабочие процессы с помощью n8n. Включает в себя инструменты, такие как Node Discovery и Configuration Validation. n8n-mcp-tools-expert هو مجموعة من المهارات ل Claude Code التي تمكن من إنشاء سير عمل مثالية مع n8n. يتضمن أدوات مثل اكتشاف العقد و التحقق من الصحة n8n-mcp-tools-expert setup guide how to use n8n-mcp-tools-expert n8n-mcp-tools-expert vs Zapier n8n-mcp-tools-expert install what is n8n-mcp-tools-expert n8n-mcp-tools-expert alternative n8n workflow automation n8n-mcp-tools-expert documentation n8n-mcp-tools-expert tutorial n8n-mcp-tools-expert n8n 工作流 AI 工具 工作流管理 节点发现 模板库 n8n-mcp Utilizes Node Discovery for efficient workflow creation Performs Configuration Validation for error-free workflows Manages workflows with the Workflow Management tool Accesses a Template Library with 2,700+ real workflows Provides Documentation & Guides for tool usage and AI agent integration n8n-mcp-tools-expert is a skillset for building n8n workflows using a range of tools, including Node Discovery, Configuration Validation, and Workflow Management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('PeonPing/peon-ping/peon-ping-config', 'community', 'PeonPing', 'peon-ping', 'PeonPing/peon-ping', 'peon-ping-config', 0, 0, 45, '2026-03-08T01:57:15.276Z', '2026-03-08T02:00:39.151Z', '4b2ff0c13199d1cfd65c2a7930d31368464b6fe0194db14b3e064f18bf5f58a5', '{"id":"PeonPing/peon-ping/peon-ping-config","name":"peon-ping-config","description":{"en":"The peon-ping-config skill enables developers to receive Warcraft III Peon voice notifications for Claude Code and Codex, automating terminal monitoring. It benefits developers seeking to streamline their workflow.","zh":"peon-ping-config是一种Warcraft III Peon语音通知工具，支持配置音量、声音包和轮换功能","ja":"peon-ping-configは、Warcraft III Peonの音声通知を提供するAIエージェントであり、音量やサウンドパックの設定が可能です","ko":"peon-ping-config는 워크래프트 III Peon 음성 알림을 제공하는 도구로, 음량, 사운드 팩 및 회전 기능을 구성할 수 있습니다","es":"peon-ping-config es una herramienta para personalizar notificaciones de voz en Claude Code y Codex. Configura ajustes como volumen y paquete de sonido.","fr":"peon-ping-config est un outil pour personnaliser les notifications vocales dans Claude Code et Codex. Configurez des paramètres tels que le volume et le pack de sons.","de":"peon-ping-config ist ein Tool zur Anpassung von Sprachbenachrichtigungen in Claude Code und Codex. Konfigurieren Sie Einstellungen wie Lautstärke und Sound-Paket.","pt":"O Peon-Ping-Config é uma ferramenta que fornece notificações de voz personalizadas para Claude Code e Codex, melhorando a produtividade dos desenvolvedores","ru":"Peon-Ping-Config - это инструмент, который предоставляет настраиваемые голосовые уведомления для Claude Code и Codex, повышая производительность разработчиков","ar":"Peon-Ping-Config هو أداة توفر إشعارات صوتية مخصصة لمنصات Claude Code و Codex، مما يحسن إنتاجية المطورين"},"seo":{"title":{"en":"peon-ping-config: Customizable Warcraft III Voice Notific...","zh":"peon-pi