INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('PeonPing/peon-ping/peon-ping-config', 'peon-ping-config', 'PeonPing', 'peon-ping', 'community', 'peon-ping-config PeonPing peon-ping community The peon-ping-config skill enables developers to receive Warcraft III Peon voice notifications for Claude Code and Codex, automating terminal monitoring. It benefits developers seeking to streamline their workflow. peon-ping-config是一种Warcraft III Peon语音通知工具，支持配置音量、声音包和轮换功能 peon-ping-configは、Warcraft III Peonの音声通知を提供するAIエージェントであり、音量やサウンドパックの設定が可能です peon-ping-config는 워크래프트 III Peon 음성 알림을 제공하는 도구로, 음량, 사운드 팩 및 회전 기능을 구성할 수 있습니다 peon-ping-config es una herramienta para personalizar notificaciones de voz en Claude Code y Codex. Configura ajustes como volumen y paquete de sonido. peon-ping-config est un outil pour personnaliser les notifications vocales dans Claude Code et Codex. Configurez des paramètres tels que le volume et le pack de sons. peon-ping-config ist ein Tool zur Anpassung von Sprachbenachrichtigungen in Claude Code und Codex. Konfigurieren Sie Einstellungen wie Lautstärke und Sound-Paket. O Peon-Ping-Config é uma ferramenta que fornece notificações de voz personalizadas para Claude Code e Codex, melhorando a produtividade dos desenvolvedores Peon-Ping-Config - это инструмент, который предоставляет настраиваемые голосовые уведомления для Claude Code и Codex, повышая производительность разработчиков Peon-Ping-Config هو أداة توفر إشعارات صوتية مخصصة لمنصات Claude Code و Codex، مما يحسن إنتاجية المطورين how to use peon-ping-config peon-ping-config setup guide what is peon-ping-config peon-ping-config alternative peon-ping-config vs custom voice notifications configuring peon-ping-config for Claude Code installing peon-ping-config for Codex peon-ping-config sound pack rotation customizing peon-ping-config voice notifications peon-ping-config Warcraft III Peon语音通知 AI工具 音频配置 JSON配置文件 开发效率 终端通知 Configurable sound volume via the volume setting in config.json Support for multiple sound packs, including ''peon'', ''sc_kerrigan'', and ''glados'' Master on/off switch using the enabled setting Pack rotation feature for randomizing sound packs per session Config file location at ${CLAUDE_CONFIG_DIR:-$HOME/.claude}/hooks/peon-ping/config.json peon-ping-config is a customizable AI agent skill that provides Warcraft III Peon voice notifications for terminal events, using a config.json file for personalized settings.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('holon-run/holon/ghx', 'community', 'holon-run', 'holon', 'holon-run/holon', 'ghx', 0, 0, 45, '2026-03-08T01:57:15.280Z', '2026-03-08T02:00:50.245Z', 'bb1a47edffee032ba03ed5d500e15eb527261f0c7125dc21a2b2191845f0826e', '{"id":"holon-run/holon/ghx","name":"ghx","description":{"en":"The ghx skill automates GitHub operations for AI agents, providing context collection and PR publishing capabilities. It benefits developers by standardizing common GitHub operations and preventing agent mistakes.","zh":"GHX 是一个增强的可靠性层，提供标准化的 GitHub 操作和稳定的上下文收集","ja":"GHX は、AIエージェントによるコーディングを強化するために、標準化された GitHub 操作と安定したコンテキスト収集を提供する層です","ko":"GHX는 AI 에이전트를 위한 표준화된 GitHub 운영과 안정적인 컨텍스트 수집을 제공하는 강화된 계층입니다","es":"ghx es una capa de confiabilidad mejorada para operaciones de GitHub, que estandariza tareas comunes y evita errores comunes","fr":"ghx est une couche de fiabilité améliorée pour les opérations GitHub, qui standardise les tâches courantes et évite les erreurs courantes","de":"ghx ist eine verbesserte Zuverlässigkeitsschicht für GitHub-Operationen, die gemeinsame Aufgaben standardisiert und häufige Fehler vermeidet","pt":"O GHX é uma camada de confiabilidade aprimorada para operações no GitHub, fornecendo coleta de contexto e publicação para fluxos de trabalho de PR","ru":"GHX - это улучшенный слой надежности для операций в GitHub, обеспечивающий сбор контекста и публикацию для рабочих процессов PR","ar":"GHX هو طبقة موثوقية محسنة للعمليات على GitHub، يوفر جمع السياق والنشر لتدفقات العمل PR"},"seo":{"title":{"en":"ghx: Automated GitHub Workflows for AI Agents | AI Agent ...","zh":"GHX 技术集成指南 - AI 编码代理增强","ja":"GHX Setup Guide - AIエージェントによるコーディングの強化","ko":"GHX 설정 가이드 - AI 에이전트를 통한 코딩 강화","es":"Guía de configuración de ghx: Agentes de codificación AI ...","fr":"Guide de mise en place de ghx : Outils d''agent de codage ...","de":"Einrichtungsleitfaden für ghx: KI-Coding-Agenten für GitHub","pt":"Guia de Configuração do GHX: Otimizando Operações no GitH...","ru":"Настройка GHX: Руководство по использованию ИИ Агентов дл...","ar":"دليل إعداد GHX: تحسين عمليات GitHub باستخدام أدوات الإي ا..."},"description":{"en":"Streamline your GitHub workflow with ghx, the AI agent skill that automates context collection and PR publishing. Learn how to set up ghx today!","zh":"GHX 技术提供了标准化的 GitHub 操作和稳定的上下文收集，用于 AI 编码代理","ja":"GHX は、AIエージェントによるコーディングを強化するために、標準化された GitHub 操作と安定したコンテキスト収集を提供します","ko":"GHX는 AI 에이전트를 위한 표준화된 GitHub 운영과 안정적인 컨텍스트 수집을 제공합니다","es":"Aprende a utilizar ghx para automatizar tareas de codificación en GitHub con agentes de codificación AI","fr":"Découvrez comment utiliser ghx pour automatiser les tâches de codage sur GitHub avec des outils d''agent de codage AI","de":"Erfahren Sie, wie Sie ghx verwenden, um Codierungsaufgaben in GitHub mit KI-Coding-Agenten zu automatisieren","pt":"Aprenda a configurar o GHX para automatizar operações no GitHub com ferramentas de IA e melhore a eficiência do seu fluxo de trabalho","ru":"Узнайте, как настроить GHX для автоматизации операций в GitHub с помощью ИИ Агентов и повысьте эффективность вашего рабочего процесса","ar":"تعرف على كيفية إعداد GHX لت 자동化 عمليات GitHub باستخدام أدوات الإي الأجنت و تحسين كفاءة سير عملك"},"definition":{"en":"ghx is an enhanced reliability layer on top of gh, standardizing GitHub operations and preventing common agent mistakes for AI agents.","zh":"GHX 是一个增强的可靠性层，用于标准化 GitHub 操作","ja":"GHX は、GitHub 操作を標準化するための強化された信頼性層です","ko":"GHX는 GitHub 운영을 표준화하기 위한 강화된 신뢰성 계층입니다","es":"ghx es un agente de codificación AI que automatiza tareas de codificación en GitHub","fr":"ghx est un outil d''agent de codage AI qui automatise les tâches de codage sur GitHub","de":"ghx ist ein KI-Coding-Agent, der Codierungsaufgaben in GitHub automatisiert","pt":"O que é GHX? É uma camada de confiabilidade para operações no GitHub, padronizando operações comuns e prevenindo erros comuns","ru":"Что такое GHX? Это слой надежности для операций в GitHub, стандартизирующий общие операции и предотвращающий общие ошибки","ar":"ما هو GHX؟ هو طبقة موثوقية للعمليات على GitHub، يؤمن العمليات الشائعة ويمنع الأخطاء الشائعة"},"features":{"en":["Provides context collection with a stable artifact manifest","Enables publishing for PR/review/comment workflows","Utilizes environment variables such as GITHUB_OUTPUT_DIR and GITHUB_CONTEXT","Supports shell escaping and multi-line payload handling","Offers a standardized way to automate GitHub operations for AI agents","Integrates with CI/CD pipelines for automated workflows"],"zh":["标准化的 GitHub 操作","稳定的上下文收集","支持多行有效负载","防止 shell 转义错误","提供 PR/审查/评论工作流","支持环境变量 GITHUB_OUTPUT_DIR"],"ja":["標準化された GitHub 操作","安定したコンテキスト収集","マルチラインペイロードのサポート","シェルエスケープエラーの防止","PR/レビュー/コメントワークフローの提供","環境変数 GITHUB_OUTPUT_DIR のサポート"],"ko":["표준화된 GitHub 운영","안정적인 컨텍스트 수집","다중 행有效载荷 지원","쉘 이스케이프 오류 방지","PR/검토/댓글 워크플로우 제공","환경 변수 GITHUB_OUTPUT_DIR 지원"],"es":["Colección de contexto con un manifiesto de artefactos estables","Publicación para flujos de trabajo de PR/revisión/comentario","Compatibilidad con variables de entorno como GITHUB_OUTPUT_DIR","Evita errores comunes de shell escaping y payloads multi-línea","Integración con GitHub para operaciones de codificación automatizadas"],"fr":["Collecte de contexte avec un manifeste d''artefacts stables","Publication pour les flux de travail de PR/examen/commentaire","Compatibilité avec des variables d''environnement comme GITHUB_OUTPUT_DIR","Évite les erreurs courantes d''échappement de shell et de payloads multi-lignes","Intégration avec GitHub pour des opérations de codage automatisées"],"de":["Kontextsammlung mit einem stabilen Artefaktmanifest","Veröffentlichung für PR/Überprüfungs/Kommentar-Workflows","Unterstützung von Umgebungsvariablen wie GITHUB_OUTPUT_DIR","Vermeidung häufiger Fehler bei Shell-Escaping und Multi-Line-Payloads","Integration mit GitHub für automatisierte Codierungsoperationen"],"pt":["Coleta de contexto com manifesto de artefatos estáveis","Publicação para fluxos de trabalho de PR/revisão/comentário","Suporte a variáveis de ambiente como GITHUB_OUTPUT_DIR","Prevenção de erros comuns de shell escaping e payloads multi-linha"],"ru":["Сбор контекста с стабильным манифестом артефактов","Публикация для рабочих процессов PR/ревью/комментариев","Поддержка переменных среды, таких как GITHUB_OUTPUT_DIR","Предотвращение общих ошибок shell escaping и multi-line payloads"],"ar":["جمع السياق مع مаниفست أرتفاكت مستقر","نشر لتدفقات العمل PR/استعراض/تعليق","دعم المتغيرات البيئية مثل GITHUB_OUTPUT_DIR","منع الأخطاء الشائعة ل shell escaping و multi-line payloads"]},"keywords":{"en":["ghx setup guide","what is ghx","ghx vs gh","how to use ghx with AI agents","ghx install","automated GitHub workflows","ghx alternative","ghx documentation","ghx tutorial","GitHub automation for AI agents"],"zh":["GHX 技术","AI 编码代理","GitHub 操作","上下文收集","shell 转义","多行有效负载","PR 工作流","GITHUB_OUTPUT_DIR"],"ja":["GHX 技術","AIエージェント","GitHub 操作","コンテキスト収集","シェルエスケープ","マルチラインペイロード","PR ワークフロー","GITHUB_OUTPUT_DIR"],"ko":["GHX 기술","AI 에이전트","GitHub 운영","컨텍스트 수집","쉘 이스케이프","다중 행有效载荷","PR 워크플로우","GITHUB_OUTPUT_DIR"],"es":["agentes de codificación AI","herramientas de codificación automática","GitHub","automatización de tareas de codificación","ghx","agentes de codificación","herramientas de desarrollo de software","integración con GitHub"],"fr":["outils d''agent de codage AI","outils de codage automatisé","GitHub","automatisation des tâches de codage","ghx","outils d''agent de codage","outils de développement de logiciels","intégration avec GitHub"],"de":["KI-Coding-Agenten","Werkzeuge für automatisierte Codierung","GitHub","Automatisierung von Codierungsaufgaben","ghx","Coding-Agenten","Software-Entwicklungstools","Integration mit GitHub"],"pt":["GHX","Ferramentas de IA para GitHub","Automatização de operações no GitHub","Fluxos de trabalho de PR","Coleta de contexto","Publicação para PR","GITHUB_OUTPUT_DIR","Shell escaping"],"ru":["GHX","ИИ Агенты для GitHub","Автоматизация операций в GitHub","Рабочие процессы PR","Сбор контекста","Публикация для PR","GITHUB_OUTPUT_DIR","Shell escaping"],"ar":["GHX","أدوات الإي الأجنت للغيت هاب","ت خودمية العمليات على GitHub","تدفقات العمل PR","جمع السياق","نشر ل PR","GITHUB_OUTPUT_DIR","_shell escaping"]}},"owner":"holon-run","repo":"holon","repoPath":"holon-run/holon","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.280Z","topics":[],"category":"community","skillMd":{"name":"ghx","description":"GitHub enhanced operations skill. Provides unified context collection and publishing commands for PR/issue workflows.","bodyPreview":"# GHX Skill\n\n`ghx` is an enhanced reliability layer on top of `gh`, used by higher-level skills.\nIt standardizes common GitHub operations and prevents common agent mistakes (especially shell escaping and multi-line payload issues).\n\nIt provides two capabilities:\n- Context collection with a stable artifact manifest\n- Publishing for PR/review/comment workflows\n\n## Environment Variables\n\n- `GITHUB_OUTPUT_DIR`: artifact directory (caller-provided; defaults to a temp dir when unset)\n- `GITHUB_CONTEXT","body":"# GHX Skill\n\n`ghx` is an enhanced reliability layer on top of `gh`, used by higher-level skills.\nIt standardizes common GitHub operations and prevents common agent mistakes (especially shell escaping and multi-line payload issues).\n\nIt provides two capabilities:\n- Context collection with a stable artifact manifest\n- Publishing for PR/review/comment workflows\n\n## Environment Variables\n\n- `GITHUB_OUTPUT_DIR`: artifact directory (caller-provided; defaults to a temp dir when unset)\n- `GITHUB_CONTEXT_DIR`: context directory (default `${GITHUB_OUTPUT_DIR}/github-context`)\n- `GITHUB_TOKEN` / `GH_TOKEN`: token used by `gh`\n- `DRY_RUN`: preview mode for publish commands (`true|false`)\n\n## Commands\n\nUse `scripts/ghx.sh` as the entrypoint.\n\n### Context collection\n\n```bash\nscripts/ghx.sh context collect holon-run/holon#123\nscripts/ghx.sh context collect 123 holon-run/holon\n```\n\n### Publish commands\n\n```bash\nscripts/ghx.sh review publish --pr=holon-run/holon#123 --body-file=review.md --comments-file=review.json\nscripts/ghx.sh pr create --repo=holon-run/holon --title=\"Title\" --body-file=summary.md --head=feature/x --base=main\nscripts/ghx.sh pr update --pr=holon-run/holon#123 --title=\"New title\" --body-file=summary.md\nscripts/ghx.sh pr comment --pr=holon-run/holon#123 --body-file=summary.md\n# stdin body is also supported\nscripts/ghx.sh pr comment --pr=holon-run/holon#123 --body-file=- <<''EOF''\nMultiline body from stdin.\nEOF\n```\n\n### Batch mode\n\n```bash\nscripts/ghx.sh batch run --batch=${GITHUB_OUTPUT_DIR}/publish-batch.json\n```\n\nUse batch mode when one run needs multiple publish actions.\nUse direct commands for single-action publish.\n\n## Contract Boundary\n\n- Public contract for other skills:\n  - Call `ghx.sh` commands.\n  - Read `${GITHUB_CONTEXT_DIR}/manifest.json` for context artifacts.\n  - Read `${GITHUB_OUTPUT_DIR}/publish-results.json` for publish execution results.\n  - Use `publish-batch.json` schema when running `ghx.sh batch run` (defined below and in `references/github-publishing.md`).\n- Integration guidance for third-party skills:\n  - Prefer direct commands for single actions.\n  - Use batch mode only when one run needs multiple publish actions.\n  - Do not depend on undocumented fields or script internals outside this documented schema.\n\n## Context Output Contract\n\n`context collect` writes:\n- `${GITHUB_CONTEXT_DIR}/manifest.json`\n- Context files under `${GITHUB_CONTEXT_DIR}/github/` (for example `pr.json`, `pr.diff`, `comments.json`)\n\n`manifest.json` is the source of truth for collected context:\n\n```json\n{\n  \"schema_version\": \"2.0\",\n  \"provider\": \"ghx\",\n  \"kind\": \"pr|issue\",\n  \"ref\": \"owner/repo#123\",\n  \"success\": true,\n  \"artifacts\": [\n    {\n      \"id\": \"pr_metadata\",\n      \"path\": \"github/pr.json\",\n      \"required_for\": [\"review\"],\n      \"status\": \"present|missing|error\",\n      \"format\": \"json|text\",\n      \"description\": \"What this artifact contains\"\n    }\n  ],\n  \"notes\": []\n}\n```\n\nConsumers must use `artifacts[]` instead of assuming fixed context filenames.\n\n## Publish Output Contract\n\nPublish commands write `${GITHUB_OUTPUT_DIR}/publish-results.json` with per-action status and summary totals.\n\n## Batch Input Contract (Public)\n\n`ghx.sh batch run` consumes `${GITHUB_OUTPUT_DIR}/publish-batch.json` (or any path passed by `--batch`).\n\n```json\n{\n  \"version\": \"1.0\",\n  \"pr_ref\": \"owner/repo#123\",\n  \"actions\": [\n    {\n      \"type\": \"post_comment\",\n      \"description\": \"optional\",\n      \"params\": {\n        \"body\": \"summary.md\"\n      }\n    }\n  ]\n}\n```\n\nSchema summary:\n- Top-level required fields: `pr_ref`, `actions`\n- Top-level optional field: `version` (default `1.0`)\n- Action required field: `type`\n- Action optional fields: `description`, `params`\n- `params` is action-specific payload; legacy inline action fields are also accepted.\n\nSupported `type` values:\n- `create_pr`\n- `update_pr`\n- `post_comment`\n- `reply_review`\n- `post_review`\n\n## Notes\n\n- Prefer `ghx` for multi-step or error-prone GitHub operations.\n- `context collect` also prints a human-readable artifact summary; this is informational only.\n- For long or multi-line text, never inline shell arguments; always write to a file and pass `--body-file`/`--comments-file`.\n- Command selection:\n  - single action: use direct commands (`review publish`, `pr create|update|comment`)\n  - multiple actions in one run: use `batch run`\n\n## Safety Rules (Text Payloads)\n\nTo reduce failure rate from quoting/newline/markdown escaping:\n\n1. Never pass large markdown/JSON payloads inline on command line.\n2. Always pass payloads via file arguments:\n   - `ghx`: `--body-file`, `--comments-file` (`--body-file=-` is allowed to read from stdin)\n   - raw `gh`: `--body-file`\n3. Apply this rule to PR reviews, PR comments/description, issue comments, and issue creation.\n\nGood:\n\n```bash\ncat > /tmp/issue-body.md <<''EOF''\n## Summary\nDetailed markdown with quotes, backticks, and newlines.\nEOF\ngh issue create --repo owner/repo --title \"Bug report\" --body-file /tmp/issue-body.md\n```\n\nBad:\n\n```bash\ngh issue create --repo owner/repo --title \"Bug report\" --body \"## Summary\nDetailed markdown with quotes, backticks, and newlines.\"\n```\n"},"lastSynced":"2026-03-08T02:00:50.245Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub Automation Agents requiring standardized and reliable repository operations","zh":"适合需要标准化和可靠的仓库操作的 GitHub Automation Agents","ja":"標準化されたリポジトリ操作を必要とする GitHub Automation Agents に最適","ko":"표준화되고 안정적인 저장소 작동이 필요한 GitHub Automation 에이전트에 적합","es":"Ideal para agentes de automatización de GitHub que requieren operaciones de repositorio estandarizadas y confiables","fr":"Idéal pour les agents d''automatisation GitHub nécessitant des opérations de référentiel standardisées et fiables","de":"Ideal für GitHub-Automatisierungsagenten, die standardisierte und zuverlässige Repository-Operationen erfordern","pt":"Ideal para Agentes de Automação do GitHub que exigem operações de repositório padronizadas e confiáveis","ru":"Идеально для агентов автоматизации GitHub, требующих стандартизированных и надежных операций с репозиторием","ar":"مثالي لعمليات وكيل آلي غيت هب التي تتطلب عمليات مستودع معيارية وموثوقة"},"recommendation":{"en":"Empowers agents to automate GitHub workflows with context collection and PR publishing capabilities, utilizing a stable artifact manifest and preventing common mistakes like shell escaping and multi-line payload issues, all while leveraging the `gh` command-line interface","zh":"赋予代理自动化 GitHub 工作流的能力，具有上下文收集和 PR 发布功能，利用稳定的构件清单，并防止常见错误，如 Shell 转义和多行有效负载问题，同时利用 `gh` 命令行接口","ja":"エージェントにGitHubワークフローを自動化する機能を付与し、コンテキストの収集とPRの公開機能を提供し、安定したアーティファクトマニフェストを利用し、シェルエスケープや多行ペイロードの問題などの一般的なエラーを防ぎながら、`gh` コマンドラインインターフェイスを利用","ko":"에이전트가 GitHub 워크플로를 자동화할 수 있는 능력을 부여하며, 컨텍스트 수집 및 PR 발행 기능을 제공하고, 안정적인 아티팩트 매니페스트를 활용하며, 셸 이스케이프 또는 다중行 페이로드 문제와 같은 일반적인 오류를 방지하면서 `gh` 명령줄 인터페이스를 활용","es":"Habilita a los agentes a automatizar flujos de trabajo de GitHub con la recolección de contexto y capacidades de publicación de PR, utilizando un manifiesto de artefactos estable y evitando errores comunes como el escape de shell y los problemas de carga de varias líneas, todo mientras aprovecha la interfaz de línea de comandos `gh`","fr":"Permet aux agents d''automatiser les flux de travail GitHub avec la collecte de contexte et les capacités de publication de PR, en utilisant un manifeste d''artefact stable et en évitant les erreurs courantes comme l''échappement de shell et les problèmes de charge de plusieurs lignes, le tout en exploitant l''interface de ligne de commande `gh`","de":"Ermächtigt Agenten, GitHub-Workflows mit Kontextsammlung und PR-Veröffentlichungsfähigkeiten zu automatisieren, indem ein stabiles Artefaktmanifest verwendet und häufige Fehler wie Shell-Escape und Mehrzeilen-Payload-Probleme vermieden werden, und zwar unter Ausnutzung der `gh`-Kommandozeilen-Schnittstelle","pt":"Permite que os agentes automatem fluxos de trabalho do GitHub com coleta de contexto e capacidades de publicação de PR, utilizando um manifesto de artefatos estável e prevenindo erros comuns como escape de shell e problemas de carga de várias linhas, tudo isso aproveitando a interface de linha de comando `gh`","ru":"Предоставляет агентам возможность автоматизировать рабочие процессы GitHub с помощью сбора контекста и возможностей публикации PR, используя стабильный манифест артефактов и предотвращая общие ошибки, такие как побег из shell и проблемы с полезной нагрузкой в несколько строк, все это при использовании интерфейса командной строки `gh`","ar":"تمكين الوكلاء من ت自动化 سير عمل غيت هب مع جمع السياق و قدرات نشر PR، باستخدام مаниفست مستقر للارتفاع و منع الأخطاء الشائعة مثل الهروب من shell و مشاكل الحمولة متعددة الخطوط، و كل ذلك بالاستفادة من واجهة سطر الأوامر `gh`"},"useCases":{"en":["Automating context collection for GitHub repositories","Publishing pull requests and reviewing code changes","Streamlining comment workflows for collaborative development"],"zh":["自动化 GitHub 仓库的上下文收集","发布拉取请求和审查代码更改","简化协作开发的评论工作流"],"ja":["GitHub リポジトリのコンテキストの収集を自動化","プルリクエストの公開とコード変更のレビュー","共同開発のコメントワークフローを簡素化"],"ko":["GitHub 저장소의 컨텍스트 수집 자동화","풀 요청 발행 및 코드 변경审查","협업 개발을 위한 댓글 워크플로우 간소화"],"es":["Automatización de la recolección de contexto para repositorios de GitHub","Publicación de solicitudes de extracción y revisión de cambios de código","Optimización de flujos de trabajo de comentarios para el desarrollo colaborativo"],"fr":["Automatisation de la collecte de contexte pour les référentiels GitHub","Publication de demandes d''extraction et de révision des modifications de code","Optimisation des flux de travail de commentaires pour le développement collaboratif"],"de":["Automatisierung der Kontextsammlung für GitHub-Repositorys","Veröffentlichung von Pull-Anfragen und Überprüfung von Code-Änderungen","Optimierung von Kommentar-Workflows für die Zusammenarbeit bei der Entwicklung"],"pt":["Automatizar a coleta de contexto para repositórios do GitHub","Publicar solicitações de pull e revisar alterações de código","Otimizar fluxos de trabalho de comentários para desenvolvimento colaborativo"],"ru":["Автоматизировать сбор контекста для репозиториев GitHub","Публиковать запросы на pull и рассматривать изменения кода","Оптимизировать рабочие процессы комментариев для совместного развития"],"ar":["تأتمتة جمع السياق لمستودعات غيت هب","نشر طلبات السحب ومراجعة تغييرات الكود","تسينير سير عمل التعليقات من أجل التطوير التعاوني"]},"limitations":{"en":["Requires `GITHUB_OUTPUT_DIR` environment variable for artifact directory","Dependent on `gh` command-line interface for GitHub operations"],"zh":["需要 `GITHUB_OUTPUT_DIR` 环境变量来指定构件目录","依赖 `gh` 命令行接口来执行 GitHub 操作"],"ja":["アーティファクトディレクトリを指定するために `GITHUB_OUTPUT_DIR` 環境変数が必要","GitHub 操作を実行するために `gh` コマンドラインインターフェイスに依存"],"ko":["아티팩트 디렉토리를 지정하기 위해 `GITHUB_OUTPUT_DIR` 환경 변수가 필요","GitHub 작동을 수행하기 위해 `gh` 명령줄 인터페이스에 의존"],"es":["Requiere la variable de entorno `GITHUB_OUTPUT_DIR` para el directorio de artefactos","Dependiente de la interfaz de línea de comandos `gh` para operaciones de GitHub"],"fr":["Nécessite la variable d''environnement `GITHUB_OUTPUT_DIR` pour le répertoire d''artefact","Dépendant de l''interface de ligne de commande `gh` pour les opérations GitHub"],"de":["Benötigt die Umgebungsvariable `GITHUB_OUTPUT_DIR` für das Artefakt-Verzeichnis","Abhängig von der `gh`-Kommandozeilen-Schnittstelle für GitHub-Operationen"],"pt":["Exige a variável de ambiente `GITHUB_OUTPUT_DIR` para o diretório de artefatos","Depende da interface de linha de comando `gh` para operações do GitHub"],"ru":["Требует переменной среды `GITHUB_OUTPUT_DIR` для каталога артефактов","Зависит от интерфейса командной строки `gh` для операций с GitHub"],"ar":["يتطلب متغير بيئة `GITHUB_OUTPUT_DIR` لمديرية الارتفاع","يعتمد على واجهة سطر الأوامر `gh` لعمليات غيت هب"]},"version":4},"contentHash":"bb1a47edffee032ba03ed5d500e15eb527261f0c7125dc21a2b2191845f0826e","qualityScore":45}');
