INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('holon-run/holon/ghx', 'ghx', 'holon-run', 'holon', 'community', 'ghx holon-run holon community The ghx skill automates GitHub operations for AI agents, providing context collection and PR publishing capabilities. It benefits developers by standardizing common GitHub operations and preventing agent mistakes. GHX 是一个增强的可靠性层，提供标准化的 GitHub 操作和稳定的上下文收集 GHX は、AIエージェントによるコーディングを強化するために、標準化された GitHub 操作と安定したコンテキスト収集を提供する層です GHX는 AI 에이전트를 위한 표준화된 GitHub 운영과 안정적인 컨텍스트 수집을 제공하는 강화된 계층입니다 ghx es una capa de confiabilidad mejorada para operaciones de GitHub, que estandariza tareas comunes y evita errores comunes ghx est une couche de fiabilité améliorée pour les opérations GitHub, qui standardise les tâches courantes et évite les erreurs courantes ghx ist eine verbesserte Zuverlässigkeitsschicht für GitHub-Operationen, die gemeinsame Aufgaben standardisiert und häufige Fehler vermeidet O GHX é uma camada de confiabilidade aprimorada para operações no GitHub, fornecendo coleta de contexto e publicação para fluxos de trabalho de PR GHX - это улучшенный слой надежности для операций в GitHub, обеспечивающий сбор контекста и публикацию для рабочих процессов PR GHX هو طبقة موثوقية محسنة للعمليات على GitHub، يوفر جمع السياق والنشر لتدفقات العمل PR ghx setup guide what is ghx ghx vs gh how to use ghx with AI agents ghx install automated GitHub workflows ghx alternative ghx documentation ghx tutorial GitHub automation for AI agents GHX 技术 AI 编码代理 GitHub 操作 上下文收集 shell 转义 多行有效负载 PR 工作流 GITHUB_OUTPUT_DIR Provides context collection with a stable artifact manifest Enables publishing for PR/review/comment workflows Utilizes environment variables such as GITHUB_OUTPUT_DIR and GITHUB_CONTEXT Supports shell escaping and multi-line payload handling Offers a standardized way to automate GitHub operations for AI agents Integrates with CI/CD pipelines for automated workflows ghx is an enhanced reliability layer on top of gh, standardizing GitHub operations and preventing common agent mistakes for AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('openclaw/openclaw/coding-agent', 'community', 'openclaw', 'openclaw', 'openclaw/openclaw', 'coding-agent', 0, 0, 45, '2026-03-08T01:57:15.281Z', '2026-03-08T02:00:51.076Z', 'c2db324a6adfa8b9172eab70118fbd5fdd3da1a6502aff25e9eb8b3d33692271', '{"id":"openclaw/openclaw/coding-agent","name":"coding-agent","description":{"en":"The coding-agent skill provides a personal AI assistant for coding tasks, utilizing bash and supporting PTY mode for interactive terminal apps like Codex, Pi, and OpenCode.","zh":"Coding Agent 是一个支持任何操作系统和平台的 AI 助手，使用 Bash 和 PTY 模式进行编码工作","ja":"Coding Agent は、Bash と PTY モードを使用して、すべての OS とプラットフォームで動作する AI アシスタントです","ko":"Coding Agent는 모든 OS와 플랫폼에서 동작하는 AI 도구로 Bash와 PTY 모드를 사용하여 코딩 작업을 수행합니다","es":"Coding Agent es un asistente AI para desarrolladores que utiliza bash y PTY para ejecutar comandos y scripts en cualquier sistema operativo y plataforma.","fr":"Coding Agent est un assistant AI pour les développeurs qui utilise bash et PTY pour exécuter des commandes et des scripts sur tous les systèmes d''exploitation et les plateformes.","de":"Coding Agent ist ein AI-Assistent für Entwickler, der bash und PTY verwendet, um Befehle und Skripte auf jedem Betriebssystem und jeder Plattform auszuführen.","pt":"O Coding Agent é uma ferramenta de desenvolvimento AI que utiliza bash para executar tarefas de codificação de forma simples e eficaz","ru":"Coding Agent - это инструмент для разработчиков ИИ Агентов, который использует bash для выполнения задач кодирования простым и эффективным способом","ar":"وكيل الترميز هو أداة تطوير العاملين الذكاء الاصطناعي التي تستخدم bash لتنفيذ مهام الترميز بطرق بسيطة وفعالة"},"seo":{"title":{"en":"Coding-Agent: Bash-First Setup Guide | AI Agent Skill","zh":"Coding Agent 设置指南：使用 Bash 和 PTY 模式","ja":"Coding Agent のベストプラクティス：Bash と PTY モードの活用","ko":"Coding Agent 설치 가이드: Bash와 PTY 모드 활용","es":"Guía de configuración de Coding Agent: Asistente AI para ...","fr":"Guide de configuration de Coding Agent : Assistant AI pou...","de":"Einrichtungsleitfaden für Coding Agent: AI-Assistent für ...","pt":"Guia de Configuração do Coding Agent: Ferramenta de Desen...","ru":"Настройка Coding Agent: Инструмент для разработчиков ИИ А...","ar":"دليل إعداد وكيل الترميز: أداة تطوير العاملين الذكاء الاصط..."},"description":{"en":"Unlock the full potential of your coding workflow with coding-agent, featuring bash-first setup and PTY mode support - get started now!","zh":"了解 Coding Agent 的技术细节，包括 Bash 和 PTY 模式的使用方法，提高您的开发效率","ja":"Coding Agent の技術的な詳細を学び、Bash と PTY モードの使用方法をマスターして開発の生産性を向上させる","ko":"Coding Agent의 기술적 세부사항을 알아보고 Bash 및 PTY 모드의 사용법을 익혀 개발 효율성을 높여보세요","es":"Descubre cómo utilizar Coding Agent, un asistente AI para desarrolladores que funciona en cualquier sistema operativo y plataforma, con capacidades de bash y...","fr":"Découvrez comment utiliser Coding Agent, un assistant AI pour les développeurs qui fonctionne sur tous les systèmes d''exploitation et les plateformes, avec d...","de":"Erfahren Sie, wie Sie Coding Agent verwenden können, einen AI-Assistenten für Entwickler, der auf jedem Betriebssystem und jeder Plattform funktioniert, mit ...","pt":"Aprenda a configurar o Coding Agent, uma ferramenta de desenvolvimento AI que funciona em qualquer sistema operacional e plataforma","ru":"Узнайте, как настроить Coding Agent, инструмент для разработчиков ИИ Агентов, который работает на любой операционной системе и платформе","ar":"تعلم كيفية إعداد وكيل الترميز، أداة تطوير العاملين الذكاء الاصطناعي التي تعمل على أي نظام تشغيل ومنصة"},"definition":{"en":"coding-agent is a bash-first AI assistant skill for coding tasks, compatible with any OS and platform, utilizing PTY mode for interactive terminal apps.","zh":"Coding Agent 是一种使用 Bash 和 PTY 模式的 AI 助手，支持任何操作系统和平台","ja":"Coding Agent は、Bash と PTY モードを使用する AI エージェントで、すべての OS とプラットフォームをサポートします","ko":"Coding Agent는 Bash와 PTY 모드를 사용하는 AI 에이전트로 모든 OS와 플랫폼을 지원합니다","es":"Coding Agent es un asistente AI que utiliza tecnologías de bash y PTY para automatizar tareas de desarrollo.","fr":"Coding Agent est un assistant AI qui utilise les technologies de bash et PTY pour automatiser les tâches de développement.","de":"Coding Agent ist ein AI-Assistent, der bash- und PTY-Technologien verwendet, um Entwicklungsaufgaben zu automatisieren.","pt":"O que é Coding Agent? É uma ferramenta de desenvolvimento AI que fornece assistência de codificação em qualquer sistema operacional e plataforma","ru":"Что такое Coding Agent? Это инструмент для разработчиков ИИ Агентов, который предоставляет помощь в кодировании на любой операционной системе и платформе","ar":"ما هو وكيل الترميز؟ هو أداة تطوير العاملين الذكاء الاصطناعي التي توفر مساعدة في الترميز على أي نظام تشغيل ومنصة"},"features":{"en":["Utilizes bash for all coding agent work","Supports PTY mode for interactive terminal apps like Codex, Pi, and OpenCode","Compatible with Claude Code CLI using --print and --permission-mode bypassPermissions","Allows for background mode execution","Supports execution of commands via bash pty:true"],"zh":["支持 Bash 和 PTY 模式","适用于 Codex、Pi 和 OpenCode","支持 Claude Code 的 --print 和 --permission-mode 选项","可用于任何操作系统和平台","使用 bash pty:true 命令进行交互式终端应用"],"ja":["Bash と PTY モードのサポート","Codex、Pi、OpenCode に対応","Claude Code の --print と --permission-mode オプションのサポート","すべての OS とプラットフォームで動作","bash pty:true コマンドを使用したインタラクティブなターミナルアプリ"],"ko":["Bash와 PTY 모드 지원","Codex, Pi, OpenCode 지원","Claude Code의 --print 및 --permission-mode 옵션 지원","모든 OS와 플랫폼에서 동작","bash pty:true 명령을 사용한 인터랙티브 터미널 애플리케이션"],"es":["Compatibilidad con cualquier sistema operativo y plataforma","Utilización de bash para ejecutar comandos y scripts","Soporte para PTY (pseudo-teletype) para aplicaciones interactivas","Compatibilidad con Codex, Pi y OpenCode","Opción de ejecución en modo de fondo"],"fr":["Compatibilité avec tous les systèmes d''exploitation et les plateformes","Utilisation de bash pour exécuter des commandes et des scripts","Prise en charge de PTY (pseudo-teletype) pour les applications interactives","Compatibilité avec Codex, Pi et OpenCode","Option d''exécution en mode d''arrière-plan"],"de":["Kompatibilität mit jedem Betriebssystem und jeder Plattform","Verwendung von bash zur Ausführung von Befehlen und Skripten","Unterstützung für PTY (pseudo-teletype) für interaktive Anwendungen","Kompatibilität mit Codex, Pi und OpenCode","Option zur Ausführung im Hintergrundmodus"],"pt":["Utiliza bash para executar tarefas de codificação","Compatível com Codex, Pi e OpenCode","Suporta modo de fundo para execução de tarefas em segundo plano","Requer PTY para aplicações interativas de terminal","Utiliza --print e --permission-mode para Claude Code"],"ru":["Использует bash для выполнения задач кодирования","Компатибелен с Codex, Pi и OpenCode","Поддерживает фоновый режим для выполнения задач в фоновом режиме","Требует PTY для интерактивных приложений терминала","Использует --print и --permission-mode для Claude Code"],"ar":["يستخدم bash لتنفيذ مهام الترميز","متوافق مع Codex و Pi و OpenCode","يدعم وضع الخلفية لتنفيذ المهام في الخلفية","يتطلب PTY للتطبيقات التفاعلية للوحة التحكم","يستخدم --print و --permission-mode ل Claude Code"]},"keywords":{"en":["how to use coding-agent","coding-agent setup guide","coding-agent vs other AI assistants","PTY mode in coding-agent","bash-first coding agent","coding-agent install","what is coding-agent","coding-agent alternative","coding-agent tutorial","coding-agent PTY mode support"],"zh":["Coding Agent","AI 助手","Bash","PTY 模式","Codex","Pi","OpenCode","Claude Code","AI 开发工具"],"ja":["Coding Agent","AI エージェント","Bash","PTY モード","Codex","Pi","OpenCode","Claude Code","AI 開発ツール"],"ko":["Coding Agent","AI 에이전트","Bash","PTY 모드","Codex","Pi","OpenCode","Claude Code","AI 개발 도구"],"es":["Agente AI para desarrolladores","Asistente AI de código","bash para desarrolladores","PTY para aplicaciones interactivas","Codex para desarrolladores","Pi para desarrolladores","OpenCode para desarrolladores","Desarrollo de software con AI"],"fr":["Assistant AI pour les développeurs","Assistant AI de code","bash pour les développeurs","PTY pour les applications interactives","Codex pour les développeurs","Pi pour les développeurs","OpenCode pour les développeurs","Développement de logiciels avec AI"],"de":["AI-Assistent für Entwickler","AI-Code-Assistent","bash für Entwickler","PTY für interaktive Anwendungen","Codex für Entwickler","Pi für Entwickler","OpenCode für Entwickler","Softwareentwicklung mit AI"],"pt":["coding agent","ferramenta de desenvolvimento ai","bash","codex","pi","opencode","claude code","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["coding agent","инструмент для разработчиков ии агентов","bash","codex","pi","opencode","claude code","разработка программного обеспечения","инструменты для разработки"],"ar":["وكيل الترميز","أداة تطوير العاملين الذكاء الاصطناعي","bash","codex","pi","opencode","claude code","تطوير البرمجيات","أدوات التطوير"]}},"owner":"openclaw","repo":"openclaw","repoPath":"openclaw/openclaw","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.281Z","topics":[],"category":"community","skillMd":{"name":"coding-agent","description":"Delegate coding tasks to Codex, Claude Code, or Pi agents via background process. Use when: (1) building/creating new features or apps, (2) reviewing PRs (spawn in temp dir), (3) refactoring large codebases, (4) iterative coding that needs file exploration. NOT for: simple one-liner fixes (just edit), reading code (use read tool), thread-bound ACP harness requests in chat (for example spawn/run Codex or Claude Code in a Discord thread; use sessions_spawn with runtime:acp), or any work in ~/clawd workspace (never spawn agents here). Claude Code: use --print --permission-mode bypassPermissions (no PTY). Codex/Pi/OpenCode: pty:true required.","bodyPreview":"# Coding Agent (bash-first)\n\nUse **bash** (with optional background mode) for all coding agent work. Simple and effective.\n\n## ⚠️ PTY Mode: Codex/Pi/OpenCode yes, Claude Code no\n\nFor **Codex, Pi, and OpenCode**, PTY is still required (interactive terminal apps):\n\n```bash\n# ✅ Correct for Codex/Pi/OpenCode\nbash pty:true command:\"codex exec ''Your prompt''\"\n```\n\nFor **Claude Code** (`claude` CLI), use `--print --permission-mode bypassPermissions` instead.\n`--dangerously-skip-permissions` with PTY can","body":"# Coding Agent (bash-first)\n\nUse **bash** (with optional background mode) for all coding agent work. Simple and effective.\n\n## ⚠️ PTY Mode: Codex/Pi/OpenCode yes, Claude Code no\n\nFor **Codex, Pi, and OpenCode**, PTY is still required (interactive terminal apps):\n\n```bash\n# ✅ Correct for Codex/Pi/OpenCode\nbash pty:true command:\"codex exec ''Your prompt''\"\n```\n\nFor **Claude Code** (`claude` CLI), use `--print --permission-mode bypassPermissions` instead.\n`--dangerously-skip-permissions` with PTY can exit after the confirmation dialog.\n`--print` mode keeps full tool access and avoids interactive confirmation:\n\n```bash\n# ✅ Correct for Claude Code (no PTY needed)\ncd /path/to/project && claude --permission-mode bypassPermissions --print ''Your task''\n\n# For background execution: use background:true on the exec tool\n\n# ❌ Wrong for Claude Code\nbash pty:true command:\"claude --dangerously-skip-permissions ''task''\"\n```\n\n### Bash Tool Parameters\n\n| Parameter    | Type    | Description                                                                 |\n| ------------ | ------- | --------------------------------------------------------------------------- |\n| `command`    | string  | The shell command to run                                                    |\n| `pty`        | boolean | **Use for coding agents!** Allocates a pseudo-terminal for interactive CLIs |\n| `workdir`    | string  | Working directory (agent sees only this folder''s context)                   |\n| `background` | boolean | Run in background, returns sessionId for monitoring                         |\n| `timeout`    | number  | Timeout in seconds (kills process on expiry)                                |\n| `elevated`   | boolean | Run on host instead of sandbox (if allowed)                                 |\n\n### Process Tool Actions (for background sessions)\n\n| Action      | Description                                          |\n| ----------- | ---------------------------------------------------- |\n| `list`      | List all running/recent sessions                     |\n| `poll`      | Check if session is still running                    |\n| `log`       | Get session output (with optional offset/limit)      |\n| `write`     | Send raw data to stdin                               |\n| `submit`    | Send data + newline (like typing and pressing Enter) |\n| `send-keys` | Send key tokens or hex bytes                         |\n| `paste`     | Paste text (with optional bracketed mode)            |\n| `kill`      | Terminate the session                                |\n\n---\n\n## Quick Start: One-Shot Tasks\n\nFor quick prompts/chats, create a temp git repo and run:\n\n```bash\n# Quick chat (Codex needs a git repo!)\nSCRATCH=$(mktemp -d) && cd $SCRATCH && git init && codex exec \"Your prompt here\"\n\n# Or in a real project - with PTY!\nbash pty:true workdir:~/Projects/myproject command:\"codex exec ''Add error handling to the API calls''\"\n```\n\n**Why git init?** Codex refuses to run outside a trusted git directory. Creating a temp repo solves this for scratch work.\n\n---\n\n## The Pattern: workdir + background + pty\n\nFor longer tasks, use background mode with PTY:\n\n```bash\n# Start agent in target directory (with PTY!)\nbash pty:true workdir:~/project background:true command:\"codex exec --full-auto ''Build a snake game''\"\n# Returns sessionId for tracking\n\n# Monitor progress\nprocess action:log sessionId:XXX\n\n# Check if done\nprocess action:poll sessionId:XXX\n\n# Send input (if agent asks a question)\nprocess action:write sessionId:XXX data:\"y\"\n\n# Submit with Enter (like typing \"yes\" and pressing Enter)\nprocess action:submit sessionId:XXX data:\"yes\"\n\n# Kill if needed\nprocess action:kill sessionId:XXX\n```\n\n**Why workdir matters:** Agent wakes up in a focused directory, doesn''t wander off reading unrelated files (like your soul.md 😅).\n\n---\n\n## Codex CLI\n\n**Model:** `gpt-5.2-codex` is the default (set in ~/.codex/config.toml)\n\n### Flags\n\n| Flag            | Effect                                             |\n| --------------- | -------------------------------------------------- |\n| `exec \"prompt\"` | One-shot execution, exits when done                |\n| `--full-auto`   | Sandboxed but auto-approves in workspace           |\n| `--yolo`        | NO sandbox, NO approvals (fastest, most dangerous) |\n\n### Building/Creating\n\n```bash\n# Quick one-shot (auto-approves) - remember PTY!\nbash pty:true workdir:~/project command:\"codex exec --full-auto ''Build a dark mode toggle''\"\n\n# Background for longer work\nbash pty:true workdir:~/project background:true command:\"codex --yolo ''Refactor the auth module''\"\n```\n\n### Reviewing PRs\n\n**⚠️ CRITICAL: Never review PRs in OpenClaw''s own project folder!**\nClone to temp folder or use git worktree.\n\n```bash\n# Clone to temp for safe review\nREVIEW_DIR=$(mktemp -d)\ngit clone https://github.com/user/repo.git $REVIEW_DIR\ncd $REVIEW_DIR && gh pr checkout 130\nbash pty:true workdir:$REVIEW_DIR command:\"codex review --base origin/main\"\n# Clean up after: trash $REVIEW_DIR\n\n# Or use git worktree (keeps main intact)\ngit worktree add /tmp/pr-130-review pr-130-branch\nbash pty:true workdir:/tmp/pr-130-review command:\"codex review --base main\"\n```\n\n### Batch PR Reviews (parallel army!)\n\n```bash\n# Fetch all PR refs first\ngit fetch origin ''+refs/pull/*/head:refs/remotes/origin/pr/*''\n\n# Deploy the army - one Codex per PR (all with PTY!)\nbash pty:true workdir:~/project background:true command:\"codex exec ''Review PR #86. git diff origin/main...origin/pr/86''\"\nbash pty:true workdir:~/project background:true command:\"codex exec ''Review PR #87. git diff origin/main...origin/pr/87''\"\n\n# Monitor all\nprocess action:list\n\n# Post results to GitHub\ngh pr comment <PR#> --body \"<review content>\"\n```\n\n---\n\n## Claude Code\n\n```bash\n# Foreground\nbash workdir:~/project command:\"claude --permission-mode bypassPermissions --print ''Your task''\"\n\n# Background\nbash workdir:~/project background:true command:\"claude --permission-mode bypassPermissions --print ''Your task''\"\n```\n\n---\n\n## OpenCode\n\n```bash\nbash pty:true workdir:~/project command:\"opencode run ''Your task''\"\n```\n\n---\n\n## Pi Coding Agent\n\n```bash\n# Install: npm install -g @mariozechner/pi-coding-agent\nbash pty:true workdir:~/project command:\"pi ''Your task''\"\n\n# Non-interactive mode (PTY still recommended)\nbash pty:true command:\"pi -p ''Summarize src/''\"\n\n# Different provider/model\nbash pty:true command:\"pi --provider openai --model gpt-4o-mini -p ''Your task''\"\n```\n\n**Note:** Pi now has Anthropic prompt caching enabled (PR #584, merged Jan 2026)!\n\n---\n\n## Parallel Issue Fixing with git worktrees\n\nFor fixing multiple issues in parallel, use git worktrees:\n\n```bash\n# 1. Create worktrees for each issue\ngit worktree add -b fix/issue-78 /tmp/issue-78 main\ngit worktree add -b fix/issue-99 /tmp/issue-99 main\n\n# 2. Launch Codex in each (background + PTY!)\nbash pty:true workdir:/tmp/issue-78 background:true command:\"pnpm install && codex --yolo ''Fix issue #78: <description>. Commit and push.''\"\nbash pty:true workdir:/tmp/issue-99 background:true command:\"pnpm install && codex --yolo ''Fix issue #99 from the approved ticket summary. Implement only the in-scope edits and commit after review.''\"\n\n# 3. Monitor progress\nprocess action:list\nprocess action:log sessionId:XXX\n\n# 4. Create PRs after fixes\ncd /tmp/issue-78 && git push -u origin fix/issue-78\ngh pr create --repo user/repo --head fix/issue-78 --title \"fix: ...\" --body \"...\"\n\n# 5. Cleanup\ngit worktree remove /tmp/issue-78\ngit worktree remove /tmp/issue-99\n```\n\n---\n\n## ⚠️ Rules\n\n1. **Use the right execution mode per agent**:\n   - Codex/Pi/OpenCode: `pty:true`\n   - Claude Code: `--print --permission-mode bypassPermissions` (no PTY required)\n2. **Respect tool choice** - if user asks for Codex, use Codex.\n   - Orchestrator mode: do NOT hand-code patches yourself.\n   - If an agent fails/hangs, respawn it or ask the user for direction, but don''t silently take over.\n3. **Be patient** - don''t kill sessions because they''re \"slow\"\n4. **Monitor with process:log** - check progress without interfering\n5. **--full-auto for building** - auto-approves changes\n6. **vanilla for reviewing** - no special flags needed\n7. **Parallel is OK** - run many Codex processes at once for batch work\n8. **NEVER start Codex in ~/.openclaw/** - it''ll read your soul docs and get weird ideas about the org chart!\n9. **NEVER checkout branches in ~/Projects/openclaw/** - that''s the LIVE OpenClaw instance!\n\n---\n\n## Progress Updates (Critical)\n\nWhen you spawn coding agents in the background, keep the user in the loop.\n\n- Send 1 short message when you start (what''s running + where).\n- Then only update again when something changes:\n  - a milestone completes (build finished, tests passed)\n  - the agent asks a question / needs input\n  - you hit an error or need user action\n  - the agent finishes (include what changed + where)\n- If you kill a session, immediately say you killed it and why.\n\nThis prevents the user from seeing only \"Agent failed before reply\" and having no idea what happened.\n\n---\n\n## Auto-Notify on Completion\n\nFor long-running background tasks, append a wake trigger to your prompt so OpenClaw gets notified immediately when the agent finishes (instead of waiting for the next heartbeat):\n\n```\n... your task here.\n\nWhen completely finished, run this command to notify me:\nopenclaw system event --text \"Done: [brief summary of what was built]\" --mode now\n```\n\n**Example:**\n\n```bash\nbash pty:true workdir:~/project background:true command:\"codex --yolo exec ''Build a REST API for todos.\n\nWhen completely finished, run: openclaw system event --text \\\"Done: Built todos REST API with CRUD endpoints\\\" --mode now''\"\n```\n\nThis triggers an immediate wake event — Skippy gets pinged in seconds, not 10 minutes.\n\n---\n\n## Learnings (Jan 2026)\n\n- **PTY is essential:** Coding agents are interactive terminal apps. Without `pty:true`, output breaks or agent hangs.\n- **Git repo required:** Codex won''t run outside a git directory. Use `mktemp -d && git init` for scratch work.\n- **exec is your friend:** `codex exec \"prompt\"` runs and exits cleanly - perfect for one-shots.\n- **submit vs write:** Use `submit` to send input + Enter, `write` for raw data without newline.\n- **Sass works:** Codex responds well to playful prompts. Asked it to write a haiku about being second fiddle to a space lobster, got: _\"Second chair, I code / Space lobster sets the tempo / Keys glow, I follow\"_ 🦞\n"},"lastSynced":"2026-03-08T02:00:51.076Z","agentAnalysis":{"suitability":{"en":"Perfect for Coding Agents needing interactive terminal capabilities with bash and PTY mode support.","zh":"适合需要交互式终端功能的编码代理，支持bash和PTY模式。","ja":"bashとPTYモードをサポートするインタラクティブターミナルの機能が必要なコーディングエージェントに適しています。","ko":"bash와 PTY 모드를 지원하는 인터랙티브 터미널 기능이 필요한 코딩 에이전트에 적합합니다.","es":"Perfecto para Agentes de Codificación que necesitan capacidades de terminal interactivas con bash y soporte de modo PTY.","fr":"Parfait pour les Agents de Codage nécessitant des capacités de terminal interactif avec bash et prise en charge du mode PTY.","de":"Perfekt für Coding-Agents, die interaktive Terminalfunktionen mit bash und PTY-Modus-Unterstützung benötigen.","pt":"Perfeito para Agentes de Codificação que necessitam de capacidades de terminal interativo com bash e suporte ao modo PTY.","ru":"Идеально подходит для Кодировочных Агентов, которым требуются интерактивные возможности терминала с bash и поддержкой режима PTY.","ar":"مثالي لعمليات الترميز التي تحتاج إلى قدرات طرفية تفاعلية مع bash ودعم وضع PTY."},"recommendation":{"en":"Empowers agents to execute coding tasks utilizing bash with optional background mode and supports PTY mode for interactive terminal apps like Codex, Pi, and OpenCode, while also accommodating Claude Code with --print and --permission-mode bypassPermissions.","zh":"赋予代理执行编码任务的能力，利用bash可选的后台模式，并支持PTY模式以运行交互式终端应用程序，如Codex、Pi和OpenCode，同时也支持使用--print和--permission-mode bypassPermissions的Claude Code。","ja":"エージェントにコーディングタスクを実行する能力を与え、bashのオプションのバックグラウンドモードを利用し、Codex、Pi、OpenCodeなどのインタラクティブターミナルアプリケーションを実行するためのPTYモードをサポートし、さらに--printと--permission-mode bypassPermissionsを使用したClaude Codeもサポートします。","ko":"에이전트가 코딩 작업을 수행할 수 있는 능력을 부여하고, bash의 선택적 백그라운드 모드를 사용하며, Codex, Pi, OpenCode 등의 인터랙티브 터미널 애플리케이션을 실행하기 위한 PTY 모드를 지원하고, --print와 --permission-mode bypassPermissions를 사용하는 Claude Code도 지원합니다.","es":"Habilita a los agentes a ejecutar tareas de codificación utilizando bash con modo de fondo opcional y soporta el modo PTY para aplicaciones de terminal interactivas como Codex, Pi y OpenCode, y también acomoda Claude Code con --print y --permission-mode bypassPermissions.","fr":"Permet aux agents d''exécuter des tâches de codage en utilisant bash avec un mode d''arrière-plan optionnel et prend en charge le mode PTY pour des applications de terminal interactif comme Codex, Pi et OpenCode, tout en accommodant Claude Code avec --print et --permission-mode bypassPermissions.","de":"Ermächtigt Agenten, Codierungsaufgaben mit bash auszuführen, optional mit Hintergrundmodus, und unterstützt PTY-Modus für interaktive Terminal-Apps wie Codex, Pi und OpenCode, und akkommodiert auch Claude Code mit --print und --permission-mode bypassPermissions.","pt":"Habilita os agentes a executar tarefas de codificação utilizando bash com modo de segundo plano opcional e suporta o modo PTY para aplicativos de terminal interativo como Codex, Pi e OpenCode, além de acomodar Claude Code com --print e --permission-mode bypassPermissions.","ru":"Наделяет агентов возможностью выполнять задачи кодирования с помощью bash с опциональным фоновым режимом и поддерживает режим PTY для интерактивных терминальных приложений, таких как Codex, Pi и OpenCode, а также обеспечивает совместимость с Claude Code при помощи --print и --permission-mode bypassPermissions.","ar":"تمكّن الوكيل من تشغيل مهام الترميز باستخدام bash مع وضع خلفية اختياري ودعم وضع PTY لتطبيقات الطرفية التفاعلية مثل Codex و Pi و OpenCode، بالإضافة إلى دعم Claude Code مع --print و --permission-mode bypassPermissions."},"useCases":{"en":["Automating coding tasks with bash","Executing interactive terminal apps like Codex and Pi","Debugging code with PTY mode","Utilizing Claude Code with bypassed permissions"],"zh":["使用bash自动执行编码任务","执行交互式终端应用程序，如Codex和Pi","使用PTY模式调试代码","使用--print和--permission-mode bypassPermissions的Claude Code"],"ja":["bashを使用してコーディングタスクを自動化する","CodexやPiなどのインタラクティブターミナルアプリケーションを実行する","PTYモードを使用してコードをデバッグする","--printと--permission-mode bypassPermissionsを使用したClaude Codeを使用する"],"ko":["bash를 사용하여 코딩 작업을 자동화하는 것","Codex와 Pi 같은 인터랙티브 터미널 애플리케이션을 실행하는 것","PTY 모드를 사용하여 코드를 디버깅하는 것","--print와 --permission-mode bypassPermissions를 사용하는 Claude Code를 사용하는 것"],"es":["Automatizar tareas de codificación con bash","Ejecutar aplicaciones de terminal interactivas como Codex y Pi","Depurar código con modo PTY","Utilizar Claude Code con permisos omitidos"],"fr":["Automatiser des tâches de codage avec bash","Exécuter des applications de terminal interactif comme Codex et Pi","Déboguer du code avec le mode PTY","Utiliser Claude Code avec des autorisations contournées"],"de":["Automatisierung von Codierungsaufgaben mit bash","Ausführen interaktiver Terminal-Apps wie Codex und Pi","Fehlerbehebung von Code im PTY-Modus","Verwenden von Claude Code mit umgangenen Berechtigungen"],"pt":["Automatizar tarefas de codificação com bash","Executar aplicativos de terminal interativo como Codex e Pi","Depurar código com modo PTY","Utilizar Claude Code com permissões ignoradas"],"ru":["Автоматизация задач кодирования с помощью bash","Выполнение интерактивных терминальных приложений, таких как Codex и Pi","Отладка кода в режиме PTY","Использование Claude Code с пропущенными разрешениями"],"ar":["تحسين مهام الترميز باستخدام bash","تشغيل تطبيقات الطرفية التفاعلية مثل Codex و Pi","تصحيح أخطاء الكود مع وضع PTY","استخدام Claude Code مع تجاوز الأذونات"]},"limitations":{"en":["PTY mode required for Codex, Pi, and OpenCode","Claude Code requires --print and --permission-mode bypassPermissions","Bash support is mandatory"],"zh":["Codex、Pi和OpenCode需要PTY模式","Claude Code需要--print和--permission-mode bypassPermissions","bash支持是必需的"],"ja":["Codex、Pi、OpenCodeではPTYモードが必要","Claude Codeでは--printと--permission-mode bypassPermissionsが必要","bashのサポートは必須"],"ko":["Codex, Pi, OpenCode에서는 PTY 모드가 필요합니다","Claude Code에서는 --print와 --permission-mode bypassPermissions가 필요합니다","bash 지원은 필수입니다"],"es":["Se requiere modo PTY para Codex, Pi y OpenCode","Claude Code requiere --print y --permission-mode bypassPermissions","Soporte de bash es obligatorio"],"fr":["Le mode PTY est requis pour Codex, Pi et OpenCode","Claude Code nécessite --print et --permission-mode bypassPermissions","La prise en charge de bash est obligatoire"],"de":["PTY-Modus wird für Codex, Pi und OpenCode benötigt","Claude Code erfordert --print und --permission-mode bypassPermissions","bash-Unterstützung ist obligatorisch"],"pt":["Modo PTY necessário para Codex, Pi e OpenCode","Claude Code requer --print e --permission-mode bypassPermissions","Suporte a bash é obrigatório"],"ru":["Режим PTY необходим для Codex, Pi и OpenCode","Claude Code требует --print и --permission-mode bypassPermissions","Поддержка bash является обязательной"],"ar":["وضع PTY مطلوب لبرامج Codex و Pi و OpenCode","Claude Code يتطلب --print و --permission-mode bypassPermissions","دعم bash إلزامي"]},"version":4},"contentHash":"c2db324a6adfa8b9172eab70118fbd5fdd3da1a6502aff25e9eb8b3d33692271","qualityScore":45}');
