INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('openclaw/openclaw/coding-agent', 'coding-agent', 'openclaw', 'openclaw', 'community', 'coding-agent openclaw openclaw community The coding-agent skill provides a personal AI assistant for coding tasks, utilizing bash and supporting PTY mode for interactive terminal apps like Codex, Pi, and OpenCode. Coding Agent 是一个支持任何操作系统和平台的 AI 助手，使用 Bash 和 PTY 模式进行编码工作 Coding Agent は、Bash と PTY モードを使用して、すべての OS とプラットフォームで動作する AI アシスタントです Coding Agent는 모든 OS와 플랫폼에서 동작하는 AI 도구로 Bash와 PTY 모드를 사용하여 코딩 작업을 수행합니다 Coding Agent es un asistente AI para desarrolladores que utiliza bash y PTY para ejecutar comandos y scripts en cualquier sistema operativo y plataforma. Coding Agent est un assistant AI pour les développeurs qui utilise bash et PTY pour exécuter des commandes et des scripts sur tous les systèmes d''exploitation et les plateformes. Coding Agent ist ein AI-Assistent für Entwickler, der bash und PTY verwendet, um Befehle und Skripte auf jedem Betriebssystem und jeder Plattform auszuführen. O Coding Agent é uma ferramenta de desenvolvimento AI que utiliza bash para executar tarefas de codificação de forma simples e eficaz Coding Agent - это инструмент для разработчиков ИИ Агентов, который использует bash для выполнения задач кодирования простым и эффективным способом وكيل الترميز هو أداة تطوير العاملين الذكاء الاصطناعي التي تستخدم bash لتنفيذ مهام الترميز بطرق بسيطة وفعالة how to use coding-agent coding-agent setup guide coding-agent vs other AI assistants PTY mode in coding-agent bash-first coding agent coding-agent install what is coding-agent coding-agent alternative coding-agent tutorial coding-agent PTY mode support Coding Agent AI 助手 Bash PTY 模式 Codex Pi OpenCode Claude Code AI 开发工具 Utilizes bash for all coding agent work Supports PTY mode for interactive terminal apps like Codex, Pi, and OpenCode Compatible with Claude Code CLI using --print and --permission-mode bypassPermissions Allows for background mode execution Supports execution of commands via bash pty:true coding-agent is a bash-first AI assistant skill for coding tasks, compatible with any OS and platform, utilizing PTY mode for interactive terminal apps.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('browser-use/browser-use/remote-browser', 'community', 'browser-use', 'browser-use', 'browser-use/browser-use', 'remote-browser', 0, 0, 45, '2026-03-08T01:57:15.282Z', '2026-03-08T02:00:52.546Z', 'fc60ca63b33235fd077b7713d63d17b70a52ec4e00189d3c0bf64976907933eb', '{"id":"browser-use/browser-use/remote-browser","name":"remote-browser","description":{"en":"The remote-browser skill makes websites accessible for AI agents, allowing them to automate tasks online. It''s designed for agents running on sandboxed remote machines.","zh":"远程浏览器技能使AIエージェント能够控制浏览器，实现在线任务的自动化","ja":"リモートブラウザ自動化は、AIエージェントがブラウザを操作してオンラインタスクを自動化する機能です","ko":"원격 브라우저 기능은 AI 에이전트가 브라우저를 제어하여 온라인 작업을 자동화 할 수 있도록 해줍니다","es":"Remote Browser permite a los agentes de IA en máquinas remotas sandboxeadas controlar un navegador web sin necesidad de Chrome local","fr":"Remote Browser permet aux outils d''IA sur des machines sandboxées à distance de contrôler un navigateur web sans avoir besoin de Chrome local","de":"Remote Browser ermöglicht es KI-Agents auf sandboxten Remote-Maschinen, einen Webbrowser zu steuern, ohne dass ein lokales Chrome benötigt wird","pt":"O Remote-Browser é uma habilidade que permite a automação de tarefas online para agentes em máquinas virtuais sandboxed, utilizando a ferramenta browser-use.","ru":"Remote-Browser - это навык, который позволяет автоматизировать задачи в Интернете для агентов в sandboxed виртуальных машинах, используя инструмент browser-use.","ar":"Remote-Browser هو مهارة تسمح بالتحكم التلقائي في المتصفحات للوكلاء في أجهزة افتراضية محمية، باستخدام أداة browser-use."},"seo":{"title":{"en":"remote-browser: Setup Guide for AI Agents | AI Agent Skill","zh":"远程浏览器自动化设置指南","ja":"リモートブラウザ自動化のベストプラクティス","ko":"원격 브라우저 자동화 설정 가이드","es":"Guía de configuración de Remote Browser para agentes de IA","fr":"Guide de configur