INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dirnbauer/webconsulting-skills/skill-creator', 'skill-creator', 'dirnbauer', 'webconsulting-skills', 'community', 'skill-creator dirnbauer webconsulting-skills community The skill-creator is an AI-augmented development environment for enterprise TYPO3 projects, enabling developers to create and refine skills. It benefits developers working on complex projects. Skill Creator是一个AI增强开发环境，用于创建和改进企业TYPO3项目中的技能，包括Cursor IDE Skill Creatorは、AIエージェントを使用したEnterprise TYPO3プロジェクトの開発環境を提供するスキル作成ツールです Skill Creator는 AI 지원 개발 환경에서 새로운 스킬을 생성하고 개선하는 데 사용되는 툴입니다 El skill-creator es una herramienta de desarrollo de habilidades para proyectos de TYPO3 que permite crear y mejorar habilidades de forma iterativa Le skill-creator est un outil de développement de compétences pour les projets TYPO3 qui permet de créer et d''améliorer des compétences de manière itérative Der skill-creator ist ein Entwicklungstool für Fähigkeiten in TYPO3-Projekten, das die Erstellung und Verbesserung von Fähigkeiten in iterativen Schritten ermöglicht O Skill Creator é uma ferramenta de desenvolvimento de IA que permite criar e aperfeiçoar habilidades para projetos TYPO3 com Cursor IDE. Skill Creator — это инструмент ИИ для разработки, позволяющий создавать и совершенствовать навыки для проектов TYPO3 с Cursor IDE. Skill Creator هو أداة تطوير ذكاء اصطناعي تمكن من إنشاء وتحسين المهارات لمشاريع TYPO3 مع Cursor IDE. how to use skill-creator what is skill-creator skill-creator alternative skill-creator vs Cursor IDE skill-creator install guide skill-creator setup for TYPO3 AI-augmented development environment iterative skill refinement claude-with-access-to-the-skill AI增强开发环境 Skill Creator Cursor IDE TYPO3项目 AI工具 开发环境 技能创建 测试和评估 量化评估 Enables iterative skill creation and refinement Supports qualitative and quantitative evaluation of skill results Utilizes claude-with-access-to-the-skill for testing prompts Facilitates drafting of quantitative evaluations Integrates with Cursor IDE for streamlined development skill-creator is an AI-powered tool for creating and iteratively improving skills within the Cursor IDE environment for enterprise TYPO3 projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aircrushin/promptMinder/agent-sdk', 'community', 'aircrushin', 'promptMinder', 'aircrushin/promptMinder', 'agent-sdk', 0, 0, 45, '2026-03-08T01:57:15.296Z', '2026-03-08T02:01:12.443Z', '02bf3f4d2c889d304dd24cad107842f193ac6d6c4656bbba29db1857ec5930c4', '{"id":"aircrushin/promptMinder/agent-sdk","name":"agent-sdk","description":{"en":"The agent-sdk skill enables developers to manage prompts efficiently, leveraging core SDK functions like query() and tool(). It benefits AI agent developers and architects seeking to optimize their prompt management workflows.","zh":"Agent-SDK是一个开源的提示词管理平台，提供query()、tool()和createSdkMcpServer()等核心功能","ja":"Agent-SDKはオープンソースのプロンプト管理プラットフォームで、query()、tool()、createSdkMcpServer()などの機能を提供する","ko":"Agent-SDK는 오픈소스의 프롬프트 관리 플랫폼으로 query()、tool()、createSdkMcpServer() 등의 핵심 기능을 제공합니다","es":"El agent-sdk es una plataforma de código abierto para la gestión de prompts de Agentes de IA, con funciones como query(), tool() y createSdkMcpServer()","fr":"L''agent-sdk est une plateforme open-source pour la gestion de prompts d''Outils d''IA, avec des fonctions telles que query(), tool() et createSdkMcpServer()","de":"Das agent-sdk ist eine Open-Source-Plattform für die Verwaltung von Prompts für KI-Agents, mit Funktionen wie query(), tool() und createSdkMcpServer()","pt":"O agent-sdk é uma plataforma de código aberto para gerenciamento de prompts, com recursos avançados como funções Core SDK e definições de agentes","ru":"agent-sdk - это открытая платформа для управления подсказками, с продвинутыми функциями, такими как основные функции SDK и определения агентов для ИИ Агентов","ar":"agent-sdk هو منصة مفتوحة المصدر لادارة التلميحات، مع ميزات متقدمة مثل وظائف Core SDK وتنسيقات الوكيل"},"seo":{"title":{"en":"agent-sdk: Mastering Prompt Management for AI Agents | AI...","zh":"Agent-SDK开发指南：提示词管理最佳实践","ja":"Agent-SDKセットアップガイド：AIエージェントのプロンプト管理","ko":"Agent-SDK 설정 가이드: 프롬프트 관리를 위한 전문가 팁","es":"Guía de configuración de agent-sdk para Agentes de IA","fr":"Guide de mise en place de l''agent-sdk pour les Outils d''IA","de":"Einrichtungsleitfaden für agent-sdk bei KI-Agents","pt":"Guia de Configuração do agent-sdk: Melhores Práticas para...","ru":"Руководство по настройке agent-sdk: Лучшие практики для р...","ar":"دليل إعداد agent-sdk: أفضل الممارسات للعاملين في مجال الإ..."},"description":{"en":"Unlock the full potential of AI agents with agent-sdk, an open-source platform for prompt management. Learn how to harness its power and streamline your work...","zh":"了解Agent-SDK的核心功能和配置选项，掌握提示词管理的最佳实践","ja":"Agent-SDKの機能と設定オプションをマスターし、AIエージェントのプロンプト管理を最適化する","ko":"Agent-SDK의 핵심 기능과 설정 옵션을 익히고 프롬프트 관리를 위한 전문가 팁을 얻으세요","es":"Aprende a utilizar el SDK de agent-sdk para gestionar promts de manera efectiva y mejorar tus Agentes de IA","fr":"Découvrez comment utiliser l''agent-sdk pour gérer les prompts et améliorer vos Outils d''IA","de":"Erfahren Sie, wie Sie das agent-sdk verwenden, um Prompts effektiv zu verwalten und Ihre KI-Agents zu verbessern","pt":"Aprenda a configurar e utilizar o agent-sdk de forma eficaz, com recursos como funções Core SDK e definições de agentes","ru":"Узнайте, как настроить и эффективно использовать agent-sdk, с функциями, такими как основные функции SDK и определения агентов для ИИ Агентов","ar":"تعرف على كيفية ضبط وتشغيل agent-sdk بشكل فعال، مع ميزات مثل وظائف Core SDK وتنسيقات الوكيل"},"definition":{"en":"agent-sdk is an open-source platform focused on prompt management, providing developers with a robust toolkit for creating and managing AI agent interactions.","zh":"Agent-SDK是一种开源的提示词管理平台，用于管理AI模型的输入和输出","ja":"Agent-SDKはAIモデルへの入出力を管理するオープンソースのプロンプト管理プラットフォームである","ko":"Agent-SDK는 AI 모델의 입력과 출력을 관리하는 오픈소스의 프롬프트 관리 플랫폼입니다","es":"El agent-sdk es un SDK de código abierto para la gestión de prompts de Agentes de IA","fr":"L''agent-sdk est un SDK open-source pour la gestion de prompts d''Outils d''IA","de":"Das agent-sdk ist ein Open-Source-SDK für die Verwaltung von Prompts für KI-Agents","pt":"O que é agent-sdk? Uma plataforma de código aberto para gerenciamento de prompts","ru":"Что такое agent-sdk? Открытая платформа для управления подсказками для ИИ Агентов","ar":"ما هو agent-sdk؟ منصة مفتوحة المصدر لادارة التلميحات"},"features":{"en":["Utilizes core SDK functions: query(), tool(), and createSdkMcpServer()","Supports various configuration options for customized use cases","Enables agent definitions and subagent patterns for complex interactions","Handles tool input/output types for all built-in tools","Allows for MCP server configurations via stdio, SSE, HTTP, and SDK"],"zh":["支持query()、tool()和createSdkMcpServer()等核心功能","提供配置选项和用例","支持Agent定义和子Agent模式","提供工具输入/输出类型","支持MCP服务器配置"],"ja":["query()、tool()、createSdkMcpServer()などの機能をサポート","設定オプションと用例を提供","Agent定義とサブエージェントパターンをサポート","ツール入出力タイプを提供","MCPサーバー設定をサポート"],"ko":["query()、tool()、createSdkMcpServer() 등의 핵심 기능을 지원","설정 옵션과 사용 사례를 제공","에이전트 정의와 하위 에이전트 패턴을 지원","도구 입력/출력 유형을 제공","MCP 서버 설정을 지원"],"es":["Funciones de SDK como query(), tool() y createSdkMcpServer()","Opciones de configuración y casos de uso","Definiciones de agentes y patrones de subagentes","Tipos de entrada/salida de herramientas para herramientas integradas","Configuraciones de servidores MCP: stdio, SSE, HTTP, SDK"],"fr":["Fonctions de SDK comme query(), tool() et createSdkMcpServer()","Options de configuration et cas d''utilisation","Définitions d''agents et modèles de sous-agents","Types d''entrée/sortie d''outils pour les outils intégrés","Configurations de serveurs MCP : stdio, SSE, HTTP, SDK"],"de":["SDK-Funktionen wie query(), tool() und createSdkMcpServer()","Konfigurationsoptionen und Anwendungsfälle","Agentendefinitionen und Subagentenmuster","Eingabe-/Ausgabetypen für integrierte Tools","MCP-Server-Konfigurationen: stdio, SSE, HTTP, SDK"],"pt":["Funções Core SDK: query(), tool(), createSdkMcpServer()","Opções de configuração e casos de uso","Definições de agentes e padrões de subagentes","Tipos de entrada/saída de ferramentas para todas as ferramentas integradas","Configurações do servidor MCP: stdio, SSE, HTTP, SDK"],"ru":["Основные функции SDK: query(), tool(), createSdkMcpServer()","Варианты конфигурации и их случаи использования для ИИ Агентов","Определения агентов и шаблоны субагентов","Типы входных/выходных данных инструментов для всех встроенных инструментов","Конфигурации сервера MCP: stdio, SSE, HTTP, SDK"],"ar":["وظائف Core SDK: query(), tool(), createSdkMcpServer()","خيارات التكوين وحالات الاستخدام","تنسيقات الوكيل وأنماط الفرع","أنواع الإدخال/الإخراج للأدوات لجميع الأدوات المدمجة","تكوينات خادم MCP: stdio, SSE, HTTP, SDK"]},"keywords":{"en":["how to use agent-sdk","agent-sdk setup guide","what is agent-sdk","agent-sdk alternative","agent-sdk vs other prompt management tools","agent-sdk install","mastering prompt management with agent-sdk","agent-sdk for AI agents","agent-sdk tutorial","agent-sdk documentation"],"zh":["Agent-SDK","提示词管理","AI模型","开源平台","核心功能","配置选项","Agent定义","子Agent模式","工具输入/输出类型","MCP服务器配置"],"ja":["Agent-SDK","AIエージェント","プロンプト管理","オープンソースプラットフォーム","コア機能","設定オプション","エージェント定義","サブエージェントパターン","ツール入出力タイプ","MCPサーバー設定"],"ko":["Agent-SDK","AI 에이전트","프롬프트 관리","오픈소스 플랫폼","핵심 기능","설정 옵션","에이전트 정의","하위 에이전트 패턴","도구 입력/출력 유형","MCP 서버 설정"],"es":["agent-sdk","Agentes de IA","gestión de prompts","SDK de código abierto","desarrollo de Agentes de IA","integración de herramientas","configuración de servidores MCP"],"fr":["agent-sdk","Outils d''IA","gestion de prompts","SDK open-source","développement d''Outils d''IA","intégration d''outils","configuration de serveurs MCP"],"de":["agent-sdk","KI-Agents","Verwaltung von Prompts","Open-Source-SDK","Entwicklung von KI-Agents","Integration von Tools","Konfiguration von MCP-Servern"],"pt":["agent-sdk","gerenciamento de prompts","funções Core SDK","definições de agentes","configuração de servidor MCP","desenvolvimento de IA","ferramentas de IA","plataforma de código aberto"],"ru":["agent-sdk","управление подсказками","основные функции SDK","определения агентов","конфигурация сервера MCP","разработка ИИ","инструменты ИИ","открытая платформа"],"ar":["agent-sdk","ادارة التلميحات","وظائف Core SDK","تنسيقات الوكيل","تكوين خادم MCP","تطوير الإي أيه","أدوات الإي أيه","منصة مفتوحة المصدر"]}},"owner":"aircrushin","repo":"promptMinder","repoPath":"aircrushin/promptMinder","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.296Z","topics":[],"category":"community","skillMd":{"name":"agent-sdk","description":"Expert in Claude Agent SDK development. Use when users ask about SDK API, agent configuration, MCP servers, hooks, permissions, file checkpointing, or when they mention @AGENT_SDK_DOCS.md. Provides accurate API reference, code examples with TypeScript types, and best practices.","bodyPreview":"You are a Claude Agent SDK expert with deep knowledge of the TypeScript SDK API, architecture, and best practices.\n\n## Your Expertise\n\n- Core SDK functions: `query()`, `tool()`, `createSdkMcpServer()`\n- Configuration options and their use cases (see AGENT_SDK_DOCS.md:90-133)\n- Agent definitions and subagent patterns (see AGENT_SDK_DOCS.md:166-185)\n- Tool input/output types for all built-in tools (see AGENT_SDK_DOCS.md:819-1816)\n- MCP server configurations: stdio, SSE, HTTP, SDK (see AGENT_SDK_DO","body":"You are a Claude Agent SDK expert with deep knowledge of the TypeScript SDK API, architecture, and best practices.\n\n## Your Expertise\n\n- Core SDK functions: `query()`, `tool()`, `createSdkMcpServer()`\n- Configuration options and their use cases (see AGENT_SDK_DOCS.md:90-133)\n- Agent definitions and subagent patterns (see AGENT_SDK_DOCS.md:166-185)\n- Tool input/output types for all built-in tools (see AGENT_SDK_DOCS.md:819-1816)\n- MCP server configurations: stdio, SSE, HTTP, SDK (see AGENT_SDK_DOCS.md:323-374)\n- Hook events and callback patterns (see AGENT_SDK_DOCS.md:571-817)\n- Permission modes and custom authorization (see AGENT_SDK_DOCS.md:280-322)\n- File checkpointing and rewind functionality (see AGENT_SDK_DOCS.md:134-165)\n- Session management and resumption (see AGENT_SDK_DOCS.md:104-127)\n- Structured outputs with JSON schemas (see AGENT_SDK_DOCS.md:120)\n- Sandbox configuration and security (see AGENT_SDK_DOCS.md:2025-2167)\n\n## When Answering Questions\n\n1. **Be Accurate**: Base all answers on AGENT_SDK_DOCS.md. Reference specific sections with file paths and line numbers (e.g., \"See AGENT_SDK_DOCS.md:90-133\")\n\n2. **Include Code Examples**: Always provide TypeScript examples with proper types:\n   ```typescript\n   import { query } from \"@anthropic-ai/claude-agent-sdk\";\n\n   const result = await query({\n     prompt: \"Analyze this code\",\n     options: {\n       model: \"claude-sonnet-4-5-20250929\",\n       permissionMode: \"bypassPermissions\"\n     }\n   });\n   ```\n\n3. **Explain Trade-offs**: When multiple approaches exist, explain the pros and cons of each:\n   - \"Using `settingSources: [''project'']` loads only team settings, while `[''user'', ''project'', ''local'']` loads all settings with precedence rules\"\n   - \"Stream mode with AsyncIterable<SDKUserMessage> enables interactive features but requires managing the async generator\"\n\n4. **Suggest Best Practices**:\n   - Use `settingSources: [''project'']` in CI/CD for consistency\n   - Enable `enableFileCheckpointing: true` when you might need to undo changes\n   - Define agents programmatically for SDK-only applications\n   - Use hooks for cross-cutting concerns like logging, telemetry, or custom permissions\n\n5. **Warn About Security**:\n   - `permissionMode: ''bypassPermissions''` requires `allowDangerfullySkipPermissions: true`\n   - Sandbox exclusions (`excludedCommands`) bypass all restrictions automatically\n   - `dangerouslyDisableSandbox: true` requires careful `canUseTool` validation\n   - Never commit secrets or credentials\n\n6. **Keep It Concise but Thorough**: Provide complete information but avoid verbosity. Focus on what the user needs to know.\n\n## Common Patterns\n\n### Basic Query\n```typescript\nimport { query } from \"@anthropic-ai/claude-agent-sdk\";\n\nfor await (const message of query({ prompt: \"Hello!\" })) {\n  console.log(message);\n}\n```\n\n### With Streaming Input\n```typescript\nimport { query } from \"@anthropic-ai/claude-agent-sdk\";\n\nasync function* userInput() {\n  yield { type: ''user'', content: ''Step 1'' };\n  // ... some logic ...\n  yield { type: ''user'', content: ''Step 2'' };\n}\n\nconst q = query({\n  prompt: userInput(),\n  options: { includePartialMessages: true }\n});\n\nfor await (const msg of q) {\n  console.log(msg);\n}\n```\n\n### Custom MCP Tool\n```typescript\nimport { tool, createSdkMcpServer } from \"@anthropic-ai/claude-agent-sdk\";\nimport { z } from \"zod\";\n\nconst myTool = tool(\n  \"my-tool\",\n  \"Does something useful\",\n  {\n    param1: z.string(),\n    param2: z.number().optional()\n  },\n  async (args, extra) => {\n    return {\n      content: [{ type: \"text\", text: `Result: ${args.param1}` }]\n    };\n  }\n);\n\nconst server = createSdkMcpServer({\n  name: \"my-server\",\n  tools: [myTool]\n});\n```\n\n### Permission Hook\n```typescript\nconst result = query({\n  prompt: \"Make changes\",\n  options: {\n    hooks: {\n      PreToolUse: [{\n        hooks: [async (input) => {\n          if (input.tool_name === \"Write\" && input.tool_input.file_path.endsWith(\".env\")) {\n            return { decision: ''block'', reason: \"Cannot write to .env files\" };\n          }\n          return { decision: ''approve'' };\n        }]\n      }]\n    }\n  }\n});\n```\n\n## Key Documentation Sections\n\n| Topic | Location |\n|-------|----------|\n| Installation | AGENT_SDK_DOCS.md:13-17 |\n| query() Function | AGENT_SDK_DOCS.md:21-45 |\n| Options Reference | AGENT_SDK_DOCS.md:90-133 |\n| Agent Definition | AGENT_SDK_DOCS.md:166-185 |\n| Setting Sources | AGENT_SDK_DOCS.md:186-279 |\n| Permission Modes | AGENT_SDK_DOCS.md:280-288 |\n| MCP Server Configs | AGENT_SDK_DOCS.md:323-374 |\n| Hook Events | AGENT_SDK_DOCS.md:575-593 |\n| Tool Input Types | AGENT_SDK_DOCS.md:819-1278 |\n| Tool Output Types | AGENT_SDK_DOCS.md:1279-1816 |\n| Sandbox Settings | AGENT_SDK_DOCS.md:2025-2167 |\n\n## When Uncertain\n\nIf you''re not 100% sure about an answer:\n1. Say \"Let me check the documentation\"\n2. Read AGENT_SDK_DOCS.md using the Read tool\n3. Provide the specific reference (e.g., \"According to AGENT_SDK_DOCS.md:90-133...\")\n4. Never make up API details or assume behavior\n"},"lastSynced":"2026-03-08T02:01:12.443Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agent Developers seeking to optimize prompt management workflows with core SDK functions like query() and tool().","zh":"适合寻求优化提示管理工作流程的AI代理开发人员，使用核心SDK函数，如query()和tool()。","ja":"query()およびtool()などのコアSDK関数を使用してプロンプト管理ワークフローを最適化するAIエージェント開発者に適しています。","ko":"query() 및 tool()와 같은 코어 SDK 함수를 사용하여 프롬프트 관리 워크플로를 최적화하려는 AI 에이전트 개발자에게 적합합니다.","es":"Ideal para desarrolladores de agentes de inteligencia artificial que buscan optimizar flujos de trabajo de administración de prompts con funciones de SDK principal como query() y tool().","fr":"Idéal pour les développeurs d''agents d''intelligence artificielle cherchant à optimiser les flux de travail de gestion de invites avec des fonctions de SDK de base comme query() et tool().","de":"Ideal für AI-Agent-Entwickler, die Workflows zur Promptverwaltung mit Core-SDK-Funktionen wie query() und tool() optimieren möchten.","pt":"Ideal para desenvolvedores de Agentes de IA que buscam otimizar fluxos de trabalho de gerenciamento de prompts com funções de SDK principais como query() e tool().","ru":"Идеально для разработчиков агентов ИИ, стремящихся оптимизировать рабочие процессы управления подсказками с помощью основных функций SDK, таких как query() и tool().","ar":"مثالي لمطوري وكلاء الذكاء الاصطناعي الذين يبحثون عن تحسين تدفقات العمل لادارة الاستفسارات باستخدام وظائف SDK الاساسية مثل query() و tool()."},"recommendation":{"en":"Empowers agents to efficiently manage prompts using the TypeScript SDK API, leveraging configuration options, agent definitions, and tool input/output types for built-in tools, while supporting various MCP server configurations such as stdio, SSE, and HTTP.","zh":"通过TypeScript SDK API赋予代理高效地管理提示的能力，利用配置选项、代理定义和内置工具的工具输入/输出类型，同时支持各种MCP服务器配置，例如stdio、SSE和HTTP。","ja":"TypeScript SDK APIを使用して、エージェントがプロンプトを効率的に管理できるようにします。構成オプション、エージェント定義、および組み込みツールのツール入力/出力タイプを利用し、stdio、SSE、HTTPなどのさまざまなMCPサーバー構成をサポートします。","ko":"TypeScript SDK API를 사용하여 에이전트가 프롬프트를 효율적으로 관리할 수 있도록 합니다. 구성 옵션, 에이전트 정의 및 내장 도구의 도구 입력/출력 유형을 활용하며 stdio, SSE, HTTP와 같은 다양한 MCP 서버 구성도 지원합니다.","es":"Habilita a los agentes a gestionar eficientemente las promts utilizando la API de SDK de TypeScript, aprovechando opciones de configuración, definiciones de agentes y tipos de entrada/salida de herramientas para herramientas integradas, mientras admite varias configuraciones de servidor MCP como stdio, SSE y HTTP.","fr":"Permet aux agents de gérer efficacement les invites en utilisant l''API de SDK de TypeScript, en exploitant les options de configuration, les définitions d''agents et les types d''entrée/sortie d''outils pour les outils intégrés, tout en prenant en charge diverses configurations de serveur MCP telles que stdio, SSE et HTTP.","de":"Ermächtigt Agenten, Prompts effizient mit der TypeScript-SDK-API zu verwalten, indem sie Konfigurationsoptionen, Agentendefinitionen und Tool-Ein-/Ausgabetypen für integrierte Tools nutzen, während sie verschiedene MCP-Serverkonfigurationen wie stdio, SSE und HTTP unterstützen.","pt":"Permite que os agentes gerenciem prompts de forma eficiente usando a API do SDK do TypeScript, aproveitando opções de configuração, definições de agente e tipos de entrada/saída de ferramentas para ferramentas integradas, além de suportar várias configurações de servidor MCP, como stdio, SSE e HTTP.","ru":"Наделяет агентов возможностью эффективно управлять подсказками, используя API SDK TypeScript, используя опции конфигурации, определения агентов и типы ввода/вывода инструментов для встроенных инструментов, а также поддержку различных конфигураций сервера MCP, таких как stdio, SSE и HTTP.","ar":"تمكّن الوكلاء من إدارة الاستفسارات بفعالية باستخدام واجهة برمجة تطبيقات SDK من TypeScript، واستخدام خيارات التهيئة وتعريفات الوكيل وأنواع الإدخال/الإخراج للأدوات للمدخلات المدمجة، مع دعم مختلف-configurations للخادم MCP مثل stdio و SSE و HTTP."},"useCases":{"en":["Automating prompt workflows with query() and tool() functions","Configuring and optimizing agent definitions and subagent patterns","Debugging tool input/output types for seamless integration with built-in tools"],"zh":["使用query()和tool()函数自动化提示工作流程","配置和优化代理定义和子代理模式","调试工具输入/输出类型以实现与内置工具的无缝集成"],"ja":["query()およびtool()関数を使用してプロンプトワークフローを自動化する","エージェント定義およびサブエージェントパターンを構成および最適化する","組み込みツールとのシームレスな統合を実現するためのツール入力/出力タイプのデバッグ"],"ko":["query() 및 tool() 함수를 사용하여 프롬프트 워크플로를 자동화하는 것","에이전트 정의 및 서브 에이전트 패턴을 구성 및 최적화하는 것","내장 도구와의 무결점 통합을 달성하기 위한 도구 입력/출력 유형 디버깅"],"es":["Automatizar flujos de trabajo de prompts con funciones query() y tool()","Configurar y optimizar definiciones de agentes y patrones de subagentes","Depurar tipos de entrada/salida de herramientas para una integración sin problemas con herramientas integradas"],"fr":["Automatiser les flux de travail d''invites avec des fonctions query() et tool()","Configurer et optimiser les définitions d''agents et les modèles de sous-agents","Déboguer les types d''entrée/sortie d''outils pour une intégration transparente avec les outils intégrés"],"de":["Automatisieren von Prompt-Workflows mit query()- und tool()-Funktionen","Konfigurieren und Optimieren von Agentendefinitionen und Subagentenmustern","Debuggen von Tool-Ein-/Ausgabetypen für eine nahtlose Integration mit integrierten Tools"],"pt":["Automatizar fluxos de trabalho de prompts com funções query() e tool()","Configurar e otimizar definições de agente e padrões de subagente","Depurar tipos de entrada/saída de ferramentas para integração perfeita com ferramentas integradas"],"ru":["Автоматизировать рабочие процессы подсказок с помощью функций query() и tool()","Настроить и оптимизировать определения агентов и подагент-паттерны","Отладить типы ввода/вывода инструментов для бесшовной интеграции с встроенными инструментами"],"ar":["أتمتة تدفقات العمل للاستفسارات باستخدام وظائف query() و tool()","تهيئة وتحسين تعريفات الوكيل وأنماط فرعي الوكيل","تصحيح أخطاء أنواع الإدخال/الإخراج للأدوات من أجل التكامل السلس مع الأدوات المدمجة"]},"limitations":{"en":["Requires knowledge of TypeScript SDK API and architecture","Dependent on MCP server configurations and compatibility","Limited to AI agent developers and architects familiar with AGENT_SDK_DOCS.md"],"zh":["需要TypeScript SDK API和架构的知识","依赖于MCP服务器配置和兼容性","仅限于熟悉AGENT_SDK_DOCS.md的AI代理开发人员和架构师"],"ja":["TypeScript SDK APIおよびアーキテクチャの知識が必要","MCPサーバー構成および互換性に依存","AGENT_SDK_DOCS.mdに精通したAIエージェント開発者およびアーキテクトのみが対象"],"ko":["TypeScript SDK API 및 아키텍처에 대한 지식이 필요함","MCP 서버 구성 및 호환성에 의존함","AGENT_SDK_DOCS.md에 익숙한 AI 에이전트 개발자 및 아키텍트만 해당"],"es":["Requiere conocimiento de la API y la arquitectura de TypeScript SDK","Dependiente de las configuraciones y la compatibilidad del servidor MCP","Limitado a desarrolladores y arquitectos de agentes de inteligencia artificial familiarizados con AGENT_SDK_DOCS.md"],"fr":["Nécessite des connaissances sur l''API et l''architecture de TypeScript SDK","Dépend des configurations et de la compatibilité du serveur MCP","Limité aux développeurs et architectes d''agents d''intelligence artificielle familiers avec AGENT_SDK_DOCS.md"],"de":["Benötigt Kenntnisse über die API und Architektur von TypeScript SDK","Abhängig von MCP-Serverkonfigurationen und Kompatibilität","Eingeschränkt auf AI-Agent-Entwickler und Architekten, die mit AGENT_SDK_DOCS.md vertraut sind"],"pt":["Exige conhecimento da API do SDK do TypeScript e arquitetura","Depende de configurações de servidor MCP e compatibilidade","Limitado a desenvolvedores e arquitetos de agentes de IA familiarizados com AGENT_SDK_DOCS.md"],"ru":["Требует знания API SDK TypeScript и архитектуры","Зависит от конфигураций сервера MCP и совместимости","Ограничен разработчиками и архитекторами агентов ИИ, знакомыми с AGENT_SDK_DOCS.md"],"ar":["يتطلب معرفة واجهة برمجة تطبيقات SDK من TypeScript والهيكل","يعتمد على إعدادات خادم MCP ومتطلبات التوافق","محدود بمطوري ومهندسي وكلاء الذكاء الاصطناعي الذين يعتزون بمستندات AGENT_SDK_DOCS.md"]},"version":4},"contentHash":"02bf3f4d2c889d304dd24cad107842f193ac6d6c4656bbba29db1857ec5930c4","qualityScore":45}');
