INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aircrushin/promptMinder/agent-sdk', 'agent-sdk', 'aircrushin', 'promptMinder', 'community', 'agent-sdk aircrushin promptMinder community The agent-sdk skill enables developers to manage prompts efficiently, leveraging core SDK functions like query() and tool(). It benefits AI agent developers and architects seeking to optimize their prompt management workflows. Agent-SDK是一个开源的提示词管理平台，提供query()、tool()和createSdkMcpServer()等核心功能 Agent-SDKはオープンソースのプロンプト管理プラットフォームで、query()、tool()、createSdkMcpServer()などの機能を提供する Agent-SDK는 오픈소스의 프롬프트 관리 플랫폼으로 query()、tool()、createSdkMcpServer() 등의 핵심 기능을 제공합니다 El agent-sdk es una plataforma de código abierto para la gestión de prompts de Agentes de IA, con funciones como query(), tool() y createSdkMcpServer() L''agent-sdk est une plateforme open-source pour la gestion de prompts d''Outils d''IA, avec des fonctions telles que query(), tool() et createSdkMcpServer() Das agent-sdk ist eine Open-Source-Plattform für die Verwaltung von Prompts für KI-Agents, mit Funktionen wie query(), tool() und createSdkMcpServer() O agent-sdk é uma plataforma de código aberto para gerenciamento de prompts, com recursos avançados como funções Core SDK e definições de agentes agent-sdk - это открытая платформа для управления подсказками, с продвинутыми функциями, такими как основные функции SDK и определения агентов для ИИ Агентов agent-sdk هو منصة مفتوحة المصدر لادارة التلميحات، مع ميزات متقدمة مثل وظائف Core SDK وتنسيقات الوكيل how to use agent-sdk agent-sdk setup guide what is agent-sdk agent-sdk alternative agent-sdk vs other prompt management tools agent-sdk install mastering prompt management with agent-sdk agent-sdk for AI agents agent-sdk tutorial agent-sdk documentation Agent-SDK 提示词管理 AI模型 开源平台 核心功能 配置选项 Agent定义 子Agent模式 工具输入/输出类型 MCP服务器配置 Utilizes core SDK functions: query(), tool(), and createSdkMcpServer() Supports various configuration options for customized use cases Enables agent definitions and subagent patterns for complex interactions Handles tool input/output types for all built-in tools Allows for MCP server configurations via stdio, SSE, HTTP, and SDK agent-sdk is an open-source platform focused on prompt management, providing developers with a robust toolkit for creating and managing AI agent interactions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('VilnaCRM-Org/user-service/quality-standards', 'community', 'VilnaCRM-Org', 'user-service', 'VilnaCRM-Org/user-service', 'quality-standards', 0, 0, 45, '2026-03-08T01:57:15.296Z', '2026-03-08T02:01:14.074Z', 'f3cf6c31c875536be97cdd16a2a53b1c129f091fef842d40e19ba2cf65eb4430', '{"id":"VilnaCRM-Org/user-service/quality-standards","name":"quality-standards","description":{"en":"The quality-standards skill helps developers understand quality metrics and route issues to appropriate specialized skills for fixes, ensuring protected quality thresholds. It benefits developers working with AI agents","zh":"质量标准技能帮助开发者了解保护质量阈值，运行综合质量检查，并确定特定问题的解决方案","ja":"品質基準スキルは、開発者が保護品質閾値を理解し、包括的な品質チェックを実行し、特定の問題の解決策を決定するのに役立ちます","ko":"품질 표준 스킬은 개발자가 보호 품질 임계값을 이해하고 포괄적인 품질 점검을 실행하며 특정 문제의 해결책을 결정하는 데 도움이 됩니다","es":"Estándares de calidad para agentes de IA que permiten comprender métricas de calidad y determinar habilidades especializadas","fr":"Normes de qualité pour outils d''IA qui permettent de comprendre les métriques de qualité et de déterminer les compétences spécialisées","de":"Qualitätsstandards für KI-Tools, die es ermöglichen, Qualitätsmetriken zu verstehen und spezialisierte Fähigkeiten zu bestimmen","pt":"O skill de padrões de qualidade ajuda a entender métricas de qualidade e aplicar correções específicas. Entenda como configurar limiares de qualidade protegidos","ru":"ИИ Агенты для контроля качества помогают понять метрики качества и применить исправления. Узнайте, как настроить защищенные пороги качества","ar":"الأجهزة الذكية الإصطناعية لمعايير الجودة تساعد على فهم معايير الجودة وتطبيق الإصلاحات المحددة. تعرف على كيفية إعداد حدود جودة محمية"},"seo":{"title":{"en":"Quality-Standards: Setup Guide for AI Agents","zh":"质量标准设置指南 - AIエージェント","ja":"品質基準設定ガイド - AIエージェント","ko":"품질 표준 설정 가이드 - AI 에이전트","es":"Configuración de estándares de calidad para agentes de IA","fr":"Mise en place des normes de qualité pour les outils d''IA","de":"Einrichtung von Qualitätsstandards für KI-Tools","pt":"Guia de Configuração de Padrões de Qualidade para Desenvo...","ru":"Настройка инструментов контроля качества: ИИ Агенты для р...","ar":"دليل إعداد معايير الجودة للأجهزة الذكية الإصطناعية"},"description":{"en":"Discover how to implement quality-standards in your AI agent workflow. Learn to route quality issues to specialized skills and ensure protected quality thres...","zh":"了解质量标准技能，设置指南，最佳实践，和技术细节，包括保护质量阈值，运行综合质量检查等","ja":"品質基準スキルを理解するための設定ガイド、ベストプラクティス、技術的な詳細を紹介します","ko":"품질 표준 스킬을 이해하는 설정 가이드, 최선의 관행, 기술적인 세부 사항을 제공합니다","es":"Aprenda a configurar estándares de calidad para agentes de IA con nuestra guía paso a paso","fr":"Découvrez comment mettre en place des normes de qualité pour les outils d''IA avec notre guide détaillé","de":"Erfahren Sie, wie Sie Qualitätsstandards für KI-Tools einrichten können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar padrões de qualidade com o skill de padrões de qualidade. Entenda métricas de qualidade e aplique correções específicas","ru":"Узнайте, как настроить контроль качества с помощью ИИ Агентов. Поймите метрики качества и примените исправления","ar":"تعرف على كيفية إعداد معايير الجودة باستخدام الأجهزة الذكية الإصطناعية. افهم معايير الجودة وتطبيق الإصلاحات المحددة"},"definition":{"en":"quality-standards is a skill that understands quality metrics and routes issues to specialized skills for fixes, ensuring adherence to protected quality thresholds","zh":"质量标准技能是指帮助开发者理解和应用质量标准的AI能力","ja":"品質基準スキルは、開発者が品質基準を理解し、適用するのを支援するAIの能力です","ko":"품질 표준 스킬은 개발자가 품질 표준을 이해하고 적용하는 것을 지원하는 AI 능력입니다","es":"Estándares de calidad son reglas críticas para evaluar la calidad de los agentes de IA","fr":"Les normes de qualité sont des règles critiques pour évaluer la qualité des outils d''IA","de":"Qualitätsstandards sind kritische Regeln zur Bewertung der Qualität von KI-Tools","pt":"Padrões de qualidade são um conjunto de regras para garantir a qualidade do código","ru":"Контроль качества - это набор правил для обеспечения качества кода","ar":"معايير الجودة هي مجموعة من القواعد لضمان جودة الكود"},"features":{"en":["Understands protected quality thresholds","Runs comprehensive quality checks before commit","Determines which specialized skill to use for specific issues","Provides quick reference for quality tool commands","Routes quality issues to appropriate specialized skills for fixes"],"zh":["保护质量阈值","运行综合质量检查","确定特定问题的解决方案","提供快速参考质量工具命令","支持CRITICAL级别的质量检查"],"ja":["保護品質閾値","包括的な品質チェックの実行","特定の問題の解決策の決定","品質ツールコマンドのクイックリファレンス","CRITICALレベルの品質チェックのサポート"],"ko":["보호 품질 임계값","포괄적인 품질 점검의 실행","특정 문제의 해결책의 결정","품질 도구 명령의 빠른 참조","CRITICAL 레벨의 품질 점검의 지원"],"es":["Comprender umbrales de calidad protegidos","Ejecutar verificaciones de calidad exhaustivas antes de comprometer","Determinar habilidades especializadas para problemas de calidad específicos","Referencia rápida para comandos de herramientas de calidad"],"fr":["Comprendre les seuils de qualité protégés","Exécuter des vérifications de qualité exhaustives avant de valider","Déterminer les compétences spécialisées pour les problèmes de qualité spécifiques","Référence rapide pour les commandes d''outils de qualité"],"de":["Verstehen geschützter Qualitäts-Schwellenwerte","Ausführung umfassender Qualitätsprüfungen vor dem Commit","Bestimmen spezialisierter Fähigkeiten für spezifische Qualitätsprobleme","Schnellreferenz für Qualitäts-Tool-Befehle"],"pt":["Entendimento de limiares de qualidade protegidos","Execução de verificações de qualidade abrangentes antes do commit","Determinação da habilidade especializada certa para problemas específicos","Referência rápida para comandos de ferramentas de qualidade"],"ru":["Понимание защищенных порогов качества","Выполнение комплексных проверок качества перед коммитом","Определение специализированной навыка для конкретных проблем","Быстрая ссылка на команды инструментов качества"],"ar":["فهم حدود جودة محمية","تنفيذ فحص جودة شاملة قبل الإلتزام","تحديد المهارة المتخصصة الصحيحة لمشاكل محددة","مرجع سريع لأوامر أدوات الجودة"]},"keywords":{"en":["how to use quality-standards","quality-standards setup guide","quality-standards alternative","quality-standards vs code analysis tools","implementing quality-standards in AI agents","quality-standards install"],"zh":["质量标准","AIエージェント","保护质量阈值","综合质量检查","特定问题解决","质量工具命令","CRITICAL质量检查"],"ja":["品質基準","AIエージェント","保護品質閾値","包括的な品質チェック","特定の問題の解決","品質ツールコマンド","CRITICAL品質チェック"],"ko":["품질 표준","AI 에이전트","보호 품질 임계값","포괄적인 품질 점검","특정 문제의 해결","품질 도구 명령","CRITICAL 품질 점검"],"es":["estándares de calidad para agentes de IA","herramientas de calidad para desarrolladores","evaluación de calidad de software","mejora de la calidad del código","agentes de IA para desarrollo","herramientas de desarrollo de IA"],"fr":["normes de qualité pour outils d''IA","outils de qualité pour développeurs","évaluation de la qualité des logiciels","amélioration de la qualité du code","outils d''IA pour développement","outils de développement d''IA"],"de":["Qualitätsstandards für KI-Tools","Qualitätstools für Entwickler","Bewertung der Qualität von Software","Verbesserung der Code-Qualität","KI-Tools für Entwicklung","Entwicklungstools für KI"],"pt":["padrões de qualidade","controle de qualidade","desenvolvimento de software","ferramentas de qualidade","commit de código","verificação de qualidade","navegação de código"],"ru":["контроль качества","ИИ Агенты","разработка программного обеспечения","инструменты качества","коммит кода","проверка качества","навигация кода"],"ar":["معايير الجودة","أجهزة ذكية إصطناعية","تطوير البرمجيات","أدوات الجودة","التزام الكود","فحص الجودة","تنقل الكود"]}},"owner":"VilnaCRM-Org","repo":"user-service","repoPath":"VilnaCRM-Org/user-service","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.296Z","topics":[],"category":"community","skillMd":{"name":"quality-standards","description":"Overview of protected quality thresholds and quick reference for all quality tools. Use when you need to understand quality metrics, run comprehensive quality checks, or learn which specialized skill to use. For specific issues, use dedicated skills (deptrac-fixer for Deptrac, complexity-management for PHPInsights, testing-workflow for coverage).","bodyPreview":"# Quality Standards Skill\n\n## Context (Input)\n\n- Need to understand protected quality thresholds\n- Running comprehensive quality checks before commit\n- Determining which specialized skill to use for specific issues\n- Quick reference for quality tool commands\n\n## Task (Function)\n\nUnderstand quality metrics and route to appropriate specialized skill for fixes.\n\n**Success Criteria**: Know which skill to use for your specific quality issue.\n\n## Protected Quality Thresholds\n\n**CRITICAL**: These thres","body":"# Quality Standards Skill\n\n## Context (Input)\n\n- Need to understand protected quality thresholds\n- Running comprehensive quality checks before commit\n- Determining which specialized skill to use for specific issues\n- Quick reference for quality tool commands\n\n## Task (Function)\n\nUnderstand quality metrics and route to appropriate specialized skill for fixes.\n\n**Success Criteria**: Know which skill to use for your specific quality issue.\n\n## Protected Quality Thresholds\n\n**CRITICAL**: These thresholds are protected and must NEVER be lowered.\n\n### PHPInsights (Source Code)\n\n| Metric       | Required | Fix With                                                   |\n| ------------ | -------- | ---------------------------------------------------------- |\n| Quality      | 100%     | [complexity-management](../complexity-management/SKILL.md) |\n| Complexity   | 94%      | [complexity-management](../complexity-management/SKILL.md) |\n| Architecture | 100%     | [deptrac-fixer](../deptrac-fixer/SKILL.md)                 |\n| Style        | 100%     | Run `make phpcsfixer`                                      |\n\n### PHPInsights (Tests)\n\n| Metric       | Required | Fix With                                                   |\n| ------------ | -------- | ---------------------------------------------------------- |\n| Quality      | 95%      | [complexity-management](../complexity-management/SKILL.md) |\n| Complexity   | 95%      | [complexity-management](../complexity-management/SKILL.md) |\n| Architecture | 90%      | [deptrac-fixer](../deptrac-fixer/SKILL.md)                 |\n| Style        | 95%      | Run `make phpcsfixer`                                      |\n\n### Other Tools\n\n| Tool      | Metric          | Required | Fix With                                         |\n| --------- | --------------- | -------- | ------------------------------------------------ |\n| Deptrac   | Violations      | 0        | [deptrac-fixer](../deptrac-fixer/SKILL.md)       |\n| Psalm     | Errors          | 0        | Fix reported issues                              |\n| Psalm     | Security Issues | 0        | Fix tainted flows                                |\n| Infection | MSI             | 100%     | [testing-workflow](../testing-workflow/SKILL.md) |\n| PHPUnit   | Coverage        | 100%     | [testing-workflow](../testing-workflow/SKILL.md) |\n\n## Quick Reference Commands\n\n### Comprehensive Checks\n\n```bash\n# Run all CI checks (recommended before commit)\nmake ci\n```\n\n**Success**: Must output \"✅ CI checks successfully passed!\"\n\n### Individual Quality Checks\n\n| Check               | Command                  | Purpose                      |\n| ------------------- | ------------------------ | ---------------------------- |\n| Code quality        | `make phpinsights`       | All PHPInsights metrics      |\n| Complexity analysis | `make phpmd`             | Find high-complexity methods |\n| Static analysis     | `make psalm`             | Type checking and errors     |\n| Security taint      | `make psalm-security`    | Security vulnerability scan  |\n| Architecture        | `make deptrac`           | Layer boundary validation    |\n| Code style          | `make phpcsfixer`        | Auto-fix PSR-12 style        |\n| Composer validation | `make composer-validate` | Validate composer.json       |\n\n### Testing Commands\n\n| Check             | Command                    | Purpose                     |\n| ----------------- | -------------------------- | --------------------------- |\n| Unit tests        | `make unit-tests`          | Domain/Application logic    |\n| Integration tests | `make integration-tests`   | Component interactions      |\n| E2E tests         | `make behat`               | Full user scenarios (Behat) |\n| All tests         | `make all-tests`           | Unit + Integration + E2E    |\n| Test coverage     | `make tests-with-coverage` | Generate coverage report    |\n| Mutation tests    | `make infection`           | Test quality validation     |\n\n## Routing to Specialized Skills\n\nWhen quality checks fail, use the appropriate specialized skill:\n\n### Architecture Issues\n\n- **Deptrac violations** → [deptrac-fixer](../deptrac-fixer/SKILL.md)\n\n  - Domain depends on Infrastructure\n  - Layer boundary violations\n  - \"must not depend on\" errors\n\n- **DDD architecture patterns** → [implementing-ddd-architecture](../implementing-ddd-architecture/SKILL.md)\n  - Creating new entities/value objects\n  - Implementing CQRS patterns\n  - Understanding layer responsibilities\n\n### Code Quality Issues\n\n- **High cyclomatic complexity** → [complexity-management](../complexity-management/SKILL.md)\n\n  - PHPInsights complexity < 94%\n  - PHPMD reports high CCN\n  - Methods too complex\n\n- **Code style issues** → Run `make phpcsfixer`\n  - PSR-12 violations\n  - Line length > 100 chars\n  - Formatting issues\n\n### Testing Issues\n\n- **Test failures** → [testing-workflow](../testing-workflow/SKILL.md)\n  - Unit/Integration/E2E failures\n  - Mutation testing (Infection)\n  - Test coverage < 100%\n\n### Workflow Integration\n\n- **Before committing** → [ci-workflow](../ci-workflow/SKILL.md)\n\n  - Run all checks systematically\n  - Fix failures in priority order\n  - Ensure all checks pass\n\n- **PR review feedback** → [code-review](../code-review/SKILL.md)\n  - Fetch and address PR comments\n  - Systematic comment resolution\n\n## Quality Improvement Workflow\n\n### Step 1: Run Comprehensive Checks\n\n```bash\nmake ci\n```\n\n### Step 2: Identify Failing Check\n\nCheck output for specific failure:\n\n```\n❌ CI checks failed:\n  - phpinsights: Complexity score too low (93.5% < 94%)\n```\n\n### Step 3: Use Specialized Skill\n\nBased on failure type, use appropriate skill:\n\n| Failure Pattern            | Skill to Use             |\n| -------------------------- | ------------------------ |\n| \"Complexity score too low\" | complexity-management    |\n| \"Deptrac violations\"       | deptrac-fixer            |\n| \"must not depend on\"       | deptrac-fixer            |\n| \"tests failed\"             | testing-workflow         |\n| \"Psalm found errors\"       | Fix type errors directly |\n| \"escaped mutants\"          | testing-workflow         |\n\n### Step 4: Re-run CI\n\n```bash\nmake ci\n```\n\nRepeat until: \"✅ CI checks successfully passed!\"\n\n## Constraints (Parameters)\n\n### NEVER\n\n- Lower quality thresholds in config files (`phpinsights.php`, `infection.json5`, etc.)\n- Skip failing checks to \"save time\"\n- Commit code without all CI checks passing\n- Modify `deptrac.yaml` to allow violations (fix code, not config)\n- Disable security checks\n\n### ALWAYS\n\n- Fix code to meet standards (not config to meet code)\n- Run `make ci` before creating commits\n- Use specialized skills for specific quality issues\n- Maintain 100% test coverage\n- Keep cyclomatic complexity low (target: < 5 per method)\n- Respect hexagonal architecture boundaries\n\n## Format (Output)\n\n### Expected CI Output\n\n```\n✅ CI checks successfully passed!\n```\n\n### Expected PHPInsights Output\n\n```\n[CODE] 100.0 pts       ✅ Target: 100%\n[COMPLEXITY] 94.0 pts  ✅ Target: 94%\n[ARCHITECTURE] 100 pts ✅ Target: 100%\n[STYLE] 100.0 pts      ✅ Target: 100%\n```\n\n### Expected Deptrac Output\n\n```\n✅ No violations found\n```\n\n### Expected Infection Output\n\n```\nMutation Score Indicator (MSI): 100%\n```\n\n## Verification Checklist\n\nAfter using this skill:\n\n- [ ] Identified which quality check is failing\n- [ ] Selected appropriate specialized skill for the issue\n- [ ] Ready to execute specialized skill workflow\n- [ ] Understand which threshold applies to the failure\n- [ ] Know the command to re-run the check after fixes\n\n## Related Skills\n\n- [ci-workflow](../ci-workflow/SKILL.md) - Run comprehensive CI validation\n- [complexity-management](../complexity-management/SKILL.md) - Reduce complexity, improve quality\n- [deptrac-fixer](../deptrac-fixer/SKILL.md) - Fix architectural violations\n- [implementing-ddd-architecture](../implementing-ddd-architecture/SKILL.md) - Understand DDD patterns\n- [testing-workflow](../testing-workflow/SKILL.md) - Fix test failures, improve coverage\n\n## Reference Documentation\n\nFor detailed examples and patterns, see:\n\n- **Refactoring patterns** → complexity-management skill\n- **Architecture rules** → implementing-ddd-architecture skill\n- **Layer boundaries** → deptrac-fixer skill\n- **Testing strategies** → testing-workflow skill\n"},"lastSynced":"2026-03-08T02:01:14.074Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing comprehensive quality metrics analysis and threshold protection.","zh":"非常适合需要全面质量指标分析和阈值保护的开发代理","ja":"開発エージェントが包括的な品質メトリクス分析としきい値保護を必要とする場合に最適","ko":"포괄적인 품질 메트릭스 분석 및 임계値 보호가 필요한 개발 에이전트에게 적합","es":"Perfecto para agentes de desarrollo que necesitan un análisis de métricas de calidad integral y protección de umbrales.","fr":"Idéal pour les agents de développement qui ont besoin d''une analyse complète des métriques de qualité et d''une protection des seuils.","de":"Perfekt für Entwicklungssagenten, die eine umfassende Analyse von Qualitätsmetriken und Schwellenschutz benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de análise de métricas de qualidade abrangentes e proteção de limiares.","ru":"Идеально для агентов разработки, которым необходим полный анализ метрик качества и защита порогов.","ar":"مثالي للوكلاء التطويينيين الذين يحتاجون إلى تحليل شاملاً لمقاييس الجودة وحماية العتبات."},"recommendation":{"en":"Empowers agents to understand and enforce protected quality thresholds, route issues to specialized skills for fixes, and utilize quality tool commands for comprehensive checks, ensuring high-quality code commits.","zh":"赋予代理理解和强制保护的质量阈值、将问题路由到专门的技能以进行修复，并利用质量工具命令进行全面检查，以确保高质量的代码提交","ja":"エージェントが保護された品質のしきい値を理解して適用し、問題を修正するための専門スキルにルーティングし、包括的なチェックのための品質ツールコマンドを利用して、高品質のコードコミットを確保する","ko":"에이전트가 보호된 품질 임계값을 이해하고 적용하고, 수정을 위한 전문 기술로 문제를 라우팅하며, 포괄적인 검사 위한 품질 툴 명령어를 활용하여, 고품질 코드 커밋을 보장","es":"Habilita a los agentes a comprender y hacer cumplir umbrales de calidad protegidos, enrutar problemas a habilidades especializadas para soluciones, y utilizar comandos de herramientas de calidad para controles integrales, garantizando compromisos de código de alta calidad.","fr":"Permet aux agents de comprendre et de faire respecter les seuils de qualité protégés, de router les problèmes vers des compétences spécialisées pour les corrections, et d''utiliser des commandes d''outils de qualité pour des vérifications complètes, garantissant des validations de code de haute qualité.","de":"Ermöglicht es Agenten, Schwellen für den Schutz der Qualität zu verstehen und durchzusetzen, Probleme an spezialisierte Fähigkeiten für Korrekturen zu übergeben und Qualitäts-Werkzeug-Befehle für umfassende Prüfungen zu nutzen, um damit hochwertige Code-Commits sicherzustellen.","pt":"Habilita os agentes a entender e aplicar limiares de qualidade protegidos, encaminhar problemas para habilidades especializadas para correções e utilizar comandos de ferramentas de qualidade para verificações abrangentes, garantindo compromissos de código de alta qualidade.","ru":"Наделяет агентов возможностью понимать и соблюдать защищенные пороги качества, направлять проблемы к специализированным навыкам для исправления и использовать команды инструментов качества для комплексных проверок, обеспечивая высококачественные коммиты кода.","ar":"يمنح الوكلاء القدرة على فهم وتنفيذ عتبات الجودة المحمية، وتوجيه المشكلات إلى مهارات متخصصة للتصحيحات، واستخدام أوامر أدوات الجودة للفحوصات الشاملة، مما يضمن الالتزامات عالية الجودة للرمز."},"useCases":{"en":["Automating quality checks before code commits","Determining appropriate specialized skills for specific quality issues","Enforcing protected quality thresholds in development workflows"],"zh":["在代码提交前自动执行质量检查","确定特定质量问题的适当专门技能","在开发工作流中执行保护的质量阈值"],"ja":["コードコミット前に自動的に品質チェックを実行する","特定の品質問題に対する適切な専門スキルを決定する","開発ワークフローで保護された品質のしきい値を適用する"],"ko":["코드 커밋 전 자동으로 품질 검사를 수행","특정 품질 문제에 대한 적절한 전문 기술을 결정","개발 워크플로에서 보호된 품질 임계값을 적용"],"es":["Automatizar controles de calidad antes de los compromisos de código","Determinar habilidades especializadas adecuadas para problemas de calidad específicos","Hacer cumplir umbrales de calidad protegidos en flujos de trabajo de desarrollo"],"fr":["Automatiser les vérifications de qualité avant les validations de code","Déterminer des compétences spécialisées appropriées pour des problèmes de qualité spécifiques","Faire respecter les seuils de qualité protégés dans les flux de travail de développement"],"de":["Automatisierung von Qualitätskontrollen vor Code-Commits","Bestimmung geeigneter spezialisierter Fähigkeiten für spezifische Qualitätsprobleme","Durchsetzung von geschützten Qualitäts-Schwellen in Entwicklungsaufträgen"],"pt":["Automação de verificações de qualidade antes dos compromissos de código","Determinação de habilidades especializadas apropriadas para problemas de qualidade específicos","Aplicação de limiares de qualidade protegidos em fluxos de trabalho de desenvolvimento"],"ru":["Автоматизация проверок качества перед коммитами кода","Определение подходящих специализированных навыков для конкретных проблем качества","Применение защищенных порогов качества в рабочих процессах разработки"],"ar":["أتمتة الفحوصات الجودة قبل الالتزامات بالرمز","تحديد المهارات التخصصية المناسبة لمشاكل الجودة النوعية","تطبيق عتبات الجودة المحمية في سير عمل التطوير"]},"limitations":{"en":["Requires understanding of quality metrics and thresholds","Dependent on availability of specialized skills for fixes"],"zh":["需要了解质量指标和阈值","依赖于修复的专门技能的可用性"],"ja":["品質メトリクスとしきい値の理解が必要","修正のための専門スキルの可用性に依存"],"ko":["품질 메트릭스와 임계값에 대한 이해가 필요","수정에 대한 전문 기술의 가용성에 의존"],"es":["Requiere comprensión de métricas y umbrales de calidad","Dependiente de la disponibilidad de habilidades especializadas para soluciones"],"fr":["Nécessite une compréhension des métriques et des seuils de qualité","Dépend de la disponibilité de compétences spécialisées pour les corrections"],"de":["Benötigt Verständnis von Qualitätsmetriken und -schwellen","Abhängig von der Verfügbarkeit spezialisierter Fähigkeiten für Korrekturen"],"pt":["Exige compreensão de métricas de qualidade e limiares","Dependente da disponibilidade de habilidades especializadas para correções"],"ru":["Требует понимания метрик качества и порогов","Зависит от наличия специализированных навыков для исправления"],"ar":["يتطلب فهمًا لمقاييس الجودة والعتبات","يعتمد على توافر مهارات متخصصة للتصحيحات"]},"version":4},"contentHash":"f3cf6c31c875536be97cdd16a2a53b1c129f091fef842d40e19ba2cf65eb4430","qualityScore":45}');
