INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('VilnaCRM-Org/user-service/quality-standards', 'quality-standards', 'VilnaCRM-Org', 'user-service', 'community', 'quality-standards VilnaCRM-Org user-service community The quality-standards skill helps developers understand quality metrics and route issues to appropriate specialized skills for fixes, ensuring protected quality thresholds. It benefits developers working with AI agents 质量标准技能帮助开发者了解保护质量阈值，运行综合质量检查，并确定特定问题的解决方案 品質基準スキルは、開発者が保護品質閾値を理解し、包括的な品質チェックを実行し、特定の問題の解決策を決定するのに役立ちます 품질 표준 스킬은 개발자가 보호 품질 임계값을 이해하고 포괄적인 품질 점검을 실행하며 특정 문제의 해결책을 결정하는 데 도움이 됩니다 Estándares de calidad para agentes de IA que permiten comprender métricas de calidad y determinar habilidades especializadas Normes de qualité pour outils d''IA qui permettent de comprendre les métriques de qualité et de déterminer les compétences spécialisées Qualitätsstandards für KI-Tools, die es ermöglichen, Qualitätsmetriken zu verstehen und spezialisierte Fähigkeiten zu bestimmen O skill de padrões de qualidade ajuda a entender métricas de qualidade e aplicar correções específicas. Entenda como configurar limiares de qualidade protegidos ИИ Агенты для контроля качества помогают понять метрики качества и применить исправления. Узнайте, как настроить защищенные пороги качества الأجهزة الذكية الإصطناعية لمعايير الجودة تساعد على فهم معايير الجودة وتطبيق الإصلاحات المحددة. تعرف على كيفية إعداد حدود جودة محمية how to use quality-standards quality-standards setup guide quality-standards alternative quality-standards vs code analysis tools implementing quality-standards in AI agents quality-standards install 质量标准 AIエージェント 保护质量阈值 综合质量检查 特定问题解决 质量工具命令 CRITICAL质量检查 Understands protected quality thresholds Runs comprehensive quality checks before commit Determines which specialized skill to use for specific issues Provides quick reference for quality tool commands Routes quality issues to appropriate specialized skills for fixes quality-standards is a skill that understands quality metrics and routes issues to specialized skills for fixes, ensuring adherence to protected quality thresholds');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('PackmindHub/packmind/packmind-create-skill', 'community', 'PackmindHub', 'packmind', 'PackmindHub/packmind', 'packmind-create-skill', 0, 0, 45, '2026-03-08T01:57:15.298Z', '2026-03-08T02:01:19.965Z', 'e6c90db53dd4143e409e763930cbefdef5cd1c54ade3005381485a4fb75fbe3b', '{"id":"PackmindHub/packmind/packmind-create-skill","name":"packmind-create-skill","description":{"en":"packmind-create-skill provides guidance for creating modular skills that extend Claude''s capabilities. It helps developers create specialized knowledge, workflows, and tools for specific domains or tasks.","zh":"Packmind Create Skill是一种将工程playbook转化为AI上下文、守护和治理的技术，实现AI开发的自动化","ja":"Packmind Create SkillはエンジニアリングプレイブックをAIコンテキスト、ガードレール、ガバナンスに変換するための技術です","ko":"Packmind Create Skill은 엔지니어링 플레이북을 AI 컨텍스트, 가드레일 및 거버넌스로 변환하여 자동화를 구현하는 기술입니다","es":"Packmind Create Skill es una habilidad que proporciona orientación para crear habilidades efectivas, transformando a Claude en un agente especializado con conocimientos procedimentales","fr":"Packmind Create Skill est une compétence qui fournit des conseils pour créer des compétences efficaces, transformant Claude en un outil d''IA spécialisé avec des connaissances procédurales","de":"Packmind Create Skill ist eine Fähigkeit, die Anleitung zur Erstellung effektiver Fähigkeiten bietet, Claude in einen spezialisierten KI-Agenten mit prozeduralen Kenntnissen verwandelnd","pt":"O Packmind Create Skill é uma ferramenta que captura o playbook de engenharia e o transforma em contexto de IA, guardrails e governança.","ru":"Packmind Create Skill — это инструмент, который захватывает инженерную книгу рецептов и преобразует ее в контекст ИИ, ограничители и управление.","ar":"Packmind Create Skill هو أداة تحول كتاب الإرشادات الهندسية إلى سياق ذكاء اصطناعي وحدود وتحكم"},"seo":{"title":{"en":"packmind-create-skill: Modular Skill Creation for AI Agen...","zh":"Packmind Create SkillSetup Guide - AIエージェント开发","ja":"Packmind Create Skill入門 - AIエージェントのカスタマイズ","ko":"Packmind Create Skill 설정 가이드 - AI 에이전트 개발","es":"Guía de configuración de Packmind Create Skill para agent...","fr":"Guide de mise en place de Packmind Create Skill pour les ...","de":"Einrichtungsanleitung für Packmind Create Skill für KI-Ag...","pt":"Guia de Configuração do Packmind Create Skill para Desenv...","ru":"Настройка Packmind Create Skill: Руководство для Разработ...","ar":"دليل إعداد Packmind Create Skill لمنصة الإيمان العامل"},"description":{"en":"Unlock specialized workflows with packmind-create-skill. Discover how to create effective skills and transform Claude into a domain-specific agent. Get start...","zh":"了解Packmind Create Skill如何将工程playbook转化为AI上下文、守护和治理，实现AI开发的自动化","ja":"Packmind Create Skillを使用してエンジニアリングプレイブックをAIコンテキスト、ガードレール、ガバナンスに変換する方法を学びます","ko":"Packmind Create Skill을 사용하여 엔지니어링 플레이북을 AI 컨텍스트, 가드레일 및 거버넌스로 변환하여 자동화를 구현하는 방법","es":"Aprende a crear habilidades efectivas con Packmind Create Skill y mejora tus agentes de IA con conocimientos especializados","fr":"Découvrez comment créer des compétences efficaces avec Packmind Create Skill et améliorez vos outils d''IA avec des connaissances spécialisées","de":"Erfahren Sie, wie Sie effektive Fähigkeiten mit Packmind Create Skill erstellen und Ihre KI-Agents mit spezialisierten Kenntnissen verbessern","pt":"Aprenda a configurar o Packmind Create Skill para melhorar a capacidade da sua equipe de desenvolvimento com workflows especializados e governança de IA.","ru":"Узнайте, как настроить Packmind Create Skill, чтобы повысить эффективность вашей команды разработчиков с помощью специализированных рабочих процессов и управ...","ar":"تعرف على كيفية إعداد Packmind Create Skill لتعزيز قدرات فريقك التطويري باستخدام سير عمل متخصصة وإدارة الية"},"definition":{"en":"packmind-create-skill is a modular skill creation tool that captures engineering playbooks and turns them into AI context, guardrails, and governance.","zh":"Packmind Create Skill是一种AI开发工具，用于创建工程playbook的AI上下文","ja":"Packmind Create SkillはAI開発ツールであり、エンジニアリングプレイブックのAIコンテキストを作成する","ko":"Packmind Create Skill은 엔지니어링 플레이북의 AI 컨텍스트를 생성하는 AI 개발 도구입니다","es":"Packmind Create Skill es una habilidad que permite crear habilidades modulares y autocontenidas para agentes de IA","fr":"Packmind Create Skill est une compétence qui permet de créer des compétences modulaires et autocontenues pour les outils d''IA","de":"Packmind Create Skill ist eine Fähigkeit, die die Erstellung modularer und selbstenthaltener Fähigkeiten für KI-Agents ermöglicht","pt":"O Packmind Create Skill é uma ferramenta de desenvolvimento que fornece workflows especializados e governança de IA.","ru":"Packmind Create Skill — это инструмент разработки, который предоставляет специализированные рабочие процессы и управление ИИ.","ar":"Packmind Create Skill هو أداة تطوير توفر سير عمل متخصصة وإدارة الية"},"features":{"en":["Provides specialized workflows for specific domains or tasks","Transforms Claude into a specialized agent with procedural knowledge","Supports creation of modular, self-contained packages","Enables development of domain-specific skills with guardrails and governance","Captures engineering playbooks and turns them into AI context","Extends Claude''s capabilities with specialized knowledge and tools"],"zh":["支持将工程playbook转化为AI上下文","提供守护和治理功能","实现AI开发的自动化","支持多种开发框架","提供CLI命令行工具"],"ja":["エンジニアリングプレイブックをAIコンテキストに変換","ガードレールとガバナンス機能を提供","AI開発の自動化を実現","複数の開発フレームワークをサポート","CLIコマンドラインツールを提供"],"ko":["엔지니어링 플레이북을 AI 컨텍스트로 변환","가드레일 및 거버넌스 기능 제공","AI 개발 자동화를 구현","다중 개발 프레임워크 지원","CLI 명령행 도구 제공"],"es":["Proporciona orientación para crear habilidades efectivas","Permite la creación de habilidades modulares y autocontenidas","Transforma a Claude en un agente especializado con conocimientos procedimentales","Ofrece flujos de trabajo especializados para dominios o tareas específicas","Permite la integración con tecnologías como Claude"],"fr":["Fournit des conseils pour créer des compétences efficaces","Permet la création de compétences modulaires et autocontenues","Transforme Claude en un outil d''IA spécialisé avec des connaissances procédurales","Offre des flux de travail spécialisés pour des domaines ou des tâches spécifiques","Permet l''intégration avec des technologies comme Claude"],"de":["Bietet Anleitung zur Erstellung effektiver Fähigkeiten","Ermöglicht die Erstellung modularen und selbstenthaltener Fähigkeiten","Verwandelt Claude in einen spezialisierten KI-Agenten mit prozeduralen Kenntnissen","Bietet spezialisierte Arbeitsabläufe für bestimmte Domänen oder Aufgaben","Ermöglicht die Integration mit Technologien wie Claude"],"pt":["Workflows especializados para domínios específicos","Governança de IA para garantir a segurança e a conformidade","Capacidade de capturar o playbook de engenharia e transformá-lo em contexto de IA","Integração com Claude para fornecer conhecimento procedural especializado","Modularidade para permitir a extensão das capacidades do agente"],"ru":["Специализированные рабочие процессы для конкретных доменов","Управление ИИ для обеспечения безопасности и соответствия","Возможность захватить инженерную книгу рецептов и преобразовать ее в контекст ИИ","Интеграция с Claude для предоставления процедурного знания специализированного","Модульность для расширения возможностей агента"],"ar":["سير عمل متخصصة لمجالات محددة","إدارة الية لضمان الأمان والامتثال","القدرة على تحويل كتاب الإرشادات الهندسية إلى سياق ذكاء اصطناعي","التكامل مع Claude لتوفير معرفة إجرائية متخصصة","الوحدات القابلة للتوسيع لتمكين توسيع قدرات العامل"]},"keywords":{"en":["how to use packmind-create-skill","what is packmind-create-skill","packmind-create-skill alternative","packmind-create-skill vs Claude","packmind-create-skill install","packmind-create-skill setup guide","modular skill creation for AI agents","specialized workflows for Claude","AI agent skill development"],"zh":["Packmind Create Skill","AI开发工具","工程playbook","AI上下文","守护和治理","自动化","开发框架","CLI命令行工具","AIエージェント开发"],"ja":["Packmind Create Skill","AI開発ツール","エンジニアリングプレイブック","AIコンテキスト","ガードレールとガバナンス","自動化","開発フレームワーク","CLIコマンドラインツール","AIエージェントのカスタマイズ"],"ko":["Packmind Create Skill","AI 개발 도구","엔지니어링 플레이북","AI 컨텍스트","가드레일 및 거버넌스","자동화","개발 프레임워크","CLI 명령행 도구","AI 에이전트 개발"],"es":["agentes de IA","Packmind Create Skill","habilidades efectivas","conocimientos procedimentales","Claude","desarrollo de habilidades","integración con tecnologías","IA y machine learning"],"fr":["outils d''IA","Packmind Create Skill","compétences efficaces","connaissances procédurales","Claude","développement de compétences","intégration avec des technologies","IA et machine learning"],"de":["KI-Agents","Packmind Create Skill","effektive Fähigkeiten","prozedurale Kenntnisse","Claude","Entwicklung von Fähigkeiten","Integration mit Technologien","KI und Machine Learning"],"pt":["Packmind Create Skill","Desenvolvimento de IA","Workflows especializados","Governança de IA","Claude","Playbook de engenharia","Contexto de IA","Desenvolvedores de IA"],"ru":["Packmind Create Skill","Разработка ИИ","Специализированные рабочие процессы","Управление ИИ","Claude","Инженерная книга рецептов","Контекст ИИ","Разработчики ИИ"],"ar":["Packmind Create Skill","تطوير الإيمان العامل","سير عمل متخصصة","إدارة الية","Claude","كتاب الإرشادات الهندسية","سياق ذكاء اصطناعي","مطوّرو الإيمان العامل"]}},"owner":"PackmindHub","repo":"packmind","repoPath":"PackmindHub/packmind","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.298Z","topics":[],"category":"community","skillMd":{"name":"packmind-create-skill","description":"Guide for creating effective skills. This skill should be used when users want to create a new skill (or update an existing skill) that extends Claudes capabilities with specialized knowledge, workflows, or tool integrations.","bodyPreview":"# Create skill\n\nThis skill provides guidance for creating effective skills.\n\n## About Skills\n\nSkills are modular, self-contained packages that extend Claude''s capabilities by providing\nspecialized knowledge, workflows, and tools. Think of them as \"onboarding guides\" for specific\ndomains or tasks—they transform Claude from a general-purpose agent into a specialized agent\nequipped with procedural knowledge that no model can fully possess.\n\n### What Skills Provide\n\n1. Specialized workflows - Multi-","body":"# Create skill\n\nThis skill provides guidance for creating effective skills.\n\n## About Skills\n\nSkills are modular, self-contained packages that extend Claude''s capabilities by providing\nspecialized knowledge, workflows, and tools. Think of them as \"onboarding guides\" for specific\ndomains or tasks—they transform Claude from a general-purpose agent into a specialized agent\nequipped with procedural knowledge that no model can fully possess.\n\n### What Skills Provide\n\n1. Specialized workflows - Multi-step procedures for specific domains\n2. Tool integrations - Instructions for working with specific file formats or APIs\n3. Domain expertise - Company-specific knowledge, schemas, business logic\n4. Bundled resources - Scripts, references, and assets for complex and repetitive tasks\n\n### Anatomy of a Skill\n\nEvery skill consists of a required SKILL.md file and optional bundled resources:\n\n```\nskill-name/\n├── SKILL.md (required)\n│   ├── YAML frontmatter metadata (required)\n│   │   ├── name: (required)\n│   │   └── description: (required)\n│   └── Markdown instructions (required)\n└── Bundled Resources (optional)\n    ├── scripts/          - Executable code (Python/Bash/etc.)\n    ├── references/       - Documentation intended to be loaded into context as needed\n    └── assets/           - Files used in output (templates, icons, fonts, etc.)\n```\n\n#### SKILL.md (required)\n\n**Metadata Quality:** The `name` and `description` in YAML frontmatter determine when Claude will use the skill. Be specific about what the skill does and when to use it. Use the third-person (e.g. \"This skill should be used when...\" instead of \"Use this skill when...\").\n\n#### Bundled Resources (optional)\n\n##### Scripts (`scripts/`)\n\nExecutable code (Python/Bash/etc.) for tasks that require deterministic reliability or are repeatedly rewritten.\n\n- **When to include**: When the same code is being rewritten repeatedly or deterministic reliability is needed\n- **Example**: `scripts/rotate_pdf.py` for PDF rotation tasks\n- **Benefits**: Token efficient, deterministic, may be executed without loading into context\n- **Note**: Scripts may still need to be read by Claude for patching or environment-specific adjustments\n\n##### References (`references/`)\n\nDocumentation and reference material intended to be loaded as needed into context to inform Claude''s process and thinking.\n\n- **When to include**: For documentation that Claude should reference while working\n- **Examples**: `references/finance.md` for financial schemas, `references/mnda.md` for company NDA template, `references/policies.md` for company policies, `references/api_docs.md` for API specifications\n- **Use cases**: Database schemas, API documentation, domain knowledge, company policies, detailed workflow guides\n- **Benefits**: Keeps SKILL.md lean, loaded only when Claude determines it''s needed\n- **Best practice**: If files are large (>10k words), include grep search patterns in SKILL.md\n- **Avoid duplication**: Information should live in either SKILL.md or references files, not both. Prefer references files for detailed information unless it''s truly core to the skill—this keeps SKILL.md lean while making information discoverable without hogging the context window. Keep only essential procedural instructions and workflow guidance in SKILL.md; move detailed reference material, schemas, and examples to references files.\n\n##### Assets (`assets/`)\n\nFiles not intended to be loaded into context, but rather used within the output Claude produces.\n\n- **When to include**: When the skill needs files that will be used in the final output\n- **Examples**: `assets/logo.png` for brand assets, `assets/slides.pptx` for PowerPoint templates, `assets/frontend-template/` for HTML/React boilerplate, `assets/font.ttf` for typography\n- **Use cases**: Templates, images, icons, boilerplate code, fonts, sample documents that get copied or modified\n- **Benefits**: Separates output resources from documentation, enables Claude to use files without loading them into context\n\n### Progressive Disclosure Design Principle\n\nSkills use a three-level loading system to manage context efficiently:\n\n1. **Metadata (name + description)** - Always in context (~100 words)\n2. **SKILL.md body** - When skill triggers (<5k words)\n3. **Bundled resources** - As needed by Claude (Unlimited\\*)\n\n\\*Unlimited because scripts can be executed without reading into context window.\n\n## Prerequisites\n\nBefore running any skill scripts, verify that the required tools are available:\n\n### Python 3\n\nCheck if Python 3 is installed:\n\n```bash\npython3 --version\n```\n\nIf not available, install it:\n- **macOS**: `brew install python3`\n- **Ubuntu/Debian**: `sudo apt-get install python3`\n- **Windows**: Download from https://python.org or use `winget install Python.Python.3`\n\n### Packmind CLI\n\nCheck if packmind-cli is installed:\n\n```bash\npackmind-cli --version\n```\n\nIf not available, install it:\n\n```bash\nnpm install -g packmind-cli\n```\n\n## Skill Creation Process\n\nTo create a skill, follow the \"Skill Creation Process\" in order, skipping steps only if there is a clear reason why they are not applicable.\n\n### Step 1: Understanding the Skill with Concrete Examples\n\nSkip this step only when the skill''s usage patterns are already clearly understood. It remains valuable even when working with an existing skill.\n\nTo create an effective skill, clearly understand concrete examples of how the skill will be used. This understanding can come from either direct user examples or generated examples that are validated with user feedback.\n\nFor example, when building an image-editor skill, relevant questions include:\n\n- \"What functionality should the image-editor skill support? Editing, rotating, anything else?\"\n- \"Can you give some examples of how this skill would be used?\"\n- \"I can imagine users asking for things like ''Remove the red-eye from this image'' or ''Rotate this image''. Are there other ways you imagine this skill being used?\"\n- \"What would a user say that should trigger this skill?\"\n\nTo avoid overwhelming users, avoid asking too many questions in a single message. Start with the most important questions and follow up as needed for better effectiveness.\n\nConclude this step when there is a clear sense of the functionality the skill should support.\n\n### Step 2: Planning the Reusable Skill Contents\n\nTo turn concrete examples into an effective skill, analyze each example by:\n\n1. Considering how to execute on the example from scratch\n2. Identifying what scripts, references, and assets would be helpful when executing these workflows repeatedly\n\nExample: When building a `pdf-editor` skill to handle queries like \"Help me rotate this PDF,\" the analysis shows:\n\n1. Rotating a PDF requires re-writing the same code each time\n2. A `scripts/rotate_pdf.py` script would be helpful to store in the skill\n\nExample: When designing a `frontend-webapp-builder` skill for queries like \"Build me a todo app\" or \"Build me a dashboard to track my steps,\" the analysis shows:\n\n1. Writing a frontend webapp requires the same boilerplate HTML/React each time\n2. An `assets/hello-world/` template containing the boilerplate HTML/React project files would be helpful to store in the skill\n\nExample: When building a `big-query` skill to handle queries like \"How many users have logged in today?\" the analysis shows:\n\n1. Querying BigQuery requires re-discovering the table schemas and relationships each time\n2. A `references/schema.md` file documenting the table schemas would be helpful to store in the skill\n\nTo establish the skill''s contents, analyze each concrete example to create a list of the reusable resources to include: scripts, references, and assets.\n\n### Step 3: Initializing the Skill\n\nAt this point, it is time to actually create the skill.\n\nSkip this step only if the skill being developed already exists, and iteration or packaging is needed. In this case, continue to the next step.\n\n**Before running the script**, verify that python3 and packmind-cli are available (see Prerequisites section). If not installed, install them first.\n\nWhen creating a new skill from scratch, always run the `init_skill.py` script. The script conveniently generates a new template skill directory that automatically includes everything a skill requires, making the skill creation process much more efficient and reliable.\n\nUsage:\n\n```bash\npython3 scripts/init_skill.py <skill-name> --path <output-directory>\n```\n\n**IMPORTANT:** The `--path` argument must be the **parent directory** where the skill folder will be created, not the skill directory itself. The script automatically creates a subdirectory named after the skill.\n\n- ✅ Correct: `python3 scripts/init_skill.py my-skill --path .claude/skills` → creates `.claude/skills/my-skill/`\n- ❌ Wrong: `python3 scripts/init_skill.py my-skill --path .claude/skills/my-skill` → creates `.claude/skills/my-skill/my-skill/` (nested!)\n\nThe script:\n\n- Creates the skill directory at the specified path\n- Generates a SKILL.md template with proper frontmatter and TODO placeholders\n- Creates example resource directories: `scripts/`, `references/`, and `assets/`\n- Adds example files in each directory that can be customized or deleted\n\nAfter initialization, customize or remove the generated SKILL.md and example files as needed.\n\n### Step 4: Edit the Skill\n\nWhen editing the (newly-generated or existing) skill, remember that the skill is being created for another instance of Claude to use. Focus on including information that would be beneficial and non-obvious to Claude. Consider what procedural knowledge, domain-specific details, or reusable assets would help another Claude instance execute these tasks more effectively.\n\n**File Placement Rule:** Always create files directly in their target subdirectory. Never create a file at the skill root and move it later.\n- Reference docs → `references/filename.md`\n- Scripts → `scripts/filename.py`\n- Assets → `assets/filename.ext`\n- Only `SKILL.md`, `README.md`, and `LICENSE.txt` belong at the skill root.\n\n#### Start with Reusable Skill Contents\n\nTo begin implementation, start with the reusable resources identified above: `scripts/`, `references/`, and `assets/` files. Note that this step may require user input. For example, when implementing a `brand-guidelines` skill, the user may need to provide brand assets or templates to store in `assets/`, or documentation to store in `references/`.\n\nAlso, delete any example files and directories not needed for the skill. The initialization script creates example files in `scripts/`, `references/`, and `assets/` to demonstrate structure, but most skills won''t need all of them.\n\n#### Update SKILL.md\n\n**Writing Style:** Write the entire skill using **imperative/infinitive form** (verb-first instructions), not second person. Use objective, instructional language (e.g., \"To accomplish X, do Y\" rather than \"You should do X\" or \"If you need to do X\"). This maintains consistency and clarity for AI consumption.\n\nTo complete SKILL.md, answer the following questions:\n\n1. What is the purpose of the skill, in a few sentences?\n2. When should the skill be used?\n3. In practice, how should Claude use the skill? All reusable skill contents developed above should be referenced so that Claude knows how to use them.\n\n### Step 5: Validating a Skill\n\nBefore distributing, validate the skill to ensure it meets all requirements.\n\n**Before running the script**, verify that python3 is available (see Prerequisites section). If not installed, install it first.\n\n```bash\npython3 scripts/quick_validate.py <path/to/skill-folder>\n```\n\nThe validation script checks:\n\n- YAML frontmatter format and required fields\n- Skill naming conventions and directory structure\n- Description completeness and quality\n\nIf validation fails, fix the reported errors and run the validation again.\n\n### Step 6: Iterate\n\nAfter testing the skill, users may request improvements. Often this happens right after using the skill, with fresh context of how the skill performed.\n\n**Iteration workflow:**\n\n1. Use the skill on real tasks\n2. Notice struggles or inefficiencies\n3. Identify how SKILL.md or bundled resources should be updated\n4. Implement changes and test again\n\n### Step 7: Distributing a Skill\n\n**After successful validation, always run the distribution command** to register the skill with Packmind. Do not skip this step.\n\n**Before running the command**, verify that packmind-cli is available (see Prerequisites section). If not installed, install it first.\n\nRun the following command with the actual skill path:\n\n```bash\npackmind-cli skills add <path/to/skill-folder>\n```\n\nThis registers the skill with Packmind, making it available for deployment to target repositories and AI coding agents.\n\n### Step 8: Offer to Add to Package\n\nAfter successful distribution, check if the skill fits an existing package:\n\n1. Run `packmind-cli install --list` to get available packages\n2. If no packages exist, skip this step silently and end the workflow\n3. Analyze the created skill''s name and description against each package''s name and description\n4. If a package is a clear semantic fit (the skill''s domain/technology aligns with the package''s purpose):\n   - Present to user: \"This skill seems to fit the `<package-slug>` package.\"\n   - Offer three options:\n     - Add to `<package-slug>`\n     - Choose a different package\n     - Skip\n5. If no clear fit is found, skip silently (do not mention packages)\n6. If user chooses to add:\n   - Run: `packmind-cli packages add --to <package-slug> --skill <skill-slug>`\n   - Ask: \"Would you like me to run `packmind-cli install` to sync the changes?\"\n   - If yes, run: `packmind-cli install`\n"},"lastSynced":"2026-03-08T02:01:19.965Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing to create modular skills for domain-specific tasks and workflows.","zh":"非常适合需要为特定领域任务和工作流创建模块化技能的开发者代理。","ja":"ドメイン固有のタスクとワークフローに対してモジュラーなスキルを作成する必要があるデベロッパーエージェントに最適です。","ko":"특정 도메인 작업 및 워크플로우를 위한 모듈러 스킬을 생성해야 하는 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan crear habilidades modulares para tareas y flujos de trabajo específicos del dominio.","fr":"Parfait pour les Agents de Développeur ayant besoin de créer des compétences modulaires pour des tâches et des flux de travail spécifiques au domaine.","de":"Perfekt für Entwickleragenten, die modulare Fähigkeiten für domänen-spezifische Aufgaben und Workflows erstellen müssen.","pt":"Perfeito para Agentes de Desenvolvedor que precisam criar habilidades modulares para tarefas e fluxos de trabalho específicos de domínio.","ru":"Идеально подходит для агентов-разработчиков, которым необходимо создавать модульные навыки для задач и рабочих процессов, специфичных для конкретной области.","ar":"مثالي لعميل التطوير الذي يحتاج إلى إنشاء مهارات مخصصة لمهام وعمليات عمل محددة لمنطقة معينة."},"recommendation":{"en":"Empowers agents to generate specialized knowledge, workflows, and tools for specific domains or tasks, transforming them into specialized agents equipped with procedural knowledge using modular skills and domain-specific onboarding guides.","zh":"赋予代理生成特定领域或任务的专业知识、工作流和工具，将他们转变为配备了模块化技能和领域特定入职指南的专业代理，拥有程序化知识。","ja":"エージェントに特定のドメインまたはタスクの専門知識、ワークフロー、ツールを生成させることで、モジュラーなスキルとドメイン固有のオンボーディングガイドを備えた専門エージェントに変貌させ、手続き知識を提供します。","ko":"에이전트가 특정 도메인 또는 작업을 위한 전문 지식, 워크플로 및 도구를 생성하도록 강화하여, 모듈러 스킬 및 도메인별 온보딩 가이드를 갖춘 전문 에이전트로 변신시키고, 절차 지식을 제공합니다.","es":"Habilita a los agentes a generar conocimiento especializado, flujos de trabajo y herramientas para dominios o tareas específicos, transformándolos en agentes especializados equipados con conocimiento procedural utilizando habilidades modulares y guías de incorporación específicas del dominio.","fr":"Permet aux agents de générer des connaissances spécialisées, des flux de travail et des outils pour des domaines ou des tâches spécifiques, les transformant en agents spécialisés équipés de connaissances procédurales en utilisant des compétences modulaires et des guides d''intégration spécifiques au domaine.","de":"Ermächtigt die Agenten, spezialisiertes Wissen, Workflows und Tools für bestimmte Domänen oder Aufgaben zu generieren, indem sie in spezialisierte Agenten mit prozeduralem Wissen ausgestattet werden, das mithilfe modularer Fähigkeiten und domänenspezifischer Onboarding-Anleitungen erstellt wird.","pt":"Habilita os agentes a gerar conhecimento especializado, fluxos de trabalho e ferramentas para domínios ou tarefas específicas, transformando-os em agentes especializados equipados com conhecimento procedural usando habilidades modulares e guias de integração específicas de domínio.","ru":"Позволяет агентам генерировать специализированные знания, рабочие процессы и инструменты для конкретных областей или задач, превращая их в специализированных агентов, оснащенных процедурными знаниями с помощью модульных навыков и руководств по интеграции, специфичных для конкретной области.","ar":"تمكين الوكلاء من توليد المعرفة المتخصصة والعمليات والمنتجات لمناطق أو مهام محددة، مما ي biếnهم إلى وكلاء متخصصين مجهزين بالمعرفة الإجرائية باستخدام المهارات المخصصة ودلائل التوجيه الخاصة بالمنطقة."},"useCases":{"en":["Creating domain-specific skills for Claude","Developing procedural knowledge for specialized tasks","Extending agent capabilities with modular workflows"],"zh":["为 Claude 创建领域特定技能","为专业任务开发程序化知识","使用模块化工作流扩展代理功能"],"ja":["Claude 用のドメイン固有スキルの作成","専門タスクの手続き知識の開発","モジュラーなワークフローでエージェントの機能を拡張"],"ko":["Claude를 위한 도메인별 스킬 생성","전문 작업을 위한 절차 지식 개발","모듈러 워크플로를 통한 에이전트 기능 확장"],"es":["Crear habilidades específicas del dominio para Claude","Desarrollar conocimiento procedural para tareas especializadas","Ampliar las capacidades del agente con flujos de trabajo modulares"],"fr":["Créer des compétences spécifiques au domaine pour Claude","Développer des connaissances procédurales pour des tâches spécialisées","Étendre les capacités de l''agent avec des flux de travail modulaires"],"de":["Erstellen von domänen-spezifischen Fähigkeiten für Claude","Entwickeln von prozeduralem Wissen für spezialisierte Aufgaben","Erweitern der Agentenfähigkeiten mit modularen Workflows"],"pt":["Criar habilidades específicas de domínio para Claude","Desenvolver conhecimento procedural para tarefas especializadas","Estender as capacidades do agente com fluxos de trabalho modulares"],"ru":["Создание навыков, специфичных для конкретной области, для Claude","Разработка процедурных знаний для специализированных задач","Расширение возможностей агента с помощью модульных рабочих процессов"],"ar":["إنشاء مهارات مخصصة لمنطقة معينة من أجل Claude","تطوير المعرفة الإجرائية للمهام المتخصصة","توسيع قدرات العميل باستخدام عمليات عمل مخصصة"]},"limitations":{"en":["Requires Claude''s capabilities as a foundation","Limited to creating skills for specific domains or tasks"],"zh":["需要 Claude 的功能作为基础","仅限于为特定领域或任务创建技能"],"ja":["Claude の機能を基盤として必要","特定のドメインまたはタスクのスキルを作成することのみに限定"],"ko":["Claude의 기능을 기반으로 필요","특정 도메인 또는 작업을 위한 스킬 생성에만 제한"],"es":["Requiere las capacidades de Claude como base","Limitado a la creación de habilidades para dominios o tareas específicos"],"fr":["Nécessite les capacités de Claude comme base","Limité à la création de compétences pour des domaines ou des tâches spécifiques"],"de":["Benötigt die Fähigkeiten von Claude als Grundlage","Begrenzt auf die Erstellung von Fähigkeiten für bestimmte Domänen oder Aufgaben"],"pt":["Requer as capacidades do Claude como base","Limitado à criação de habilidades para domínios ou tarefas específicas"],"ru":["Требует возможностей Claude в качестве основы","Ограничен созданием навыков для конкретных областей или задач"],"ar":["يتطلب قدرات Claude كقاعدة","محدود بإنشاء مهارات لمجالات أو مهام محددة"]},"version":4},"contentHash":"e6c90db53dd4143e409e763930cbefdef5cd1c54ade3005381485a4fb75fbe3b","qualityScore":45}');
