INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pr-pm/prpm/thoroughness', 'thoroughness', 'pr-pm', 'prpm', 'community', 'thoroughness pr-pm prpm community Thoroughness ensures comprehensive implementation of complex tasks, ideal for fixing critical bugs, implementing multi-step features, and production deployments. It benefits developers who prioritize quality and completeness. 代码彻底性是指在代码实现中注重质量和完整性，减少错误和 bug。通过遵循严格的方法论，开发人员可以确保代码的可靠性和可维护性 AIエージェントの徹底性とは、コードの品質と完成度を優先すること。徹底した方法論に従うことで、開発者はコードの信頼性とメンテナンス性を向上させることができる 코드 완전성은 코드 구현에서 품질과 완전성을 중시하는 것을 의미한다. 개발자는 엄격한 방법론을 따라 코드의 신뢰성과 유지 보수를 향상시킬 수 있다 La thoroughness es una habilidad que garantiza la implementación completa y compleja de tareas sin atajos La thoroughness est une compétence qui assure la mise en place complète et complexe de tâches sans raccourcis Die Thoroughness ist eine Fähigkeit, die die vollständige und komplexe Implementierung von Aufgaben ohne Abkürzungen gewährleistet A minuciosidade é uma habilidade que garante a implementação completa e precisa de tarefas complexas sem atalhos, usando ferramentas de codificação AI Тщательность - это навык, который обеспечивает полную и точную реализацию сложных задач без обходных путей, используя инструменты кодирования ИИ Агентов الدقة هي مهارة تضمن تنفيذ دقيق وكامل للمهام المعقدة بدون اختصارات، باستخدام أدوات التشفير للوكلاء الذكية how to use thoroughness in coding what is thoroughness in software development thoroughness alternative for complex tasks thoroughness vs agile methodology thoroughness implementation guide for AI agents thoroughness setup for production deployments benefits of thoroughness in debugging thoroughness best practices for quality assurance thoroughness and completeness in coding thoroughness for fixing critical bugs 代码彻底性 AI工具 代码质量 代码完整性 错误减少 bug修复 代码可靠性 代码维护性 Conducts comprehensive analysis for complex tasks Ensures complete implementation of multi-step features Facilitates debugging of test failures without shortcuts Supports refactoring of large codebases for quality and completeness Optimizes production deployments for future reliability Guarantees detailed methodology for critical bug fixing Thoroughness is a skill that ensures comprehensive and complete implementation of complex tasks without taking shortcuts, prioritizing quality and completeness over speed.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('eysenfalk/git-review/escalation', 'community', 'eysenfalk', 'git-review', 'eysenfalk/git-review', 'escalation', 0, 0, 45, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:31.391Z', '8b21649730646f2cd6186f44a0593423ddd716801842749c124e8c9c63d8d9f2', '{"id":"eysenfalk/git-review/escalation","name":"escalation","description":{"en":"The escalation skill provides a structured approach to troubleshooting, benefiting developers and technical leads. It ensures efficient issue resolution by progressing through Haiku, Sonnet, and Opus tiers.","zh":"AI智能代理的升级涉及Haiku、Sonnet和Opus等级，每个等级都有特定的角色和职责","ja":"AIエージェントのエスカレーションはHaiku、Sonnet、Opusの各レベルで構成され、各レベルに固有の役割と責任があります","ko":"AI 에이전트의升级에는 Haiku, Sonnet, Opus 등급이 포함되며, 각 등급에는 고유한 역할과 책임이 있습니다","es":"La escalación de AI Agents implica la asignación de tareas a diferentes niveles de complejidad, desde Haiku hasta Opus, para garantizar la resolución eficiente de problemas","fr":"L''escalade des outils IA implique l''assignation de tâches à différents niveaux de complexité, de Haiku à Opus, pour assurer une résolution efficace des problèmes","de":"Die Eskalation von KI-Agents beinhaltet die Zuweisung von Aufgaben zu verschiedenen Komplexitätsstufen, von Haiku bis Opus, um eine effiziente Problemlösung zu gewährleisten","pt":"A escalada de IA é um processo que envolve a transição entre níveis de complexidade. Ela é composta por três níveis: Haiku, Sonnet e Opus.","ru":"Эскалация ИИ - это процесс, включающий переход между уровнями сложности. Она состоит из трех уровней: Haiku, Sonnet и Opus.","ar":"تصعيد الذكاء الاصطناعي هو عملية تتضمن الانتقال بين مستويات التعقيد. يتألف من ثلاثة مستويات: Haiku و Sonnet و Opus."},"seo":{"title":{"en":"Escalation: Tiered Troubleshooting Setup Guide | AI Agent...","zh":"AI智能代理升级设定指南 - Escalation","ja":"AIエージェントのエスカレーション設定ガイド","ko":"AI 에이전트升级 설정 가이드 - Escalation","es":"Guía de configuración de escalación de AI Agents","fr":"Guide de mise en place de l''escalade pour les outils IA","de":"Einrichtungsleitfaden für die Eskalation von KI-Agents","pt":"Guia de Configuração de Escalada de IA","ru":"ИИ Агенты: Руководство по настройке эскалации","ar":"دليل إعداد تصعيد وكيل الذكاء الاصطناعي"},"description":{"en":"Master escalation techniques with Haiku, Sonnet, and Opus tiers. Learn how to troubleshoot efficiently and optimize your workflow with our expert guide.","zh":"了解AI智能代理的升级流程和最佳实践，包括Haiku、Sonnet和Opus等级","ja":"AIエージェントのエスカレーションプロセスとベストプラクティスについて学習する - Haiku、Sonnet、Opus","ko":"AI 에이전트의升级 프로세스와 최선의 실践 방법을 알아보세요 - Haiku, Sonnet, Opus","es":"Aprende a configurar la escalación de tareas en AI Agents de manera efectiva con nuestros consejos y mejores prácticas","fr":"Découvrez comment configurer l''escalade des tâches dans les outils IA de manière efficace avec nos conseils et bonnes pratiques","de":"Erfahren Sie, wie Sie die Eskalation von Aufgaben in KI-Agents effektiv konfigurieren können, mit unseren Tipps und Best Practices","pt":"Aprenda a configurar a escalada de IA para melhorar a eficiência do seu modelo. Descubra as melhores práticas e dicas para otimizar a escalada.","ru":"Узнайте, как настроить эскалацию ИИ для повышения эффективности вашей модели. Откройте для себя лучшие практики и советы для оптимизации эскалации.","ar":"تعرف على كيفية ضبط تصعيد الذكاء الاصطناعي لتحسين كفاءة نموذجك. اكتشف_afأفضل الممارسات والنصائح لتحسين التصعيد."},"definition":{"en":"Escalation is a tiered troubleshooting process using Haiku, Sonnet, and Opus levels to efficiently resolve issues in a structured manner.","zh":"升级是AI智能代理中的一种机制，用于在任务失败时将问题升级到更高级别的处理","ja":"エスカレーションは、AIエージェントの中でタスクが失敗した場合に問題をより高いレベルの処理に昇格させるメカニズムです","ko":"升级은 AI 에이전트에서 작업이 실패한 경우에 문제를 더 높은 수준의 처리로升级시키는 메커니즘입니다","es":"La escalación es un proceso de asignación de tareas a diferentes niveles de complejidad para resolver problemas de manera eficiente","fr":"L''escalade est un processus d''assignation de tâches à différents niveaux de complexité pour résoudre les problèmes de manière efficace","de":"Die Eskalation ist ein Prozess der Zuweisung von Aufgaben zu verschiedenen Komplexitätsstufen, um Probleme effizient zu lösen","pt":"Escalada de IA é um processo de transição entre níveis de complexidade para resolver problemas complexos.","ru":"Эскалация ИИ - это процесс перехода между уровнями сложности для решения сложных проблем.","ar":"تصعيد الذكاء الاصطناعي هو عملية الانتقال بين مستويات التعقيد لحل المشكلات المعقدة."},"features":{"en":["Utilizes Haiku tier for initial troubleshooting attempts","Employs Sonnet tier for intermediate issue resolution","Leverages Opus tier for complex, cross-cutting problems","Ensures never skipping tiers with a sequential escalation approach","Allows one attempt per tier before escalating to the next level","Supports exception handling for tasks requiring Opus level expertise"],"zh":["Haiku等级：junior-coder、docs、explainer、optimizer","Sonnet等级：coder、tech-lead、reviewer、qa、architect、explorer","Opus等级：senior-coder、planner、red-teamer","升级流程：Haiku → Sonnet → Opus","每个等级仅有一次尝试机会","特定任务可直接升级到Opus"],"ja":["Haikuレベル：junior-coder、docs、explainer、optimizer","Sonnetレベル：coder、tech-lead、reviewer、qa、architect、explorer","Opusレベル：senior-coder、planner、red-teamer","エスカレーションプロセス：Haiku → Sonnet → Opus","各レベルには1回の試行機会のみ","特定のタスクはOpusに直接エスカレート可能"],"ko":["Haiku 등급：junior-coder、docs、explainer、optimizer","Sonnet 등급：coder、tech-lead、reviewer、qa、architect、explorer","Opus 등급：senior-coder、planner、red-teamer","升级 프로세스：Haiku → Sonnet → Opus","각 등급에는 1회의 시도 기회만","특정 작업은 Opus로 직접升级 가능"],"es":["Niveles de complejidad escalonados: Haiku, Sonnet y Opus","Asignación de tareas a diferentes roles: junior-coder, coder, senior-coder","Mecanismo de escalación automática en caso de fallo","Limitación de intentos por nivel: solo un intento por nivel antes de escalar","Excepción para tareas que requieren arquitectura o funcionalidad transversal"],"fr":["Niveaux de complexité escalonés : Haiku, Sonnet et Opus","Assignation de tâches à différents rôles : junior-coder, coder, senior-coder","Mécanisme d''escalade automatique en cas d''échec","Limitation des tentatives par niveau : une seule tentative par niveau avant d''escalader","Exception pour les tâches qui nécessitent une architecture ou une fonctionnalité transversale"],"de":["Stufen der Komplexität: Haiku, Sonnet und Opus","Zuweisung von Aufgaben zu verschiedenen Rollen: junior-coder, coder, senior-coder","Mechanismus der automatischen Eskalation im Falle eines Fehlers","Begrenzung der Versuche pro Stufe: nur ein Versuch pro Stufe vor der Eskalation","Ausnahme für Aufgaben, die Architektur oder Querschnittsfunktion erfordern"],"pt":["Três níveis de complexidade: Haiku, Sonnet e Opus","Transição entre níveis baseada em falha","Cada nível tem apenas uma tentativa antes da escalada","Exceção para tarefas que requerem Opus","Ordem de escalada: Haiku → Sonnet → Opus"],"ru":["Три уровня сложности: Haiku, Sonnet и Opus","Переход между уровнями на основе неудачи","Каждый уровень имеет только одну попытку перед эскалацией","Исключение для задач, требующих Opus","Порядок эскалации: Haiku → Sonnet → Opus"],"ar":["ثلاثة مستويات من التعقيد: Haiku و Sonnet و Opus","الانتقال بين المستويات على أساس الفشل","كل مستوى له محاولة واحدة فقط قبل التصعيد","استثناء للمهام التي تتطلب Opus","ترتيب التصعيد: Haiku → Sonnet → Opus"]},"keywords":{"en":["how to use escalation in AI agents","what is escalation in troubleshooting","escalation vs traditional troubleshooting methods","escalation setup guide for developers","escalation tiered troubleshooting approach","escalation Haiku Sonnet Opus levels"],"zh":["AI智能代理","升级","Haiku","Sonnet","Opus","AI代理升级流程","AI代理最佳实践","AI智能代理升级设定"],"ja":["AIエージェント","エスカレーション","Haiku","Sonnet","Opus","AIエージェントのエスカレーションプロセス","AIエージェントのベストプラクティス","AIエージェントのエスカレーション設定"],"ko":["AI 에이전트","升级","Haiku","Sonnet","Opus","AI 에이전트의升级 프로세스","AI 에이전트의 최선의 실践 방법","AI 에이전트의升级 설정"],"es":["escalación de AI Agents","configuración de escalación","niveles de complejidad","asignación de tareas","roles de desarrollo","mécanismo de escalación","limitación de intentos","excepción para tareas complejas"],"fr":["escalade des outils IA","configuration de l''escalade","niveaux de complexité","assignation de tâches","rôles de développement","mécanisme d''escalade","limitation des tentatives","exception pour les tâches complexes"],"de":["Eskalation von KI-Agents","Einrichtung der Eskalation","Stufen der Komplexität","Zuweisung von Aufgaben","Entwicklungsrollen","Mechanismus der Eskalation","Begrenzung der Versuche","Ausnahme für komplexe Aufgaben"],"pt":["escalada de ia","ia agents","modelos de ia","otimização de ia","desenvolvimento de ia","ia para desenvolvedores","guias de configuração de ia"],"ru":["эскалация ии","ии агенты","модели ии","оптимизация ии","разработка ии","ии для разработчиков","руководства по настройке ии"],"ar":["تصعيد الذكاء الاصطناعي","أدوات الذكاء الاصطناعي","نماذج الذكاء الاصطناعي","تحسين الذكاء الاصطناعي","تطوير الذكاء الاصطناعي","الذكاء الاصطناعي للمطورين","دلائل إعداد الذكاء الاصطناعي"]}},"owner":"eysenfalk","repo":"git-review","repoPath":"eysenfalk/git-review","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.300Z","topics":[],"category":"community","skillMd":{"name":"escalation","description":"Confidence-based model tier escalation for agent tasks. Defines when to escalate from Haiku to Sonnet to Opus, escalation signals, and the never-skip-tiers rule. Use when an agent fails or underperforms.","bodyPreview":"# Model Escalation\n\n## Escalation Tiers\n\n```\nHaiku (junior-coder, docs, explainer, optimizer)\n  ↓ on failure\nSonnet (coder, tech-lead, reviewer, qa, architect, explorer)\n  ↓ on failure\nOpus (senior-coder, planner, red-teamer)\n```\n\n## Never Skip Tiers\n\n- ALWAYS try the next tier first before jumping to Opus\n- Haiku → Sonnet → Opus (never Haiku → Opus directly)\n- Each tier gets ONE attempt before escalation\n- Exception: if the task is known to require Opus (architecture, cross-cutting), start ther","body":"# Model Escalation\n\n## Escalation Tiers\n\n```\nHaiku (junior-coder, docs, explainer, optimizer)\n  ↓ on failure\nSonnet (coder, tech-lead, reviewer, qa, architect, explorer)\n  ↓ on failure\nOpus (senior-coder, planner, red-teamer)\n```\n\n## Never Skip Tiers\n\n- ALWAYS try the next tier first before jumping to Opus\n- Haiku → Sonnet → Opus (never Haiku → Opus directly)\n- Each tier gets ONE attempt before escalation\n- Exception: if the task is known to require Opus (architecture, cross-cutting), start there\n\n## Escalation Signals\n\nEscalate to the next tier when:\n\n- **Test failures**: Agent''s code fails tests and agent can''t fix in one retry\n- **Clippy warnings**: Agent introduces warnings it can''t resolve\n- **Wrong output schema**: Agent produces output that doesn''t match expected format\n- **Tech-lead BLOCKED twice**: Tech-lead rejects the same agent''s work twice on the same task\n- **Task timeout**: Agent exceeds expected completion time by 2x\n- **Repeated hook blocks**: Agent triggers enforcement hooks 3+ times on the same operation\n\n## Do NOT Escalate When\n\n- Task is simply large (break it down instead)\n- Agent needs more context (add skills/instructions instead)\n- Infrastructure error (retry, don''t escalate)\n- First-time failure on a reasonable task (retry once at same tier)\n\n## Escalation Protocol\n\n1. Diagnose the failure (see `capability-diagnostic` skill)\n2. Determine if it''s a model capability issue (Step 3 of diagnostic)\n3. If yes: re-assign task to next tier agent with original prompt + \"Previous attempt failed because: [reason]\"\n4. If no: fix the actual issue (context, tools, spec) and retry at same tier\n\n## Tracking\n\n- Log escalations to claude-mem: \"Escalated [task type] from [tier] to [tier] because [reason]\"\n- After 3+ escalations of the same task type → update agent-routing defaults\n- The optimizer agent reviews escalation patterns periodically\n"},"lastSynced":"2026-03-08T02:01:31.391Z","agentAnalysis":{"suitability":{"en":"Ideal for Technical Support Agents requiring structured issue resolution and escalation procedures.","zh":"适合需要结构化问题解决和升级程序的技术支持代理","ja":"技術サポートエージェントが構造化された問題解決とエスカレーション手順を必要とする場合に最適","ko":"구조화된 문제 해결 및 에스컬레이션 절차가 필요한 기술 지원 에이전트에게 적합","es":"Ideal para Agentes de Soporte Técnico que requieren una resolución de problemas estructurada y procedimientos de escalación.","fr":"Idéal pour les agents de support technique nécessitant une résolution de problèmes structurée et des procédures d''escalade.","de":"Ideal für technische Support-Agenten, die eine strukturierte Problemlösung und Eskalationsverfahren erfordern.","pt":"Ideal para Agentes de Suporte Técnico que exigem resolução de problemas estruturada e procedimentos de escalação.","ru":"Идеально для технических агентов поддержки, требующих структурированного решения проблем и процедур эскалации.","ar":"مثالي لوكلاء الدعم الفني الذين يتطلبون حل vấnة منظم وإجراءات تصعيد."},"recommendation":{"en":"Empowers agents to progress through Haiku, Sonnet, and Opus tiers for efficient issue resolution, utilizing a structured approach to troubleshooting with junior-coder, coder, and senior-coder expertise, ensuring never to skip tiers and always attempting the next tier first.","zh":"赋予代理人使用结构化方法进行故障排除的能力，利用初级编码员、编码员和高级编码员的专业知识，逐步推进Haiku、Sonnet和Opus级别，以确保高效的问题解决，从不跳过级别，总是尝试下一个级别","ja":"エージェントに構造化されたアプローチを使用してトラブルシューティングを行う能力を与え、ジュニアコーダー、コーダー、シニアコーダーの専門知識を利用してHaiku、Sonnet、Opusの各レベルを効率的に進めることができるようになります。レベルをスキップしないことを保証し、常に次のレベルを最初に試みます","ko":"에이전트에게 구조화된 접근 방식을 사용하여 문제를 해결하는 능력을 부여하여 Haiku, Sonnet 및 Opus 티어를 효율적으로 진행할 수 있도록 하며, 주니어 코더, 코더 및 시니어 코더의 전문 지식을 활용하여 티어를 건너뛰지 않고 항상 다음 티어를 먼저 시도","es":"Permite a los agentes progresar a través de las categorías Haiku, Sonnet y Opus para una resolución eficiente de problemas, utilizando un enfoque estructurado para la resolución de problemas con experiencia junior-coder, coder y senior-coder, asegurando de no saltar categorías y siempre intentando la siguiente categoría primero.","fr":"Permet aux agents de progresser à travers les catégories Haiku, Sonnet et Opus pour une résolution efficace des problèmes, en utilisant une approche structurée pour la résolution des problèmes avec une expertise junior-coder, coder et senior-coder, en s''assurant de ne pas sauter les catégories et en essayant toujours la catégorie suivante en premier.","de":"Ermöglicht es den Agenten, durch die Kategorien Haiku, Sonnet und Opus für eine effiziente Problemlösung zu gelangen, indem sie einen strukturierten Ansatz für die Fehlerbehebung mit junior-coder-, coder- und senior-coder-Expertise verwenden, wobei sichergestellt wird, dass keine Kategorien übersprungen werden und immer zuerst der nächste Tier versucht wird.","pt":"Habilita os agentes a progredir através das camadas Haiku, Sonnet e Opus para resolução eficiente de problemas, utilizando uma abordagem estruturada para solução de problemas com expertise de junior-coder, coder e senior-coder, garantindo nunca pular as camadas e sempre tentar a próxima camada primeiro.","ru":"Наделяет агентов возможностью продвигаться через уровни Haiku, Sonnet и Opus для эффективного решения проблем, используя структурированный подход к устранению неполадок с опытом junior-coder, coder и senior-coder, гарантируя, что ни один уровень не будет пропущен и всегда будет предприниматься попытка следующего уровня сначала.","ar":"تمكن الوكلاء من التقدم من خلال مستويات Haiku و Sonnet و Opus لحل مشكلات فعال، باستخدام نهج منظم للتصحيح مع خبرة junior-coder و coder و senior-coder، وضمان ألا يتم تخطي أي مستوى ومحاولة المستوى التالي أولاً."},"useCases":{"en":["Escalating issues through Haiku and Sonnet tiers before reaching Opus","Implementing a structured troubleshooting approach for technical leads and developers","Resolving cross-cutting issues by starting directly at the Opus tier"],"zh":["通过Haiku和Sonnet级别升级问题，然后到达Opus级别","为技术负责人和开发人员实施结构化的故障排除方法","从Opus级别直接开始解决跨领域问题"],"ja":["HaikuとSonnetのレベルを経て問題をエスカレートし、Opusレベルに到達する","技術リードと開発者向けに構造化されたトラブルシューティングアプローチを実装する","Opusレベルから直接開始して、クロスカットする問題を解決する"],"ko":["Haiku 및 Sonnet 티어를 통해 문제를 에스컬레이션하여 Opus 티어에 도달","기술 리드 및 개발자에게 구조화된 문제 해결 접근 방식을 구현","Opus 티어에서 직접 시작하여 교차 문제를 해결"],"es":["Escalando problemas a través de las categorías Haiku y Sonnet antes de llegar a Opus","Implementando un enfoque de resolución de problemas estructurado para líderes técnicos y desarrolladores","Resolviendo problemas que afectan varios ámbitos iniciando directamente en la categoría Opus"],"fr":["Escalader des problèmes à travers les catégories Haiku et Sonnet avant d''atteindre Opus","Mettre en œuvre une approche de résolution de problèmes structurée pour les responsables techniques et les développeurs","Résoudre des problèmes transversaux en commençant directement par la catégorie Opus"],"de":["Probleme durch die Kategorien Haiku und Sonnet eskalieren, bevor Opus erreicht wird","Ein strukturiertes Ansatz für die Fehlerbehebung für technische Leiter und Entwickler implementieren","Probleme, die mehrere Bereiche betreffen, lösen, indem direkt mit der Kategorie Opus begonnen wird"],"pt":["Escalando problemas através das camadas Haiku e Sonnet antes de atingir a camada Opus","Implementando uma abordagem de solução de problemas estruturada para leads técnicos e desenvolvedores","Resolvendo problemas transversais iniciando diretamente na camada Opus"],"ru":["Эскалация проблем через уровни Haiku и Sonnet до достижения уровня Opus","Реализация структурированного подхода к устранению неполадок для технических лидеров и разработчиков","Решение перекрестных проблем, начиная直接 с уровня Opus"],"ar":["تصعيد المشكلات من خلال مستويات Haiku و Sonnet قبل الوصول إلى مستوى Opus","تنفيذ نهج منظم لتصحيح الأخطاء لفريق التطوير والقادة الفنيين","حل المشكلات المتقاطعة بالبدء مباشرةً من مستوى Opus"]},"limitations":{"en":["Requires adherence to the tiered escalation structure","Each tier allows only one attempt before escalation","Exceptions apply for tasks known to require Opus-level expertise"],"zh":["需要遵守分级升级结构","每个级别只允许一次尝试，然后升级","已知需要Opus级别专业知识的任务除外"],"ja":["階層化されたエスカレーション構造に従う必要がある","各レベルではエスカレート前に1回だけ試行することができる","Opusレベルの専門知識を必要とするタスクは除外される"],"ko":["티어화된 에스컬레이션 구조를 준수해야 함","각 티어에서는 에스컬레이션 전에 1회만 시도할 수 있음","Opus 티어의 전문 지식이 필요한 작업은 예외"],"es":["Requiere adherirse a la estructura de escalación por categorías","Cada categoría solo permite un intento antes de la escalación","Se aplican excepciones para tareas conocidas que requieren experiencia de nivel Opus"],"fr":["Nécessite d''adhérer à la structure d''escalade par catégories","Chaque catégorie n''autorise qu''une seule tentative avant l''escalade","Des exceptions s''appliquent pour les tâches connues pour nécessiter une expertise de niveau Opus"],"de":["Erfordert die Einhaltung der eskalierten Struktur nach Kategorien","Jede Kategorie erlaubt nur einen Versuch vor der Eskalation","Ausnahmen gelten für Aufgaben, die bekanntermaßen Expertenwissen auf Opus-Ebene erfordern"],"pt":["Exige aderência à estrutura de escalação em camadas","Cada camada permite apenas uma tentativa antes da escalação","Exceções se aplicam para tarefas conhecidas por exigir expertise de nível Opus"],"ru":["Требует соблюдения структуры эскалации по уровням","Каждый уровень позволяет только одну попытку до эскалации","Исключения применяются для задач, известных как требующие опыта уровня Opus"],"ar":["يتطلب الالتزام ببنية التصعيد المتدرج","يسمح كل مستوى بمحاولة واحدة فقط قبل التصعيد","تطبق الاستثناءات على المهام المعروفة التي تتطلب خبرة على مستوى Opus"]},"version":4},"contentHash":"8b21649730646f2cd6186f44a0593423ddd716801842749c124e8c9c63d8d9f2","qualityScore":45}');
