INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eysenfalk/git-review/escalation', 'escalation', 'eysenfalk', 'git-review', 'community', 'escalation eysenfalk git-review community The escalation skill provides a structured approach to troubleshooting, benefiting developers and technical leads. It ensures efficient issue resolution by progressing through Haiku, Sonnet, and Opus tiers. AI智能代理的升级涉及Haiku、Sonnet和Opus等级，每个等级都有特定的角色和职责 AIエージェントのエスカレーションはHaiku、Sonnet、Opusの各レベルで構成され、各レベルに固有の役割と責任があります AI 에이전트의升级에는 Haiku, Sonnet, Opus 등급이 포함되며, 각 등급에는 고유한 역할과 책임이 있습니다 La escalación de AI Agents implica la asignación de tareas a diferentes niveles de complejidad, desde Haiku hasta Opus, para garantizar la resolución eficiente de problemas L''escalade des outils IA implique l''assignation de tâches à différents niveaux de complexité, de Haiku à Opus, pour assurer une résolution efficace des problèmes Die Eskalation von KI-Agents beinhaltet die Zuweisung von Aufgaben zu verschiedenen Komplexitätsstufen, von Haiku bis Opus, um eine effiziente Problemlösung zu gewährleisten A escalada de IA é um processo que envolve a transição entre níveis de complexidade. Ela é composta por três níveis: Haiku, Sonnet e Opus. Эскалация ИИ - это процесс, включающий переход между уровнями сложности. Она состоит из трех уровней: Haiku, Sonnet и Opus. تصعيد الذكاء الاصطناعي هو عملية تتضمن الانتقال بين مستويات التعقيد. يتألف من ثلاثة مستويات: Haiku و Sonnet و Opus. how to use escalation in AI agents what is escalation in troubleshooting escalation vs traditional troubleshooting methods escalation setup guide for developers escalation tiered troubleshooting approach escalation Haiku Sonnet Opus levels AI智能代理 升级 Haiku Sonnet Opus AI代理升级流程 AI代理最佳实践 AI智能代理升级设定 Utilizes Haiku tier for initial troubleshooting attempts Employs Sonnet tier for intermediate issue resolution Leverages Opus tier for complex, cross-cutting problems Ensures never skipping tiers with a sequential escalation approach Allows one attempt per tier before escalating to the next level Supports exception handling for tasks requiring Opus level expertise Escalation is a tiered troubleshooting process using Haiku, Sonnet, and Opus levels to efficiently resolve issues in a structured manner.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AbeJitsu/Need_This_Done/think-ahead', 'community', 'AbeJitsu', 'Need_This_Done', 'AbeJitsu/Need_This_Done', 'think-ahead', 0, 0, 45, '2026-03-08T01:57:15.301Z', '2026-03-08T02:01:33.431Z', 'ac02661c0ab9e5a96412b0486a7dd2670b314cf94ba1d7f7cbad7acf02fd370a', '{"id":"AbeJitsu/Need_This_Done/think-ahead","name":"think-ahead","description":{"en":"think-ahead is a strategic planning partner that reads worker instance progress, helping you understand what''s been built and plan the next moves. It benefits developers by providing insightful planning and coordination.","zh":"Think Ahead是您的战略规划伙伴，帮助您理解项目进度、发现依赖关系和阻塞点、规划下一步","ja":"Think Aheadは、プロジェクトの進捗を理解し、依存関係とブロッキングポイントを特定し、次のステップを計画するための戦略的パートナーです","ko":"Think Ahead는 프로젝트 진행状況을 이해하고 의존 관계와 차단 지점을 식별하며 다음 단계를 계획하는 전략적 파트너입니다","es":"Think Ahead es un partner de planificación estratégica que lee el progreso de tu proyecto y te ayuda a planificar el próximo movimiento","fr":"Think Ahead est un partenaire de planification stratégique qui lit le progrès de votre projet et vous aide à planifier le prochain mouvement","de":"Think Ahead ist ein Partner für strategische Planung, der den Fortschritt Ihres Projekts liest und Ihnen hilft, den nächsten Schritt zu planen","pt":"O Think Ahead é uma ferramenta de planejamento estratégico que ajuda a entender o progresso e a planejar as próximas etapas, utilizando tecnologias como CLI para coordenar tarefas","ru":"ИИ Агент Think Ahead - это инструмент стратегического планирования, который помогает понять прогресс и спланировать следующие шаги, используя технологии như CLI для координации задач","ar":"Think Ahead هو أداة التخطيط الاستراتيجي التي تساعد على فهم التقدم وخطط الخطوات التالية، باستخدام تقنيات مثل CLI لتنسيق المهام"},"seo":{"title":{"en":"think-ahead: Strategic Planning Partner for AI Agents | A...","zh":"Think Ahead Setup Guide - AIエージェント工具","ja":"Think Ahead ベストプラクティス - AIエージェントを活用する","ko":"Think Ahead 개발자 가이드 - AI 도구를 활용한 프로젝트 관리","es":"Guía para configurar Think Ahead: Planificación estratégi...","fr":"Think Ahead: Le partenaire de planification stratégique p...","de":"Think Ahead-Setup-Anleitung: Strategische Planung für Ent...","pt":"Guia de Configuração do Think Ahead: Ferramenta de Planej...","ru":"Настройка ИИ Агента Think Ahead: Руководство по стратегич...","ar":"دليل إعداد Think Ahead: أداة التخطيط الاستراتيجي"},"description":{"en":"Get ahead of your workflow with think-ahead. Discover how to anticipate problems, spot dependencies, and plan thoughtfully. Learn more and start optimizing y...","zh":"了解Think Ahead AIエージェント工具，实现项目管理的自动化和优化，提高开发效率","ja":"Think Ahead AIエージェントを使用して、プロジェクト管理を最適化し、開発効率を向上させる","ko":"Think Ahead AI 도구를 사용하여 프로젝트 관리를 자동화하고 개발 효율성을 높여보세요","es":"Descubre cómo Think Ahead te ayuda a entender el progreso, detectar dependencias y planificar el próximo movimiento en tu proyecto de desarrollo","fr":"Découvrez comment Think Ahead vous aide à comprendre le progrès, à détecter les dépendances et à planifier le prochain mouvement dans votre projet de dévelop...","de":"Erfahren Sie, wie Think Ahead Ihnen hilft, den Fortschritt zu verstehen, Abhängigkeiten zu erkennen und den nächsten Schritt in Ihrem Entwicklungsprojekt zu ...","pt":"Aprenda a configurar o Think Ahead, uma ferramenta de planejamento estratégico que ajuda a entender o progresso e a planejar as próximas etapas","ru":"Узнайте, как настроить ИИ Агент Think Ahead, инструмент стратегического планирования, который помогает понять прогресс и спланировать следующие шаги","ar":"تعرف على كيفية إعداد Think Ahead، أداة التخطيط الاستراتيجي التي تساعد على فهم التقدم وخطط الخطوات التالية"},"definition":{"en":"think-ahead is a skill that acts as a thinking partner to a working partner, enabling developers to stay one step ahead in their workflow by understanding progress, spotting opportunities, and planning the next features.","zh":"Think Ahead是一种AIエージェント工具，帮助开发者理解项目进度、发现依赖关系和阻塞点","ja":"Think Aheadは、開発者がプロジェクトの進捗を理解し、依存関係とブロッキングポイントを特定するためのAIエージェントです","ko":"Think Ahead는 개발자가 프로젝트 진행 상황을 이해하고 의존 관계와 차단 지점을 식별할 수 있는 AI 도구입니다","es":"Think Ahead es una habilidad de planificación estratégica que ayuda a los desarrolladores a entender y planificar su proyecto","fr":"Think Ahead est une compétence de planification stratégique qui aide les développeurs à comprendre et à planifier leur projet","de":"Think Ahead ist eine Fähigkeit zur strategischen Planung, die Entwicklern hilft, ihr Projekt zu verstehen und zu planen","pt":"O que é Think Ahead? É uma ferramenta de planejamento estratégico que ajuda a entender o progresso e a planejar as próximas etapas","ru":"Что такое ИИ Агент Think Ahead? Это инструмент стратегического планирования, который помогает понять прогресс и спланировать следующие шаги","ar":"ما هو Think Ahead؟ هو أداة التخطيط الاستراتيجي التي تساعد على فهم التقدم وخطط الخطوات التالية"},"features":{"en":["Reads worker instance progress to understand what''s been built","Spots dependencies and blockers to plan the next moves","Plans the next feature thoughtfully to ensure smooth workflow","Coordinates between tasks to anticipate problems before they happen"],"zh":["理解项目进度","发现依赖关系和阻塞点","规划下一步","协调任务","预测问题"],"ja":["プロジェクトの進捗を理解","依存関係とブロッキングポイントを特定","次のステップを計画","タスクの調整","問題の予測"],"ko":["프로젝트 진행 상황을 이해","의존 관계와 차단 지점을 식별","다음 단계를 계획","작업 조정","문제 예측"],"es":["Lectura del progreso del proyecto","Detección de dependencias y bloqueos","Planificación del próximo movimiento","Coordinación entre tareas","Anticipación de problemas"],"fr":["Lecture du progrès du projet","Détection des dépendances et des bloqueurs","Planification du prochain mouvement","Coordination entre les tâches","Anticipation des problèmes"],"de":["Lese den Fortschritt des Projekts","Erkennung von Abhängigkeiten und Blockierungen","Planung des nächsten Schritts","Koordinierung zwischen Aufgaben","Vorhersage von Problemen"],"pt":["Entenda o progresso do trabalhador","Identifique dependências e bloqueadores","Planeje as próximas características com cuidado","Coordene tarefas utilizando CLI","Antecipe problemas antes que ocorram"],"ru":["Понимайте прогресс рабочего","Определите зависимости и блокировщики","Спланируйте следующие характеристики тщательно","Координируйте задачи с помощью CLI","Предвидьте проблемы до их возникновения"],"ar":["افهم تقدم العامل","حدد الاعتماديات والموانع","خطط للميزات التالية بعناية","تنسق المهام باستخدام CLI","توقع المشاكل قبل حدوثها"]},"keywords":{"en":["how to use think-ahead","what is think-ahead","think-ahead alternative","think-ahead vs workflow management tools","think-ahead install","think-ahead setup guide","think-ahead for AI agents","strategic planning with think-ahead","workflow optimization with think-ahead"],"zh":["AIエージェント工具","项目管理","自动化","优化","开发效率","Think Ahead","战略规划","依存关系","阻塞点"],"ja":["AIエージェント","プロジェクト管理","自動化","最適化","開発効率","Think Ahead","戦略的パートナー","依存関係","ブロッキングポイント"],"ko":["AI 도구","프로젝트 관리","자동화","최적화","개발 효율성","Think Ahead","전략적 파트너","의존 관계","차단 지점"],"es":["Think Ahead","planificación estratégica","desarrollo de software","herramientas de desarrollo","Agente de IA para desarrolladores","planificación de proyectos","gestión de dependencias","coordinación de tareas"],"fr":["Think Ahead","planification stratégique","développement de logiciels","outils de développement","Agent IA pour développeurs","planification de projets","gestion de dépendances","coordination de tâches"],"de":["Think Ahead","strategische Planung","Software-Entwicklung","Entwicklertools","KI-Agent für Entwickler","Projektplanung","Abhängigkeitsmanagement","Aufgabenkoordinierung"],"pt":["Think Ahead","ferramenta de planejamento estratégico","CLI","coordenação de tarefas","planejamento de recursos","gestão de projetos","desenvolvimento de software"],"ru":["ИИ Агент Think Ahead","инструмент стратегического планирования","CLI","координация задач","планирование ресурсов","управление проектами","разработка программного обеспечения"],"ar":["Think Ahead","أداة التخطيط الاستراتيجي","CLI","تنسيق المهام","تخطيط الموارد","إدارة المشاريع","تطوير البرمجيات"]}},"owner":"AbeJitsu","repo":"Need_This_Done","repoPath":"AbeJitsu/Need_This_Done","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.301Z","topics":[],"category":"community","skillMd":{"name":"think-ahead","description":"AI thinking partner for strategy and planning. Reads the current work state, analyzes progress, and helps you plan the next phase while the worker instance builds. Triggered by think ahead.","bodyPreview":"# Think Ahead\n\nYour strategic planning partner. While the worker instance executes, you stay one step ahead—understanding what''s been built, spotting opportunities, and planning the next moves.\n\n## The Role\n\nYou''re the **thinking partner** ↔ They''re the **working partner**\n\nThis skill reads their progress and helps you:\n- Understand what just shipped\n- Spot dependencies and blockers\n- Plan the next feature thoughtfully\n- Coordinate between tasks\n- Anticipate problems before they happen\n\n## When","body":"# Think Ahead\n\nYour strategic planning partner. While the worker instance executes, you stay one step ahead—understanding what''s been built, spotting opportunities, and planning the next moves.\n\n## The Role\n\nYou''re the **thinking partner** ↔ They''re the **working partner**\n\nThis skill reads their progress and helps you:\n- Understand what just shipped\n- Spot dependencies and blockers\n- Plan the next feature thoughtfully\n- Coordinate between tasks\n- Anticipate problems before they happen\n\n## When To Use\n\nSay: **\"think ahead\"**\n\nPerfect for:\n- **Between work cycles** - Worker finishes a task, you plan the next one\n- **Strategic pauses** - Before committing to a direction, validate the approach\n- **Blocking detection** - Spot if work is waiting on external setup (Google Cloud, credentials, etc.)\n- **Dependency mapping** - See what needs what, plan build order\n- **Opportunity spotting** - Notice refactoring chances or improvements\n- **Coordination** - When multiple features are in flight, stay synchronized\n\n## What This Delivers\n\nI''ll:\n\n1. **Read current state** - `git status`, `git diff`, last 10 commits\n2. **Check plan alignment** - What was TODO, what actually got built\n3. **Analyze trajectory** - See patterns in commits and progress\n4. **Flag blockers** - External setup, missing credentials, test failures\n5. **Suggest next moves** - What logically comes next, in priority order\n\nThen present it as:\n\n```\n### Current State\nBranch, staged changes, unstaged work\n\n### What Just Shipped\nStaged changes ready to commit\nTests, screenshots, infrastructure\n\n### What''s In Progress\nUnstaged changes still being polished\nIncomplete work that needs finishing\n\n### The Arc\nRecent commits showing the direction\nHow pieces fit together\nWhat the pattern suggests\n\n### Strategic Recommendations\nPriority 1: What must happen next\nPriority 2: What depends on that\nPriority 3: What''s blocked and why\nWhat should the worker tackle next?\n```\n\n## The Workflow\n\n```\nWorker builds → You think ahead → Plan next task → Worker executes\n     ↓\n   Repeat\n```\n\nThink of it like:\n- **Worker** = Getting things done, implementing features\n- **You** = Understanding the landscape, planning strategically\n- **This skill** = Bridging the gap, keeping strategy and execution aligned\n"},"lastSynced":"2026-03-08T02:01:33.431Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring strategic planning and coordination capabilities to enhance worker instance progress analysis.","zh":"适用于需要战略规划和协调能力以增强工人实例进度分析的开发代理。","ja":"開発エージェントが戦略的計画と調整能力を必要とする場合に適しています。そうすることで、ワーカーインスタンスの進捗状況分析が強化されます。","ko":"전략적 계획 및 조정 기능을 통해 작업자 인스턴스 진행 상황 분석을 강화해야 하는 개발 에이전트에게 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren capacidades de planificación estratégica y coordinación para mejorar el análisis del progreso de las instancias de trabajador.","fr":"Idéal pour les agents de développement nécessitant des capacités de planification stratégique et de coordination pour améliorer l''analyse du progrès des instances de travailleur.","de":"Ideal für Entwicklungssagenten, die strategische Planungs- und Koordinierungsfähigkeiten benötigen, um die Analyse des Fortschritts von Arbeitsinstanzen zu verbessern.","pt":"Ideal para Agentes de Desenvolvimento que requerem capacidades de planejamento estratégico e coordenação para melhorar a análise de progresso de instâncias de trabalhador.","ru":"Идеально для агентов разработки, требующих стратегического планирования и координации для улучшения анализа прогресса экземпляров рабочих.","ar":"مثالي للوكلاء النموذجيين الذين يتطلبون قدرات التخطيط الاستراتيجي والتنسيق لتحسين تحليل التقدم لمثيلات العامل."},"recommendation":{"en":"Empowers agents to anticipate problems before they happen, spot dependencies and blockers, and plan the next feature thoughtfully using insightful planning and coordination, leveraging progress analysis and dependency spotting through protocols like worker instance execution tracking.","zh":"赋予代理预测问题的能力，在问题发生之前发现依赖关系和阻塞点，并利用洞察性的计划和协调，通过协议如工人实例执行跟踪来进行进度分析和依赖关系发现，从而深思熟虑地规划下一个功能。","ja":"エージェントが問題を起こす前に予測し、依存関係やブロッカーやを特定し、洞察力のある計画と調整を利用して、ワーカーインスタンスの実行追跡などのプロトコルを通じて進捗状況分析と依存関係の特定を行い、次の機能を慎重に計画することができる。","ko":"에이전트가 문제가 발생하기 전에 예측할 수 있도록 하며, 의존성 및 차단점을 식별하고, 통찰력을 가진 계획 및 조정을 사용하여 프로토콜과 같은 작업자 인스턴스 실행 추적을 통해 진행 상황 분석 및 의존성 탐지를 수행하여 다음 기능을 신중하게 계획할 수 있습니다.","es":"Habilita a los agentes a anticipar problemas antes de que ocurran, detectar dependencias y bloqueadores, y planificar la próxima característica de manera reflexiva utilizando una planificación y coordinación perspicaz, aprovechando el análisis de progreso y la detección de dependencias a través de protocolos como el seguimiento de la ejecución de instancias de trabajador.","fr":"Permet aux agents d''anticiper les problèmes avant qu''ils ne se produisent, de détecter les dépendances et les bloqueurs, et de planifier la prochaine fonctionnalité de manière réfléchie en utilisant une planification et une coordination perspicaces, en exploitant l''analyse de progrès et la détection de dépendances via des protocoles tels que le suivi de l''exécution des instances de travailleur.","de":"Ermächtigt Agenten, Probleme vor ihrem Eintreten vorherzusehen, Abhängigkeiten und Blockierungen zu erkennen und die nächste Funktion sorgfältig unter Nutzung von einblicksvoller Planung und Koordinierung zu planen, die Analyse des Fortschritts und die Erkennung von Abhängigkeiten durch Protokolle wie die Nachverfolgung der Ausführung von Arbeitsinstanzen nutzend.","pt":"Habilita os agentes a antecipar problemas antes que ocorram, identificar dependências e bloqueadores e planejar a próxima funcionalidade de forma reflexiva utilizando o planejamento e a coordenação perspicazes, aproveitando a análise de progresso e a detecção de dependências por meio de protocolos como o rastreamento de execução de instâncias de trabalhador.","ru":"Наделяет агентов возможностью предвидеть проблемы до их возникновения, выявлять зависимости и блокировщики, и планировать следующую функцию вдумчиво, используя проницательное планирование и координацию, используя анализ прогресса и обнаружение зависимостей посредством протоколов, таких как отслеживание выполнения экземпляров рабочих.","ar":"تمكّن الوكلاء من توقع المشكلات قبل حدوثها، وتحديد الاعتماديات والحواجز، والتنبؤ بالميزة التالية بعناية فائقة باستخدام التخطيط والتنسيق الذكيين، واستخدام تحليل التقدم والكشف عن الاعتماديات من خلال بروتوكولات مثل تتبع تنفيذ مثيلات العامل."},"useCases":{"en":["Analyzing worker instance progress to inform strategic planning","Identifying dependencies and blockers to optimize development workflows","Coordinating tasks to ensure seamless execution and minimize delays"],"zh":["分析工人实例进度以告知战略规划","识别依赖关系和阻塞点以优化开发工作流","协调任务以确保无缝执行并最小化延迟"],"ja":["戦略的計画に情報を提供するためにワーカーインスタンスの進捗状況を分析する","開発ワークフローを最適化するために依存関係とブロッカーやを識別する","遅延を最小限に抑えながらスムーズに実行するためにタスクを調整する"],"ko":["전략적 계획에 정보를 제공하기 위해 작업자 인스턴스의 진행 상황을 분석합니다.","개발 워크플로를 최적화하기 위해 의존성 및 차단점을 식별합니다.","지연을 최소화하면서 무缝하게 실행하기 위해 작업을 조정합니다."],"es":["Analizar el progreso de las instancias de trabajador para informar la planificación estratégica","Identificar dependencias y bloqueadores para optimizar los flujos de trabajo de desarrollo","Coordinar tareas para garantizar una ejecución sin problemas y minimizar los retrasos"],"fr":["Analyser le progrès des instances de travailleur pour éclairer la planification stratégique","Identifier les dépendances et les bloqueurs pour optimiser les flux de travail de développement","Coordiner les tâches pour assurer une exécution sans problème et minimiser les retards"],"de":["Analysieren des Fortschritts von Arbeitsinstanzen, um die strategische Planung zu unterstützen","Identifizieren von Abhängigkeiten und Blockierungen, um Entwicklungswerkflüsse zu optimieren","Koordinieren von Aufgaben, um eine reibungslose Ausführung zu gewährleisten und Verzögerungen zu minimieren"],"pt":["Analisar o progresso de instâncias de trabalhador para informar o planejamento estratégico","Identificar dependências e bloqueadores para otimizar fluxos de trabalho de desenvolvimento","Coordenar tarefas para garantir a execução sem interrupções e minimizar atrasos"],"ru":["Анализ прогресса экземпляров рабочих для информирования стратегического планирования","Выявление зависимостей и блокировщиков для оптимизации потоков разработки","Координация задач для обеспечения бесперебойного выполнения и минимизации задержек"],"ar":["تحليل تقدم مثيلات العامل لإعلام التخطيط الاستراتيجي","تحديد الاعتماديات والحواجز لتحسين تدفقات العمل النموذجية","تنسيق المهام لضمان التنفيذ السلس والحد من التأخيرات"]},"limitations":{"en":["Requires access to worker instance progress data","Limited to development environments with worker instances"],"zh":["需要访问工人实例进度数据","仅限于具有工人实例的开发环境"],"ja":["ワーカーインスタンスの進捗状況データへのアクセスが必要","ワーカーインスタンスを持つ開発環境に限定される"],"ko":["작업자 인스턴스 진행 상황 데이터에 대한 액세스가 필요합니다.","작업자 인스턴스를 갖춘 개발 환경으로 제한됩니다."],"es":["Requiere acceso a los datos de progreso de las instancias de trabajador","Limitado a entornos de desarrollo con instancias de trabajador"],"fr":["Nécessite un accès aux données de progrès des instances de travailleur","Limité aux environnements de développement avec des instances de travailleur"],"de":["Benötigt Zugriff auf die Daten des Fortschritts von Arbeitsinstanzen","Begrenzt auf Entwicklungsumgebungen mit Arbeitsinstanzen"],"pt":["Requer acesso aos dados de progresso de instâncias de trabalhador","Limitado a ambientes de desenvolvimento com instâncias de trabalhador"],"ru":["Требует доступа к данным прогресса экземпляров рабочих","Ограничен средами разработки с экземплярами рабочих"],"ar":["يتطلب الوصول إلى بيانات تقدم مثيلات العامل","محدود بالبيئات النموذجية التي تحتوي على مثيلات العامل"]},"version":4},"contentHash":"ac02661c0ab9e5a96412b0486a7dd2670b314cf94ba1d7f7cbad7acf02fd370a","qualityScore":45}');
