INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AbeJitsu/Need_This_Done/think-ahead', 'think-ahead', 'AbeJitsu', 'Need_This_Done', 'community', 'think-ahead AbeJitsu Need_This_Done community think-ahead is a strategic planning partner that reads worker instance progress, helping you understand what''s been built and plan the next moves. It benefits developers by providing insightful planning and coordination. Think Ahead是您的战略规划伙伴，帮助您理解项目进度、发现依赖关系和阻塞点、规划下一步 Think Aheadは、プロジェクトの進捗を理解し、依存関係とブロッキングポイントを特定し、次のステップを計画するための戦略的パートナーです Think Ahead는 프로젝트 진행状況을 이해하고 의존 관계와 차단 지점을 식별하며 다음 단계를 계획하는 전략적 파트너입니다 Think Ahead es un partner de planificación estratégica que lee el progreso de tu proyecto y te ayuda a planificar el próximo movimiento Think Ahead est un partenaire de planification stratégique qui lit le progrès de votre projet et vous aide à planifier le prochain mouvement Think Ahead ist ein Partner für strategische Planung, der den Fortschritt Ihres Projekts liest und Ihnen hilft, den nächsten Schritt zu planen O Think Ahead é uma ferramenta de planejamento estratégico que ajuda a entender o progresso e a planejar as próximas etapas, utilizando tecnologias como CLI para coordenar tarefas ИИ Агент Think Ahead - это инструмент стратегического планирования, который помогает понять прогресс и спланировать следующие шаги, используя технологии như CLI для координации задач Think Ahead هو أداة التخطيط الاستراتيجي التي تساعد على فهم التقدم وخطط الخطوات التالية، باستخدام تقنيات مثل CLI لتنسيق المهام how to use think-ahead what is think-ahead think-ahead alternative think-ahead vs workflow management tools think-ahead install think-ahead setup guide think-ahead for AI agents strategic planning with think-ahead workflow optimization with think-ahead AIエージェント工具 项目管理 自动化 优化 开发效率 Think Ahead 战略规划 依存关系 阻塞点 Reads worker instance progress to understand what''s been built Spots dependencies and blockers to plan the next moves Plans the next feature thoughtfully to ensure smooth workflow Coordinates between tasks to anticipate problems before they happen think-ahead is a skill that acts as a thinking partner to a working partner, enabling developers to stay one step ahead in their workflow by understanding progress, spotting opportunities, and planning the next features.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SangIlMo/.dotfiles/specs-status', 'community', 'SangIlMo', '.dotfiles', 'SangIlMo/.dotfiles', 'specs-status', 0, 0, 45, '2026-03-08T01:57:15.301Z', '2026-03-08T02:01:34.125Z', '2798f5481515e69105f79c6ff15070e1fd2d34bc38eeba68d909ebbe201cab6b', '{"id":"SangIlMo/.dotfiles/specs-status","name":"specs-status","description":{"en":"The specs-status skill displays the specs status of the current project or a specified project, benefiting developers in managing project specifications. It provides a command-line interface to view project specs.","zh":"specs-status 是一个命令行工具，用于显示当前项目或指定项目的规范状态。支持显示所有项目的规范状态。","ja":"specs-status は、現在のプロジェクトまたは指定されたプロジェクトの仕様の状態を表示するコマンドラインツールです。すべてのプロジェクトの仕様の状態を表示することもできます。","ko":"specs-status는 현재 프로젝트 또는 지정된 프로젝트의 스펙 상태를 표시하는 명령줄 도구입니다. 모든 프로젝트의 스펙 상태를 표시할 수도 있습니다.","es":"specs-status es una herramienta de línea de comandos que muestra el estado de los proyectos y specs en el directorio actual o especificado","fr":"specs-status est un outil en ligne de commande qui affiche l''état des projets et des specs dans le répertoire actuel ou spécifié","de":"specs-status ist ein Kommandozeilen-Tool, das den Status von Projekten und Spezifikationen im aktuellen oder angegebenen Verzeichnis anzeigt","pt":"O specs-status é uma ferramenta de linha de comando que exibe o status de especificações do projeto atual ou de um projeto especificado.","ru":"specs-status - это инструмент командной строки, который отображает статус спецификаций текущего проекта или указанного проекта.","ar":"specs-status هي أداة سطر أوامر تعرض حالة المواصفات للمشروع الحالي أو المشروع المحدد"},"seo":{"title":{"en":"specs-status: Project Specs Management Setup Guide | AI A...","zh":"specs-status 设置指南：项目规范状态查看","ja":"specs-status セットアップガイド：プロジェクト仕様の状態表示","ko":"specs-status 설정 가이드: 프로젝트 스펙 상태 표시","es":"Guía de configuración de s