INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dejanvasic85/williamstownsc/dribl-crawling', 'dribl-crawling', 'dejanvasic85', 'williamstownsc', 'community', 'dribl-crawling dejanvasic85 williamstownsc community dribl-crawling is a skill that extracts data from fv.dribl.com for the Williamstown soccer club website, powered by Next and Sanity. It benefits developers who need to maintain up-to-date clubs and fixtures data. Dribl Crawling 是一个使用 Playwright-core 和 Next.js 构建的静态网站，用于爬取 Dribl 的网页并获取最新的俱乐部和比赛数据 Dribl Crawling は、Playwright-core と Next.js を使用して構築された静的 Web サイトで、Dribl の Web ページをクロールして最新のクラブと試合データを取得 Dribl Crawling은 Playwright-core와 Next.js를 사용하여 구축된 정적 웹사이트로 Dribl의 웹 페이지를 크롤링하여 최신 클럽 및 경기 데이터를 가져옵니다 Dribl Crawling es una herramienta para extraer datos de clubes y partidos de Dribl utilizando Playwright-core y Sanity Dribl Crawling est un outil pour extraire les données de clubs et de matchs de Dribl en utilisant Playwright-core et Sanity Dribl Crawling ist ein Tool zur Extraktion von Vereins- und Spieltagsdaten von Dribl mit Playwright-core und Sanity O Dribl Crawling é uma ferramenta que extrai dados de clubes e partidas do site dribl.com usando Playwright-Core. É projetado para manter os dados atualizados para o site do Williamstown SC. Dribl Crawling - это инструмент, который извлекает данные клубов и матчей с сайта dribl.com с помощью Playwright-Core. Он предназначен для поддержания актуальности данных для сайта Williamstown SC: ИИ Агенты Dribl Crawling هو أداة لاستخراج بيانات الأندية والمباريات من موقع dribl.com باستخدام Playwright-Core. تم تصميمه لتحديث البيانات على موقع Williamstown SC وأدوات الذكاء الاصطناعي how to use dribl-crawling dribl-crawling setup guide dribl-crawling vs web scraping dribl-crawling install what is dribl-crawling dribl-crawling alternative playwright-core tutorial Sanity.io integration Next.js static website Dribl Crawling Playwright-core Next.js Sanity 网页爬取 AIエージェント 俱乐部和比赛数据 Cloudflare 保护 Extracts clubs and fixtures data from https://fv.dribl.com/fixtures/ using playwright-core Uses a two-phase workflow: extraction and transformation of raw API data Stores raw data in data/external/fixtures/{team}/ format Transforms data into validated, merged format in data/matches/ Utilizes Cloudflare protection for secure data extraction Powers static websites built with Next and Sanity dribl-crawling is a technique using playwright-core for real browser automation to extract data from fv.dribl.com');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TobiasWooldridge/WaveCap-SDR/frequency-lookup', 'community', 'TobiasWooldridge', 'WaveCap-SDR', 'TobiasWooldridge/WaveCap-SDR', 'frequency-lookup', 0, 0, 45, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:40.685Z', 'fc0ab586bd7cd73ea0d356ec706fc9e5c782d6386e37098ade17638c524f7bc2', '{"id":"TobiasWooldridge/WaveCap-SDR/frequency-lookup","name":"frequency-lookup","description":{"en":"The frequency-lookup skill helps developers and radio enthusiasts find frequencies and band plans for various radio services, including marine, aviation, and amateur bands. It benefits those planning SDR monitoring scenarios and creating new recipes for specific bands.","zh":"频率查找工具是 WaveCap-SDR 的子模块，帮助开发者查找各种无线电服务的频率和频段计划","ja":"周波数検索ツールは WaveCap-SDR のサブモジュールであり、開発者がさまざまな無線サービスに対する周波数とバンドプランを見つけるのに役立ちます","ko":"주파수 조회 도구는 WaveCap-SDR의 하위 모듈로, 개발자가 다양한 무선 서비스의 주파수와 대역 계획을 찾도록 도와줍니다","es":"El módulo frequency-lookup para WaveCap-SDR ayuda a encontrar frecuencias y planes de banda para servicios de radio. Soporta bandas como VHF Marina (156-162 MHz).","fr":"Le module frequency-lookup pour WaveCap-SDR aide à trouver des fréquences et des plans de bande pour les services radio. Il prend en charge des bandes comme VHF Marine (156-162 MHz).","de":"Das frequency-lookup-Modul für WaveCap-SDR hilft bei der Suche nach Frequenzen und Bandplänen für Radiodienste. Es unterstützt Band wie VHF-Marine (156-162 MHz).","pt":"O frequency-lookup é um módulo do WaveCap-SDR que ajuda a encontrar frequências e planos de banda para serviços de rádio. Ele suporta bandas como VHF Marine e pode ser usado para planejar cenários de monitoramento SDR","ru":"ИИ Агент frequency-lookup - это подмодуль WaveCap-SDR, который помогает найти частоты и планы полосы для радиослужб. Он поддерживает диапазоны, такие как VHF Marine, и может быть использован для планирования сценариев мониторинга SDR","ar":"وحدة frequency-lookup هي وحدة فرعية من WaveCap-SDR تساعد في العثور على الترددات وخطط الحزمة لخدمات الراديو. تدعم الحزمة البحرية VHF ويمكن استخدامها لتنظيم سيناريوهات مراقبة SDR"},"seo":{"title":{"en":"frequency-lookup: WaveCap SDR Frequency Planning Guide | ...","zh":"频率查找工具：WaveCap-SDR 设置指南","ja":"周波数検索ツール：WaveCap-SDR のベストプラクティス","ko":"주파수 조회 도구: WaveCap-SDR 사용 가이드","es":"Guía de configuración de frequency-lookup para WaveCap-SDR","fr":"Configurer frequency-lookup pour WaveCap-SDR : meilleures...","de":"Einrichtungsleitfaden für frequency-lookup in WaveCap-SDR","pt":"Guia de Configuração do frequency-lookup para WaveCap-SDR","ru":"ИИ Агент frequency-lookup: Руководство по Настройке для W...","ar":"دليل إعداد frequency-lookup ل WaveCap-SDR"},"description":{"en":"Discover how to use frequency-lookup for WaveCap SDR to find frequencies, band plans, and more. Get started with our expert guide and optimize your SDR monit...","zh":"了解如何使用频率查找工具来查找海事、航空和业余无线电频段，以及如何查找广播电台和验证频率分配","ja":"WaveCap-SDR の周波数検索ツールを使用して、海事、航空、無線アマチュアバンドの周波数を検索し、放送局を検索し、周波数割り当てを確認する方法について学びます","ko":"주파수 조회 도구를 사용하여 선박, 항공, 아마추어 무선 주파수대를 찾고 방송국을 검색하며 주파수 할당을 확인하는 방법에 대해 알아보세요","es":"Descubre cómo utilizar frequency-lookup para encontrar frecuencias y planes de banda para servicios de radio con Herramientas de Inteligencia Artificial","fr":"Découvrez comment utiliser frequency-lookup pour trouver des fréquences et des plans de bande pour les services radio avec des Outils d''Intelligence Artifici...","de":"Erfahren Sie, wie Sie frequency-lookup verwenden, um Frequenzen und Bandpläne für Radiodienste mit KI-Tools zu finden","pt":"Aprenda a utilizar o frequency-lookup para encontrar frequências e planos de banda para serviços de rádio, incluindo bandas marítimas e aeronáuticas","ru":"Узнайте, как использовать ИИ Агент frequency-lookup для поиска частот и планов полосы для радиослужб, включая морские и авиационные диапазоны","ar":"تعرف على كيفية استخدام frequency-lookup للعثور على الترددات وخطط الحزمة لخدمات الراديو، بما في ذلك الحزمة البحرية والطيران"},"definition":{"en":"frequency-lookup is a WaveCap SDR sub-module that enables users to look up frequencies, band plans, and broadcast stations by location, verifying frequency allocations and discovering what''s on a frequency.","zh":"频率查找工具是一种用于查找和验证无线电频率和频段计划的 AI 工具","ja":"周波数検索ツールは、無線の周波数とバンドプランを検索および確認するための AI エージェントです","ko":"주파수 조회 도구는 무선 주파수와 대역 계획을 검색하고 확인하기 위한 AI 도구입니다","es":"frequency-lookup es un módulo de WaveCap-SDR que permite buscar frecuencias y planes de banda para servicios de radio","fr":"frequency-lookup est un module de WaveCap-SDR qui permet de rechercher des fréquences et des plans de bande pour les services radio","de":"frequency-lookup ist ein Modul von WaveCap-SDR, das die Suche nach Frequenzen und Bandplänen für Radiodienste ermöglicht","pt":"frequency-lookup é um módulo de software que ajuda a encontrar frequências e planos de banda para serviços de rádio","ru":"ИИ Агент frequency-lookup - это программный модуль, который помогает найти частоты и планы полосы для радиослужб","ar":"وحدة frequency-lookup هي وحدة برمجية تساعد في العثور على الترددات وخطط الحزمة لخدمات الراديو"},"features":{"en":["Finds frequencies for marine, aviation, and amateur bands","Looks up broadcast stations by location","Verifies frequency allocations","Discovers what''s on a frequency","Plans SDR monitoring scenarios","Creates new recipes for specific bands like VHF Marine (156-162 MHz)"],"zh":["支持海事、航空和业余无线电频段","可查找广播电台和验证频率分配","支持 VHF 海事频段（156-162 MHz）","可用于规划 SDR 监控场景","支持创建特定频段的新 recipe"],"ja":["海事、航空、無線アマチュアバンドのサポート","放送局の検索と周波数割り当ての確認","VHF 海事バンド（156-162 MHz）のサポート","SDR 監視シナリオの計画","特定のバンドの新しい recipe の作成"],"ko":["선박, 항공, 아마추어 무선 주파수대의 지원","방송국 검색 및 주파수 할당 확인","VHF 선박 대역（156-162 MHz）的 지원","SDR 모니터링 시나리오 계획","특정 대역의 새로운 레시피 생성"],"es":["Búsqueda de frecuencias para bandas marinas, aeronáuticas y aficionadas","Búsqueda de estaciones de radiodifusión por ubicación","Verificación de asignaciones de frecuencia","Descubrimiento de servicios en una frecuencia determinada","Planificación de escenarios de monitoreo SDR","Soporte para la banda VHF Marina (156-162 MHz)"],"fr":["Recherche de fréquences pour les bandes marines, aéronautiques et amateur","Recherche de stations de radiodiffusion par emplacement","Vérification des allocations de fréquence","Découverte de services sur une fréquence donnée","Planification de scénarios de surveillance SDR","Prise en charge de la bande VHF Marine (156-162 MHz)"],"de":["Suche nach Frequenzen für Marine-, Luftfahrt- und Amateurfunkbänder","Suche nach Rundfunksendern nach Standort","Überprüfung von Frequenzzuweisungen","Entdeckung von Diensten auf einer bestimmten Frequenz","Planung von SDR-Überwachungsszenarien","Unterstützung für das VHF-Marineband (156-162 MHz)"],"pt":["Suporte a bandas como VHF Marine","Capacidade de encontrar frequências para serviços de rádio","Planejamento de cenários de monitoramento SDR","Suporte a planos de banda para serviços de rádio","Capacidade de verificar alocações de frequência"],"ru":["Поддержка диапазонов, таких как VHF Marine","Возможность найти частоты для радиослужб","Планирование сценариев мониторинга SDR","Поддержка планов полосы для радиослужб","Возможность проверить выделения частот"],"ar":["دعم الحزمة البحرية VHF","القدرة على العثور على الترددات لخدمات الراديو","تنظيم سيناريوهات مراقبة SDR","دعم خطط الحزمة لخدمات الراديو","القدرة على التحقق من تخصيصات التردد"]},"keywords":{"en":["how to use frequency-lookup","frequency-lookup setup guide","WaveCap SDR frequency planning","frequency-lookup alternative","frequency-lookup vs other SDR tools","install frequency-lookup","frequency-lookup for amateur radio","SDR monitoring scenarios","frequency allocation lookup"],"zh":["频率查找工具","WaveCap-SDR","AI 工具","无线电频率","频段计划","海事频段","航空频段","业余无线电频段"],"ja":["周波数検索ツール","WaveCap-SDR","AI エージェント","無線の周波数","バンドプラン","海事バンド","航空バンド","無線アマチュアバンド"],"ko":["주파수 조회 도구","WaveCap-SDR","AI 도구","무선 주파수","대역 계획","선박 주파수대","항공 주파수대","아마추어 무선 주파수대"],"es":["frequency-lookup","WaveCap-SDR","Herramientas de Inteligencia Artificial","búsqueda de frecuencias","planes de banda","servicios de radio","VHF Marina","SDR","monitoreo de radio","configuración de frequency-lookup"],"fr":["frequency-lookup","WaveCap-SDR","Outils d''Intelligence Artificielle","recherche de fréquences","plans de bande","services radio","VHF Marine","SDR","surveillance radio","configuration de frequency-lookup"],"de":["frequency-lookup","WaveCap-SDR","KI-Tools","Frequenzsuche","Bandpläne","Radiodienste","VHF-Marine","SDR","Radiouberwachung","Einrichtung von frequency-lookup"],"pt":["frequency-lookup","WaveCap-SDR","serviços de rádio","bandas de frequência","planejamento de monitoramento SDR","VHF Marine","frequências de rádio","planos de banda"],"ru":["ИИ Агент frequency-lookup","WaveCap-SDR","радиослужбы","диапазоны частот","планирование мониторинга SDR","VHF Marine","частоты радио","планы полосы"],"ar":["وحدة frequency-lookup","WaveCap-SDR","خدمات الراديو","حزم التردد","تنظيم مراقبة SDR","VHF البحرية","ترددات الراديو","خطط الحزمة"]}},"owner":"TobiasWooldridge","repo":"WaveCap-SDR","repoPath":"TobiasWooldridge/WaveCap-SDR","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"frequency-lookup","description":"Look up frequency allocations, band plans, and known stations for radio services (marine, aviation, amateur, broadcast, NOAA weather). Use when finding frequencies to monitor, verifying band allocations, or discovering channels in a frequency range.","bodyPreview":"# Frequency Lookup for WaveCap-SDR\n\nThis skill helps find frequencies and band plans for various radio services.\n\n## When to Use This Skill\n\nUse this skill when:\n- Finding frequencies for marine/aviation/amateur bands\n- Looking up broadcast stations by location\n- Verifying frequency allocations\n- Discovering what''s on a frequency\n- Planning SDR monitoring scenarios\n- Creating new recipes for specific bands\n\n## Common Frequency Bands\n\n### VHF Marine (156-162 MHz)\n\n**Channel 16 (156.800 MHz)** - I","body":"# Frequency Lookup for WaveCap-SDR\n\nThis skill helps find frequencies and band plans for various radio services.\n\n## When to Use This Skill\n\nUse this skill when:\n- Finding frequencies for marine/aviation/amateur bands\n- Looking up broadcast stations by location\n- Verifying frequency allocations\n- Discovering what''s on a frequency\n- Planning SDR monitoring scenarios\n- Creating new recipes for specific bands\n\n## Common Frequency Bands\n\n### VHF Marine (156-162 MHz)\n\n**Channel 16 (156.800 MHz)** - International Distress/Safety/Calling\n**Channel 9 (156.450 MHz)** - Recreational calling (US)\n**Channel 6 (156.300 MHz)** - Intership safety\n\nFull band plan: https://www.navcen.uscg.gov/marine-communications-channel-table\n\n### Aviation (118-137 MHz)\n\n**121.500 MHz** - Emergency frequency\n**Typical ranges:**\n- Tower: 118.0-121.4 MHz\n- Ground: 121.6-121.9 MHz\n- ATIS: Varies by airport\n\nFind local frequencies: https://www.airnav.com\n\n### NOAA Weather Radio (162-163 MHz)\n\n**WX1: 162.550 MHz**\n**WX2: 162.400 MHz**\n**WX3: 162.475 MHz**\n**WX4: 162.425 MHz**\n**WX5: 162.450 MHz**\n**WX6: 162.500 MHz**\n**WX7: 162.525 MHz**\n\nCoverage map: https://www.weather.gov/nwr/\n\n### FM Broadcast (88-108 MHz)\n\n**US band:** 88.1-107.9 MHz (odd tenths only)\n**Europe/Asia:** 87.5-108.0 MHz\n\nFind local stations:\n- https://radio-locator.com\n- https://fmscan.org\n\n### Amateur Radio (Ham)\n\n**2 meters:** 144-148 MHz (FM repeaters typically 145-147 MHz)\n**70 cm:** 420-450 MHz\n**HF bands:** 3.5, 7, 14, 21, 28 MHz\n\nRepeater directory: https://www.repeaterbook.com\n\n### Public Safety / Trunking\n\n**VHF:** 150-174 MHz\n**UHF:** 450-470 MHz, 806-824 MHz\n\nDatabase: https://www.radioreference.com\n\n## Online Resources\n\n**RadioReference.com** - Comprehensive frequency database\n- Trunked systems\n- Talkgroup IDs\n- Local agencies\n\n**SignalWiki** - Signal identification\n- Decode unknown signals\n- Modulation types\n\n**WebSDR** - Remote SDR receivers\n- Listen without hardware\n- Check propagation\n\n**FlightAware/FlightRadar24** - Aviation tracking\n- Find airport frequencies\n- Track aircraft\n\n## Usage Examples\n\n### Find Marine Channels\n```\nVHF Marine channels are spaced 25 kHz apart\nChannel number = (Frequency - 156.000) / 0.025\nChannel 16 = 156.800 MHz\nChannel 9 = 156.450 MHz\n```\n\n### Find Local FM Stations\nVisit https://radio-locator.com and enter your ZIP code\n\n### Find NOAA Weather\nFind nearest transmitter at https://www.weather.gov/nwr/\n\n### Find Aviation Frequencies\nVisit https://www.airnav.com and search for airport code (e.g., KSEA)\n\n## Integration with WaveCap-SDR\n\nAfter finding frequencies, create a recipe:\n\n```yaml\nrecipes:\n  my_frequencies:\n    name: \"My Frequencies\"\n    capture:\n      center_hz: 156800000  # Center on Ch 16\n      sample_rate: 250000\n      gain_db: 35\n    channels:\n      - {name: \"Ch 16\", offset_hz: 0, mode: \"fm\"}\n      - {name: \"Ch 9\", offset_hz: -350000, mode: \"fm\"}\n```\n\nOr use presets for quick tuning.\n\n## Band Plan Quick Reference\n\n| Service | Frequency Range | Typical Use |\n|---------|----------------|-------------|\n| AM Broadcast | 530-1700 kHz | Radio stations |\n| Ham 160m | 1.8-2.0 MHz | Amateur HF |\n| Marine SSB | 2-4 MHz | Long-range marine |\n| Ham 80m | 3.5-4.0 MHz | Amateur HF |\n| Ham 40m | 7.0-7.3 MHz | Amateur HF |\n| Ham 20m | 14.0-14.35 MHz | Amateur HF |\n| Ham 10m | 28-29.7 MHz | Amateur HF |\n| CB | 26.965-27.405 MHz | Citizens Band |\n| Ham 6m | 50-54 MHz | Amateur VHF |\n| FM Broadcast | 88-108 MHz | Radio stations |\n| Aviation | 118-137 MHz | Air traffic control |\n| Ham 2m | 144-148 MHz | Amateur VHF |\n| Marine VHF | 156-162 MHz | Maritime |\n| NOAA WX | 162.400-162.550 MHz | Weather |\n| Ham 70cm | 420-450 MHz | Amateur UHF |\n| GMRS/FRS | 462-467 MHz | Personal radio |\n\n## Files in This Skill\n\n- `SKILL.md`: This file - frequency reference and lookup guide\n\n## Notes\n\n- Frequencies vary by country (this guide is US-centric)\n- Always check local regulations before transmitting\n- Some frequencies require licenses (ham, marine, aviation)\n- SDR receiving is legal, transmitting requires proper licensing\n- Band plans change - verify with official sources\n- Use RadioReference.com for most comprehensive database\n"},"lastSynced":"2026-03-08T02:01:40.685Z","agentAnalysis":{"suitability":{"en":"Perfect for Radio Frequency Analysis Agents needing accurate band plan and frequency data for marine, aviation, and amateur services.","zh":"适合需要准确的波段计划和频率数据的无线电频率分析代理，例如海事、航空和业余服务。","ja":"無線周波数分析エージェントが海事、航空、Amateurサービス向けの正確なバンドプランと周波数データを必要とする場合に適しています。","ko":"해상, 항공, 아마추어 서비스를 위한 정확한 밴드 플랜 및 주파수 데이터가 필요한 무선 주파수 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de Análisis de Frecuencia de Radio que necesitan un plan de banda y datos de frecuencia precisos para servicios marítimos, aeronáuticos y de aficionados.","fr":"Parfait pour les agents d''Analyse de Fréquence Radio nécessitant un plan de bande et des données de fréquence précises pour les services maritimes, aériens et amateurs.","de":"Perfekt für Radiofrequenzanalyse-Agents, die genaue Bandpläne und Frequenzdaten für maritime, Luftfahrt- und Amateurdienste benötigen.","pt":"Perfeito para Agentes de Análise de Frequência de Rádio que necessitam de plano de banda e dados de frequência precisos para serviços marítimos, aeronáuticos e amadores.","ru":"Идеально подходит для агентов анализа радиочастот, которым необходимы точные планы частот и данные о частотах для морских, авиационных и любительских услуг.","ar":"مثالي للوكلاء التحليليّين لترددات الراديو الذين يحتاجون إلى خطة حزمة وبيانات تردد دقيقة للخدمات البحرية والطيران والهواة."},"recommendation":{"en":"Empowers agents to verify frequency allocations and discover broadcast stations by location using VHF Marine, Aviation, and Amateur band plans, facilitating SDR monitoring scenario planning and new recipe creation for specific bands.","zh":"赋予代理验证频率分配和通过VHF海事、航空和业余波段计划根据位置发现广播电台的能力，促进SDR监控场景规划和特定波段的新配方创建。","ja":"VHF海事、航空、Amateurバンドプランを使用して、エージェントが周波数割り当てを検証し、ロケーションによって放送局を検出できるようにし、SDRモニタリングシナリオの計画と特定のバンドの新しいレシピの作成を促進します。","ko":"VHF 해상, 항공, 아마추어 밴드 플랜을 사용하여 에이전트가 주파수 할당을 확인하고 위치에 따라 방송국을 검색할 수 있도록 하며, SDR 모니터링 시나리오 계획 및 특정 밴드에 대한 새로운 레시피 생성을促進합니다.","es":"Habilita a los agentes a verificar las asignaciones de frecuencia y a descubrir estaciones de broadcast por ubicación utilizando planes de banda VHF Marina, Aviación y Aficionados, lo que facilita la planificación de escenarios de monitoreo SDR y la creación de nuevas recetas para bandas específicas.","fr":"Permet aux agents de vérifier les allocations de fréquence et de découvrir les stations de diffusion par emplacement en utilisant les plans de bande VHF Marine, Aviation et Amateur, ce qui facilite la planification des scénarios de surveillance SDR et la création de nouvelles recettes pour des bandes spécifiques.","de":"Ermächtigt die Agents, Frequenzzuweisungen zu überprüfen und Sendestationen nach Standort zu entdecken, indem sie VHF-Marine-, Luftfahrt- und Amateurbandpläne verwenden, was die Planung von SDR-Überwachungsszenarien und die Erstellung neuer Rezepte für bestimmte Bänder erleichtert.","pt":"Habilita os agentes a verificar alocações de frequência e descobrir estações de transmissão por localização usando planos de banda VHF Marinha, Aviação e Amadora, facilitando o planejamento de cenários de monitoramento SDR e a criação de novas receitas para bandas específicas.","ru":"Наделяет агентов возможностью проверять выделение частот и обнаруживать передающие станции по местоположению с помощью планов диапазонов VHF Морской, Авиационной и Любительской служб, облегчая планирование сценариев мониторинга SDR и создание новых рецептов для конкретных диапазонов.","ar":"يمنح الوكلاء القدرة على التحقق من تخصيص الترددات واكتشاف محطات البث حسب الموقع باستخدام خطط حزمة VHF البحرية والطيران والهواة، مما يسهل تخطيط سيناريوهات مراقبة SDR وإنشاء وصفات جديدة للنطاقات المحددة."},"useCases":{"en":["Looking up frequencies for marine, aviation, and amateur bands","Planning SDR monitoring scenarios for optimal signal reception","Creating new recipes for specific bands, such as VHF Marine Channel 16","Verifying frequency allocations for compliance and interference avoidance"],"zh":["查找海事、航空和业余波段的频率","规划SDR监控场景以实现最佳信号接收","为特定波段（如VHF海事第16频道）创建新配方","验证频率分配以确保遵守规定并避免干扰"],"ja":["海事、航空、Amateurバンドの周波数を調べる","SDRモニタリングシナリオを最適な信号受信のために計画する","特定のバンド（VHF海事チャンネル16など）向けに新しいレシピを作成する","周波数割り当てを検証して規制遵守と干渉回避を確認する"],"ko":["해상, 항공, 아마추어 밴드의 주파수를 조회하는 것","최적의 신호 수신을 위한 SDR 모니터링 시나리오 계획","특정 밴드(VHF 해상 채널 16 등)에 대한 새로운 레시피 생성","규제 준수 및 간섭 방지를 위한 주파수 할당 확인"],"es":["Buscar frecuencias para bandas marinas, aeronáuticas y de aficionados","Planificar escenarios de monitoreo SDR para una recepción de señal óptima","Crear nuevas recetas para bandas específicas, como el canal 16 de VHF Marina","Verificar las asignaciones de frecuencia para el cumplimiento y la evitación de interferencias"],"fr":["Rechercher des fréquences pour les bandes marines, aériennes et amateurs","Planifier des scénarios de surveillance SDR pour une réception de signal optimale","Créer de nouvelles recettes pour des bandes spécifiques, comme le canal 16 VHF Marine","Vérifier les allocations de fréquence pour le respect et l''évitement des interférences"],"de":["Frequenzen für maritime, Luftfahrt- und Amateurband suchen","SDR-Überwachungsszenarien für optimale Signalreception planen","Erstellen neuer Rezepte für bestimmte Bänder, wie z.B. VHF-Marine-Kanal 16","Frequenzzuweisungen für die Einhaltung und Vermeidung von Störungen überprüfen"],"pt":["Pesquisar frequências para bandas marinha, aviação e amadora","Planejar cenários de monitoramento SDR para recepção de sinal ótima","Criar novas receitas para bandas específicas, como o Canal 16 da VHF Marinha","Verificar alocações de frequência para cumprimento e evasão de interferência"],"ru":["Поиск частот для морских, авиационных и любительских диапазонов","Планирование сценариев мониторинга SDR для оптимального приема сигнала","Создание новых рецептов для конкретных диапазонов, таких как канал 16 VHF Морской","Проверка выделения частот для соблюдения и избежания помех"],"ar":["بحث الترددات للهوائيات البحرية والطيران والهواة","تخطيط سيناريوهات مراقبة SDR لاستقبال الإشارات المثالية","إنشاء وصفات جديدة للنطاقات المحددة، مثل قناة VHF البحرية 16","التحقق من تخصيص الترددات للامتثال والتفادي للتداخل"]},"limitations":{"en":["Limited to radio frequency services, including marine, aviation, and amateur bands","Requires knowledge of frequency bands and plans, such as VHF Marine (156-162 MHz)"],"zh":["仅限于无线电频率服务，包括海事、航空和业余波段","需要了解频率波段和计划，如VHF海事（156-162 MHz）"],"ja":["無線周波数サービス（海事、航空、Amateurバンドなど）に限定される","周波数バンドとプラン（VHF海事（156-162 MHz）など）の知識が必要"],"ko":["무선 주파수 서비스(해상, 항공, 아마추어 밴드 등)로 제한됨","주파수 밴드 및 플랜(VHF 해상(156-162 MHz) 등)에 대한 지식이 필요"],"es":["Limitado a servicios de radiofrecuencia, incluyendo bandas marinas, aeronáuticas y de aficionados","Requiere conocimiento de bandas y planes de frecuencia, como VHF Marina (156-162 MHz)"],"fr":["Limité aux services de fréquence radio, y compris les bandes marines, aériennes et amateurs","Nécessite des connaissances sur les bandes et les plans de fréquence, tels que VHF Marine (156-162 MHz)"],"de":["Begrenzt auf Radiofrequenzdienste, einschließlich maritimer, Luftfahrt- und Amateurband","Benötigt Kenntnisse von Frequenzbändern und -plänen, wie z.B. VHF-Marine (156-162 MHz)"],"pt":["Limitado a serviços de frequência de rádio, incluindo bandas marinha, aviação e amadora","Requer conhecimento de bandas de frequência e planos, como VHF Marinha (156-162 MHz)"],"ru":["Ограничен услугами радиочастот, включая морские, авиационные и любительские диапазоны","Требует знания диапазонов частот и планов, таких как VHF Морская (156-162 МГц)"],"ar":["محدود للخدمات التردديّة الراديويّة، بما في ذلك النطاقات البحرية والطيران والهواة","يحتاج إلى معرفة الحزم التردديّة والخطط، مثل VHF البحرية (156-162 ميغاهيرتز)"]},"version":4},"contentHash":"fc0ab586bd7cd73ea0d356ec706fc9e5c782d6386e37098ade17638c524f7bc2","qualityScore":45}');
