INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TobiasWooldridge/WaveCap-SDR/frequency-lookup', 'frequency-lookup', 'TobiasWooldridge', 'WaveCap-SDR', 'community', 'frequency-lookup TobiasWooldridge WaveCap-SDR community The frequency-lookup skill helps developers and radio enthusiasts find frequencies and band plans for various radio services, including marine, aviation, and amateur bands. It benefits those planning SDR monitoring scenarios and creating new recipes for specific bands. 频率查找工具是 WaveCap-SDR 的子模块，帮助开发者查找各种无线电服务的频率和频段计划 周波数検索ツールは WaveCap-SDR のサブモジュールであり、開発者がさまざまな無線サービスに対する周波数とバンドプランを見つけるのに役立ちます 주파수 조회 도구는 WaveCap-SDR의 하위 모듈로, 개발자가 다양한 무선 서비스의 주파수와 대역 계획을 찾도록 도와줍니다 El módulo frequency-lookup para WaveCap-SDR ayuda a encontrar frecuencias y planes de banda para servicios de radio. Soporta bandas como VHF Marina (156-162 MHz). Le module frequency-lookup pour WaveCap-SDR aide à trouver des fréquences et des plans de bande pour les services radio. Il prend en charge des bandes comme VHF Marine (156-162 MHz). Das frequency-lookup-Modul für WaveCap-SDR hilft bei der Suche nach Frequenzen und Bandplänen für Radiodienste. Es unterstützt Band wie VHF-Marine (156-162 MHz). O frequency-lookup é um módulo do WaveCap-SDR que ajuda a encontrar frequências e planos de banda para serviços de rádio. Ele suporta bandas como VHF Marine e pode ser usado para planejar cenários de monitoramento SDR ИИ Агент frequency-lookup - это подмодуль WaveCap-SDR, который помогает найти частоты и планы полосы для радиослужб. Он поддерживает диапазоны, такие как VHF Marine, и может быть использован для планирования сценариев мониторинга SDR وحدة frequency-lookup هي وحدة فرعية من WaveCap-SDR تساعد في العثور على الترددات وخطط الحزمة لخدمات الراديو. تدعم الحزمة البحرية VHF ويمكن استخدامها لتنظيم سيناريوهات مراقبة SDR how to use frequency-lookup frequency-lookup setup guide WaveCap SDR frequency planning frequency-lookup alternative frequency-lookup vs other SDR tools install frequency-lookup frequency-lookup for amateur radio SDR monitoring scenarios frequency allocation lookup 频率查找工具 WaveCap-SDR AI 工具 无线电频率 频段计划 海事频段 航空频段 业余无线电频段 Finds frequencies for marine, aviation, and amateur bands Looks up broadcast stations by location Verifies frequency allocations Discovers what''s on a frequency Plans SDR monitoring scenarios Creates new recipes for specific bands like VHF Marine (156-162 MHz) frequency-lookup is a WaveCap SDR sub-module that enables users to look up frequencies, band plans, and broadcast stations by location, verifying frequency allocations and discovering what''s on a frequency.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yarang/chatbot_ai_assistant_v2/moai-foundation-core', 'community', 'yarang', 'chatbot_ai_assistant_v2', 'yarang/chatbot_ai_assistant_v2', 'moai-foundation-core', 0, 0, 45, '2026-03-08T01:57:15.303Z', '2026-03-08T02:01:53.271Z', 'ba557f6796bb1005494c38e99568e3b8d58ac73724b4bd67b0a18238d018d0ff', '{"id":"yarang/chatbot_ai_assistant_v2/moai-foundation-core","name":"moai-foundation-core","description":{"en":"moai-foundation-core provides foundational principles and architectural patterns for AI-driven development workflows, benefiting developers and teams seeking quality-first and efficient AI development.","zh":"MoAI Foundation Core 提供了六个基本原则，确保 AI 应用的质量、效率和可扩展性","ja":"MoAI Foundation Core は、AI アプリケーションの品質、効率、スケーラビリティを確保する 6 つの基本原則を提供します","ko":"MoAI Foundation Core 는 AI 애플리케이션의 품질, 효율성, 확장성을 보장하는 6개의 기본 원칙을 제공합니다","es":"MoAI Foundation Core es un conjunto de principios y patrones arquitectónicos que permiten el desarrollo de soluciones de inteligencia artificial de alta calidad","fr":"MoAI Foundation Core est un ensemble de principes et de modèles architecturaux qui permettent de développer des solutions d''IA de haute qualité","de":"MoAI Foundation Core ist eine Sammlung von Grundsätzen und Architekturmuster, die die Entwicklung von hochwertigen KI-Lösungen ermöglichen","pt":"O MoAI Foundation Core é um conjunto de princípios e padrões arquitetônicos que garantem qualidade e eficiência no desenvolvimento de soluções de IA.","ru":"MoAI Foundation Core - это набор принципов и архитектурных паттернов, обеспечивающих качество и эффективность в разработке ИИ Агентов","ar":"مواي فاونديشن كور هو مجموعة من المبادئ والأنماط المعمارية التي تضمن الجودة والكفاءة في تطوير أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"moai-foundation-core: Core Principles for AI Development ...","zh":"MoAI Foundation Core 设置指南 - AI 工具开发最佳实践","ja":"MoAI Foundation Core セットアップガイド - AI エージェント開発のベストプラクティス","ko":"MoAI Foundation Core 설정 가이드 - AI 에이전트 개발 최적화","es":"Guía de configuración de MoAI Foundation Core para agente...","fr":"Guide de démarrage de MoAI Foundation Core pour les outil...","de":"Einrichtungsleitfaden für MoAI Foundation Core und künstl...","pt":"Guia de Configuração do MoAI Foundation Core para Desenvo...","ru":"Настройка MoAI Foundation Core для эффективной разработки...","ar":"دليل إعداد مواي فاونديشن كور لتحسين أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient AI development with moai-foundation-core. Discover the 6 essential principles for quality, efficiency, and scalability. Get started now!","zh":"了解 MoAI Foundation Core 的核心原则和架构模式，通过测试驱动和模块化开发实现高质量的 AI 应用","ja":"MoAI Foundation Core の基本原則とアーキテクチャパターンを学び、テスト駆動開発とモジュール化で高品質の AI アプリケーションを実現する","ko":"MoAI Foundation Core 의 핵심 원칙과 아키텍처 패턴을 배우고, 테스트 주도 개발과 모듈화로 고품질의 AI 애플리케이션을 구현합니다","es":"Aprende a implementar MoAI Foundation Core para desarrollar soluciones de inteligencia artificial de alta calidad y escalables","fr":"Découvrez comment mettre en œuvre MoAI Foundation Core pour développer des solutions d''IA robustes et efficaces","de":"Erfahren Sie, wie Sie MoAI Foundation Core einsetzen, um skalierbare und qualitativ hochwertige KI-Lösungen zu entwickeln","pt":"Aprenda a configurar o MoAI Foundation Core para desenvolver soluções de IA de alta qualidade e escalabilidade","ru":"Узнайте, как настроить MoAI Foundation Core для создания эффективных ИИ Агентов и решений","ar":"اكتشف كيفية إعداد مواي فاونديشن كور لتحسين أداء أدوات الذكاء الاصطناعي"},"definition":{"en":"moai-foundation-core is a set of core principles and architectural patterns that power MoAI-ADK''s AI-driven development workflow, emphasizing quality, efficiency, and scalability.","zh":"MoAI Foundation Core 是一种 AI 工具开发框架，提供了测试驱动和模块化开发的核心原则和架构模式","ja":"MoAI Foundation Core は、テスト駆動開発とモジュール化開発の基本原則とアーキテクチャパターンを提供する AI エージェント開発フレームワークです","ko":"MoAI Foundation Core 는 테스트 주도 개발과 모듈화 개발의 핵심 원칙과 아키텍처 패턴을 제공하는 AI 에이전트 개발 프레임워크입니다","es":"MoAI Foundation Core es un marco de trabajo para el desarrollo de inteligencia artificial que se basa en principios de calidad, eficiencia y escalabilidad","fr":"MoAI Foundation Core est un cadre de travail pour le développement d''IA qui repose sur des principes de qualité, d''efficacité et de scalabilité","de":"MoAI Foundation Core ist ein Rahmenwerk für die Entwicklung von künstlicher Intelligenz, das auf Grundsätzen von Qualität, Effizienz und Skalierbarkeit basiert","pt":"O que é MoAI Foundation Core? É um conjunto de seis princípios essenciais para desenvolvimento de IA de alta qualidade","ru":"Что такое MoAI Foundation Core? Это шесть основных принципов для эффективной разработки ИИ Агентов","ar":"ما هو مواي فاونديشن كور؟ هو مجموعة من ستة مبادئ أساسية لتحسين أداء أدوات الذكاء الاصطناعي"},"features":{"en":["Implements the TRUST 5 Framework for quality gate system","Enforces test-driven development for reliable AI models","Promotes modular and efficient AI development through proven patterns","Supports automated workflows for streamlined development","Ensures readability, unified, and secured AI development practices","Employs a quality-first approach for high-quality AI outputs"],"zh":["TRUST 5 框架 - 质量门控系统","测试驱动开发","模块化开发","自动化工作流","可扩展的架构"],"ja":["TRUST 5 フレームワーク - 品質ゲートシステム","テスト駆動開発","モジュール化開発","自動化ワークフロー","スケーラブルなアーキテクチャ"],"ko":["TRUST 5 프레임워크 - 품질 게이트 시스템","테스트 주도 개발","모듈화 개발","자동화 워크플ロー","확장 가능한 아키텍처"],"es":["TRUST 5 Framework para garantizar la calidad del código","Desarrollo de soluciones de inteligencia artificial modulares y escalables","Patrones arquitectónicos para una mayor eficiencia y productividad","Automatización de flujos de trabajo para reducir errores y tiempos de desarrollo","Integración con herramientas de desarrollo de inteligencia artificial como React y Python"],"fr":["TRUST 5 Framework pour garantir la qualité du code","Développement de solutions d''IA modulaires et scalables","Modèles architecturaux pour une plus grande efficacité et productivité","Automatisation des flux de travail pour réduire les erreurs et les temps de développement","Intégration avec des outils de développement d''IA tels que React et Python"],"de":["TRUST 5 Framework für die Gewährleistung der Code-Qualität","Entwicklung von modularen und skalierbaren KI-Lösungen","Architekturmuster für eine höhere Effizienz und Produktivität","Automatisierung von Workflows zur Reduzierung von Fehlern und Entwicklungszeiten","Integration mit KI-Entwicklungstools wie React und Python"],"pt":["TRUST 5 Framework para garantir a qualidade do código","Desenvolvimento de IA modular e eficiente","Automatização de workflows para melhorar a produtividade","Padrões arquitetônicos para escalabilidade e manutenção","Suporte à testes unitários e integração contínua"],"ru":["TRUST 5 Framework для обеспечения качества кода","Модульное и эффективное развитие ИИ","Автоматизация рабочих процессов для повышения производительности","Архитектурные паттерны для масштабируемости и обслуживания","Поддержка unit-тестов и непрерывной интеграции"],"ar":["إطار عمل TRUST 5 لضمان جودة الكود","تطوير_IA_المدولار والكفء","أتمتة سير العمل لتحسين الإنتاجية","أنماط معمارية لتحسين القدرة على التوسع والصيانة","دعم اختبارات الوحدة والدمج المستمر"]},"keywords":{"en":["what is moai-foundation-core","moai-foundation-core setup guide","moai-foundation-core alternative","how to use moai-foundation-core","moai-foundation-core vs MoAI-ADK","moai-foundation-core install","TRUST 5 Framework","AI development workflow","quality-first AI development","efficient AI development"],"zh":["AI 工具开发","MoAI Foundation Core","测试驱动开发","模块化开发","自动化工作流","AI 应用开发","质量门控系统"],"ja":["AI エージェント開発","MoAI Foundation Core","テスト駆動開発","モジュール化開発","自動化ワークフロー","AI アプリケーション開発","品質ゲートシステム"],"ko":["AI 에이전트 개발","MoAI Foundation Core","테스트 주도 개발","모듈화 개발","자동화 워크플ロー","AI 애플리케이션 개발","품질 게이트 시스템"],"es":["agentes de inteligencia artificial","desarrollo de inteligencia artificial","MoAI Foundation Core","TRUST 5 Framework","patrones arquitectónicos para IA","automatización de flujos de trabajo","herramientas de desarrollo de inteligencia artificial","React y Python para IA"],"fr":["outils d''IA","développement d''IA","MoAI Foundation Core","TRUST 5 Framework","modèles architecturaux pour l''IA","automatisation des flux de travail","outils de développement d''IA","React et Python pour l''IA"],"de":["künstliche Intelligenz-Tools","KI-Entwicklung","MoAI Foundation Core","TRUST 5 Framework","Architekturmuster für KI","Automatisierung von Workflows","KI-Entwicklungstools","React und Python für KI"],"pt":["desenvolvimento de IA","MoAI Foundation Core","TRUST 5 Framework","desenvolvimento de software","testes unitários","integração contínua","automatização de workflows"],"ru":["разработка ИИ","MoAI Foundation Core","TRUST 5 Framework","разработка программного обеспечения","unit-тесты","непрерывная интеграция","автоматизация рабочих процессов"],"ar":["تطوير_IA","مواي فاونديشن كور","إطار عمل TRUST 5","تطوير البرمجيات","اختبارات الوحدة","الدمج المستمر","أتمتة سير العمل"]}},"owner":"yarang","repo":"chatbot_ai_assistant_v2","repoPath":"yarang/chatbot_ai_assistant_v2","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.303Z","topics":[],"category":"community","skillMd":{"name":"moai-foundation-core","description":"MoAI-ADKs foundational principles - TRUST 5, SPEC-First TDD, delegation patterns, token optimization, progressive disclosure, modular architecture, agent catalog, command reference, and execution rules for building AI-powered development workflows","version":"2.4.0","tags":["foundation","core","orchestration","agents","commands","trust-5","spec-first-tdd"],"bodyPreview":"# MoAI Foundation Core\n\nFoundational principles and architectural patterns that power MoAI-ADK''s AI-driven development workflow.\n\nCore Philosophy: Quality-first, test-driven, modular, and efficient AI development through proven patterns and automated workflows.\n\n## Quick Reference\n\nWhat is MoAI Foundation Core?\n\nSix essential principles that ensure quality, efficiency, and scalability in AI-powered development:\n\n1. TRUST 5 Framework - Quality gate system (Test-first, Readable, Unified, Secured,","body":"# MoAI Foundation Core\n\nFoundational principles and architectural patterns that power MoAI-ADK''s AI-driven development workflow.\n\nCore Philosophy: Quality-first, test-driven, modular, and efficient AI development through proven patterns and automated workflows.\n\n## Quick Reference\n\nWhat is MoAI Foundation Core?\n\nSix essential principles that ensure quality, efficiency, and scalability in AI-powered development:\n\n1. TRUST 5 Framework - Quality gate system (Test-first, Readable, Unified, Secured, Trackable)\n2. SPEC-First TDD - Specification-driven test-driven development workflow\n3. Delegation Patterns - Task orchestration via specialized agents (never direct execution)\n4. Token Optimization - 200K budget management and context efficiency\n5. Progressive Disclosure - Three-tier knowledge delivery (Quick, Implementation, Advanced)\n6. Modular System - File splitting and reference architecture for scalability\n\nQuick Access:\n\n- Quality standards in modules/trust-5-framework.md\n- Development workflow in modules/spec-first-tdd.md\n- Agent coordination in modules/delegation-patterns.md\n- Budget management in modules/token-optimization.md\n- Content structure in modules/progressive-disclosure.md\n- File organization in modules/modular-system.md\n- Agent catalog in modules/agents-reference.md\n- Command reference in modules/commands-reference.md\n- Security and constraints in modules/execution-rules.md\n\nUse Cases:\n\n- New agent creation with quality standards\n- New skill development with structural guidelines\n- Complex workflow orchestration\n- Token budget planning and optimization\n- Documentation architecture design\n- Quality gate configuration\n\n---\n\n## Implementation Guide\n\n### 1. TRUST 5 Framework - Quality Assurance System\n\nPurpose: Automated quality gates ensuring code quality, security, and maintainability.\n\nFive Pillars:\n\nTest-first Pillar: Maintain test coverage at or above 85 percent. Execute pytest with coverage reporting. Block merge and generate missing tests on failure. High coverage ensures code reliability and reduces production defects. Catches bugs early and reduces debugging time by 60-70 percent.\n\nReadable Pillar: Use clear and descriptive naming conventions. Execute ruff linter checks. Issue warning and suggest refactoring improvements on failure. Clear naming improves code comprehension and team collaboration. Reduces onboarding time by 40 percent and improves maintenance velocity.\n\nUnified Pillar: Apply consistent formatting and import patterns. Execute black formatter and isort checks. Auto-format code or issue warning on failure. Consistency eliminates style debates and merge conflicts. Reduces code review time by 30 percent and improves readability.\n\nSecured Pillar: Comply with OWASP security standards. Execute security-expert agent analysis. Block merge and require security review on failure. Security vulnerabilities create critical business and legal risks. Prevents 95+ percent of common security vulnerabilities.\n\nTrackable Pillar: Write clear and structured commit messages. Match Git commit message regex patterns. Suggest proper commit message format on failure. Clear history enables debugging, auditing, and collaboration. Reduces issue investigation time by 50 percent.\n\nIntegration Points: Pre-commit hooks for automated validation, CI/CD pipelines for quality gate enforcement, Agent workflows for core-quality validation, Documentation for quality metrics.\n\nDetailed Reference: modules/trust-5-framework.md\n\n---\n\n### 2. SPEC-First TDD - Development Workflow\n\nPurpose: Specification-driven development ensuring clear requirements before implementation.\n\nThree-Phase Workflow:\n\nPhase 1 SPEC (/moai:1-plan): workflow-spec generates EARS format. Output is .moai/specs/SPEC-XXX/spec.md. Execute /clear to save 45-50K tokens.\n\nPhase 2 TDD (/moai:2-run): RED for failing tests, GREEN for passing code, REFACTOR for optimization. Validate with at least 85% coverage.\n\nPhase 3 Docs (/moai:3-sync): API documentation, architecture diagrams, project reports.\n\nEARS Format: Ubiquitous for system-wide always active requirements. Event-driven for trigger-based when X do Y requirements. State-driven for conditional while X do Y requirements. Unwanted for prohibited shall not do X requirements. Optional for nice-to-have where possible do X requirements.\n\nToken Budget: SPEC takes 30K, TDD takes 180K, Docs takes 40K, Total is 250K.\n\nKey Practice: Execute /clear after Phase 1 to initialize context.\n\nDetailed Reference: modules/spec-first-tdd.md\n\n---\n\n### 3. Delegation Patterns - Agent Orchestration\n\nPurpose: Task delegation to specialized agents, avoiding direct execution.\n\nCore Principle: Alfred must delegate all work through Task() to specialized agents. Direct execution bypasses specialization, quality gates, and token optimization. Proper delegation improves task success rate by 40 percent and enables parallel execution.\n\nDelegation Syntax: Call Task with subagent_type parameter for specialized agent, prompt parameter for clear specific task, and context parameter with relevant data dictionary.\n\nThree Patterns:\n\nSequential for dependencies: Call Task to api-designer for design, then Task to backend-expert for implementation with design context.\n\nParallel for independent work: Call Promise.all with Task to backend-expert and Task to frontend-expert simultaneously.\n\nConditional for analysis-based: Call Task to debug-helper for analysis, then based on analysis.type, call Task to security-expert or other appropriate agent.\n\nAgent Selection: Simple tasks with 1 file use 1-2 agents sequential. Medium tasks with 3-5 files use 2-3 agents sequential. Complex tasks with 10+ files use 5+ agents mixed.\n\nDetailed Reference: modules/delegation-patterns.md\n\n---\n\n### 4. Token Optimization - Budget Management\n\nPurpose: Efficient 200K token budget through strategic context management.\n\nBudget Allocation:\n\nSPEC Phase takes 30K tokens. Strategy is to load requirements only and execute /clear after completion. Specification phase requires minimal context for requirement analysis. Saves 45-50K tokens for implementation phase.\n\nTDD Phase takes 180K tokens. Strategy is selective file loading, load only implementation-relevant files. Implementation requires deep context but not full codebase. Enables 70 percent larger implementations within budget.\n\nDocs Phase takes 40K tokens. Strategy is result caching and template reuse. Documentation builds on completed work artifacts. Reduces redundant file reads by 60 percent.\n\nTotal Budget is 250K tokens across all phases. Phase separation with context reset between phases provides clean context boundaries and prevents token bloat. Enables 2-3x larger projects within same budget.\n\nToken Saving Strategies:\n\nPhase Separation: Execute /clear between phases, after /moai:1-plan to save 45-50K, when context exceeds 150K, after 50+ messages.\n\nSelective Loading: Load only necessary files.\n\nContext Optimization: Target 20-30K tokens.\n\nModel Selection: Sonnet for quality, Haiku for speed and cost with 70% cheaper rates for 60-70% total savings.\n\nDetailed Reference: modules/token-optimization.md\n\n---\n\n### 5. Progressive Disclosure - Content Architecture\n\nPurpose: Three-tier knowledge delivery balancing value with depth.\n\nThree Levels:\n\nQuick Reference Level: 30 seconds time investment, core principles and essential concepts, approximately 1,000 tokens. Rapid value delivery for time-constrained users. Users gain 80 percent understanding in 5 percent of time.\n\nImplementation Level: 5 minutes time investment, workflows, practical examples, integration patterns, approximately 3,000 tokens. Bridges concept to execution with actionable guidance. Enables immediate productive work without deep expertise.\n\nAdvanced Level: 10+ minutes time investment, deep technical dives, edge cases, optimization techniques, approximately 5,000 tokens. Provides mastery-level knowledge for complex scenarios. Reduces escalations by 70 percent through comprehensive coverage.\n\nSKILL.md Structure (maximum 500 lines): Quick Reference section, Implementation Guide section, Advanced Patterns section, Works Well With section.\n\nModule Architecture: SKILL.md as entry point with cross-references, modules directory for deep dives with unlimited size, examples.md for working samples, reference.md for external links.\n\nFile Splitting when exceeding 500 lines: SKILL.md contains Quick at 80-120 lines, Implementation at 180-250 lines, Advanced at 80-140 lines, References at 10-20 lines. Overflow content goes to modules/topic.md.\n\nDetailed Reference: modules/progressive-disclosure.md\n\n---\n\n### 6. Modular System - File Organization\n\nPurpose: Scalable file structure enabling unlimited content.\n\nStandard Structure: Create .claude/skills/skill-name/ directory containing SKILL.md as core file under 500 lines, modules directory for extended content with unlimited size including patterns.md, examples.md for working samples, reference.md for external links, scripts directory for utilities (optional), templates directory (optional).\n\nFile Principles: SKILL.md stays under 500 lines with progressive disclosure and cross-references. modules directory is topic-focused with no limits and self-contained content. examples.md is copy-paste ready with comments. reference.md contains API docs and resources.\n\nCross-Reference Syntax: Reference modules as Details in modules/patterns.md, reference examples as Examples in examples.md#auth, reference external docs as External in reference.md#api.\n\nDiscovery Flow: SKILL.md to Topic to modules/topic.md to Deep dive.\n\nDetailed Reference: modules/modular-system.md\n\n---\n\n## Advanced Implementation\n\nAdvanced patterns including cross-module integration, quality validation, and error handling are available in the detailed module references.\n\nKey Advanced Topics:\n\n- Cross-Module Integration: Combining TRUST 5 + SPEC-First TDD\n- Token-Optimized Delegation: Parallel execution with context reset\n- Progressive Agent Workflows: Escalation patterns\n- Quality Validation: Pre/Post execution validation\n- Error Handling: Delegation failure recovery\n\nDetailed Reference: examples.md for working code samples\n\n---\n\n## Works Well With\n\nAgents: agent-factory for creating agents with foundation principles, skill-factory for generating skills with modular architecture, core-quality for automated TRUST 5 validation, workflow-spec for EARS format specification, workflow-tdd for RED-GREEN-REFACTOR execution, workflow-docs for documentation with progressive disclosure.\n\nSkills: moai-cc-claude-md for CLAUDE.md with foundation patterns, moai-cc-configuration for config with TRUST 5, moai-cc-memory for token optimization, moai-context7-integration for MCP integration.\n\nTools: AskUserQuestion for direct user interaction and clarification needs.\n\nCommands: /moai:1-plan for SPEC-First Phase 1, /moai:2-run for TDD Phase 2, /moai:3-sync for Documentation Phase 3, /moai:9-feedback for continuous improvement, /clear for token management.\n\nFoundation Modules (Extended Documentation): modules/agents-reference.md for 26-agent catalog with 7-tier hierarchy, modules/commands-reference.md for 6 core commands workflow, modules/execution-rules.md for security, Git strategy, and compliance.\n\n---\n\n## Quick Decision Guide\n\nNew Agent: Primary principle is TRUST 5 and Delegation. Supporting principles are Token Optimization and Modular.\n\nNew Skill: Primary principle is Progressive and Modular. Supporting principles are TRUST 5 and Token Optimization.\n\nWorkflow: Primary principle is Delegation Patterns. Supporting principles are SPEC-First and Token Optimization.\n\nQuality: Primary principle is TRUST 5 Framework. Supporting principle is SPEC-First TDD.\n\nBudget: Primary principle is Token Optimization. Supporting principles are Progressive and Modular.\n\nDocs: Primary principle is Progressive and Modular. Supporting principle is Token Optimization.\n\nModule Deep Dives: modules/trust-5-framework.md, modules/spec-first-tdd.md, modules/delegation-patterns.md, modules/token-optimization.md, modules/progressive-disclosure.md, modules/modular-system.md, modules/agents-reference.md, modules/commands-reference.md, modules/execution-rules.md.\n\nFull Examples: examples.md\nExternal Resources: reference.md\n"},"lastSynced":"2026-03-08T02:01:53.271Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing quality-first and efficient AI development workflows through foundational principles and architectural patterns","zh":"非常适合需要以质量为先和高效的AI开发工作流的AI代理，通过基础原则和架构模式","ja":"品質優先で効率的なAI開発ワークフローを必要とするAIエージェントに最適で、基礎原則とアーキテクチャパターンを介して","ko":"품질 우선과 효율적인 AI 개발 워크플로우가 필요한 AI 에이전트에게 적합하며, 기초 원칙과 아키텍처 패턴을 통해","es":"Perfecto para agentes de IA que necesitan flujos de trabajo de desarrollo de IA de calidad y eficientes a través de principios y patrones arquitectónicos fundamentales","fr":"Parfait pour les agents IA ayant besoin de flux de travail de développement d''IA de qualité et efficaces via des principes et des modèles d''architecture fondamentaux","de":"Perfekt für KI-Agenten, die qualitativ hochwertige und effiziente KI-Entwicklungsworkflows durch grundlegende Prinzipien und Architekturmuster benötigen","pt":"Perfeito para Agentes de IA que precisam de fluxos de trabalho de desenvolvimento de IA de qualidade e eficientes por meio de princípios fundamentais e padrões arquiteturais","ru":"Идеально для агентов ИИ, которым необходимы качественные и эффективные рабочие процессы разработки ИИ через основополагающие принципы и архитектурные шаблоны","ar":"مثالي لعمليات الوكلاء الذكية التي تحتاج إلى سير عمل تطوير ذكاء اصطناعي جيد وفعّال من خلال المبادئ الأساسية وأنماط الهندسة المعمارية"},"recommendation":{"en":"Empowers agents to implement the TRUST 5 Framework, ensuring quality gate systems with test-driven, modular, and efficient AI development through proven patterns and automated workflows, utilizing unified and secured protocols","zh":"赋予代理实现TRUST 5 Framework的能力，确保质量门控系统，通过测试驱动、模块化和高效的AI开发，使用统一和安全的协议","ja":"TRUST 5 Frameworkを実装するためのエージェントをEmpowerし、品質ゲートシステムを確保する、テスト駆動、モジュラー、効率的なAI開発を実現し、統一されたセキュアなプロトコルを使用する","ko":"에이전트가 TRUST 5 Framework를 구현할 수 있도록 강화하여, 품질 게이트 시스템을 보장하고, 테스트 주도형, 모듈화되고 효율적인 AI 개발을 통해, 통일되고 보안된 프로토콜을 사용한다","es":"Habilita a los agentes a implementar el marco de trabajo TRUST 5, garantizando sistemas de puerta de calidad con desarrollo de IA dirigido por pruebas, modular y eficiente a través de patrones probados y flujos de trabajo automatizados, utilizando protocolos unificados y seguros","fr":"Permet aux agents de mettre en œuvre le cadre TRUST 5, garantissant des systèmes de passerelle de qualité avec un développement d''IA piloté par des tests, modulaire et efficace via des modèles éprouvés et des flux de travail automatisés, en utilisant des protocoles unifiés et sécurisés","de":"Ermöglicht es den Agenten, das TRUST-5-Framework zu implementieren, indem es Qualitätsschrankensysteme mit testgetriebenem, modularem und effizientem KI-Entwicklung durch bewährte Muster und automatisierte Workflows gewährleistet, unter Verwendung von einheitlichen und gesicherten Protokollen","pt":"Habilita os agentes a implementar o Framework TRUST 5, garantindo sistemas de portas de qualidade com desenvolvimento de IA orientado a testes, modular e eficiente por meio de padrões comprovados e fluxos de trabalho automatizados, utilizando protocolos unificados e seguros","ru":"Наделяет агентов возможностью реализовать Framework TRUST 5, обеспечивая системы контроля качества с разработкой ИИ, управляемой тестами, модульной и эффективной через проверенные шаблоны и автоматизированные рабочие процессы, используя унифицированные и защищенные протоколы","ar":"يمنح الوكلاء القدرة على تنفيذ إطار عمل TRUST 5، مما يضمن أنظمة بوابات جودة مع سير عمل تطوير ذكاء اصطناعي مدفوع بالاختبار والمتوحد والفعال من خلال النمط المثبت والتدفقات العملية المتمة، باستخدام بروتوكولات موحدة وأمنة"},"useCases":{"en":["Implementing quality gate systems with the TRUST 5 Framework","Developing modular and efficient AI workflows","Ensuring scalability in AI-powered development through proven architectural patterns"],"zh":["使用TRUST 5 Framework实现质量门控系统","开发模块化和高效的AI工作流","通过经验证的架构模式确保AI驱动开发的可扩展性"],"ja":["TRUST 5 Frameworkを使用して品質ゲートシステムを実装する","モジュラーで効率的なAIワークフローを開発する","実証済みのアーキテクチャパターンを使用してAI駆動開発のスケーラビリティを確保する"],"ko":["TRUST 5 Framework를 사용하여 품질 게이트 시스템을 구현한다","모듈화되고 효율적인 AI 워크플로우를 개발한다","실증된 아키텍처 패턴을 사용하여 AI 구동 개발의 확장성을 보장한다"],"es":["Implementar sistemas de puerta de calidad con el marco de trabajo TRUST 5","Desarrollar flujos de trabajo de IA modulares y eficientes","Garantizar la escalabilidad en el desarrollo impulsado por IA a través de patrones arquitectónicos probados"],"fr":["Mettre en œuvre des systèmes de passerelle de qualité avec le cadre TRUST 5","Développer des flux de travail d''IA modulaires et efficaces","Assurer la scalabilité dans le développement piloté par l''IA via des modèles d''architecture éprouvés"],"de":["Implementierung von Qualitätsschrankensystemen mit dem TRUST-5-Framework","Entwicklung von modularen und effizienten KI-Workflows","Gewährleistung der Skalierbarkeit in der KI-gesteuerten Entwicklung durch bewährte Architekturmuster"],"pt":["Implementar sistemas de portas de qualidade com o Framework TRUST 5","Desenvolver fluxos de trabalho de IA modulares e eficientes","Garantir escalabilidade no desenvolvimento alimentado por IA por meio de padrões arquiteturais comprovados"],"ru":["Реализация систем контроля качества с Framework TRUST 5","Разработка модульных и эффективных рабочих процессов ИИ","Обеспечение масштабируемости в разработке, управляемой ИИ, через проверенные архитектурные шаблоны"],"ar":["تنفيذ أنظمة بوابات الجودة بإطار عمل TRUST 5","تطوير سير عمل ذكاء اصطناعي متوحد وفعال","ضمان قابلية التوسع في التطوير الذي يعتمد على الذكاء الاصطناعي من خلال الأنماط المعمارية المثبتة"]},"limitations":{"en":["Requires adherence to quality-first and test-driven development principles","Limited to AI-driven development workflows"],"zh":["需要遵循质量优先和测试驱动开发原则","仅限于AI驱动开发工作流"],"ja":["品質優先でテスト駆動開発の原則に従う必要がある","AI駆動開発ワークフローに限定される"],"ko":["품질 우선과 테스트 주도 개발 원칙을 따라야 한다","AI 구동 개발 워크플로우에만 제한된다"],"es":["Requiere adherencia a los principios de desarrollo de calidad y dirigido por pruebas","Limitado a flujos de trabajo de desarrollo impulsado por IA"],"fr":["Nécessite l''adhésion aux principes de développement de qualité et piloté par des tests","Limité aux flux de travail de développement piloté par l''IA"],"de":["Erfordert die Einhaltung der Grundsätze für qualitätsorientierte und testgetriebene Entwicklung","Begrenzt auf KI-gesteuerte Entwicklungsworkflows"],"pt":["Exige adesão a princípios de desenvolvimento orientados a qualidade e testes","Limitado a fluxos de trabalho de desenvolvimento orientados a IA"],"ru":["Требует соблюдения принципов разработки, ориентированных на качество и тестирование","Ограничен рабочими процессами разработки, управляемыми ИИ"],"ar":["يتطلب الالتزام بمبادئ التطوير التي تتمحور حول الجودة والاختبار","محدود بسير عمل التطوير الذي يعتمد على الذكاء الاصطناعي"]},"version":4},"contentHash":"ba557f6796bb1005494c38e99568e3b8d58ac73724b4bd67b0a18238d018d0ff","qualityScore":45}');
