INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yarang/chatbot_ai_assistant_v2/moai-foundation-core', 'moai-foundation-core', 'yarang', 'chatbot_ai_assistant_v2', 'community', 'moai-foundation-core yarang chatbot_ai_assistant_v2 community moai-foundation-core provides foundational principles and architectural patterns for AI-driven development workflows, benefiting developers and teams seeking quality-first and efficient AI development. MoAI Foundation Core 提供了六个基本原则，确保 AI 应用的质量、效率和可扩展性 MoAI Foundation Core は、AI アプリケーションの品質、効率、スケーラビリティを確保する 6 つの基本原則を提供します MoAI Foundation Core 는 AI 애플리케이션의 품질, 효율성, 확장성을 보장하는 6개의 기본 원칙을 제공합니다 MoAI Foundation Core es un conjunto de principios y patrones arquitectónicos que permiten el desarrollo de soluciones de inteligencia artificial de alta calidad MoAI Foundation Core est un ensemble de principes et de modèles architecturaux qui permettent de développer des solutions d''IA de haute qualité MoAI Foundation Core ist eine Sammlung von Grundsätzen und Architekturmuster, die die Entwicklung von hochwertigen KI-Lösungen ermöglichen O MoAI Foundation Core é um conjunto de princípios e padrões arquitetônicos que garantem qualidade e eficiência no desenvolvimento de soluções de IA. MoAI Foundation Core - это набор принципов и архитектурных паттернов, обеспечивающих качество и эффективность в разработке ИИ Агентов مواي فاونديشن كور هو مجموعة من المبادئ والأنماط المعمارية التي تضمن الجودة والكفاءة في تطوير أدوات الذكاء الاصطناعي what is moai-foundation-core moai-foundation-core setup guide moai-foundation-core alternative how to use moai-foundation-core moai-foundation-core vs MoAI-ADK moai-foundation-core install TRUST 5 Framework AI development workflow quality-first AI development efficient AI development AI 工具开发 MoAI Foundation Core 测试驱动开发 模块化开发 自动化工作流 AI 应用开发 质量门控系统 Implements the TRUST 5 Framework for quality gate system Enforces test-driven development for reliable AI models Promotes modular and efficient AI development through proven patterns Supports automated workflows for streamlined development Ensures readability, unified, and secured AI development practices Employs a quality-first approach for high-quality AI outputs moai-foundation-core is a set of core principles and architectural patterns that power MoAI-ADK''s AI-driven development workflow, emphasizing quality, efficiency, and scalability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('PlaneInABottle/fitnessMobileApp/react-native-navigation-builder', 'community', 'PlaneInABottle', 'fitnessMobileApp', 'PlaneInABottle/fitnessMobileApp', 'react-native-navigation-builder', 0, 0, 45, '2026-03-08T01:57:15.303Z', '2026-03-08T02:01:54.269Z', '7adfee476297100e4e76446d84f4036d47265b23adf4aebddcaa84efbab8c24a', '{"id":"PlaneInABottle/fitnessMobileApp/react-native-navigation-builder","name":"react-native-navigation-builder","description":{"en":"The react-native-navigation-builder skill helps developers create and maintain the navigation structure of their Fitness Tracker App, ensuring type safety and consistency. It benefits developers working with React Native navigation.","zh":"React Native 导航构建器帮助创建和维护健身跟踪器应用的导航结构，确保类型安全性和一致性","ja":"React Native ナビゲーションビルダーは、フィットネストラッカー アプリのナビゲーション構造を作成および維持し、タイプ セーフティと一貫性を確保します","ko":"React Native 네비게이션 빌더는 피트니스 트래커 앱의 네비게이션 구조를 생성하고 유지하여 유형 안전성과 일관성을 보장합니다","es":"react-native-navigation-builder es una habilidad que ayuda a crear y mantener la estructura de navegación de la aplicación Fitness Tracker, garantizando la seguridad de los tipos y la coherencia en navegadores anidados","fr":"react-native-navigation-builder est une compétence qui aide à créer et maintenir la structure de navigation de l''application Fitness Tracker, en garantissant la sécurité des types et la cohérence dans les navigateurs imbriqués","de":"react-native-navigation-builder ist eine Fähigkeit, die dabei hilft, die Navigationsstruktur der Fitness-Tracker-App zu erstellen und zu pflegen, wobei die Typsicherheit und die Konsistenz in verschachtelten Navigatoren gewährleistet werden","pt":"O React Native Navigation Builder ajuda a criar e manter a estrutura de navegação do aplicativo, garantindo segurança de tipo e consistência","ru":"ИИ Агент React Native Navigation Builder помогает создавать и поддерживать навигационную структуру приложения, обеспечивая типобезопасность и согласованность","ar":"يساعد React Native Navigation Builder في إنشاء وتنفيذ هيكل التوجه في التطبيق، مع ضمان سلامة النوع و الاتساق"},"seo":{"title":{"en":"react-native-navigation-builder: Setup Guide for AI Agents","zh":"React Native 导航构建器设置指南","ja":"React Native ナビゲーションビルダー ベストプラクティス","ko":"React Native 네비게이션 빌더 구성 가이드","es":"Guía de configuración de react-native-navigation-builder","fr":"Guide de mise en place de react-native-navigation-builder","de":"Einrichtungsleitfaden für react-native-navigation-builder","pt":"Guia de Configuração do React Native Navigation Builder","ru":"Настройка навигации в React Native с помощью ИИ Агентов","ar":"دليل إعداد React Native Navigation Builder"},"description":{"en":"Discover how to create and maintain navigation structures in your Fitness Tracker App with react-native-navigation-builder. Learn how to add new screens and ...","zh":"使用 React Native 导航构建器创建和维护健身跟踪器应用的导航结构，确保类型安全性和一致性","ja":"React Native ナビゲーションビルダーを使用してフィットネストラッカー アプリのナビゲーション構造を作成および維持し、タイプ セーフティと一貫性を確保します","ko":"React Native 네비게이션 빌더를 사용하여 피트니스 트래커 앱의 네비게이션 구조를 생성하고 유지하여 유형 안전성과 일관성을 보장합니다","es":"Aprende a crear y mantener estructuras de navegación seguras y consistentes con react-native-navigation-builder","fr":"Découvrez comment créer et maintenir des structures de navigation sécurisées et cohérentes avec react-native-navigation-builder","de":"Erfahren Sie, wie Sie mit react-native-navigation-builder sichere und konsistente Navigationsstrukturen erstellen und pflegen","pt":"Aprenda a criar e manter a estrutura de navegação do seu aplicativo com o React Native Navigation Builder","ru":"Используйте ИИ Агенты для создания навигации в React Native: настройка и лучшие практики","ar":"تعلم كيفية إنشاء وتنفيذ هيكل التوجه في تطبيقك باستخدام React Native Navigation Builder"},"definition":{"en":"react-native-navigation-builder is a skill that helps create and maintain navigation structures in React Native apps, ensuring type safety and consistency across nested navigators.","zh":"React Native 导航构建器是一种 AI エージェント，帮助创建和维护 React Native 应用的导航结构","ja":"React Native ナビゲーションビルダーは、React Native アプリのナビゲーション構造を作成および維持する AI エージェントです","ko":"React Native 네비게이션 빌더는 React Native 앱의 네비게이션 구조를 생성하고 유지하는 인공지능 에이전트입니다","es":"¿Qué es react-native-navigation-builder? Es una herramienta de Herramientas de Inteligencia Artificial que ayuda a crear estructuras de navegación seguras","fr":"Qu''est-ce que react-native-navigation-builder ? C''est un outil d''Outils d''Intelligence Artificielle qui aide à créer des structures de navigation sécurisées","de":"Was ist react-native-navigation-builder? Es ist ein Tool von KI-Tools, das dabei hilft, sichere Navigationsstrukturen zu erstellen","pt":"O que é React Native Navigation Builder? É uma ferramenta que ajuda a criar e manter a estrutura de navegação do aplicativo","ru":"Что такое React Native Navigation Builder? Это инструмент, помогающий создавать и поддерживать навигационную структуру приложения","ar":"ما هو React Native Navigation Builder؟ هو أداة تساعد في إنشاء وتنفيذ هيكل التوجه في التطبيق"},"features":{"en":["Adds new screens to the AppStack or MainTabs","Creates new nested navigators, such as sub-stacks or tabs","Defines navigation types for new routes","Sets up screen props for components","Configures navigation options, including headers, tab bars, and presentation"],"zh":["创建和维护 AppStack 和 MainTabs","定义导航类型和路由","设置屏幕属性和组件","配置导航选项（标题、标签栏、呈现）"],"ja":["AppStack と MainTabs の作成および維持","ナビゲーション タイプとルートの定義","画面のプロパティとコンポーネントの設定","ナビゲーション オプション（ヘッダー、タブ バー、表示）の構成"],"ko":["AppStack 및 MainTabs 생성 및 유지","네비게이션 유형 및路由 정의","화면 속성 및 구성요소 설정","네비게이션 옵션（헤더、탭 바、표시）구성"],"es":["Creación de estructuras de navegación seguras y consistentes","Soporte para navegadores anidados","Definición de tipos de navegación para nuevas rutas","Configuración de opciones de navegación","Compatibilidad con React Native"],"fr":["Création de structures de navigation sécurisées et cohérentes","Prise en charge des navigateurs imbriqués","Définition des types de navigation pour les nouvelles routes","Configuration des options de navigation","Compatibilité avec React Native"],"de":["Erstellung sicherer und konsistenter Navigationsstrukturen","Unterstützung für verschachtelte Navigatoren","Definition von Navigationsarten für neue Routen","Konfiguration von Navigationsoptionen","Kompatibilität mit React Native"],"pt":["Criação de telas novas no AppStack ou MainTabs","Definição de tipos de navegação para novas rotas","Configuração de opções de navegação, como headers e tab bar","Suporte a navegadores aninhados, como sub-stacks e tabs","Garantia de segurança de tipo e consistência na navegação"],"ru":["Создание новых экранов в AppStack или MainTabs","Определение типов навигации для новых маршрутов","Настройка параметров навигации, таких как headers и tab bar","Поддержка вложенных навигаторов, таких как sub-stacks и tabs","Обеспечение типобезопасности и согласованности в навигации"],"ar":["إنشاء شاشات جديدة في AppStack أو MainTabs","تحديد أنواع التوجه للطرق الجديدة","تكوين خيارات التوجه، مثل headers و tab bar","دعم الملاحة المتداخلة، مثل sub-stacks و tabs","ضمان سلامة النوع و الاتساق في التوجه"]},"keywords":{"en":["how to use react-native-navigation-builder","react-native-navigation-builder setup guide","react native navigation builder alternative","react-native-navigation-builder vs react-navigation","react-native-navigation-builder install","react native navigation best practices","react-native-navigation-builder documentation","react native navigation tutorial"],"zh":["React Native 导航构建器","健身跟踪器应用","导航结构","类型安全性","一致性","AI エージェント","React Native 开发"],"ja":["React Native ナビゲーションビルダー","フィットネストラッカー アプリ","ナビゲーション構造","タイプ セーフティ","一貫性","AI エージェント","React Native 開発"],"ko":["React Native 네비게이션 빌더","피트니스 트래커 앱","네비게이션 구조","유형 안전성","일관성","인공지능 에이전트","React Native 개발"],"es":["react-native-navigation-builder","Herramientas de Inteligencia Artificial","navegación segura","estructuras de navegación","React Native","desarrollo de aplicaciones móviles","navegadores anidados","tipos de navegación"],"fr":["react-native-navigation-builder","Outils d''Intelligence Artificielle","navigation sécurisée","structures de navigation","React Native","développement d''applications mobiles","navigateurs imbriqués","types de navigation"],"de":["react-native-navigation-builder","KI-Tools","sichere Navigation","Navigationsstrukturen","React Native","Entwicklung von mobilen Anwendungen","verschachtelte Navigatoren","Navigationsarten"],"pt":["React Native Navigation Builder","navegação em React Native","criação de telas em React Native","definição de tipos de navegação","configuração de opções de navegação","navegadores aninhados em React Native","segurança de tipo em React Native"],"ru":["React Native Navigation Builder","навигация в React Native","создание экранов в React Native","определение типов навигации","настройка параметров навигации","вложенные навигаторы в React Native","типобезопасность в React Native","ИИ Агенты для навигации"],"ar":["React Native Navigation Builder","التوجيه في React Native","إنشاء شاشات في React Native","تحديد أنواع التوجه","تكوين خيارات التوجه","ملاحة متداخلة في React Native","سلامة النوع في React Native","أدوات الذكاء الاصطناعي للتوجيه"]}},"owner":"PlaneInABottle","repo":"fitnessMobileApp","repoPath":"PlaneInABottle/fitnessMobileApp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.303Z","topics":[],"category":"community","skillMd":{"name":"react-native-navigation-builder","description":"Creates navigation structures following the apps nested navigator pattern. Handles type-safe navigation, stack and tab setup, and screen parameter management in Fitness Tracker App.","bodyPreview":"# React Native Navigation Builder\n\nThis skill helps create and maintain the navigation structure of the Fitness Tracker App, ensuring type safety and consistency across nested navigators.\n\n## When to Use This Skill\n\nUse this skill when you need to:\n- Add a new screen to the `AppStack` or `MainTabs`\n- Create a new nested navigator (e.g., a sub-stack or tabs)\n- Define navigation types for new routes\n- Set up screen props for components\n- Configure navigation options (headers, tab bar, presentation","body":"# React Native Navigation Builder\n\nThis skill helps create and maintain the navigation structure of the Fitness Tracker App, ensuring type safety and consistency across nested navigators.\n\n## When to Use This Skill\n\nUse this skill when you need to:\n- Add a new screen to the `AppStack` or `MainTabs`\n- Create a new nested navigator (e.g., a sub-stack or tabs)\n- Define navigation types for new routes\n- Set up screen props for components\n- Configure navigation options (headers, tab bar, presentation modes)\n\n## Navigation Structure\n\nThe app uses a nested navigation structure:\n1. **AppNavigator**: The top-level `NavigationContainer`.\n2. **AppStack**: A `NativeStack` containing global screens (Welcome, Legal, Modals) and the `MainTabs`.\n3. **MainTabs**: A `BottomTab` navigator for the primary app features (Home, Capture, Map, Profile).\n\n## Type Safety\n\n### Defining Parameters\n```typescript\n// app/navigators/navigationTypes.ts\nexport type AppStackParamList = {\n  Welcome: undefined\n  MainTabs: NavigatorScreenParams<MainTabParamList>\n  RoutineDetail: { routineId: string }\n  // ...\n}\n```\n\n### Screen Props\n```typescript\nexport type AppStackScreenProps<T extends keyof AppStackParamList> = \n  NativeStackScreenProps<AppStackParamList, T>\n\nexport type MainTabScreenProps<T extends keyof MainTabParamList> = \n  CompositeScreenProps<\n    BottomTabScreenProps<MainTabParamList, T>,\n    AppStackScreenProps<keyof AppStackParamList>\n  >\n```\n\n## Adding a New Screen\n\n### 1. Update Param List\nAdd the screen name and its parameters to `navigationTypes.ts`.\n\n### 2. Update Navigator\nAdd a `<Stack.Screen>` or `<Tab.Screen>` to the appropriate navigator file.\n\n### 3. Implement Component\nUse the defined props in your screen component:\n```tsx\nexport const MyNewScreen = (props: AppStackScreenProps<\"MyNewScreen\">) => {\n  const { navigation, route } = props\n  // ...\n}\n```\n\n## Common Patterns\n\n### Modal Presentation\n```tsx\n<Stack.Screen\n  name=\"RoutineEdit\"\n  component={RoutineEditScreen}\n  options={{ presentation: \"modal\" }}\n/>\n```\n\n### Tab Bar Icons\n```tsx\n<Tab.Screen\n  name=\"Home\"\n  component={HomeScreen}\n  options={{\n    tabBarLabel: \"Home\",\n    tabBarIcon: ({ color }) => <Home size={24} color={color} />,\n  }}\n/>\n```\n\n## References\n\nSee [NAVIGATION_TYPES.md](references/NAVIGATION_TYPES.md) for detailed type patterns.\n\nSee [NAVIGATOR_SETUP.md](references/NAVIGATOR_SETUP.md) for stack and tab configuration examples.\n"},"lastSynced":"2026-03-08T02:01:54.269Z","agentAnalysis":{"suitability":{"en":"Perfect for Mobile App Agents needing streamlined React Native navigation development with type safety and consistency.","zh":"适合需要简化 React Native 导航开发的移动应用代理，具有类型安全和一致性。","ja":"React Native のナビゲーション開発をストリームライン化するためにタイプセーフティと一貫性を必要とするモバイルアプリエージェントに最適です。","ko":"타입 안전성과 일관성을 제공하는 React Native 네비게이션 개발을 스트리밍하는 모바일 앱 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Aplicaciones Móviles que necesitan desarrollo de navegación de React Native optimizado con seguridad y consistencia de tipos.","fr":"Idéal pour les agents d''applications mobiles nécessitant un développement de navigation React Native rationalisé avec une sécurité et une cohérence de types.","de":"Perfekt für Mobile App-Agents, die eine strukturierte React Native-Navigationsentwicklung mit Typsicherheit und Konsistenz benötigen.","pt":"Perfeito para Agentes de Aplicativos Móveis que precisam de navegação do React Native otimizada com segurança e consistência de tipo.","ru":"Идеально подходит для Мобильных Приложений-агентов, которым необходима оптимизированная навигация React Native с безопасностью и согласованностью типа.","ar":"مثالي لعميل التطبيق المحمول الذي يحتاج إلى تنقل React Native منسق مع سلامة وثبات النوع."},"recommendation":{"en":"Empowers agents to create and maintain complex navigation structures in React Native apps, ensuring seamless integration with nested navigators, type-safe routing, and customizable navigation options using React Native navigation libraries.","zh":"赋予代理创建和维护 React Native 应用中复杂的导航结构的能力，确保与嵌套导航器、类型安全路由和自定义导航选项的无缝集成，使用 React Native 导航库。","ja":"React Native アプリケーションで複雑なナビゲーション構造を作成して維持する能力をエージェントに与え、ネストされたナビゲーター、タイプセーフなルーティング、および React Native ナビゲーションライブラリを使用したカスタマイズ可能なナビゲーションオプションとのシームレスな統合を保証します。","ko":"에이전트가 React Native 애플리케이션에서 복잡한 네비게이션 구조를 생성하고 유지하는 기능을 제공하여 중첩된 네비게이터, 타입 안전한 라우팅 및 React Native 네비게이션 라이브러리를 사용한 사용자 정의 네비게이션 옵션과의 無縫な統合을 보장합니다.","es":"Habilita a los agentes a crear y mantener estructuras de navegación complejas en aplicaciones de React Native, garantizando una integración fluida con navegadores anidados, enrutamiento seguro de tipos y opciones de navegación personalizables utilizando bibliotecas de navegación de React Native.","fr":"Permet aux agents de créer et de maintenir des structures de navigation complexes dans les applications React Native, en garantissant une intégration fluide avec les navigateurs imbriqués, le routage sécurisé de types et les options de navigation personnalisables en utilisant les bibliothèques de navigation React Native.","de":"Ermöglicht es Agents, komplexe Navigationsstrukturen in React Native-Apps zu erstellen und zu warten, indem eine nahtlose Integration mit verschachtelten Navigatoren, typsicherer Routing und anpassbaren Navigationsoptionen unter Verwendung von React Native-Navigationsbibliotheken sichergestellt wird.","pt":"Habilita os agentes a criarem e manterem estruturas de navegação complexas em aplicativos React Native, garantindo integração perfeita com navegadores aninhados, roteamento seguro por tipo e opções de navegação personalizáveis usando bibliotecas de navegação do React Native.","ru":"Наделяет агентов возможностью создавать и поддерживать сложные навигационные структуры в приложениях React Native, обеспечивая бесперебойную интеграцию с вложенными навигаторами, безопасным маршрутизацией по типу и настраиваемыми опциями навигации с помощью библиотек навигации React Native.","ar":"تمكين الوكيل من إنشاء هيكل تحكم متقدم في تطبيقات React Native، مع ضمان التكامل السلس بين الملاحة المضمنة وتنقل آمن ونظام ملاحة قابل للتخصيص باستخدام مكتبات React Native."},"useCases":{"en":["Automating the setup of new screens in the AppStack or MainTabs","Generating navigation types for new routes in the Fitness Tracker App","Configuring screen props and navigation options for components","Creating nested navigators such as sub-stacks or tabs","Defining navigation structures for React Native apps with consistency and type safety"],"zh":["自动设置 AppStack 或 MainTabs 中的新屏幕","为 Fitness Tracker 应用中的新路由生成导航类型","配置组件的屏幕属性和导航选项","创建嵌套导航器，例如子栈或选项卡","为 React Native 应用定义具有一致性和类型安全的导航结构"],"ja":["AppStack または MainTabs 内の新しい画面のセットアップを自動化する","Fitness Tracker アプリケーションの新しいルートに対してナビゲーション型を生成する","コンポーネントの画面プロパティとナビゲーションオプションを構成する","ネストされたナビゲーター（サブスタックやタブなど）を作成する","React Native アプリケーションのナビゲーション構造を一貫性とタイプセーフティを保って定義する"],"ko":["AppStack 또는 MainTabs 내의 새로운 화면 설정 자동화","Fitness Tracker 애플리케이션의 새로운 ルート에 대한 네비게이션 유형 생성","컴포넌트의 화면 속성 및 네비게이션 옵션 구성","중첩된 네비게이터(서브 스택 또는 탭 등) 생성","React Native 애플리케이션의 네비게이션 구조를 일관성 및 타입 안전성을 보장하여 정의"],"es":["Automatizar la configuración de nuevas pantallas en AppStack o MainTabs","Generar tipos de navegación para nuevas rutas en la aplicación Fitness Tracker","Configurar propiedades de pantalla y opciones de navegación para componentes","Crear navegadores anidados como sub-pilas o pestañas","Definir estructuras de navegación para aplicaciones de React Native con consistencia y seguridad de tipos"],"fr":["Automatiser la configuration d''écrans nouveaux dans AppStack ou MainTabs","Générer des types de navigation pour de nouvelles routes dans l''application Fitness Tracker","Configurer les propriétés d''écran et les options de navigation pour les composants","Créer des navigateurs imbriqués tels que des sous-empiles ou des onglets","Définir des structures de navigation pour les applications React Native avec cohérence et sécurité de types"],"de":["Automatisieren der Einrichtung neuer Bildschirme in AppStack oder MainTabs","Generieren von Navigationsarten für neue Routen in der Fitness-Tracker-App","Konfigurieren von Bildschirm-Eigenschaften und Navigations-Optionen für Komponenten","Erstellen von verschachtelten Navigatoren wie Sub-Stacks oder Registerkarten","Definieren von Navigationsstrukturen für React Native-Apps mit Konsistenz und Typsicherheit"],"pt":["Automatizar a configuração de novas telas no AppStack ou MainTabs","Gerar tipos de navegação para novas rotas no Aplicativo de Rastreador de Fitness","Configurar propriedades de tela e opções de navegação para componentes","Criar navegadores aninhados, como sub-pilhas ou abas","Definir estruturas de navegação para aplicativos React Native com consistência e segurança de tipo"],"ru":["Автоматизировать настройку новых экранов в AppStack или MainTabs","Генерировать типы навигации для новых маршрутов в Приложении для отслеживания фитнеса","Настроить свойства экрана и опции навигации для компонентов","Создавать вложенные навигаторы, такие как под-стеки или вкладки","Определить структуры навигации для приложений React Native с согласованностью и безопасностью типа"],"ar":["توفير إعداد شاشات جديدة في AppStack أو MainTabs","توليد أنواع الملاحة لطرق جديدة في تطبيق مراقبة اللياقة البدنية","تكوين خصائص الشاشة وخيارات الملاحة للمكونات","إنشاء ملاحة مدمجة مثل المجموعات الفرعية أو الألسنة","تحديد هياكل الملاحة لتطبيقات React Native بالاتساق و سلامة النوع"]},"limitations":{"en":["Requires React Native environment","Limited to React Native navigation development","Type safety and consistency may require additional setup and configuration"],"zh":["需要 React Native 环境","仅限 React Native 导航开发","类型安全和一致性可能需要额外的设置和配置"],"ja":["React Native 環境が必要","React Native ナビゲーション開発に限定される","タイプセーフティと一貫性は追加の設定と構成が必要となる場合がある"],"ko":["React Native 환경이 필요","React Native 네비게이션 개발에만 제한","타입 안전성 및 일관성은 추가 설정 및 구성이 필요한 경우가 있음"],"es":["Requiere entorno de React Native","Limitado al desarrollo de navegación de React Native","La seguridad y la consistencia de los tipos pueden requerir una configuración y configuración adicionales"],"fr":["Nécessite un environnement React Native","Limité au développement de navigation React Native","La sécurité et la cohérence des types peuvent nécessiter une configuration et une configuration supplémentaires"],"de":["Benötigt React Native-Umgebung","Begrenzt auf die Entwicklung von React Native-Navigationsfunktionen","Die Typsicherheit und Konsistenz können eine zusätzliche Einrichtung und Konfiguration erfordern"],"pt":["Exige ambiente do React Native","Limitado ao desenvolvimento de navegação do React Native","Segurança de tipo e consistência podem exigir configuração e instalação adicionais"],"ru":["Требует среды React Native","Ограничен разработкой навигации React Native","Безопасность типа и согласованность могут требовать дополнительной настройки и конфигурации"],"ar":["يتطلب بيئة React Native","محدود بالتنمية الملاحة React Native","سلامة النوع والاتساق قد يتطلب إعدادًا وتكوينًا إضافيًا"]},"version":4},"contentHash":"7adfee476297100e4e76446d84f4036d47265b23adf4aebddcaa84efbab8c24a","qualityScore":45}');
