INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('PlaneInABottle/fitnessMobileApp/react-native-navigation-builder', 'react-native-navigation-builder', 'PlaneInABottle', 'fitnessMobileApp', 'community', 'react-native-navigation-builder PlaneInABottle fitnessMobileApp community The react-native-navigation-builder skill helps developers create and maintain the navigation structure of their Fitness Tracker App, ensuring type safety and consistency. It benefits developers working with React Native navigation. React Native 导航构建器帮助创建和维护健身跟踪器应用的导航结构，确保类型安全性和一致性 React Native ナビゲーションビルダーは、フィットネストラッカー アプリのナビゲーション構造を作成および維持し、タイプ セーフティと一貫性を確保します React Native 네비게이션 빌더는 피트니스 트래커 앱의 네비게이션 구조를 생성하고 유지하여 유형 안전성과 일관성을 보장합니다 react-native-navigation-builder es una habilidad que ayuda a crear y mantener la estructura de navegación de la aplicación Fitness Tracker, garantizando la seguridad de los tipos y la coherencia en navegadores anidados react-native-navigation-builder est une compétence qui aide à créer et maintenir la structure de navigation de l''application Fitness Tracker, en garantissant la sécurité des types et la cohérence dans les navigateurs imbriqués react-native-navigation-builder ist eine Fähigkeit, die dabei hilft, die Navigationsstruktur der Fitness-Tracker-App zu erstellen und zu pflegen, wobei die Typsicherheit und die Konsistenz in verschachtelten Navigatoren gewährleistet werden O React Native Navigation Builder ajuda a criar e manter a estrutura de navegação do aplicativo, garantindo segurança de tipo e consistência ИИ Агент React Native Navigation Builder помогает создавать и поддерживать навигационную структуру приложения, обеспечивая типобезопасность и согласованность يساعد React Native Navigation Builder في إنشاء وتنفيذ هيكل التوجه في التطبيق، مع ضمان سلامة النوع و الاتساق how to use react-native-navigation-builder react-native-navigation-builder setup guide react native navigation builder alternative react-native-navigation-builder vs react-navigation react-native-navigation-builder install react native navigation best practices react-native-navigation-builder documentation react native navigation tutorial React Native 导航构建器 健身跟踪器应用 导航结构 类型安全性 一致性 AI エージェント React Native 开发 Adds new screens to the AppStack or MainTabs Creates new nested navigators, such as sub-stacks or tabs Defines navigation types for new routes Sets up screen props for components Configures navigation options, including headers, tab bars, and presentation react-native-navigation-builder is a skill that helps create and maintain navigation structures in React Native apps, ensuring type safety and consistency across nested navigators.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('atc-net/atc-agentic-toolkit/iot-edge-module', 'community', 'atc-net', 'atc-agentic-toolkit', 'atc-net/atc-agentic-toolkit', 'iot-edge-module', 0, 0, 45, '2026-03-08T01:57:15.304Z', '2026-03-08T02:01:58.076Z', '458fb9702f20e3576ba5761b15818b4c46687c096b4aa04e0ff3f5d71d619c00', '{"id":"atc-net/atc-agentic-toolkit/iot-edge-module","name":"iot-edge-module","description":{"en":"The iot-edge-module skill provides a standardized approach to setting up IoT Edge modules, benefiting developers and teams by simplifying the scaffolding process.","zh":"IoT Edge 模块是一种标准化的模块设置和加速工具，提供模块名称、描述和项目结构检测等功能","ja":"IoT Edge モジュールは、モジュール名、説明、プロジェクト構造検出などの機能を提供する標準化されたモジュール設定と加速ツールです","ko":"IoT Edge 모듈은 모듈 이름, 설명, 프로젝트 구조 감지 등의 기능을 제공하는 표준화된 모듈 설정 및 가속화 도구입니다","es":"El módulo de borde de IoT es una colección de plantillas y prácticas recomendadas para agilizar la configuración de agentes de IA","fr":"Le module de bord de l''IoT est une collection de modèles et de bonnes pratiques pour accélérer la configuration des agents d''IA","de":"Das IoT-Edge-Modul ist eine Sammlung von Vorlagen und Best Practices, um die Konfiguration von KI-Agents zu beschleunigen","pt":"O módulo IoT Edge é uma coleção de prompts, skills e plugins para agentes de codificação de IA, que padroniza e acelera a configuração de agentes em equipes","ru":"Модуль IoT Edge - это коллекция промтов, навыков и плагинов для ИИ Агентов, которая стандартизирует и ускоряет настройку агентов в командах","ar":"وحدة الحواف الإلكترونية هي مجموعة من المفاتيح وال مهارات وأدوات الإضافة لآلات التعلم الاصطناعي، التي توحد وتسرع من عملية الإعداد للوكلاء في الفرق"},"seo":{"title":{"en":"iot-edge-module: IoT Edge Module Scaffolding Setup Guide ...","zh":"IoT Edge 模块设置指南","ja":"IoT Edge モジュールのベストプラクティス","ko":"IoT Edge 모듈 설정 가이드","es":"Guía de configuración de módulo de borde de IoT con Agent...","fr":"Guide de configuration du module de bord de l''IoT avec le...","de":"Konfigurationsleitfaden für IoT-Edge-Module mit KI-Agents","pt":"Guia de Configuração do Módulo IoT Edge para Ferramentas ...","ru":"Руководство по настройке модуля IoT Edge для ИИ Агентов","ar":"دليل إعداد وحدة الحواف الإلكترونية لآلات التعلم الاصطناعي"},"description":{"en":"Streamline IoT Edge module development with our curated collection of prompts and best practices - get started now and accelerate your setup!","zh":"了解 IoT Edge 模块的设置和最佳实践，包括模块名称、描述和项目结构检测","ja":"IoT Edge モジュールの設定とベストプラクティスを学びましょう。モジュール名、説明、プロジェクト構造検出など","ko":"IoT Edge 모듈 설정 및 최고의 실践에 대한 정보를 얻으십시오. 모듈 이름, 설명, 프로젝트 구조 감지 등","es":"Aprende a configurar módulos de borde de IoT con nuestra guía paso a paso y mejora la eficiencia de tus proyectos de IA","fr":"Découvrez comment configurer des modules de bord de l''IoT avec notre guide étape par étape et améliorez l''efficacité de vos projets d''IA","de":"Erfahren Sie, wie Sie IoT-Edge-Module mit unserer Schritt-für-Schritt-Anleitung konfigurieren und die Effizienz Ihrer KI-Projekte verbessern","pt":"Aprenda a configurar módulos IoT Edge com nossa coleção de prompts, skills e plugins para agentes de codificação de IA","ru":"Настройте модули IoT Edge с помощью нашей коллекции промтов, навыков и плагинов для ИИ Агентов","ar":"تعلم كيفية إعداد وحدات الحواف الإلكترونية باستخدام مجموعة من المفاتيح وال مهارات وأدوات الإضافة لآلات التعلم الاصطناعي"},"definition":{"en":"iot-edge-module is a curated collection of prompts, skills, and best practices for AI coding agents to standardize and accelerate IoT Edge module setup.","zh":"IoT Edge 模块是一种用于标准化和加速 AI 编码代理设置的工具","ja":"IoT Edge モジュールは、AI コーディング エージェントの設定を標準化し、加速するためのツールです","ko":"IoT Edge 모듈은 AI 코딩 에이전트 설정을 표준화하고 가속화하는 데 사용되는 도구입니다","es":"Un módulo de borde de IoT es un conjunto de herramientas y prácticas para configurar y implementar agentes de IA en entornos de borde","fr":"Un module de bord de l''IoT est un ensemble d''outils et de pratiques pour configurer et déployer des agents d''IA dans des environnements de bord","de":"Ein IoT-Edge-Modul ist eine Sammlung von Tools und Praktiken zur Konfiguration und Implementierung von KI-Agents in Edge-Umgebungen","pt":"O módulo IoT Edge é uma ferramenta de inteligência artificial que permite a configuração de agentes de codificação","ru":"Модуль IoT Edge - это инструмент ИИ, который позволяет настраивать агентов кодирования","ar":"وحدة الحواف الإلكترونية هي أداة من أدوات الذكاء الاصطناعي التي تمكن من إعداد وكلاء الترميز"},"features":{"en":["Detects existing project structure using Python scripts","Scaffolds new IoT Edge modules with PascalCase naming convention","Loads project structure for streamlined development","Runs project structure detection script for pattern identification","Supports brief module descriptions for clarity and documentation"],"zh":["支持模块名称和描述的设置","提供项目结构检测功能","支持 Python 脚本的运行","提供模块设置的最佳实践"],"ja":["モジュール名と説明の設定をサポート","プロジェクト構造検出機能を提供","Python スクリプトの実行をサポート","モジュール設定のベストプラクティスを提供"],"ko":["모듈 이름과 설명 설정 지원","프로젝트 구조 감지 기능 제공","Python 스크립트 실행 지원","모듈 설정의 최고의 실践 제공"],"es":["Scaffolding de módulos de borde de IoT","Detección de estructura de proyecto","Carga de scripts de Python","Configuración de módulos con descripciones y nombres personalizados"],"fr":["Scaffolding de modules de bord de l''IoT","Détection de structure de projet","Chargement de scripts Python","Configuration de modules avec des descriptions et des noms personnalisés"],"de":["Scaffolding von IoT-Edge-Modulen","Erkennung von Projekstrukturen","Laden von Python-Skripten","Konfiguration von Modulen mit benutzerdefinierten Beschreibungen und Namen"],"pt":["Scaffolding de módulos IoT Edge","Detecção de estrutura de projeto","Criação de módulos personalizados","Integração com scripts de detecção de projeto","Suporte a linguagens de programação como Python"],"ru":["Создание модулей IoT Edge","Обнаружение структуры проекта","Создание пользовательских модулей","Интеграция со скриптами обнаружения проекта","Поддержка языков программирования như Python"],"ar":["إنشاء وحدات الحواف الإلكترونية","اكتشاف هيكل المشروع","إنشاء وحدات مخصصة","التكامل مع سكريبتات اكتشاف المشروع","دعم لغات البرمجة مثل بايثون"]},"keywords":{"en":["how to use iot-edge-module","iot-edge-module setup guide","iot-edge-module alternative","iot-edge-module vs Azure IoT Edge","iot-edge-module install","what is iot-edge-module","iot-edge-module scaffolding process","iot-edge-module best practices"],"zh":["IoT Edge 模块","AI 编码代理","模块设置","项目结构检测","Python 脚本","AIエージェント工具","IoT Edge开发"],"ja":["IoT Edge モジュール","AI コーディング エージェント","モジュール設定","プロジェクト構造検出","Python スクリプト","AIエージェント","IoT Edge開発"],"ko":["IoT Edge 모듈","AI 코딩 에이전트","모듈 설정","프로젝트 구조 감지","Python 스크립트","AI 에이전트 도구","IoT Edge 개발"],"es":["iot edge module","agentes de ia","configuración de módulos","scaffolding de iot","desarrollo de ia","herramientas de ia","=configuración de agentes de ia"],"fr":["module de bord de l''iot","outils d''ia","configuration de modules","scaffolding de l''iot","développement d''ia","outils d''ia","configuration d''agents d''ia"],"de":["iot-edge-modul","ki-agents","konfiguration von modulen","scaffolding von iot","entwicklung von ki","ki-tools","konfiguration von ki-agents"],"pt":["iot edge module","ferramentas de inteligência artificial","agentes de codificação","scaffolding de módulos","detecção de estrutura de projeto","criação de módulos personalizados","integração com scripts de detecção de projeto","suporte a linguagens de programação como Python"],"ru":["модуль IoT Edge","инструменты ИИ","агенты кодирования","создание модулей","обнаружение структуры проекта","создание пользовательских модулей","интеграция со скриптами обнаружения проекта","поддержка языков программирования как Python"],"ar":["وحدة الحواف الإلكترونية","أدوات الذكاء الاصطناعي","وكلاء الترميز","إنشاء وحدات","اكتشاف هيكل المشروع","إنشاء وحدات مخصصة","التكامل مع سكريبتات اكتشاف المشروع","دعم لغات البرمجة مثل بايثون"]}},"owner":"atc-net","repo":"atc-agentic-toolkit","repoPath":"atc-net/atc-agentic-toolkit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.304Z","topics":[],"category":"community","skillMd":{"name":"iot-edge-module","description":"Automates Azure IoT Edge module scaffolding, manifest configuration, and shared contract generation with intelligent project structure detection. Use when the user wants to create, scaffold, or set up a new IoT Edge module, or add a new module to an edge deployment.","bodyPreview":"# IoT Edge Module Scaffolding\n\n## Prerequisites\n\nBefore scaffolding a module, gather the following information from the user:\n\n1. **Module name** (PascalCase, e.g., \"DataProcessorModule\")\n2. **Module description** (brief description of module purpose)\n\n## Scaffolding Process\n\nFollow these steps in order to scaffold a new IoT Edge module:\n\n### Step 1: Detect or Load Project Structure\n\nRun the project structure detection script to identify existing patterns:\n\n```bash\npython scripts/detect_project_","body":"# IoT Edge Module Scaffolding\n\n## Prerequisites\n\nBefore scaffolding a module, gather the following information from the user:\n\n1. **Module name** (PascalCase, e.g., \"DataProcessorModule\")\n2. **Module description** (brief description of module purpose)\n\n## Scaffolding Process\n\nFollow these steps in order to scaffold a new IoT Edge module:\n\n### Step 1: Detect or Load Project Structure\n\nRun the project structure detection script to identify existing patterns:\n\n```bash\npython scripts/detect_project_structure.py --root .\n```\n\n### Step 1.5: Verify IoTEdgeModules Folder Structure\n\nIf `modules_base_path` wasn''t found or doesn''t exist, ask the user via AskUserQuestion:\n- Option 1: Create at default `src/IoTEdgeModules/modules/`\n- Option 2: Specify custom path\n- Option 3: Cancel scaffolding\n\n**Processing detection output:**\n\n1. Parse the JSON output\n2. If `config_source` is `\"saved\"`, use silently\n3. If `config_source` is `\"detected\"`, present findings and ask for confirmation via AskUserQuestion:\n   - \"Yes, use it\" / \"Save and use\" / \"No, customize\"\n4. If \"Save and use\": run `python scripts/detect_project_structure.py --root . --save`\n5. If \"No, customize\" or detection fails, prompt for: project namespace, container registry URL, modules base path, contracts project name/path\n\n### Step 2: Gather Module-Specific Information\n\nAsk the user for:\n\n**Required:**\n\n1. **Module name** (PascalCase)\n2. **Module description**\n\n**Optional Features:**\n\n**A. Private NuGet Feed**\n\n- Ask: \"Does this project require a private NuGet feed? (Yes/No)\"\n- If Yes and not detected: Prompt for NuGet feed URL\n- If Yes and detected: Confirm detected URL or allow override\n\n**B. Shared Contracts Project**\n\n- If contracts project was detected: Automatically use it for module constants (no prompt needed)\n- If not detected: Ask \"Do you have a shared contracts project? (Yes/No/Create standalone)\"\n\n### Step 3: Validate and Normalize Module Names\n\nConvert the user-provided module name to required formats:\n\n**ModuleName (PascalCase):**\n\n- Remove \"Module\" suffix if present, then add it back\n- Example: \"DataProcessor\" → \"DataProcessorModule\"\n- Example: \"DataProcessorModule\" → \"DataProcessorModule\"\n\n**modulename (lowercase):**\n\n- Convert ModuleName to lowercase\n- Example: \"DataProcessorModule\" → \"dataprocessormodule\"\n\n**Confirm with user using AskUserQuestion tool:**\n\nPresent the module details and ask for confirmation:\n\n- **Question**: \"Proceed with creating this module?\"\n- **Header**: \"Confirm Module\"\n- **Options**:\n  - \"Yes, create module\" → Continue to Step 4\n  - \"No, use different name\" → Go back to Step 2 (gather module name)\n\nDisplay in the question description:\n\n```\nModule will be created as:\n• C# class name: <ModuleName>\n• Module ID: <modulename>\n• Directory: <modules_base_path>/<modulename>/\n```\n\n**Do NOT assume \"Yes\" or proceed without using AskUserQuestion tool and getting explicit user confirmation**\n\n### Step 4: Create Module Directory Structure\n\nCreate the module directory:\n\n```\n<modules_base_path>/<modulename>/\n```\n\nCheck if directory already exists (MUST use this exact bash syntax):\n\n```bash\ntest -d \"<modules_base_path>/<modulename>\" && echo \"EXISTS\" || echo \"NOT_EXISTS\"\n```\n\n**Note:** Do NOT use Windows CMD syntax like `if exist`. Always use Unix bash syntax as shown above.\n\n- If EXISTS: Ask user \"Module directory exists. Overwrite? (Yes/Rename/Cancel)\"\n- If Rename: Prompt for new name and restart from Step 3\n\n### Step 5: Generate Module Files from Templates\n\nUse the template files in `assets/` to generate module files with runtime substitutions. The skill generates 11 files total.\n\n**Placeholder substitutions:**\n\n| Placeholder | Value | Example |\n|-------------|-------|---------|\n| `{{ModuleName}}` | PascalCase module name | DataProcessorModule |\n| `{{modulename}}` | Lowercase module name | dataprocessormodule |\n| `{{ModuleDescription}}` | User-provided description | Processes sensor data |\n| `{{CONTAINER_REGISTRY}}` | Detected or provided registry | myregistry.azurecr.io |\n| `{{PROJECT_NAMESPACE}}` | Detected or provided namespace | Company.IoT.EdgeAPI |\n| `{{MODULE_CSPROJ_PATH}}` | Calculated module csproj path: `<modules_base_path>/<modulename>/<ModuleName>.csproj` | src/IoTEdgeModules/modules/dataprocessormodule/DataProcessorModule.csproj |\n| `{{MODULE_PUBLISH_PATH}}` | Calculated publish path | src/IoTEdgeModules/modules/dataprocessormodule |\n| `{{CONTRACTS_PROJECT_REFERENCE}}` | Conditional contracts reference | See below |\n| `{{CONTRACTS_CSPROJ_COPY}}` | Conditional Dockerfile COPY | See below |\n| `{{NUGET_CONFIG_SECTION}}` | Conditional NuGet configuration | See below |\n\n**Conditional placeholder handling:**\n\n**A. Contracts Project Reference (`{{CONTRACTS_PROJECT_REFERENCE}}`)**\n\n**Calculate relative path from module directory to contracts directory:**\n\nExample:\n\n- Module at: `src/IoTEdgeModules/modules/mydemomodule/`\n- Contracts at: `src/Company.IoT.Modules.Contracts/`\n- Relative path: `../../../Company.IoT.Modules.Contracts`\n  - Go up 3 levels: `mydemomodule/` → `modules/` → `IoTEdgeModules/` → `src/`\n  - Then down to: `Company.IoT.Modules.Contracts/`\n\nIf using shared contracts:\n\n```xml\n  <ItemGroup>\n    <ProjectReference Include=\"<relative-path-to-contracts>/<contracts_project_name>.csproj\" />\n  </ItemGroup>\n```\n\nIf NOT using shared contracts:\n\n```xml\n  <!-- No shared contracts project -->\n```\n\n**B. Contracts Dockerfile COPY (`{{CONTRACTS_CSPROJ_COPY}}`)**\n\nIf using shared contracts:\n\n```dockerfile\nCOPY <contracts_project_path>/*.csproj ./src/\n```\n\nIf NOT using shared contracts:\n```\n(empty - no COPY line)\n```\n\n**C. NuGet Configuration (`{{NUGET_CONFIG_SECTION}}`)**\n\nIf using private NuGet feed:\n\n```dockerfile\nENV VSS_NUGET_EXTERNAL_FEED_ENDPOINTS=\"{\\\"endpointCredentials\\\": [{\\\"endpoint\\\":\\\"<nuget_feed_url>\\\", \\\"username\\\":\\\"docker\\\", \\\"password\\\":\\\"${FEED_ACCESSTOKEN}\\\"}]}\"\n\n```\n\nIf NOT using private NuGet feed:\n\n```\n(empty - no ENV line)\n```\n\n**Template file mappings:**\n\n| Template File | Target File | Notes |\n|---------------|-------------|-------|\n| `template.csproj` | `<ModuleName>.csproj` | Rename to match ModuleName |\n| `template-module.json` | `module.json` | - |\n| `template-Program.cs` | `Program.cs` | - |\n| `template-Service.cs` | `<ModuleName>Service.cs` | Rename to match ModuleName |\n| `template-GlobalUsings.cs` | `GlobalUsings.cs` | - |\n| `template-ServiceLoggerMessages.cs` | `<ModuleName>ServiceLoggerMessages.cs` | Rename to match ModuleName |\n| `template-Dockerfile.amd64` | `Dockerfile.amd64` | - |\n| `template-Dockerfile.amd64.debug` | `Dockerfile.amd64.debug` | - |\n| `template-.dockerignore` | `.dockerignore` | - |\n| `template-.gitignore` | `.gitignore` | - |\n| `template-launchSettings.json` | `Properties/launchSettings.json` | Create Properties/ first |\n\n**Processing workflow:**\n\nFor each template file listed in the table above, process sequentially:\n\n1. Read the template file from `assets/`\n2. Replace all placeholders with calculated values\n3. Write to target location in module directory using the target filename from the table\n4. Report progress: \"✓ Created <filename>\"\n\nProcess all 11 files one at a time before proceeding to Step 6.\n\n### Step 6: Create Shared Contract Constants (Conditional)\n\n**If using shared contracts project:**\n\n**Directory:** `<contracts_project_path>/<ModuleName>/`\n\n**File:** `<ModuleName>Constants.cs`\n\n**Process:**\n\n1. Create directory if it doesn''t exist\n2. Read `template-ModuleConstants.cs`\n3. Replace placeholders\n4. Write to contracts project location\n\n**If NOT using shared contracts:**\n\n**Directory:** `<modules_base_path>/<modulename>/Contracts/`\n\n**File:** `<ModuleName>Constants.cs`\n\n**Process:**\n\n1. Create `Contracts/` folder in module directory\n2. Read `template-ModuleConstants.cs`\n3. Replace `{{PROJECT_NAMESPACE}}.Modules.Contracts` with just `{{ModuleName}}.Contracts`\n4. Write to module''s Contracts folder\n\n### Step 6.5: Create LoggingBuilderExtensions (First Module Only)\n\nThis extension method is required for `AddModuleConsoleLogging()` in Program.cs.\n\n**If using shared contracts project:**\n\nCheck if `<contracts_project_path>/Extensions/LoggingBuilderExtensions.cs` exists:\n\n- If file exists: Skip this step (already created by previous module)\n- If file does NOT exist: Create it\n\n**Directory:** `<contracts_project_path>/Extensions/`\n\n**File:** `LoggingBuilderExtensions.cs`\n\n**Process:**\n\n1. Create `Extensions/` directory if it doesn''t exist\n2. Read `template-LoggingBuilderExtensions.cs`\n3. Replace `{{PROJECT_NAMESPACE}}` placeholder\n4. Write to contracts project Extensions folder\n5. Report to user: \"✓ Created LoggingBuilderExtensions.cs in shared contracts project\"\n\n**If NOT using shared contracts:**\n\n**Directory:** `<modules_base_path>/<modulename>/Extensions/`\n\n**File:** `LoggingBuilderExtensions.cs`\n\n**Process:**\n\n1. Create `Extensions/` folder in module directory\n2. Read `template-LoggingBuilderExtensions.cs`\n3. Replace `{{PROJECT_NAMESPACE}}.Modules.Contracts` with `{{ModuleName}}`\n4. Write to module''s Extensions folder\n\n### Step 7: Scan and Select Deployment Manifests\n\nRun the manifest scanning script:\n\n```bash\npython scripts/scan_manifests.py --root .\n```\n\n**Process the output:**\n\n1. Parse JSON to get list of manifest files\n2. If 0 manifests found: Go to Step 7.5 (create base manifest)\n3. If 1 manifest found: Ask \"Add module to <manifest_name>? (Yes/No)\"\n4. If multiple manifests found: Present selection list\n\n### Step 7.5: Handle \"No Manifests Found\" Scenario\n\nIf 0 manifests found, ask user to create a base manifest or skip:\n\n- **If Yes**: Prompt for manifest name (default: \"base\"), create from `assets/template-base.deployment.manifest.json` at `<manifests_base_path>/{name}.deployment.manifest.json`, then add module via the update script\n- **If No**: Skip to Step 9\n\n**Multi-manifest selection**: If multiple manifests found, present list with module counts and let user pick which to update (comma-separated numbers, ''all'', or ''none'').\n\n### Step 8: Update Deployment Manifests (Automated)\n\nFor each selected manifest, run the update script:\n\n```bash\npython scripts/update_deployment_manifest.py \\\n  \"<manifest_path>\" \\\n  \"<modulename>\" \\\n  --registry \"<container_registry>\"\n```\n\n**Process the output:**\n\n1. Check for `\"success\": true` in JSON output\n2. Report to user: \"✓ Added <modulename> to <manifest_name> (startup order: <startup_order>)\"\n3. If error: Report error and provide manual fallback instructions\n\nIf the script fails, show the error and provide manual fallback instructions from `references/deployment-manifests.md`.\n\n### Step 9: Update README.md (Optional)\n\nSearch for \"Solution project overview\" or \"IoTEdge modules\" section in README.md:\n\n**If section exists:**\n\n- Add entry: `- **<modulename>** (\\`<module_path>\\`) - <ModuleDescription>`\n- Insert alphabetically\n\n**If section doesn''t exist:**\n\n- Ask user: \"README.md section not found. Create it? (Yes/No)\"\n\n### Step 9.5: Add Module to Solution File\n\n**Detect solution file:**\n\nRun the solution detection script:\n\n```bash\npython scripts/manage_solution.py --root . --detect\n```\n\n**Process detection results:**\n\n**If .slnx file found:**\n\nAutomatically add module to solution:\n\n```bash\npython scripts/manage_solution.py \\\n  --root . \\\n  --add-module \"<module_csproj_path>\" \\\n  --module-name \"<ModuleName>\"\n```\n\n- Parse JSON output\n- If `action: \"added\"`: Report \"✓ Added to solution at position <insertion_index>\"\n- If `action: \"already_exists\"`: Report \"Module already in solution\"\n- If `action: \"error\"`: Show error and continue\n\n**If .sln file found:**\n\n- Run manual instruction generator:\n  ```bash\n  python scripts/manage_solution.py \\\n    --root . \\\n    --add-module \"<module_csproj_path>\" \\\n    --module-name \"<ModuleName>\"\n  ```\n- Parse JSON output and display `instructions` field to user\n- Recommend using: `dotnet sln add \"<module_csproj_path>\"`\n\n**If no solution file found:**\n\n- Skip this step\n- Inform user: \"No solution file found. Module created successfully without solution integration.\"\n\n### Step 10: Provide Summary and Next Steps\n\n**Summary of created files:**\n```\n✓ Module scaffolding complete!\n\nCreated:\n• Module directory: <module_full_path>/ (11 files)\n• Constants file: <constants_full_path>\n• LoggingBuilderExtensions: <\"Created\" or \"Already exists - skipped\">\n• Updated manifests: <manifest_count> manifest(s) [or \"Created base manifest\" if first module]\n• Solution integration: <\"Added to .slnx\" or \"Manual instructions provided\" or \"Skipped\">\n\nConfiguration:\n• Container registry: <container_registry>\n• Project namespace: <project_namespace>\n• NuGet feed: <nuget_feed_url or \"None\">\n• Shared contracts: <\"Yes\" or \"No\">\n```\n\n**Next steps for the user:**\n\n1. Implement business logic in `<ModuleName>Service.cs` → `ExecuteAsync()`\n2. Test locally: `dotnet run --project <module_path>` (uses mock IoT Hub client)\n3. Build Docker image, push to registry, deploy manifest to IoT Hub\n\nFor post-scaffolding customizations (Quartz, config options, routing, direct methods, etc.), see `references/customizations.md`.\n\n## Reference Documentation\n\n- `references/module-structure.md` - Module structure, naming conventions, and notes\n- `references/deployment-manifests.md` - Deployment manifest configuration\n- `references/customizations.md` - Post-scaffolding customizations, error handling, and config file format\n"},"lastSynced":"2026-03-08T02:01:58.076Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Automation Agents specializing in IoT infrastructure deployment and management.","zh":"非常适合专门从事IoT基础设施部署和管理的DevOps自动化代理。","ja":"IoTインフラストラクチャの展開と管理を専門とするDevOps自動化エージェントに最適です。","ko":"IoT 인프라스트럭처 배포 및 관리를 전문으로 하는 DevOps 자동화 에이전트에 적합합니다.","es":"Perfecto para agentes de automatización de DevOps que se especializan en la implementación y administración de infraestructura de IoT.","fr":"Parfait pour les agents d''automatisation DevOps spécialisés dans le déploiement et la gestion d''infrastructures IoT.","de":"Perfekt für DevOps-Automationsagenten, die sich auf die Bereitstellung und Verwaltung von IoT-Infrastrukturen spezialisieren.","pt":"Perfeito para Agentes de Automação DevOps especializados em implantação e gerenciamento de infraestrutura IoT.","ru":"Идеально подходит для агентов автоматизации DevOps, специализирующихся на развертывании и управлении инфраструктурой IoT.","ar":"مثالي لعميل تلقائي DevOps المتخصص في نشر وبناء البنية التحتية لإنترنت الأشياء."},"recommendation":{"en":"Enables agents to automate IoT Edge module scaffolding with standardized project structures, reducing manual setup time and ensuring consistency across deployments. It provides automated project structure detection and module generation capabilities.","zh":"使代理能够自动执行IoT Edge模块的脚手架设置，具有标准化的项目结构，减少手动设置时间，并确保跨部署的一致性。它提供自动化项目结构检测和模块生成能力。","ja":"エージェントがIoT Edgeモジュールのスケルトン設定を自動化できるようにし、標準化されたプロジェクト構造で手動設定時間を短縮し、展開全体で一貫性を保証します。自動化されたプロジェクト構造検出とモジュール生成機能を提供します。","ko":"에이전트가 IoT Edge 모듈의 스캐폴딩을 자동화 할 수 있도록 하여 표준화된 프로젝트 구조로 수동 설정 시간을 단축하고 배포 전체에서 일관성을 보장합니다. 자동화 된 프로젝트 구조 감지 및 모듈 생성 기능을 제공합니다.","es":"Permite a los agentes automatizar la creación de módulos de IoT Edge con estructuras de proyecto estandarizadas, reduciendo el tiempo de configuración manual y garantizando la consistencia en los despliegues. Proporciona capacidades de detección de estructuras de proyecto automatizadas y generación de módulos.","fr":"Permet aux agents d''automatiser la création de modules IoT Edge avec des structures de projet standardisées, réduisant le temps de configuration manuelle et garantissant la cohérence des déploiements. Il offre des capacités de détection de structure de projet automatisées et de génération de modules.","de":"Ermöglicht es Agenten, die Erstellung von IoT-Edge-Modulen mit standardisierten Projektstrukturen zu automatisieren, wodurch die manuelle Einrichtungszeit reduziert und die Konsistenz über die Bereitstellungen hinweg sichergestellt wird. Es bietet automatisierte Projektstruktur-Erkennung und Modulgenerierungsfunktionen.","pt":"Permite que os agentes automatizem a criação de módulos IoT Edge com estruturas de projeto padronizadas, reduzindo o tempo de configuração manual e garantindo a consistência em todos os ambientes. Fornece capacidades de detecção de estrutura de projeto automatizada e geração de módulos.","ru":"Позволяет агентам автоматизировать создание модулей IoT Edge с стандартизированными структурами проектов, сокращая время ручной настройки и гарантируя согласованность во всех развертываниях. Он обеспечивает автоматические возможности обнаружения структуры проекта и генерации модулей.","ar":"يمكن للعميل تلقائي إتمام عمل تلقائي لإنشاء وحدة من وحدات حافة إنترنت الأشياء مع بنية مشروع معيارية، مما يقلل من وقت الإعداد اليدوي وضمان الاتساق عبر جميع التوزيعات. إنه يوفر قدرات الكشف التلقائي عن بنية المشروع وتوليد الوحدات."},"useCases":{"en":["Automating IoT Edge module initialization","Standardizing project scaffolding across teams","Detecting existing project patterns for integration"],"zh":["自动执行IoT Edge模块初始化","跨团队标准化项目脚手架","检测现有项目模式以进行集成"],"ja":["IoT Edgeモジュールの初期化を自動化する","チーム全体でプロジェクトスケルトンを標準化する","統合するための既存のプロジェクトパターンを検出する"],"ko":["IoT Edge 모듈 초기화를 자동화하는 것","팀 전체에서 프로젝트 스캐폴딩을 표준화하는 것","통합을 위한 기존 프로젝트 패턴을 감지하는 것"],"es":["Automatización de la inicialización de módulos de IoT Edge","Estandarización de la estructura de proyecto de scaffolding en equipos","Detección de patrones de proyecto existentes para integración"],"fr":["Automatisation de l''initialisation des modules IoT Edge","Standardisation de la structure de projet de scaffolding dans les équipes","Détection de modèles de projet existants pour l''intégration"],"de":["Automatisierung der Initialisierung von IoT-Edge-Modulen","Standardisierung der Projektstruktur-Scaffolding in Teams","Erkennung von vorhandenen Projektmustern für die Integration"],"pt":["Automatizar a inicialização do módulo IoT Edge","Padronizar a estrutura de projeto de scaffolding em equipes","Detectar padrões de projeto existentes para integração"],"ru":["Автоматизировать инициализацию модуля IoT Edge","Стандартизировать структуру проекта scaffolding в командах","Обнаруживать существующие шаблоны проекта для интеграции"],"ar":["توفير آلي لتأسيس وحدة من وحدات حافة إنترنت الأشياء","تقييس هيكل المشروع عبر الفريق","اكتشاف أنماط المشروع الموجودة من أجل التكامل"]},"limitations":{"en":["Requires Python environment for detection scripts","Needs module name in PascalCase format","Depends on IoT Edge framework compatibility"],"zh":["需要Python环境用于检测脚本","需要以PascalCase格式命名模块","依赖于IoT Edge框架的兼容性"],"ja":["検出スクリプトにPython環境が必要","モジュール名はPascalCase形式でなければならない","IoT Edgeフレームワークの互換性に依存する"],"ko":["감지 스크립트에 Python 환경이 필요합니다.","모듈 이름은 PascalCase 형식이어야 합니다.","IoT Edge 프레임워크의 호환성에 의존합니다."],"es":["Requiere un entorno Python para los scripts de detección","Necesita el nombre del módulo en formato PascalCase","Depende de la compatibilidad del marco IoT Edge"],"fr":["Nécessite un environnement Python pour les scripts de détection","A besoin du nom du module au format PascalCase","Dépend de la compatibilité du framework IoT Edge"],"de":["Benötigt eine Python-Umgebung für die Erkennungsskripte","Benötigt den Modulnamen im PascalCase-Format","Hängt von der Kompatibilität des IoT-Edge-Frameworks ab"],"pt":["Exige ambiente Python para scripts de detecção","Necessita do nome do módulo no formato PascalCase","Depende da compatibilidade do framework IoT Edge"],"ru":["Требует среды Python для скриптов обнаружения","Требует имени модуля в формате PascalCase","Зависит от совместимости фреймворка IoT Edge"],"ar":["يتطلب بيئة بايثون من أجل كتابة البرامج النصية للكشف","يحتاج إلى اسم الوحدة بالتنسيق PascalCase","يعتمد على توافق إطار حافة إنترنت الأشياء"]},"version":4},"contentHash":"458fb9702f20e3576ba5761b15818b4c46687c096b4aa04e0ff3f5d71d619c00","qualityScore":45}');
