INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('atc-net/atc-agentic-toolkit/iot-edge-module', 'iot-edge-module', 'atc-net', 'atc-agentic-toolkit', 'community', 'iot-edge-module atc-net atc-agentic-toolkit community The iot-edge-module skill provides a standardized approach to setting up IoT Edge modules, benefiting developers and teams by simplifying the scaffolding process. IoT Edge 模块是一种标准化的模块设置和加速工具，提供模块名称、描述和项目结构检测等功能 IoT Edge モジュールは、モジュール名、説明、プロジェクト構造検出などの機能を提供する標準化されたモジュール設定と加速ツールです IoT Edge 모듈은 모듈 이름, 설명, 프로젝트 구조 감지 등의 기능을 제공하는 표준화된 모듈 설정 및 가속화 도구입니다 El módulo de borde de IoT es una colección de plantillas y prácticas recomendadas para agilizar la configuración de agentes de IA Le module de bord de l''IoT est une collection de modèles et de bonnes pratiques pour accélérer la configuration des agents d''IA Das IoT-Edge-Modul ist eine Sammlung von Vorlagen und Best Practices, um die Konfiguration von KI-Agents zu beschleunigen O módulo IoT Edge é uma coleção de prompts, skills e plugins para agentes de codificação de IA, que padroniza e acelera a configuração de agentes em equipes Модуль IoT Edge - это коллекция промтов, навыков и плагинов для ИИ Агентов, которая стандартизирует и ускоряет настройку агентов в командах وحدة الحواف الإلكترونية هي مجموعة من المفاتيح وال مهارات وأدوات الإضافة لآلات التعلم الاصطناعي، التي توحد وتسرع من عملية الإعداد للوكلاء في الفرق how to use iot-edge-module iot-edge-module setup guide iot-edge-module alternative iot-edge-module vs Azure IoT Edge iot-edge-module install what is iot-edge-module iot-edge-module scaffolding process iot-edge-module best practices IoT Edge 模块 AI 编码代理 模块设置 项目结构检测 Python 脚本 AIエージェント工具 IoT Edge开发 Detects existing project structure using Python scripts Scaffolds new IoT Edge modules with PascalCase naming convention Loads project structure for streamlined development Runs project structure detection script for pattern identification Supports brief module descriptions for clarity and documentation iot-edge-module is a curated collection of prompts, skills, and best practices for AI coding agents to standardize and accelerate IoT Edge module setup.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Redth/MAUI.Sherpa/maui-ai-debugging', 'community', 'Redth', 'MAUI.Sherpa', 'Redth/MAUI.Sherpa', 'maui-ai-debugging', 0, 0, 45, '2026-03-08T01:57:15.310Z', '2026-03-08T02:02:27.742Z', 'e40916183c284bc41db89e2ca98c3290e2d45675c28e815f719d65e6749d4473', '{"id":"Redth/MAUI.Sherpa/maui-ai-debugging","name":"maui-ai-debugging","description":{"en":"The maui-ai-debugging skill enables a complete feedback loop for .NET MAUI app development, allowing developers to build, deploy, inspect, and debug apps from the terminal.","zh":"MAUI AI调试工具提供了.NET MAUI应用的构建、部署、检查和调试功能。使用CLI命令行工具来管理您的开发环境","ja":"MAUI AIデバッグツールは、.NET MAUIアプリのビルド、デプロイ、検査、デバッグ機能を提供します。CLIコマンドラインツールを使用して開発環境を管理します","ko":"MAUI AI 디버깅 도구는 .NET MAUI 애플리케이션의 빌드, 배포, 검사 및 디버깅 기능을 제공합니다. CLI 명령줄 도구를 사용하여 개발 환경을 관리합니다","es":"MAUI AI Debugging permite una retroalimentación completa para aplicaciones .NET MAUI: construir, implementar, inspeccionar y depurar desde la terminal","fr":"MAUI AI Debugging permet une boucle de rétroaction complète pour les applications .NET MAUI : construire, déployer, inspecter et déboguer depuis le terminal","de":"MAUI-AI-Debugging ermöglicht eine vollständige Rückmeldeschleife für .NET-MAUI-Anwendungen: Erstellen, Bereitstellen, Untersuchen und Debuggen von der Terminal aus","pt":"O MAUI Sherpa oferece uma solução completa para debugging de AI MAUI em .NET MAUI, permitindo um ciclo de feedback completo: build, deploy, inspect, fix e rebuild.","ru":"MAUI Sherpa предоставляет полное решение для отладки ИИ MAUI в .NET MAUI, позволяя выполнить полный цикл обратной связи: build, deploy, inspect, fix и rebuild.","ar":"يقدم MAUI Sherpa حلًا كاملاً لأداة Debugging للذكاء الاصطناعي MAUI في .NET MAUI، مما يسمح بتحقيق دورة تغذية راجعة كاملة: build، deploy، inspect، fix و rebuild."},"seo":{"title":{"en":"maui-ai-debugging: AI-Powered .NET MAUI Debugging Setup G...","zh":"MAUI AI调试工具：终端调试.NET MAUI应用的设置指南","ja":"MAUI AIデバッグツール：.NET MAUIアプリのターミナルデバッグ設定ガイド","ko":"MAUI AI 디버깅 도구: 터미널에서 .NET MAUI 애플리케이션 디버깅 설정 가이드","es":"Guía de configuración de depuración de AI de MAUI","fr":"Guide de débogage MAUI AI pour les développeurs","de":"MAUI-AI-Debugging-Setup-Anleitung","pt":"Guia de Configuração para Debugging de AI MAUI","ru":"Руководство по настройке отладки ИИ MAUI","ar":"دليل إعداد أداة Debugging للذكاء الاصطناعي MAUI"},"description":{"en":"Unlock efficient .NET MAUI app debugging with maui-ai-debugging. Learn how to install and use this skill to streamline your development workflow today!","zh":"使用MAUI AI调试工具，轻松完成.NET MAUI应用的构建、部署、检查和调试。了解如何安装和更新该工具","ja":"MAUI AIデバッグツールを使用して、.NET MAUIアプリのビルド、デプロイ、検査、デバッグを簡単に行う。インストールと更新方法を学ぶ","ko":"MAUI AI 디버깅 도구를 사용하여 .NET MAUI 애플리케이션의 빌드, 배포, 검사 및 디버깅을 간단하게 수행하십시오. 설치 및 업데이트 방법을 알아보십시오","es":"Aprende a depurar aplicaciones .NET MAUI con MAUI Sherpa y mejora tu flujo de trabajo de desarrollo","fr":"Découvrez comment déboguer les applications .NET MAUI avec MAUI Sherpa et améliorez votre flux de travail de développement","de":"Erfahren Sie, wie Sie .NET MAUI-Apps mit MAUI Sherpa debuggen und verbessern Sie Ihren Entwicklungsworkflow","pt":"Aprenda a configurar o debugging de AI MAUI para .NET MAUI com o MAUI Sherpa e melhore sua produtividade","ru":"Узнайте, как настроить отладку ИИ MAUI для .NET MAUI с помощью MAUI Sherpa и повысьте свою производительность","ar":"تعلم كيفية إعداد أداة Debugging للذكاء الاصطناعي MAUI ل.NET MAUI مع MAUI Sherpa وطور إنتاجيتك"},"definition":{"en":"maui-ai-debugging is a skill that provides AI-powered debugging capabilities for .NET MAUI applications, facilitating a seamless development experience.","zh":"MAUI AI调试工具是一种用于.NET MAUI应用的终端调试工具，提供构建、部署、检查和调试功能","ja":"MAUI AIデバッグツールは、.NET MAUIアプリ用のターミナルデバッグツールで、ビルド、デプロイ、検査、デバッグ機能を提供する","ko":"MAUI AI 디버깅 도구는 .NET MAUI 애플리케이션을 위한 터미널 디버깅 도구로, 빌드, 배포, 검사 및 디버깅 기능을 제공합니다","es":"MAUI AI Debugging es una herramienta de depuración de AI para aplicaciones .NET MAUI que permite una retroalimentación completa","fr":"MAUI AI Debugging est un outil de débogage AI pour les applications .NET MAUI qui permet une boucle de rétroaction complète","de":"MAUI-AI-Debugging ist ein AI-Debugging-Tool für .NET-MAUI-Anwendungen, das eine vollständige Rückmeldeschleife ermöglicht","pt":"O debugging de AI MAUI é uma ferramenta que permite aos desenvolvedores criar, implantar, inspecionar e depurar aplicativos .NET MAUI","ru":"Отладка ИИ MAUI - это инструмент, который позволяет разработчикам создавать, развертывать, инспектировать и отлаживать приложения .NET MAUI","ar":"أداة Debugging للذكاء الاصطناعي MAUI هي أداة تسمح للمطورين بإنشاء وتوزيع وتفتيش وإصلاح تطبيقات .NET MAUI"},"features":{"en":["Enables build, deploy, inspect, and debug operations for .NET MAUI apps via the terminal","Supports installation and updates via dotnet tool install and update commands","Requires Redth.MauiDevFlow.CLI and androidsdk.tool/appledev.tools for Android and iOS/Mac development","Allows for skill updates using the maui-devflow update-skill command","Facilitates a complete feedback loop: build → deploy → inspect → fix → rebuild"],"zh":["使用CLI命令行工具构建和部署.NET MAUI应用","检查和调试.NET MAUI应用","支持Android和iOS/Mac平台","使用dotnet tool install和update-skill命令更新工具"],"ja":["CLIコマンドラインツールを使用して.NET MAUIアプリをビルドおよびデプロイする",".NET MAUIアプリを検査およびデバッグする","AndroidおよびiOS/Macプラットフォームをサポートする","dotnet tool installおよびupdate-skillコマンドを使用してツールを更新する"],"ko":["CLI 명령줄 도구를 사용하여 .NET MAUI 애플리케이션을 빌드 및 배포합니다",".NET MAUI 애플리케이션을 검사 및 디버깅합니다","Android 및 iOS/Mac 플랫폼을 지원합니다","dotnet tool install 및 update-skill 명령을 사용하여 도구를 업데이트합니다"],"es":["Construir e implementar aplicaciones .NET MAUI desde la terminal","Inspeccionar y depurar aplicaciones .NET MAUI con MAUI Sherpa","Uso de herramientas de línea de comandos como Redth.MauiDevFlow.CLI","Compatibilidad con Android e iOS/Mac","Actualización de habilidades con ''maui-devflow update-skill''","Soporte para flujos de trabajo de desarrollo de aplicaciones .NET MAUI"],"fr":["Construire et déployer des applications .NET MAUI depuis le terminal","Inspecter et déboguer des applications .NET MAUI avec MAUI Sherpa","Utilisation d''outils de ligne de commande tels que Redth.MauiDevFlow.CLI","Compatibilité avec Android et iOS/Mac","Mise à jour des compétences avec ''maui-devflow update-skill''","Prise en charge des flux de travail de développement d''applications .NET MAUI"],"de":["Erstellen und Bereitstellen von .NET-MAUI-Anwendungen von der Terminal aus","Untersuchen und Debuggen von .NET-MAUI-Anwendungen mit MAUI Sherpa","Verwendung von Befehlszeilentools wie Redth.MauiDevFlow.CLI","Kompatibilität mit Android und iOS/Mac","Aktualisierung von Fähigkeiten mit ''maui-devflow update-skill''","Unterstützung von Entwicklungsworkflows für .NET-MAUI-Anwendungen"],"pt":["Ciclo de feedback completo: build, deploy, inspect, fix e rebuild","Instalação do CLI do Redth.MauiDevFlow","Atualização do skill com `maui-devflow update-skill`","Suporte a ferramentas de desenvolvimento Android e iOS","Integração com o terminal para debugging de aplicativos .NET MAUI"],"ru":["Полный цикл обратной связи: build, deploy, inspect, fix и rebuild","Установка CLI Redth.MauiDevFlow","Обновление навыка с помощью `maui-devflow update-skill`","Поддержка инструментов разработки Android и iOS","Интеграция с терминалом для отладки приложений .NET MAUI"],"ar":["دورة تغذية راجعة كاملة: build، deploy، inspect، fix و rebuild","تثبيت CLI Redth.MauiDevFlow","تحديث المهارة باستخدام `maui-devflow update-skill`","دعم أدوات تطوير Android و iOS","التكامل مع Terminal لتصحيح أخطاء تطبيقات .NET MAUI"]},"keywords":{"en":["how to use maui-ai-debugging","maui-ai-debugging install","maui-ai-debugging setup guide","what is maui-ai-debugging","maui-ai-debugging alternative","maui-ai-debugging vs traditional debugging methods"],"zh":["MAUI AI调试工具","NET MAUI应用调试","终端调试工具","CLI命令行工具","Android和iOS/Mac开发","dotnet tool install","update-skill命令"],"ja":["MAUI AIデバッグツール","NET MAUIアプリデバッグ","ターミナルデバッグツール","CLIコマンドラインツール","AndroidおよびiOS/Mac開発","dotnet tool install","update-skillコマンド"],"ko":["MAUI AI 디버깅 도구","NET MAUI 애플리케이션 디버깅","터미널 디버깅 도구","CLI 명령줄 도구","Android 및 iOS/Mac 개발","dotnet tool install","update-skill 명령"],"es":["depuración de AI de MAUI","herramientas de desarrollo de .NET MAUI","MAUI Sherpa","Redth.MauiDevFlow.CLI","desarrollo de aplicaciones .NET MAUI","depuración de aplicaciones .NET MAUI","terminal de línea de comandos","Android","iOS","Mac"],"fr":["débogage MAUI AI","outils de développement .NET MAUI","MAUI Sherpa","Redth.MauiDevFlow.CLI","développement d''applications .NET MAUI","débogage d''applications .NET MAUI","terminal de ligne de commande","Android","iOS","Mac"],"de":["MAUI-AI-Debugging","Entwicklungstools für .NET-MAUI","MAUI Sherpa","Redth.MauiDevFlow.CLI","Entwicklung von .NET-MAUI-Anwendungen","Debuggen von .NET-MAUI-Anwendungen","Terminal-Befehlszeile","Android","iOS","Mac"],"pt":["debugging de AI MAUI","MAUI Sherpa","CLI do Redth.MauiDevFlow","desenvolvimento de aplicativos .NET MAUI","ferramentas de desenvolvimento Android","ferramentas de desenvolvimento iOS","ciclo de feedback completo","otimização de produtividade"],"ru":["отладка ИИ MAUI","MAUI Sherpa","CLI Redth.MauiDevFlow","разработка приложений .NET MAUI","инструменты разработки Android","инструменты разработки iOS","полный цикл обратной связи","оптимизация производительности"],"ar":["أداة Debugging للذكاء الاصطناعي MAUI","MAUI Sherpa","CLI Redth.MauiDevFlow","تطوير تطبيقات .NET MAUI","أدوات تطوير Android","أدوات تطوير iOS","دورة تغذية راجعة كاملة","تحسين الإنتاجية"]}},"owner":"Redth","repo":"MAUI.Sherpa","repoPath":"Redth/MAUI.Sherpa","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.310Z","topics":[],"category":"community","skillMd":{"name":"maui-ai-debugging","description":">","bodyPreview":"# MAUI AI Debugging\n\nBuild, deploy, inspect, and debug .NET MAUI apps from the terminal. This skill enables a complete\nfeedback loop: **build → deploy → inspect → fix → rebuild**.\n\n## Prerequisites\n\n```bash\ndotnet tool install --global Redth.MauiDevFlow.CLI || dotnet tool update --global Redth.MauiDevFlow.CLI\ndotnet tool install --global androidsdk.tool    # Android only\ndotnet tool install --global appledev.tools     # iOS/Mac only\n```\n\nKeep the skill up to date: `maui-devflow update-skill`. Ch","body":"# MAUI AI Debugging\n\nBuild, deploy, inspect, and debug .NET MAUI apps from the terminal. This skill enables a complete\nfeedback loop: **build → deploy → inspect → fix → rebuild**.\n\n## Prerequisites\n\n```bash\ndotnet tool install --global Redth.MauiDevFlow.CLI || dotnet tool update --global Redth.MauiDevFlow.CLI\ndotnet tool install --global androidsdk.tool    # Android only\ndotnet tool install --global appledev.tools     # iOS/Mac only\n```\n\nKeep the skill up to date: `maui-devflow update-skill`. Check installed version vs remote\nwith `maui-devflow skill-version`. For full update procedures, see\n[references/setup.md](references/setup.md#checking-for-updates).\n\n## Integrating MauiDevFlow into a MAUI App\n\nFor complete setup instructions, see [references/setup.md](references/setup.md).\n\n**Quick summary:**\n1. Add NuGet packages (`Redth.MauiDevFlow.Agent`, and `Redth.MauiDevFlow.Blazor` for Blazor Hybrid)\n   - For **Linux/GTK apps** (detected via `grep -i ''GirCore\\|Maui\\.Gtk'' *.csproj`), use `Agent.Gtk` and `Blazor.Gtk` instead\n   - For **macOS (AppKit) apps** (detected via `grep -i ''Platform\\.Maui\\.MacOS'' *.csproj`), the standard `Agent` and `Blazor` packages include macOS support\n2. Register in `MauiProgram.cs` inside `#if DEBUG`\n3. For Blazor Hybrid: chobitsu.js is auto-injected (no manual script tag needed)\n4. For Mac Catalyst: ensure `network.server` entitlement\n5. For Android: run `adb reverse` for broker + agent ports\n6. For Linux: no special network setup needed (direct localhost)\n7. For macOS (AppKit): separate app head project, uses `open App.app` to launch. See [references/macos.md](references/macos.md)\n\n## Core Workflow\n\n### 1. Ensure a Device/Simulator/Emulator is Running\n\n**⚠️ Multi-project conflict avoidance:** When multiple projects may run simultaneously\n(common with AI agents), each project should use its own dedicated simulator/emulator to\nprevent apps from replacing each other. Check what''s already in use first:\n\n```bash\nmaui-devflow list                                             # see all registered agents\n```\n\nIf another iOS or Android agent is already registered, **create a new simulator/emulator**\nfor your project instead of reusing the one that''s already booted.\n\n**iOS Simulator:**\n```bash\nxcrun simctl list devices booted                              # check booted sims\n\n# Create a project-dedicated simulator to avoid conflicts\nxcrun simctl create \"MyApp-iPhone17Pro\" \"iPhone 17 Pro\" \"iOS 26.2\"\nxcrun simctl boot <UDID>                                      # boot the new sim\n```\n\n**Android Emulator:**\n```bash\nandroid avd list                                              # list AVDs\n\n# Create a project-dedicated emulator to avoid conflicts\nandroid avd create --name \"MyApp-Pixel8\" \\\n  --sdk \"system-images;android-35;google_apis;arm64-v8a\" --device pixel_8\nandroid avd start --name \"MyApp-Pixel8\"\n```\n\n**Mac Catalyst / macOS (AppKit) / Linux/GTK:** No device setup needed — runs as desktop app.\nMultiple desktop apps can run simultaneously without conflicts.\n\n### 2. Detect the TFM\n\n**IMPORTANT:** Before building, detect the correct Target Framework Moniker from the project.\nDo NOT assume `net10.0` — many projects use `net9.0`, `net8.0`, etc.\n\n```bash\ngrep -i ''TargetFrameworks'' *.csproj Directory.Build.props 2>/dev/null\n```\n\nUse the detected version (e.g. `net9.0`) in all build commands. The examples use `$TFM`.\n\n### 3. Build, Deploy, and Connect\n\nFollow these steps for every launch and rebuild.\n\n**Step 1: Kill any previous instance** (skip on first launch).\nA stale app''s agent stays registered with the broker, causing `maui-devflow wait` to return\nthe old port instantly instead of waiting for the new build.\n\n```bash\n# Stop the async shell from the previous launch, then confirm:\nmaui-devflow list                 # should show no agents (or only unrelated ones)\n```\n\n**Step 2: Launch in an async shell.**\n\n```bash\n# iOS Simulator\ndotnet build -f $TFM-ios -t:Run -p:_DeviceName=:v2:udid=<UDID>\n\n# Android Emulator\ndotnet build -f $TFM-android -t:Run\n\n# Mac Catalyst\ndotnet build -f $TFM-maccatalyst -t:Run\n\n# macOS AppKit — build exits after compiling; launch separately\ndotnet build -f $TFM-macos <path-to-macos-project>\nopen path/to/bin/Debug/$TFM-macos/osx-arm64/AppName.app\n\n# Linux/GTK\ndotnet run --project <path-to-gtk-project>\n```\n\n**⚠️ Process lifecycle rules:**\n- `dotnet build -t:Run` (iOS, Android, Mac Catalyst) and `dotnet run` (Linux/GTK) **block\n  for the lifetime of the app**. Killing or stopping the shell **kills the app**. Use\n  `mode: \"async\"` with `initial_wait: 120` and do NOT stop the shell until you are done.\n- **macOS (AppKit)** is the exception: `dotnet build` exits after compiling, and `open`\n  launches the app independently — the app survives shell termination.\n\n**Step 3: Wait for the agent** — never use `sleep`.\n\n```bash\nmaui-devflow wait                                # blocks until agent registers (default 120s)\nmaui-devflow wait --project path/to/App.csproj   # filter to specific project\n```\n\n`maui-devflow wait` prints the assigned port as soon as the agent connects. Exit code 1\nmeans timeout — check async shell output for build errors.\n\n**Android only** — set up port forwarding after the agent connects:\n```bash\nadb reverse tcp:19223 tcp:19223   # Broker (lets agent in emulator reach host broker)\nadb forward tcp:<port> tcp:<port> # Agent (lets CLI reach agent in emulator)\n```\n\n**To rebuild:** repeat from Step 1. See [references/troubleshooting.md](references/troubleshooting.md)\nif the build fails.\n\n### 4. Inspect and Interact\n\n**Typical inspection flow:**\n1. `maui-devflow MAUI tree` — see the full visual tree with element IDs, types, text, bounds\n2. `maui-devflow MAUI tree --window 1` — filter to a specific window (0-based index)\n3. `maui-devflow MAUI query --automationId \"MyButton\"` — find specific elements\n4. `maui-devflow MAUI element <id>` — get full details (type, bounds, visibility, children)\n5. `maui-devflow MAUI property <id> Text` — read any property by name\n6. `maui-devflow MAUI screenshot --output screen.png` — visual verification\n7. `maui-devflow MAUI screenshot --id <elementId> --output el.png` — element-only screenshot\n8. `maui-devflow MAUI screenshot --selector \"Button\" --output btn.png` — screenshot by CSS selector\n\n**Property inspection** is more reliable than screenshots for verifying exact runtime values:\n```bash\nmaui-devflow MAUI property <id> BackgroundColor    # verify dark mode colors\nmaui-devflow MAUI property <id> IsVisible          # check element visibility\n```\n\n**Live editing (no rebuild needed):**\n```bash\nmaui-devflow MAUI set-property <id> TextColor \"Tomato\"\nmaui-devflow MAUI set-property <id> FontSize \"24\"\n```\nSupports: string, bool, int, double, Color (named/hex), Thickness, enums. Changes persist\nuntil the app restarts — safe for experimentation.\n\n**Typical interaction flow:**\n1. `maui-devflow MAUI fill <entryId> \"text\"` — type into Entry/Editor fields\n2. `maui-devflow MAUI tap <buttonId>` — tap buttons, checkboxes, list items\n3. `maui-devflow MAUI clear <entryId>` — clear text fields\n4. Take screenshot to verify result\n\n**Blazor WebView (if applicable):**\n1. `maui-devflow cdp snapshot` — DOM tree as accessible text (best for AI)\n2. `maui-devflow cdp Input fill \"css-selector\" \"text\"` — fill inputs\n3. `maui-devflow cdp Input dispatchClickEvent \"css-selector\"` — click elements\n4. `maui-devflow cdp Runtime evaluate \"js-expression\"` — run JS\n\n**Multiple BlazorWebViews:** If the app has more than one `BlazorWebView`, each is\nregistered independently with its `AutomationId`. Use `cdp webviews` to list them,\nthen target a specific one with `--webview` (or `-w`):\n\n```bash\nmaui-devflow cdp webviews                                  # list all WebViews\nmaui-devflow cdp -w BlazorLeft snapshot                    # snapshot of a specific WebView\nmaui-devflow cdp -w 1 Runtime evaluate \"document.title\"    # target by index\n```\n\nWithout `--webview`, commands target the first (index 0) WebView.\n\n**Live CSS/DOM editing in Blazor (no rebuild needed):**\n```bash\nmaui-devflow cdp Runtime evaluate \"document.querySelector(''h1'').style.color = ''tomato''\"\nmaui-devflow cdp Runtime evaluate \"document.documentElement.style.setProperty(''--bg-color'', ''#1a1a2e'')\"\n```\n\n### 5. Reading Application Logs\n\nMauiDevFlow automatically captures all `ILogger` output and WebView `console.*` calls\nto rotating log files, retrievable remotely:\n\n```bash\nmaui-devflow MAUI logs                   # fetch 100 most recent log entries\nmaui-devflow MAUI logs --limit 50        # fetch 50 entries\nmaui-devflow MAUI logs --source webview  # only WebView/Blazor console logs\nmaui-devflow MAUI logs --source native   # only native ILogger logs\nmaui-devflow MAUI logs --follow          # stream logs in real-time (Ctrl+C to stop)\nmaui-devflow MAUI logs -f --source native  # stream only native logs\nmaui-devflow MAUI logs -f --json         # stream as JSONL (machine-readable)\n```\n\n**Debugging workflow:** Reproduce the issue → `maui-devflow MAUI logs --limit 20` → check for\nerrors. Add temporary `ILogger` calls for more detail, rebuild, reproduce, and fetch logs again.\n\n### 6. Screen Recording\n\nCapture video of the app while performing interactions. Recording is host-side (not in-app)\nusing platform-native tools.\n\n```bash\n# Start recording (default 30s timeout)\nmaui-devflow MAUI recording start --output demo.mp4\n\n# Interact with the app\nmaui-devflow MAUI tap <buttonId>\nmaui-devflow MAUI navigate \"//blazor\"\nmaui-devflow MAUI fill <entryId> \"Hello World\"\n\n# Stop and save\nmaui-devflow MAUI recording stop\n```\n\n**Platform tools used automatically:**\n- **Android:** `adb screenrecord` (max 180s, capped with warning)\n- **iOS Simulator:** `xcrun simctl io recordVideo`\n- **Mac Catalyst / macOS (AppKit):** `screencapture -v` (targets app window when possible)\n- **Windows/Linux:** `ffmpeg` (must be on PATH)\n\n**Options:** `--timeout <seconds>` (default 30), `--output <path>` (default `recording_<timestamp>.mp4`).\nOnly one recording at a time — stop before starting a new one.\n\n### 7. Network Request Monitoring\n\nMonitor HTTP requests made by the app in real-time. MauiDevFlow automatically intercepts\nall `IHttpClientFactory`-based HTTP traffic via a `DelegatingHandler` — no app code changes\nneeded beyond the standard `AddMauiDevFlowAgent()` setup.\n\n```bash\n# Live monitor — streams requests as they happen (Ctrl+C to stop)\nmaui-devflow MAUI network\n\n# JSONL streaming — machine-readable, one JSON object per line\nmaui-devflow MAUI network --json\n\n# One-shot: list recent captured requests\nmaui-devflow MAUI network list\n\n# Filter by method or host\nmaui-devflow MAUI network list --method POST\nmaui-devflow MAUI network list --host api.example.com\n\n# Full request/response details (headers + body)\nmaui-devflow MAUI network detail <requestId>\n\n# Clear captured requests\nmaui-devflow MAUI network clear\n```\n\n**How it works:**\n- A `DelegatingHandler` wraps the platform''s HTTP handler (AndroidMessageHandler,\n  NSUrlSessionHandler, etc.), capturing request/response metadata, headers, and bodies\n- Auto-injected via `ConfigureHttpClientDefaults` — works for all `IHttpClientFactory` clients\n- For `new HttpClient()` outside DI, use `DevFlowHttp.CreateClient()` helper\n- Bodies up to 256KB are captured (configurable via `AgentOptions.MaxNetworkBodySize`)\n- A ring buffer (default 500 entries) stores recent requests in-memory\n\n**JSONL output** is ideal for AI parsing — pipe to `jq` or process programmatically:\n```bash\nmaui-devflow MAUI network --json | jq ''select(.statusCode >= 400)''\n```\n\n**WebSocket streaming:** The live monitor uses WebSocket (`/ws/network`) for real-time push.\nConnecting clients receive a replay of buffered history, then live entries as they arrive.\n\n## Command Reference\n\n### maui-devflow MAUI (Native Agent)\n\nGlobal options: `--agent-host` (default localhost), `--agent-port` (auto-discovered via broker), `--platform`.\n\nThese options work on any subcommand position: `maui-devflow MAUI status --agent-port 10224`\nor `maui-devflow --agent-port 10224 MAUI status` — both are valid.\n\n| Command | Description |\n|---------|-------------|\n| `MAUI status [--window W]` | Agent connection status, platform, app name, window count |\n| `MAUI tree [--depth N] [--window W]` | Visual tree (IDs, types, text, bounds). Depth 0=unlimited. Window is 0-based index; omit for all windows |\n| `MAUI query --type T --automationId A --text T` | Find elements (any/all filters) |\n| `MAUI hittest <x> <y> [--window W]` | Find elements at a point (deepest first). Returns IDs, types, bounds |\n| `MAUI tap <elementId>` | Tap an element |\n| `MAUI fill <elementId> <text>` | Fill text into Entry/Editor |\n| `MAUI clear <elementId>` | Clear text from element |\n| `MAUI screenshot [--output path.png] [--window W] [--id ID] [--selector SEL]` | PNG screenshot. Capture full window or a specific element by ID/selector. Window is 0-based index; default first window |\n| `MAUI property <elementId> <prop>` | Read property (Text, IsVisible, FontSize, etc.) |\n| `MAUI set-property <elementId> <prop> <value>` | Set property (live editing — colors, text, sizes, etc.) |\n| `MAUI element <elementId>` | Full element JSON (type, bounds, children, etc.) |\n| `MAUI navigate <route>` | Shell navigation (e.g. `//native`, `//blazor`) |\n| `MAUI scroll [--element id] [--dx N] [--dy N] [--window W]` | Scroll by delta or scroll element into view |\n| `MAUI focus <elementId>` | Set focus to element |\n| `MAUI resize <width> <height> [--window W]` | Resize app window. Window is 0-based index; default first window |\n| `MAUI logs [--limit N] [--skip N] [--source S] [--follow] [--json]` | Fetch or stream application logs. `--follow` / `-f` streams in real-time via WebSocket (Ctrl+C to stop). `--json` outputs JSONL. Source: native, webview, or omit for all |\n| `MAUI recording start [--output path] [--timeout 30]` | Start screen recording. Default timeout 30s. Uses platform-native tools (adb screenrecord, xcrun simctl, screencapture, ffmpeg) |\n| `MAUI recording stop` | Stop active recording and save the video file |\n| `MAUI recording status` | Check if a recording is currently in progress |\n| `MAUI network` | Live network monitor — streams HTTP requests in real-time (Ctrl+C to stop). Use `--json` for JSONL output |\n| `MAUI network list [--host H] [--method M] [--json]` | One-shot: dump recent captured HTTP requests as table or JSONL |\n| `MAUI network detail <requestId>` | Full request/response details: headers, body, timing |\n| `MAUI network clear` | Clear the captured request buffer |\n\nElement IDs come from `MAUI tree` or `MAUI query`. AutomationId-based elements use their\nAutomationId directly. Others use generated hex IDs. When multiple elements share the same\nAutomationId, suffixes are appended: `TodoCheckBox`, `TodoCheckBox_1`, `TodoCheckBox_2`, etc.\n\n### maui-devflow cdp (Blazor WebView CDP)\n\nGlobal options: `--agent-host` (default localhost), `--agent-port` (auto-discovered via broker).\nCDP commands use the same agent port — all communication goes through a single port.\nUse `--webview <id>` (or `-w <id>`) on any CDP command to target a specific WebView\nby index, AutomationId, or element ID. Default: first WebView.\n\n| Command | Description |\n|---------|-------------|\n| `cdp status` | CDP connection status and WebView count |\n| `cdp webviews [--json]` | List available CDP WebViews (index, AutomationId, ready status) |\n| `cdp snapshot` | Accessible DOM text (best for AI agents) |\n| `cdp source` | Get full page HTML source |\n| `cdp Browser getVersion` | Browser/WebView version info |\n| `cdp Runtime evaluate <expr>` | Evaluate JavaScript |\n| `cdp DOM getDocument` | Full DOM document |\n| `cdp DOM querySelector <sel>` | Find first matching element |\n| `cdp DOM querySelectorAll <sel>` | Find all matching elements |\n| `cdp DOM getOuterHTML <sel>` | Get outer HTML of element |\n| `cdp Page navigate <url>` | Navigate to URL |\n| `cdp Page reload` | Reload page |\n| `cdp Page captureScreenshot` | Screenshot as base64 |\n| `cdp Input dispatchClickEvent <sel>` | Click element by CSS selector |\n| `cdp Input insertText <text>` | Insert text at focused element |\n| `cdp Input fill <selector> <text>` | Focus + fill text into element |\n\n**Multi-WebView targeting:** If the app has multiple BlazorWebViews, use `cdp webviews`\nto list them, then `--webview <index-or-automationId>` on any command to target a specific one.\nExample: `maui-devflow cdp --webview 1 snapshot` or `maui-devflow cdp -w MyWebView Runtime evaluate \"1+1\"`.\n\n### maui-devflow Broker & Discovery\n\nThe broker is a background daemon that manages port assignments for all running agents.\nThe CLI auto-starts the broker on first use — no manual setup needed.\n\n| Command | Description |\n|---------|-------------|\n| `list` | Show all registered agents (ID, app, platform, TFM, port, uptime) |\n| `wait [--timeout 120] [--project path] [--wait-platform P] [--json]` | Wait for an agent to connect. Outputs the port (or JSON with `--json`). Useful after `dotnet build -t:Run` to block until the app is ready |\n| `broker status` | Broker daemon status and connected agent count |\n| `broker start` | Start broker daemon (auto-started by CLI — rarely needed manually) |\n| `broker stop` | Stop broker daemon |\n| `broker log` | Show broker log file |\n\n### maui-devflow batch (Multi-Command Execution)\n\nExecute multiple commands in one invocation via stdin. Returns JSONL responses. Use for\nmulti-step interactions to avoid repeated port resolution.\n\n```bash\necho \"MAUI fill textUsername user; MAUI fill textPassword pwd123; MAUI tap buttonLogin\" | maui-devflow batch\n```\n\nFor full options, JSONL format, and streaming details, see [references/batch.md](references/batch.md).\n\n## Platform Details\n\nFor detailed platform-specific setup, simulator/emulator management, and troubleshooting:\n\n- **Setup & Installation**: See [references/setup.md](references/setup.md)\n- **iOS / Mac Catalyst**: See [references/ios-and-mac.md](references/ios-and-mac.md)\n- **macOS (AppKit)**: See [references/macos.md](references/macos.md)\n- **Android**: See [references/android.md](references/android.md)\n- **Linux / GTK**: See [references/linux.md](references/linux.md)\n- **Troubleshooting**: See [references/troubleshooting.md](references/troubleshooting.md)\n\n## ⚠️ Non-Disruptive Operation\n\n**CRITICAL:** Never run commands that steal focus, move windows, simulate mouse/keyboard input,\nor otherwise disrupt the user''s desktop. The user is likely working on the same computer.\n\n**Never use:**\n- `osascript` to focus/activate windows, click UI elements, or send keystrokes\n- `screencapture` interactively (the MauiDevFlow screenshot command captures in-process instead)\n- `xdotool` focus/activate/key commands that affect the active window\n- Any command that moves the mouse cursor or simulates input at the OS level\n- `open -a` to bring apps to the foreground (use `open` only to launch, not to focus)\n\n**Instead:** All inspection and interaction goes through `maui-devflow` CLI commands, which\ncommunicate with the in-app agent over HTTP — no foreground focus required. If you need\nsomething that would require OS-level control (e.g., dismissing a system dialog outside the\napp), **ask the user** to do it manually rather than attempting automation that would hijack\ntheir input.\n\n## Tips\n\n- **Use `maui-devflow batch`** for multi-step interactions — resolves port once, adds delays,\n  returns structured JSONL. See [references/batch.md](references/batch.md).\n- **Always use `maui-devflow MAUI screenshot`** — captures in-process, app does NOT need\n  foreground focus.\n- Use `AutomationId` on important MAUI controls for stable element references.\n- For Blazor Hybrid, `cdp snapshot` is the most AI-friendly way to read page state.\n- Port discovery, multi-project setup, and custom ports: see [references/setup.md](references/setup.md#3b-port-configuration).\n"},"lastSynced":"2026-03-08T02:02:27.742Z","agentAnalysis":{"suitability":{"en":"Perfect for Mobile App Development Agents needing comprehensive .NET MAUI debugging capabilities.","zh":"非常适合需要全面.NET MAUI调试功能的移动应用开发代理。","ja":".NET MAUIの包括的なデバッグ機能を必要とするモバイルアプリ開発エージェントに最適です。","ko":".NET MAUI의 완전한 디버깅 기능을 필요로 하는 모바일 앱 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo de Aplicaciones Móviles que necesitan capacidades de depuración de .NET MAUI integrales.","fr":"Parfait pour les agents de développement d''applications mobiles ayant besoin de capacités de débogage .NET MAUI complètes.","de":"Perfekt für Mobile App Development Agents, die umfassende .NET MAUI-Debugging-Funktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento de Aplicativos Móveis que necessitam de capacidades de depuração do .NET MAUI abrangentes.","ru":"Идеально подходит для агентов разработки мобильных приложений, которым необходимы всесторонние возможности отладки .NET MAUI.","ar":"مثالي للوكلاء الذين يحتاجون إلى mogelijkات تشخيص شاملة لبرامج الهاتف المحمول التي تستخدم .NET MAUI."},"recommendation":{"en":"Empowers agents to build, deploy, inspect, and debug .NET MAUI apps from the terminal, utilizing tools like Redth.MauiDevFlow.CLI, androidsdk.tool, and appledev.tools, and enabling a complete feedback loop through the terminal.","zh":"赋予代理构建、部署、检查和调试.NET MAUI应用的能力，从终端使用Redth.MauiDevFlow.CLI、androidsdk.tool和appledev.tools等工具，并通过终端实现完整的反馈循环。","ja":"エージェントがRedth.MauiDevFlow.CLI、androidsdk.tool、appledev.toolsなどのツールを使用して、.NET MAUIアプリを構築、デプロイ、検査、デバッグする能力を付与し、ターミナルから完全なフィードバックループを実現します。","ko":"에이전트가 Redth.MauiDevFlow.CLI, androidsdk.tool, appledev.tools 등의 도구를 사용하여 .NET MAUI 애플리케이션을 구축, 배포, 검사 및 디버깅할 수 있는 기능을 부여하며, 터미널을 통해 완전한 피드백 루프를 구현합니다.","es":"Habilita a los agentes a compilar, implementar, inspeccionar y depurar aplicaciones .NET MAUI desde la terminal, utilizando herramientas como Redth.MauiDevFlow.CLI, androidsdk.tool y appledev.tools, y permitiendo un bucle de retroalimentación completo a través de la terminal.","fr":"Permet aux agents de construire, de déployer, d''inspecter et de déboguer des applications .NET MAUI à partir du terminal, en utilisant des outils tels que Redth.MauiDevFlow.CLI, androidsdk.tool et appledev.tools, et en permettant une boucle de rétroaction complète via le terminal.","de":"Ermächtigt die Agenten, .NET MAUI-Apps aus der Terminal-Konsole zu erstellen, zu bereitstellen, zu überprüfen und zu debuggen, unter Verwendung von Tools wie Redth.MauiDevFlow.CLI, androidsdk.tool und appledev.tools, und ermöglicht einen vollständigen Feedbackkreis über die Konsole.","pt":"Permite que os agentes construam, implantem, inspecionem e depurem aplicativos .NET MAUI a partir do terminal, utilizando ferramentas como Redth.MauiDevFlow.CLI, androidsdk.tool e appledev.tools, e habilitando um loop de feedback completo por meio do terminal.","ru":"Позволяет агентам строить, развертывать, инспектировать и отлаживать приложения .NET MAUI из терминала, используя инструменты seperti Redth.MauiDevFlow.CLI, androidsdk.tool и appledev.tools, и обеспечивая полный цикл обратной связи через терминал.","ar":"يسمح للوكلاء ببناء وتشغيل وتحليل وتشخيص تطبيقات .NET MAUI من الطرفية، باستخدام أدوات مثل Redth.MauiDevFlow.CLI و androidsdk.tool و appledev.tools، وتمكين حلقة ردود الفعل الكاملة من خلال الطرفية."},"useCases":{"en":["Debugging .NET MAUI apps on Android and iOS devices","Inspecting and fixing app issues from the terminal","Streamlining the build → deploy → inspect → fix → rebuild process"],"zh":["在Android和iOS设备上调试.NET MAUI应用","从终端检查和修复应用问题","简化构建 → 部署 → 检查 → 修复 → 重新构建的过程"],"ja":[".NET MAUIアプリをAndroidおよびiOSデバイスでデバッグする","ターミナルからアプリの問題を検査して修正する","ビルド → デプロイ → 検査 → 修正 → 再構築のプロセスを合理化する"],"ko":[".NET MAUI 애플리케이션을 안드로이드 및 iOS 디바이스에서 디버깅하는 것","터미널에서 애플리케이션 문제를 검사하고 수정하는 것","구축 → 배포 → 검사 → 수정 → 재구축의 프로세스를 간소화하는 것"],"es":["Depuración de aplicaciones .NET MAUI en dispositivos Android e iOS","Inspección y corrección de problemas de aplicaciones desde la terminal","Optimización del proceso de compilación → implementación → inspección → corrección → recompilación"],"fr":["Débogage des applications .NET MAUI sur les appareils Android et iOS"," Inspection et correction des problèmes d''applications à partir du terminal","Optimisation du processus de construction → déploiement → inspection → correction → reconstruction"],"de":["Debuggen von .NET MAUI-Apps auf Android- und iOS-Geräten","Überprüfung und Korrektur von App-Problemen über die Konsole","Optimierung des Prozesses Erstellen → Bereitstellen → Überprüfen → Korrigieren → Neu erstellen"],"pt":["Depuração de aplicativos .NET MAUI em dispositivos Android e iOS","Inspecionar e corrigir problemas de aplicativos a partir do terminal","Otimizar o processo de compilação → implantação → inspeção → correção → recompilação"],"ru":["Отладка приложений .NET MAUI на устройствах Android и iOS","Проверка и исправление проблем приложений из терминала","Оптимизация процесса сборки → развертывания → инспекции → исправления → пересборки"],"ar":["تشخيص برامج .NET MAUI على أجهزة Android و iOS","فحص وإصلاح مشاكل التطبيقات من الطرفية","بصرينة عملية بناء → نشر → فحص → إصلاح → إعادة بناء"]},"limitations":{"en":["Requires installation of Redth.MauiDevFlow.CLI, androidsdk.tool, and appledev.tools",".NET MAUI only","Terminal access necessary"],"zh":["需要安装Redth.MauiDevFlow.CLI、androidsdk.tool和appledev.tools",".NET MAUI仅限","需要终端访问"],"ja":["Redth.MauiDevFlow.CLI、androidsdk.tool、appledev.toolsのインストールが必要",".NET MAUIのみ","ターミナルアクセスが必要"],"ko":["Redth.MauiDevFlow.CLI, androidsdk.tool, appledev.tools의 설치가 필요",".NET MAUI만 해당","터미널 액세스가 필요"],"es":["Requiere la instalación de Redth.MauiDevFlow.CLI, androidsdk.tool y appledev.tools",".NET MAUI solo","Acceso a la terminal necesario"],"fr":["Nécessite l''installation de Redth.MauiDevFlow.CLI, androidsdk.tool et appledev.tools",".NET MAUI uniquement","Accès au terminal nécessaire"],"de":["Erfordert die Installation von Redth.MauiDevFlow.CLI, androidsdk.tool und appledev.tools",".NET MAUI nur","Terminal-Zugriff erforderlich"],"pt":["Requer instalação do Redth.MauiDevFlow.CLI, androidsdk.tool e appledev.tools","Somente .NET MAUI","Acesso ao terminal necessário"],"ru":["Требуется установка Redth.MauiDevFlow.CLI, androidsdk.tool и appledev.tools","Только .NET MAUI","Необходим доступ к терминалу"],"ar":["يتطلب تثبيت Redth.MauiDevFlow.CLI و androidsdk.tool و appledev.tools",".NET MAUI فقط","الوصول إلى الطرفية ضروري"]},"version":4},"contentHash":"e40916183c284bc41db89e2ca98c3290e2d45675c28e815f719d65e6749d4473","qualityScore":45}');
